/*
方針:
アウトになるのは
?AG+C
?GA+C
A?G+C
AG?+C
?AC+G
の5パターン
->最後4文字から考える
*/
int N;
int ans;
int solve()
{
    int memo[101][4][4][4];
    memo[0][3][3][3] = 1;
    for (int length = 0; length < N; length++)
    {
        for (int c1 = 0; c1 < 4; c1++)
        {
            for (int c2 = 0; c2 < 4; c2++)
            {
                for (int c3 = 0; c3 < 4; c3++)
                {
                    for (int c4 = 0; c4 < 4; c4++)
                    {
                        if (c2 == 0 && c3 == 1 && c4 == 2) //?012
                            continue;
                        if (c1 == 0 && c3 == 1 && c4 == 2) //0?12
                            continue;
                        if (c2 == 1 && c3 == 0 && c4 == 2) //?102
                            continue;
                        if (c1 == 0 && c2 == 1 && c4 == 2) //01?2
                            continue;
                        if (c2 == 0 && c3 == 2 && c4 == 1) //?021
                            continue;
                        memo[length + 1][c2][c3][c4] += memo[length][c1][c2][c3];
                        memo[length + 1][c2][c3][c4] %= MOD;
                    }
                }
            }
        }
    }
    for (int c1 = 0; c1 < 4; c1++)
    {
        for (int c2 = 0; c2 < 4; c2++)
        {
            for (int c3 = 0; c3 < 4; c3++)
            {
                ans += memo[N][c1][c2][c3];
            }
        }
    }
}
int main()
{
    cin >> N;
    solve();
    cout << ans << endl;
    return 0;
}

