typedef long long ll;

#define mod 1000000007

ll madd(ll a, ll b){
    return (a + b) % mod;
}
ll msub(ll a, ll b){
    return (a + mod - b) % mod;
}
ll mmul(ll a, ll b){
    return ((a % mod) * (b % mod)) % mod;
}
ll mpow(ll a, ll b){
    if(b == 0) return 1;
    else if(b == 1) return a % mod;
    else if(b % 2 == 0){
        ll hlf = mpow(a,b/2);
        return (hlf * hlf) % mod;
    }
    else {
        ll hlf = mpow(a,b/2);
        return ( mmul(hlf , hlf) * a ) % mod;
    }
}
ll mdiv(ll a, ll b){
    return mmul(a, mpow(b, mod-2));
}

// AGC ... 021
bool isAGC(int a,int b,int c,int d){
    if(a == 0 && b == 2 && c == 1)return true;
    if(b == 0 && c == 2 && d == 1)return true;
    return false;
}

// A 0 C 1 G 2 T 3
bool islegal(int a,int b,int c, int d){
    if(isAGC(a,b,c,d))return false;
    if(isAGC(b,a,c,d))return false;
    if(isAGC(a,c,b,d))return false;
    if(isAGC(a,b,d,c))return false;
    return true;
}

