                rep(k,4){
                    ans[j][i] = madd(ans[j][i] , ans[j-1][k*64+a*16+b*4+c]);
                }
            }
        }
    }
    ll ans2 = 0;
    rep(i,256) ans2 = madd(ans2,ans[N][i]);
    cout << ans2 << endl;
    return 0;
}

