int N;
vector<map<string, int>> memo;

const bool IsOK(const string last4)
{
    if (last4.find("AGC") != -1)
    {
        return false;
    }
    for (int i = 0; i < 3; ++i)
    {
        string str = last4;
        char tmp = str[i];
        str[i] = str[i + 1];
        str[i + 1] = tmp;
        if (str.find("AGC") != -1)
        {
            return false;
        }
    }
    return true;
}

const int DFS(int cur, string last3)
{
    if (memo[cur].find(last3) != memo[cur].end())
    {
        return memo[cur][last3];
    }
    if (cur == N)
    {
        return 1;
    }
    int ret = 0;
    for (const char ch : {'A', 'C', 'G', 'T'})
    {
        if (IsOK(last3 + ch))
        {
            ret = (ret + DFS(cur + 1, last3.substr(1, 2) + ch)) % 1000000007;
        }
    }
    memo[cur][last3] = ret;
    return ret;
}

