bool ok(int l1, int l2, int l3, int last) {
    if (isAGC(l1, l2, l3) || isAGC(l2, l3, last)) return false;
    if (isAGC(l2, l1, l3) || isAGC(l1, l3, last)) return false;
    if (isAGC(l1, l3, l2) || isAGC(l3, l2, last)) return false;
    if (isAGC(l1, l2, last) || isAGC(l2, last, l3)) return false;
    return true;
}

