                for (int l = 0; l < 5; ++l) {
                    for (int m = 1; m < 5; ++m) {
                        if (ok(j, k, l, m)) {
                            (dp[i + 1][k][l][m] += dp[i][j][k][l]) %= MOD;
                        }
                    }
                }
            }
        }
    }

    int ans = 0;
    for (int j = 0; j < 5; ++j) {
        for (int k = 0; k < 5; ++k) {
