    int n;
    cin >> n;
    vector<vector<Mint>> dp(n + 1, vector<Mint>(625, 0));
    vector<bool> vis(625, false);
    dp[0][0] = 1;
    for (int i = 0; i < 5; ++i) {
      vis[f(i, 1, 2, 3)] = true;
      vis[f(1, i, 2, 3)] = true;
      vis[f(1, 2, i, 3)] = true;
      vis[f(i, 2, 1, 3)] = true;
      vis[f(i, 1, 3, 2)] = true;
    }
    for (int i = 0; i < n; ++i) {
      for (int mask = 0; mask < 625; ++mask) {
        if (!dp[i][mask]) continue;
        for (int x = 1; x < 5; ++x) {
          int nxt = (5 * mask % 625) + x;
          if (vis[nxt]) continue;
          dp[i + 1][nxt] += dp[i][mask];
        }
      }
    }
    Mint ans = 0;
    for (int i = 0; i < 625; ++i) {
      ans += dp[n][i];
    }
    cout << ans << '\n';
  }
