}
int decode(int order, int code)
{
    return code / (int)pow(5, order) % 5;
}
int removeTop(int code)
{
    return code % 125;
}
bool okay(int code)
{
    return removeTop(code) != encode(A, G, C) &&
           removeTop(code) != encode(G, A, C) &&
           removeTop(code) != encode(A, C, G) &&
           code != encode(A, G, G, C) &&
           code != encode(A, C, G, C) &&
           code != encode(A, T, G, C) &&
           code != encode(A, G, C, C) &&
           code != encode(A, G, T, C) ;
}
map<int, ll> solve(ll length)
{
    if (length == 0)
    {
        map<int, ll> ret;
        ret.insert(make_pair(0, 1));
        return ret;
    }
    else
    {
        auto prev = solve(length - 1);
        map<int, ll> ret;
        for (auto item : prev)
        {
            int code = removeTop(item.first);
            ll value = item.second;
            for (int i = 1; i <= 4; i++)
            {
                auto nextcode = code * 5 + i;
                if (okay(nextcode))
                {
                    auto find = ret.find(nextcode);
                    if (find == ret.end())
                    {
                        ret.insert(make_pair(nextcode, value));
                    }
                    else
                    {
                        ret.at(nextcode) = (ret.at(nextcode) + value) % mod;
                    }
                }
            }
        }
        return ret;
    }
    throw 42;
}
