#define int long long
#define MOD 1000000007

int memo[200][10][10][10][10] = {};
int n;

int dp(int i, int a, int b, int c, int d){

    if(a == 1 && b == 2 && c == 3){
        return 0;
    }

    if(a == 2 && b == 1 && c == 3){
        return 0;
    }

    if(a == 1 && b == 3 && c == 2){
        return 0;
    }

    if(a == 1 && b == 2 && d == 3){
        return 0;
    }

    if(a == 1 && c == 2 && d == 3){
        return 0;
    }

    if(b == 1 && c == 2 && d == 3){
        return 0;
    }

    if(b == 2 && c == 1 && d == 3){
        return 0;
    }

    if(b == 1 && c == 3 && d == 2){
        return 0;
    }


    if(i == n){
        return 1;
    }

    int ta, tb, tc, td;
    ta = a;
    tb = b;
    tc = c;
    td = d;
    if(memo[i][a][b][c][d] != -1){
        return memo[i][a][b][c][d];
    }

    a = b;
    b = c;
    c = d;
    int ans = 0;
    for(int j = 0;j < 4;j++){
        d = j;
        ans += dp(i+1, a, b, c, d);
        ans %= MOD;
    }

    return memo[i][ta][tb][tc][td] = ans;
}

signed main(){
    cin >> n;

    memset(memo, -1, sizeof(memo));

    cout << dp(0, 5, 5, 5, 5) << endl;
    return 0;
}

