constexpr long long MOD = 1000000007;

int main()
{
  constexpr std::size_t LIMIT = 1 << 6;
  constexpr std::size_t A = 0b00;
  constexpr std::size_t T = 0b01;
  constexpr std::size_t G = 0b10;
  constexpr std::size_t C = 0b11;

  constexpr std::size_t AGC = A | (G << 2) | (C << 4);
  constexpr std::size_t GAC = G | (A << 2) | (C << 4);
  constexpr std::size_t ACG = A | (C << 2) | (G << 4);
  int N;
  std::cin >> N;
  std::vector<std::vector<long long>> dp(N + 1, std::vector<long long>(LIMIT, 0));

  for (int i = 0; i < LIMIT; ++i)
  {
    if (i != AGC &&
        i != GAC &&
        i != ACG)
    {
      dp[3][i] = 1;
    }
  }

  for (int i = 4; i <= N; ++i)
  {
    for (std::size_t j = 0; j < LIMIT; ++j)
    {
      if (j != AGC &&
          j != GAC &&
          j != ACG)
      {
        int c0 = j >> 4;
        int c1 = (j >> 2) & 0b0011;
        int c2 = j & 0b000011;
        for (std::size_t k = 0; k < (1 << 2); ++k)
        {
          auto l = ((j & 0b001111) << 2) | k;
          if (!(c0 == C && c1 == G && k == A) &&
              !(c0 == C && c2 == G && k == A))
            dp[i][j] = (dp[i][j] + dp[i - 1][l]) % MOD;
        }
      }
    }
  }


  long long ans = 0;
  for (std::size_t i = 0; i < LIMIT; ++i)
    ans = (ans + dp[N][i]) % MOD;
  std::cout << ans << std::endl;

  return 0;
}

