ll solve(int pos, int l1, int l2, int l3){

	if(pos == n)
		return 1ll;

	if(dp[pos][l1][l2][l3] != -1)
		return dp[pos][l1][l2][l3];

	ll ans = 0;

	for(int k = 0; k < 4; k++){
		if(!ok3(l2, l3, k))
			continue;
		if(!ok4(l1, l2, l3, k))
			continue;
		ans = (ans + solve(pos + 1, l2, l3, k)) % mod;
	}

	return dp[pos][l1][l2][l3] = ans;
}

