  for(int i=0;i<3;i++){
    string t = "";
    int j=0;
    while(j<4){
      if (i == j) {
        t += s[j+1];
        t += s[j];
        j += 2;
      } else {
        t += s[j];
        j += 1;
      }
    }
    if (t.find("AGC")!=string::npos) {
      return false;
    }
  }
  return true;
}
long dfs(char last[3], int cur) {
  if (cur == n) {
    return 1;
  }
  vector<char> key(last, last + 3);
  if (memo[cur].find(key) != memo[cur].end()) {
    return memo[cur][key];
  }
  int ret = 0;
  for(char c: {'A','G','C','T'}) {
    if(ok(last, c)) {
      char next_last[3] = {last[1], last[2], c};
      ret = (ret + dfs(next_last, cur+1)) % MOD;
    }
  }
  memo[cur][key] = ret;
  return ret;
}
