const string ng[] = {"AG*C", "*ACG", "*GAC", "A*GC", "*AGC"};
bool isNG(string s) {
    for (int i : range(5)) {
        bool ngCheck = true;
        for (int j : range(4)) {
            if (ng[i][j] == '*') continue;
            if (ng[i][j] != s[j]) {
                ngCheck = false;
            }
        }
        if (ngCheck) {
            if (n == 3) cerr << s << "is ng" << endl;
            return true;
        }
    }
    return false;
}

int main() {
    /* write here */
    // ng AG*C,*ACG, *GAC, A*GC

    cin >> n;
    map<string, ModInt> dp;
    for (char a : string("AGCT")) {
        for (char b : string("AGCT")) {
            for (char c : string("AGCT")) {
                dp["T" + string(1, a) + string(1, b) + string(1, c)] = 1;
                // cerr << "T" + string(1, a) + string(1, b) + string(1, c)
                //     << endl;
            }
        }
    }

    for (auto &it : dp) {
        if (isNG(it.first)) {
            it.second = 0;
        }
    }
    for (int i : range(n - 3)) {
        map<string, ModInt> nx;
        for (auto &it : dp) {
            for (char c : string("AGCT")) {
                nx[it.first.substr(1) + string(1, c)] += it.second;
            }
        }
        swap(dp, nx);
        for (auto &it : dp) {
            if (isNG(it.first)) {
                it.second = 0;
            }
        }
    }
    ModInt ret = 0;
    for (auto &it : dp) ret += it.second;
    cout << *ret << endl;
    return 0;
}

