const long mod=10e9+7;

long numbcha(char c){
    if(c=='A') return 0;
    if(c=='C') return 1;
    if(c=='G') return 2;
    if(c=='T') return 3;
}

long numberize(string S){//最後3桁を4進数に変換 
    int fir=numbcha(S.at(S.size()-3));
    int sec=numbcha(S.at(S.size()-2));
    int thi=numbcha(S.at(S.size()-1));
    return fir*16+sec*4+thi*1;
}

bool notC(long i){
    bool result=false;
    if(i/16 == numbcha('A') && (i%4 == numbcha('G') || (i/4)%4 == numbcha('G'))) result=true;
    if(i%4 == numbcha('A') && (i/4)%4 == numbcha('G')) result=true;
    if(i%4 == numbcha('G') && (i/4)%4 == numbcha('A')) result=true;
    return result;
}

bool notG(long i){
    bool result=false;
    if(i%4 == numbcha('C') && (i/4)%4 == numbcha('A')) result=true;
    return result;
}



//main関数
int main() {



    //入力
    int N;
    cin>>N;




    //計算
    vector<vector<long>> count(64, vector<long>(N+1));//0~2は無視
    for(int i=0;i<64;i++){
        count.at(i).at(3)=1;
    }
    count.at(numberize("AGC")).at(3)=0;
    count.at(numberize("ACG")).at(3)=0;
    count.at(numberize("GAC")).at(3)=0;

    for(int n=3;n<N;n++){
        for(int i=0;i<64;i++){
            count.at((i%16)*4+numbcha('A')).at(n+1)+=count.at(i).at(n);
            count.at((i%16)*4+numbcha('A')).at(n+1)%=mod;
            if(!notC(i)) count.at((i%16)*4+numbcha('C')).at(n+1)+=count.at(i).at(n);
            count.at((i%16)*4+numbcha('C')).at(n+1)%=mod;
            if(!notG(i)) count.at((i%16)*4+numbcha('G')).at(n+1)+=count.at(i).at(n);
            count.at((i%16)*4+numbcha('G')).at(n+1)%=mod;
            count.at((i%16)*4+numbcha('T')).at(n+1)+=count.at(i).at(n);
            count.at((i%16)*4+numbcha('T')).at(n+1)%=mod;
        }
    }

    long ans=0;

    for(int i=0;i<64;i++){
        ans+=count.at(i).at(N);
        ans%=mod;
    }


    //出力
    cout<<ans<<endl;
}

