    T
};

ll Solve(int pre1, int pre2, int pre3, int remain)
{
    if(remain == 0)
        return 1;

    ll& ret = cache[pre1][pre2][pre3][remain];
    if(ret != -1)
        return ret;

    ret = 0;

    for(int i = 1; i <= 4; i++)
    {
        if(pre2 == A && pre3 == G && i == C)
            continue;

        if(pre2 == G && pre3 == A && i == C)
            continue;

        if(pre2 == A && pre3 == C && i == G)
            continue;

        if(pre1 == A && pre3 == G && i == C)
            continue;

        if(pre1 == A && pre2 == G && i == C)
            continue;

        ret += Solve(pre2, pre3, i, remain-1);
        ret %= MOD;
    }

    return ret;
}

