bool check(const string& s){

  if(s.find("AGC") != string::npos) return false;

  int n = s.size();

  for(int i = 0; i < n-1; i++){
    string t = s;

    swap(t[i], t[i+1]);

    if(t.find("AGC") != string::npos) return false;
  }

  return true;

}

