int mod = int(1e+9) + 7;

int dp[101][4][4][4];

int main() {
  int n;
  cin >> n;

  // A: 0, G: 1, C: 2, T: 3

  // 長さ 0 の文字列は1である。
  // 0, 1, 2, に関する制約しかないので S は 333S と考えても問題がない
  dp[0][3][3][3] = 1;

  rep(len, n) {
    rep(i, 4) {      // 1つ前の文字について 0, 1, 2, 3 を全部
      rep(j, 4) {    // 2つ前の文字について 0, 1, 2, 3 を全部
        rep(k, 4) {  // 3つ前の文字について 0, 1, 2, 3 を全部
          if (dp[len][i][j][k] == 0) continue;
          // 新しく追加する文字列
          rep(a, 4) {
            if (a == 2 && i == 1 && j == 0) continue;  // AGC
            if (a == 2 && i == 0 && j == 1) continue;  // GAC
            if (a == 1 && i == 2 && j == 0) continue;  // ACG
            if (a == 2 && i == 1 && k == 0) continue;  // A*GC
            if (a == 2 && j == 1 && k == 0) continue;  // AG*C

            dp[len+1][a][i][j] += dp[len][i][j][k];
            dp[len+1][a][i][j] %= mod;
          }
        }
      }
    }
  }

  int ans = 0;
  rep(i, 4) {
    rep(j, 4) {
      rep(k, 4) {
        ans += dp[n][i][j][k];
        ans %= mod;
      }
    }
  }

  cout << ans << endl;

