#define mod 1000000007
using ll = long long;

ll DP[101][5][5][5]; // 先に宣言すれば0で初期化

int main() {
    int N;
    cin >> N;

    string S = " ACGT"; // バグ回避の特効薬

    DP[0][0][0][0] = 1;
    for (int i = 0; i < N; ++i) {
        // 1番外側のforループだけ別格
        for (int j = 0; j < 5; ++j) {
            for (int k = 0; k < 5; ++k) {
                for (int l = 0; l < 5; ++l) {
                    // DP[i][j][k][l] に対してDP[i+1][][][]を計算
                    for (int m = 1; m < 5; ++m) {
                        if(S[k] == 'A' && S[l] == 'G' && S[m] == 'C') continue;
                        if(S[j] == 'A' && S[k] == 'G' && S[m] == 'C') continue;
                        if(S[j] == 'A' && S[l] == 'G' && S[m] == 'C') continue;

                        if(S[k] == 'G' && S[l] == 'A' && S[m] == 'C') continue;
                        if(S[k] == 'A' && S[l] == 'C' && S[m] == 'G') continue;

                        DP[i+1][k][l][m] += DP[i][j][k][l];
                        DP[i+1][k][l][m] %= mod;
                    }
                }
            }
        }
    }

    ll ans = 0;
    for (int i = 0; i < 5; ++i) {
        for (int j = 0; j < 5; ++j) {
            for (int k = 0; k < 5; ++k) {
                ans += DP[N][i][j][k];
                ans %= mod;
            }
        }
    }
    cout << ans;
    return 0;
}

