int n;
bool visited[5][5][5][110];
mint memo[5][5][5][110];
mint solve(int ppp, int pp, int p, int pos) {
  mint &res = memo[ppp][pp][p][pos];
  if(!visited[ppp][pp][p][pos]) {
    visited[ppp][pp][p][pos] = true;
    if(pos == n) {
      res = 1;
    } else {
      res = 0;
      REP(c, 4) {
        if(isOK(BASE[ppp], BASE[pp], BASE[p], BASE[c])) {
          res += solve(pp, p, c, pos+1);
        }
      }
    }
  }
  return res;
}

