// NG ケース一覧
enum Char {
	A,
	G,
	C,
	T
};

bool is_ok(int val[4])
{
	// NG ケースは A_GC, AG_C, GAC, ACG, AGC
	if (val[0] == A && val[2] == G && val[3] == C) return false;
	if (val[0] == A && val[1] == G && val[3] == C) return false;
	if (val[0] == G && val[1] == A && val[2] == C) return false;
	if (val[1] == G && val[2] == A && val[3] == C) return false;
	if (val[0] == A && val[1] == C && val[2] == G) return false;
	if (val[1] == A && val[2] == C && val[3] == G) return false;
	if (val[0] == A && val[1] == G && val[2] == C) return false;
	if (val[1] == A && val[2] == G && val[3] == C) return false;

	return true;
}

void dp_progress(vector<uint64_t[4][4][4]>& dp, int i, int j, int k, int m)
{
	uint64_t val = 0;
	for (int h = 0; h < 4; h++) {
		int sel[4] = { h, i, j, k };
		if (!is_ok(sel)) continue;

		val += dp[m-1][h][i][j];
	}

	dp[m][i][j][k] = val % kRem;
}

int main()
{
	int n; cin >> n;

	// 4 次元 DP
	vector<uint64_t[4][4][4]> dp(n + 1); // 1 origin

	// 初期化
	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			for (int k = 0; k < 4; k++) {
				dp[3][i][j][k] = 1;
			}
		}
	}
	// AGC, GAC, ACG のみ不可
	dp[3][A][G][C] = 0;
	dp[3][G][A][C] = 0;
	dp[3][A][C][G] = 0;

	// 4 - n DP
	for (int m = 4; m <= n; m++) {
		for (int i = 0; i < 4; i++) {
			for (int j = 0; j < 4; j++) {
				for (int k = 0; k < 4; k++) {
					dp_progress(dp, i, j, k, m);
				}
			}
		}
	}

	// 最終結果
	uint64_t val = 0;
	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			for (int k = 0; k < 4; k++) {
				val += dp[n][i][j][k];
			}
		}
	}
	cout << (val %= kRem) << endl;

	return 0;
}

