#include <bits/stdc++.h>
using namespace std;
#define ll long long 

const ll mod=1e9+7;

ll dp[1000][5][5][5]{0};
ll n;
bool cc(ll a,ll b,ll c,ll d){
    if(b==0 && c==1 && d==2) return false;
    if(b==0 && d==1 && c==2) return false;
    if(a==0 && c==1 && d==2) return false;
    if(c==0 && b==1 && d==2) return false;
    if(a==0 && b==1 && d==2) return false;
    return true;
}

ll solve(ll i,ll a,ll b,ll c){
    // Base Case
    if(i==n){
        return 1;
    }

    if(dp[i][a][b][c]!=-1){
        return dp[i][a][b][c];
    }

    // Rec Case

    ll ans=0;

    // At ith index , s[i]='A'
    if(cc(a,b,c,0))
        ans+=solve(i+1,b,c,0);
        ans%=mod;
    // At ith index , s[i]='G'
    if(cc(a,b,c,1)){
        ans+=solve(i+1,b,c,1);
        ans%=mod;
    }
    // At ith index , s[i]='C'
    // (i) (c,b)==G (ii)(a,b)==A
    if(cc(a,b,c,2)){
        ans+=solve(i+1,b,c,2);
        ans%=mod;
    }
    // At ith index , s[i]='T'
    if(cc(a,b,c,3))
        ans+=solve(i+1,b,c,3);
        ans%=mod;
    return dp[i][a][b][c]=ans;

}   


int main() {


    cin>>n;
    memset(dp,-1,sizeof(dp));
    ll ans=(solve(0,4,4,4))%mod;
    ans%=mod;

    cout<<ans<<endl;

}

