#include <iostream>
using namespace std;

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N;
    const int mod = 1e9 + 7;

    int dp[101][4][4][4] = {0};

    // 1文字目は前に3つTがある "TTT*" とみなして問題ない。
    // dp[0][3][3][3]は、長さ0の文字列のうち、
    // 最後から3番目の文字が3(T), 最後から2番目の文字が3(T),
    // 最後から1番目の文字が3(T)である個数を表す。
    dp[0][3][3][3] = 1;

    for (int len = 0; len < N; len++)
    {
        for (int i = 0; i < 4; i++)
        {
            for (int j = 0; j < 4; j++)
            {
                for (int k = 0; k < 4; k++)
                {
                    // 条件に当てはまるものがなければcontinue
                    if (dp[len][i][j][k] == 0)
                    {
                        continue;
                    }

                    // 新しく文字を追加
                    for (int a = 0; a < 4; a++)
                    {
                        if (j == 0 && i == 1 && a == 2)
                        {
                            continue;
                        }
                        if (j == 0 && i == 2 && a == 1)
                        {
                            continue;
                        }
                        if (j == 1 && i == 0 && a == 2)
                        {
                            continue;
                        }
                        if (k == 0 && i == 1 && a == 2)
                        {
                            continue;
                        }
                        if (k == 0 && j == 1 && a == 2)
                        {
                            continue;
                        }

                        dp[len + 1][a][i][j] += dp[len][i][j][k];
                        dp[len + 1][a][i][j] %= mod;
                    }
                }
            }
        }
    }

    int ans = 0;
    for (int i = 0; i < 4; i++)
    {
        for (int j = 0; j < 4; j++)
        {
            for (int k = 0; k < 4; k++)
            {
                ans += dp[N][i][j][k];
                ans %= mod;
            }
        }
    }
    cout << ans << endl;

    return 0;
}

