int mod = 1000000007;
struct acgt{
    int ans[4][4][4];

    int sum(){
        int result;
        loop(i,4){
            loop(j,4){
                loop(k,4){
                    if(i == 2 && j == 0 && k == 1) continue;
                    if(i == 0 && j == 1 && k == 2) continue;
                    if(i == 0 && j == 2 && k == 1) continue;
                    result += ans[i][j][k];
                    result %= mod;
                }
            }
        }

        return result;
    };
};


acgt three(){
    acgt tmp = acgt();
    loop(i,4){
        loop(j,4){
            loop(k,4){
                if(i == 2 && j == 0 && k == 1) continue;
                if(i == 0 && j == 1 && k == 2) continue;
                if(i == 0 && j == 2 && k == 1) continue;
                tmp.ans[i][j][k] = 1;
            }
        }
    }

    return tmp;
}

acgt dp(acgt prev){
    acgt newAcgt = acgt();
    loop(i,4){
        loop(j,4){
            loop(k,4){
                loop(l,4){
                    if(j == 2 && k == 0 && l == 1) continue;
                    if(j == 0 && k == 1 && l == 2) continue;
                    if(j == 0 && k == 2 && l == 1) continue;
                    if(i == 0 && j == 2 && l == 1) continue;
                    if(i == 0 && k == 2 && l == 1) continue;
                    newAcgt.ans[j][k][l] += prev.ans[i][j][k];
                    newAcgt.ans[j][k][l] %= mod;
                }
            }
        }
    }
    return newAcgt;
}

