string toStr(int n) {
  string s;
  for (int i = 0; i < 3; i++) {
    if (n % 4 == 0) {
      s = 'A' + s;
    } else if (n % 4 == 1) {
      s = 'C' + s;
    } else if (n % 4 == 2) {
      s = 'G' + s;
    } else {
      s = 'T' + s;
    }
    n /= 4;
  }

  return s;
}

int main() {
  int N;
  cin >> N;

  vector<vector<long long> > count(N, vector<long long>(64));
  for (int i = 0; i < 64; i++) {
    string s = toStr(i);
    if (s == "AGC" || s == "ACG" || s == "GAC") {
      count[2][i] = 0;
    } else {
      count[2][i] = 1;
    }
  }

  for (int i = 3; i < N; i++) {
    for (int j = 0; j < 64; j++) {
      string s = toStr(j);
      for (int k = 0; k < 64; k++) {
        string ts = toStr(k);
        if (ts[1] == s[0] && ts[2] == s[1]) {
          string temp = ts + s[2];
          if ((temp[0] == 'A' && temp[1] == 'G' && (temp[2] == 'C' || temp[3] == 'C')) ||
              ((temp[0] == 'A' || temp[1] == 'A') && temp[2] == 'G' && temp[3] == 'C') ||
              (temp[0] == 'A' && temp[1] == 'C' && temp[2] == 'G') ||
              (temp[0] == 'G' && temp[1] == 'A' && temp[2] == 'C') ||
              (temp[1] == 'A' && temp[2] == 'C' && temp[3] == 'G') ||
              (temp[1] == 'G' && temp[2] == 'A' && temp[3] == 'C')
             ) {
            continue;
          } else {
            count[i][j] = (count[i][j] + count[i - 1][k]) % mod;
          }
        }
      }
    }
  }

  long long ans = 0;
  for (int i = 0; i < 64; i++) {
    ans = (ans + count[N - 1][i]) % mod;
  }

  cout << ans << endl;

  return 0;
}

