#include <bits/stdc++.h>
using namespace std;
vector<long long> fac;
vector<long long> fac_inv;
vector<long long> inv;

void init_combination(long long n, long long mod)
{
	fac.resize(n+1);
	fac_inv.resize(n+1);
	inv.resize(n+1);
	fac[0] = 1;
	fac[1] = 1;
	fac_inv[0] = 1;
	fac_inv[1] = 1;
	inv[1] = 1;
	for (long long i = 2; i <= n; i++) {
		fac[i] = fac[i-1]*i%mod;
		inv[i] = mod - (inv[mod%i] * (mod / i)) % mod;
		fac_inv[i] = fac_inv[i-1] * inv[i] % mod;
	}
}
long long modpow(long long x, long long y, long long mod)
{
	long long result = 1;
	while (y != 0) {
		if (y%2 != 0) {
			result *= x;
			result %= mod;
			y -= 1;
		}	
		x *= x;
		x %= mod;
		y /= 2;
	}
	return result;
}


int main(void)
{
	int n;
	cin >> n;
	long long p = (long long)1e9 + 7;
	long long d[n][4][4][4];
	const int A = 0, C = 1, G = 2, T = 3;
	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			for (int k = 0; k < 4; k++) {
				d[0][i][j][k] = 0;
				d[1][i][j][k] = 0;
				if (i == A && j == G && k == C)
					d[2][i][j][k] = 0;
				else if (i == G && j == A && k == C)
					d[2][i][j][k] = 0;
				else if (i == A && j == C && k == G)
					d[2][i][j][k] = 0;
				else
					d[2][i][j][k] = 1;
			}
		}
	}
	for (int i = 3; i < n; i++) {
		for (int j = 0; j < 4; j++) {
			for (int k = 0; k < 4; k++) {
				for (int l = 0; l < 4; l++) {
					d[i][j][k][l] = 0;
					if (j == A && k == G && l == C)
						continue;
					if (j == G && k == A && l == C)
						continue;
					if (j == A && k == C && l == G)
