					for (int m = 0; m < 4; m++) {
						if ((m == A && k == G && l == C) ||
								(m == A && j == G && l == C)) {
							continue;
						}
						d[i][j][k][l] += d[i-1][m][j][k];
						d[i][j][k][l] %= p;
					}
				}
