using namespace std;
const int mod = 1000000007;
const string cand = "ATGC";
bool valid(string last) {
	if (last.size() < 3) return true;
	if (last.find("AGC") != string::npos) return false;
	for (int i = 1; i < last.size(); ++i) {
		swap(last[i - 1], last[i]);
		if (last.find("AGC") != string::npos) return false;
		swap(last[i - 1], last[i]);
	}
	return true;
}
map<string, bool> vis[109];
map<string, int> dp[109];
int solve(int limit, string last) {
	if (limit == 0) {
		return 1;
	}
	if (vis[limit][last]) return dp[limit][last];
	int ans = 0;
	for (int i = 0; i < 4; ++i) {
		string nxt = last + cand[i];
		if (nxt.size() >= 5) nxt = nxt.substr(1);
		if (valid(nxt)) {
			ans += solve(limit - 1, nxt);
			if (ans >= mod) ans -= mod;
		}
	}
	vis[limit][last] = true;
	dp[limit][last] = ans;
	return ans;
}
int main() {
	int n;
	cin >> n;
	int ans = solve(n, string());
	cout << ans << endl;
	return 0;
}

