    for(int j : string("AGCT")) {
      for(int k = 0; k < dp.size(); k++) {
        if(dp[k]) {
          int c = k;
          if(aho.move(j, c)) continue;
          dp2[c] += dp[k];
          dp2[c] %= mod;
        }
      }
    }
    dp.swap(dp2);
  }

  cout << accumulate(begin(dp), end(dp), 0LL) % mod << endl;
}

