bool is_ok(string s)
{
	return s != out[0] and s != out[1] and s != out[2];
}

void f(string s, int d)
{
	if (d == 3) {
		pattern.push_back(s);
		return;
	}

	rep(i, S.size()) {
		f(s + S[i], d + 1);
	}
}

bool check(string s)
{
	string tmp = s;
	rep(i, 3) {
		swap(tmp[i], tmp[i+1]);
		if (tmp.substr(0, 3) == "AGC" or tmp.substr(1, 3) == "AGC") {
			return false;
		}
		swap(tmp[i], tmp[i+1]);
	}

	return true;
}

