	f("", 0);

	for (string &s : pattern) {
		if (is_ok(s)) {
			dp[3][s] = 1;
		}
	}

	for (int i = 4; i <= N; ++i) {
		for (string &s : pattern) {
			if (!is_ok(s)) continue;
			for (string &t : pattern) {
				if (!is_ok(t)) continue;

				if (s[0] != t[1] or s[1] != t[2]) continue;

