#include <bits/stdc++.h>

using namespace std;

constexpr int64_t mod = INT64_C(1000000007);

using acgt_t = std::array<std::array<std::array<int64_t, 4>, 4>, 4>;

int64_t solve(int n) {
  acgt_t acgt{};
  for (int i = 0; i < 4; ++i) {
    for (int j = 0; j < 4; ++j) {
      for (int k = 0; k < 4; ++k) {
        if (i == 0 && j == 1 && k == 2) {
          continue;
        }
        if (i == 0 && j == 2 && k == 1) {
          continue;
        }
        if (i == 2 && j == 0 && k == 1) {
          continue;
        }
        acgt[i][j][k] = 1;
      }
    }
  }

  //

  for (int nn = 4; nn <= n; ++nn) {
    acgt_t next{};
    for (int i = 0; i < 4; ++i) {
      for (int j = 0; j < 4; ++j) {
        for (int k = 0; k < 4; ++k) {
          int64_t const value = acgt[i][j][k];
          if ((i == 0 & j == 0 & k == 2) || (i == 0 & j == 2 & k == 0) ||
              (i == 0 & j == 2 & k == 2) || (i == 0 & j == 2 & k == 3) ||
              (i == 0 & j == 3 & k == 2) || (i == 1 & j == 0 & k == 2) ||
              (i == 1 & j == 2 & k == 0) || (i == 2 & j == 0 & k == 2) ||
              (i == 2 & j == 2 & k == 0) || (i == 3 & j == 0 & k == 2) ||
              (i == 3 & j == 2 & k == 0)) {
            //  0021
            //  0201
            //  0221
            //  0231
            //  0321
            //  1021
            //  1201
            //  2021
            //  2201
            //  3021
            //  3201
            next[j][k][0] += value;
            next[j][k][2] += value;
            next[j][k][3] += value;
            next[j][k][0] %= mod;
            next[j][k][2] %= mod;
            next[j][k][3] %= mod;
          } else if ((i == 0 & j == 0 & k == 1) || (i == 1 & j == 0 & k == 1) ||
                     (i == 3 & j == 0 & k == 1)) {
            //  0012
            //  1012
            //  3012
            next[j][k][0] += value;
            next[j][k][1] += value;
            next[j][k][3] += value;
            next[j][k][0] %= mod;
            next[j][k][1] %= mod;
            next[j][k][3] %= mod;
          } else {
            next[j][k][0] += value;
            next[j][k][1] += value;
            next[j][k][2] += value;
            next[j][k][3] += value;
            next[j][k][0] %= mod;
            next[j][k][1] %= mod;
            next[j][k][2] %= mod;
            next[j][k][3] %= mod;
          }
        }
      }
    }
    acgt = next;
  }

  int64_t ret = 0;
  for (int i = 0; i < 4; ++i) {
    for (int j = 0; j < 4; ++j) {
      for (int k = 0; k < 4; ++k) {
        ret += acgt[i][j][k];
        ret %= mod;
      }
    }
  }
  return ret;
}

int main() {
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);
  int n;
  std::cin >> n;
  std::cout << solve(n) << std::endl;
  return 0;
}

