    if(cm[a] + cm[b] + cm[d] == "AGC") { return 0; }
    if(cm[a] + cm[c] + cm[d] == "AGC") { return 0; }
    if(cm[a] + cm[c] + cm[b] == "AGC") { return 0; }
    if(cm[b] + cm[a] + cm[c] == "AGC") { return 0; }
    if(cm[b] + cm[c] + cm[d] == "AGC") { return 0; }
    if(cm[b] + cm[d] + cm[c] == "AGC") { return 0; }
    if(cm[c] + cm[b] + cm[d] == "AGC") { return 0; }
