#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef pair<ll, string> pls;

const ll N = 50 + 3;
const ll M = 1e9 + 7;
const vector<string> S = {"A", "C", "G", "T"};

ll n;
unordered_set<string> violated;
map<pls, ll> mp;

void init() {
	for (string x: S) {
		violated.insert("AGC");
		violated.insert("GAC");
		violated.insert("ACG");
		violated.insert(x + "AGC");
		violated.insert(x + "GAC");
		violated.insert(x + "ACG");
		violated.insert("AGC" + x);
		violated.insert("GAC" + x);
		violated.insert("ACG" + x);
		violated.insert("A" + x + "GC");	
		violated.insert("AG" + x + "C");
	}
}

ll dfs(ll v, string s) {
	if (mp.count({v, s})) return mp[{v, s}];
	if (v == n) return 1;

	ll r = 0;
	for (string x : S) {
		x = s + x;
		if (!violated.count(x)) {
			x.erase(0, 1);
			r = (r + dfs(v + 1, x)) % M;
		}
	}

	return mp[{v, s}] = r;
}

int main() {
	ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);

	init();
	cin >> n;
	cout << dfs(0, "TTT");

	return 0;
}

