            add(dp[i][b][c][d], dp[i-1][a][b][c]);
          }
        }
      }
    }
  }
  int ans = 0;
  for(int i = 0; i < 4; i++){
    for(int j = 0; j < 4; j++){
      for(int k = 0; k < 4; k++){
        add(ans, dp[n][i][j][k]);
      }
    }
  }
  cout << ans << endl;
}

