/*
 * A - 0, C - 1, G - 2, T - 3
 * banned: *AGC AG*C A*GC *ACG *GAC
 */
enum { A = 0, C, G, T, };
int dfs(int pos, int stat)
{
    if (pos > n)
        return 1;
    if (dp[pos][stat] != -1)
        return dp[pos][stat];
    //echo("%d%d%d%d\n", get(stat, 0), get(stat, 1), get(stat, 2), A);
    //echo("%d%d%d%d\n", get(stat, 0), get(stat, 1), get(stat, 2), T);
    dp[pos][stat] = (dfs(pos + 1, comb(get(stat, 1), get(stat, 2), A))
        + dfs(pos + 1, comb(get(stat, 1), get(stat, 2), T))) % Mod;
    // Verify 'C'
    if ((get(stat, 1) == A && get(stat, 2) == G) ||  // *AGC
            (get(stat, 1) == G && get(stat, 2) == A) ||  // *GAC
            (get(stat, 0) == A && get(stat, 1) == G) ||  // AG*C
            (get(stat, 0) == A && get(stat, 2) == G))
        ;
    else
    {
        //echo("%d%d%d%d\n", get(stat, 0), get(stat, 1), get(stat, 2), C);
        dp[pos][stat] = (dp[pos][stat]
                + dfs(pos + 1, comb(get(stat, 1), get(stat, 2), C))) % Mod;
    }
    // Verify 'G'
    if (get(stat, 1) == A && get(stat, 2) == C)
        ;
    else
    {
        dp[pos][stat] = (dp[pos][stat]
                + dfs(pos + 1, comb(get(stat, 1), get(stat, 2), G))) % Mod;
        //echo("%d%d%d%d\n", get(stat, 0), get(stat, 1), get(stat, 2), G);
    }
    return dp[pos][stat];
}

