const ll mod = 1e9 + 7;
int N;
ll dp[1 << 6][110];
int GAC = 1 + (1 << 5);
int ACG = (1 << 3) + (1 << 4);
int AGC = (1 << 2) + (1 << 5);
int AXG = 1 << 4;
int AGX = 1 << 2;
int mask1 = (1 << 6) - 1 - (3 << 2);
int mask2 = (1 << 6) - 1 - (3 << 4);
int main(){

    cin >> N;
    for(int i = 0; i < 4; i++){
        dp[i << 4][1] = 1;
    }
    for(int i = 1; i <= N; i++){
        if(i < 3){
            for(int j = 0; j < (1 << 6); j++){
                for(int k = 0; k < 4; k++){ 
                    dp[(j >> 2) + (k << 4)][i + 1] += dp[j][i];
                    dp[(j >> 2) + (k << 4)][i + 1] %= mod;

                }
            }    
        }else{
            dp[GAC][i] = 0;
            dp[ACG][i] = 0;
            dp[AGC][i] = 0;
            for(int j = 0; j < (1 << 6); j++){
                for(int k = 0; k < 4; k++){
                    if(k == 2 && (j & mask1) == AXG) continue;
                    if(k == 2 && (j & mask2) == AGX) continue;
                    dp[(j >> 2) + (k << 4)][i + 1] += dp[j][i];
                    dp[(j >> 2) + (k << 4)][i + 1] %= mod;
                }
            }
        }
    }
    ll ans = 0;
    for(int i = 0; i < (1 << 6); i++){
        ans += dp[i][N];
        ans %= mod;
    }
    cout << ans << endl;
    return 0;
}

