static const ll MOD = 1e9 + 7;

bool judge(string s) {
  string t = s.substr(s.size() - 4);
  if(t[1] == 'A' && t[2] == 'G' && t[3] == 'C') return false;
  if(t[1] == 'G' && t[2] == 'A' && t[3] == 'C') return false;
  if(t[1] == 'A' && t[2] == 'C' && t[3] == 'G') return false;
  if(t[0] == 'A' && t[2] == 'G' && t[3] == 'C') return false;
  if(t[0] == 'A' && t[1] == 'G' && t[3] == 'C') return false;
  return true;
}

map<pair<int, string>, ll> mp;

ll dfs(int i, int n, string s) {
  if(i == n) return judge(s);
  string t = s.substr(s.size() - 3);
  ll ret = 0;
  if(judge(t + "A")){
    if(mp[make_pair(i + 1, t + "A")]) ret += mp[make_pair(i + 1, t + "A")];
    else{
      mp[make_pair(i + 1, t + "A")] = dfs(i + 1, n, t + "A");
      ret += mp[make_pair(i + 1, t + "A")];
    }
  }
  if(judge(t + "G")){
    if(mp[make_pair(i + 1, t + "G")]) ret += mp[make_pair(i + 1, t + "G")];
    else{
      mp[make_pair(i + 1, t + "G")] = dfs(i + 1, n, t + "G");
      ret += mp[make_pair(i + 1, t + "G")];
    }
  }
  if(judge(t + "C")){
    if(mp[make_pair(i + 1, t + "C")]) ret += mp[make_pair(i + 1, t + "C")];
    else{
      mp[make_pair(i + 1, t + "C")] = dfs(i + 1, n, t + "C");
      ret += mp[make_pair(i + 1, t + "C")];
    }
  }
  if(judge(t + "T")){
    if(mp[make_pair(i + 1, t + "T")]) ret += mp[make_pair(i + 1, t + "T")];
    else{
      mp[make_pair(i + 1, t + "T")] = dfs(i + 1, n, t + "T");
      ret += mp[make_pair(i + 1, t + "T")];
    }
  }
  return ret % MOD;
}

