    constexpr auto idx = [](int i1, int i2, int i3) { return 4 * 4 * i1 + 4 * i2 + i3; };

    vc<vc<mint>> dp(n, vc<mint>(4 * 4 * 4, 0));
    REP(ch, 0, 4) dp[0][idx(t, t, ch)] = 1;
    REP(i, 1, n) {
        REP(j, 0, 4) REP(k, 0, 4) REP(l, 0, 4) REP(m, 0, 4) {
