            if (idx(j, l, m) == idx(a, g, c) || idx(j, k, m) == idx(a, g, c)) continue;
            dp[i][ni] += dp[i - 1][idx(j, k, l)];
        }
    }
    cout << accumulate(ALL(dp[n - 1]), mint(0)) << endl;
}

