}

bool check(string s) {
	bool bad = !ok(s);
	for (int i = 0; i < s.size() - 1; ++i) {
		swap(s[i], s[i + 1]);
		bad = bad | (!ok(s));
		swap(s[i], s[i + 1]);
	}
	return !bad;
}

