int main() {
	int N;
	cin >> N;
	ll dp[110][4][4][4];
	//dp[N][i][j][k]でN文字目まで確定していてN-2文字目がi,N-1文字目がj,N文字目がk
	//Aなら0,Cなら1,Gなら2,Tなら3
	for (int i = 0; i < 110; ++i) {
		for (int j = 0; j < 4; ++j) {
			for (int k = 0; k < 4; ++k) {
				for (int l = 0; l < 4; ++l) {
						dp[i][j][k][l] = 0;
				}
			}
		}
	}
	for (int i = 0; i < 4; ++i) {
		for (int j = 0; j < 4; ++j) {
			for (int k = 0; k < 4; ++k) {
				if ((i == 0 && j == 2 && k == 1) || (i == 0 && j == 1 && k == 2) || (i == 2 && j == 0 && k == 1)) {
					continue;
				}
				dp[3][i][j][k] = 1;
			}
		}
	}
	for (int i = 3; i < 110; ++i) {
		for (int j = 0; j < 4; ++j) {
			for (int k = 0; k < 4; ++k) {
				for (int l = 0; l < 4; ++l) {
					for (int m = 0; m < 4; ++m) {
						if (j == 0 && k == 2 && l == 1)continue;
						if (j == 2 && k == 0 && l == 1)continue;
						if (j == 0 && k == 1 && l == 2)continue;
						if (m == 0 && k == 2 && l == 1)continue;
						if (m == 0 && j == 2 && l == 1)continue;
						dp[i + 1][j][k][l] += dp[i][m][j][k];
						dp[i + 1][j][k][l] %= INF;
					}
				}
			}
		}
	}
	ll ans = 0;
	for (int i = 0; i < 4; ++i) {
		for (int j = 0; j < 4; ++j) {
			for (int k = 0; k < 4; ++k) {
				ans += dp[N][i][j][k];
			}
		}
	}
	cout << ans % INF << endl;
	return 0;
}

