//約数
std::vector<int> divisor(int n) {
	std::vector<int> ret;
	for (int i = 1; i * i <= n; ++i) {
		if (n % i == 0) {
			ret.push_back(i);
			if (i * i != n) {
				ret.push_back(n / i);
			}
		}
	}
	return ret;
}

//素数判定
bool isPrime(int n) {
	if (n <= 1)return false;
	if (n == 2)return true;
	if (n % 2 == 0)return false;
	for (int i = 3; i * i <= n; i += 2) {
		if (n % i == 0)return false;
	}
	return true;
}

//素因数分解
std::map<int, int> primeFactorization(int n) {
	std::map<int, int> res;
	int k = 2;
	while (k * k <= n) {
		while (n % k == 0) {
			res[k]++;
			n /= k;
		}
		++k;
	}
	if (n != 1) {
		res[n]++;
	}
	return res;
}



//二項係数(N<=10^6,O(NlogN))、int128は使わなく64で十分
class Combination {
	std::vector<long long>fac, finv, inv;
	long long M;		//剰余
public:
	Combination(long long N, long long M_ = MOD)
		:fac(N + 1), finv(N + 1), inv(N + 1), M(M_) {
		fac[0] = fac[1] = 1;
		finv[0] = finv[1] = 1;
		inv[1] = 1;
		for (long long i = 2; i < N + 1; i++) {
			fac[i] = fac[i - 1] * i % M;
			inv[i] = M - inv[M % i] * (M / i) % M;
			finv[i] = finv[i - 1] * inv[i] % M;
		}
	}
	long long get(long long n, long long k) {
		if (n < k) return 0;
		if (n < 0 || k < 0) return 0;
		return fac[n] * (finv[k] * finv[n - k] % M) % M;
	}
	long long factrial(int n) {
		return fac[n];
	}
};

