		for (int i = 0; i < com.size(); ++i) {
			com[i].resize(i + 1);
			for (int j = 0; j < i + 1; ++j) {
				if (j == 0 || i == j) {
					com[i][j] = 1;
				}
				else {
					com[i][j] = com[i - 1][j] + com[i - 1][j - 1];
				}
			}
		}
	}
public:
