            else if(k==0 && j==1 && l==2) continue;
            else if(k==0 && i==1 && l==2) continue;
            dp[len+1][l][i][j] += dp[len][i][j][k];
            dp[len+1][l][i][j] %= mod;
          }
        }
      }
    }
  }
  ll ans=0;
  rep(i, 4){
      rep(j, 4){
        rep(k, 4){
          if(dp[N][i][j][k]==0) continue;
          ans += dp[N][i][j][k];
          ans %= mod;
        }
      }
  }
  cout << ans << endl;

}

