ll power(int x, int n){
  ll v=1;
  while(n>=1){
    if(n&1){
      (v*=x)%=mod;
    }
    n=n>>1;
    x=(x*x)%mod;
  }
  return v;
}


bool is_bad(int a, int b, int c, int d){
  if(      b==1&&c==2&&d==3){return true;}
  if(      b==1&&c==3&&d==2){return true;}
  if(      b==2&&c==1&&d==3){return true;}
  if(a==1&&      c==2&&d==3){return true;}
  if(a==1&&b==2&&      d==3){return true;}
  return false;
}


ll solve(int N){
  ll dp[N+1][256][2];
  dp[0][0][0]=1;
  dp[0][0][1]=0;

  for (int i=0;i<N+1;i++){
    for (int a=0;a<4;++a) for(int b=0;b<4;++b) for(int c=0;c<4;++c) for (int d=0;d<4;++d){
      abcd=((a*4+b)*4+c)*4+d;
      for (int e=0;e<4;++e){
        bcde=((b*4+c)*4+d)*4+e;
        bad_=is_bad(b,c,d,e);
        for (int j=0;j<2;++j){
          dp[i+1][bcde][bad_|j]+=dp[i][abcd][j];
        }
      }
    }
  }

  ll ans=0;
  for (int i=0;i<256;i++){
    ans+=dp[N][i][1];
  }
  ans=(power(4,N)-ans+mod)%mod;
  return ans;
}

