    i64 N;
    cin >> N;

    vector<char> sym={'A','C','G','T'};

    vector<map<string,i64>> memo(N+1);
    vector<map<string,bool>> done(N+1);
    function<i64(i64,string)> rec=[&](i64 i,string s){
        auto& res=memo[i][s];
        if(done[i][s]) return res;
        done[i][s]=true;
        if(i==N){
            return res=i64(1);
