    for (int i = 4; i <= N; i++) {
        for (int h = 0; h < 64; h++) { // e1 e2 e3
            for (int k = 0; k < 4; k++) { // new
                int e1 = h / 16;
                int e2 = (h % 16) / 4;
                int e3 = h % 4;

                // pattern = '*AC'
                if (e2 == ehash('A') && e3 == ehash('C') && k == ehash('G')) continue;
                // pattern = '*GA'
                if (e2 == ehash('G') && e3 == ehash('A') && k == ehash('C')) continue;
                // pattern = '*AG'
                if (e2 == ehash('A') && e3 == ehash('G') && k == ehash('C')) continue;
                // pattern = 'AG*'
                if (e1 == ehash('A') && e2 == ehash('G') && k == ehash('C')) continue;
                // pattern = 'A*G'
                if (e1 == ehash('A') && e3 == ehash('G') && k == ehash('C')) continue;

                dp[i][e2][e3][k] = (dp[i][e2][e3][k] + dp[i - 1][e1][e2][e3]) % LARGE_NUM;
            }
        }
    }

    lli ans = 0LL;
    for (int h = 0; h < 64; h++) { // e1 e2 e3
        int e1 = h / 16;
        int e2 = (h % 16) / 4;
        int e3 = h % 4;
        ans = (ans + dp[N][e1][e2][e3]) % LARGE_NUM;
    }
    cout << ans << endl;
    return 0;
}

