ll count(string str, ll depth) {
  //手前三文字から次の一文字を決める
  if (table[depth].find(str) != table[depth].end()) {
    return table[depth][str];
  }
  ll ret = 0;
  string sub = str.substr(1, 2);

  if (depth == N) {
    return 1;
  }

  if (str == "AGT" || 
      str == "AGG" || 
      str == "ATG" || 
      str == "AAG" || 
      str == "TAG" || 
      str == "GAG" || 
      str == "CAG" || 
      str == "AGA" ||
      str == "TGA" ||
      str == "GGA" ||
      str == "CGA") {
    ret += count(sub+"A", depth+1);
    ret %= MOD;
    ret += count(sub+"T", depth+1);
    ret %= MOD;
    ret += count(sub+"G", depth+1);
    ret %= MOD;
  } else if (
      str == "AAC" ||
      str == "TAC" ||
      str == "GAC" ||
      str == "CAC") {
    ret += count(sub+"A", depth+1);
    ret %= MOD;
    ret += count(sub+"T", depth+1);
    ret %= MOD;
    ret += count(sub+"C", depth+1);
    ret %= MOD;
  } else {
    ret += count(sub+"A", depth+1);
    ret %= MOD;
    ret += count(sub+"T", depth+1);
    ret %= MOD;
    ret += count(sub+"G", depth+1);
    ret %= MOD;
    ret += count(sub+"C", depth+1);
    ret %= MOD;
  }
  table[depth][str] = ret;
  return ret;
}

