#include <bits/stdc++.h>
using namespace std;

typedef enum{A=0, C=1, G=2, T=3} ACGT;

int memo[100][4][4][4];

bool good(ACGT last4[])
{
  ACGT c0 = last4[0];
  ACGT c1 = last4[1];
  ACGT c2 = last4[2];
  ACGT c3 = last4[3];

  // AGC
  if ((c0 == A && c1 == G && c2 == C) ||
      (c1 == A && c2 == G && c3 == C)){ return false; }

  // GAC
  if ((c0 == G && c1 == A && c2 == C) ||
      (c1 == G && c2 == A && c3 == C)){ return false; }

  // ACG
  if ((c0 == A && c1 == C && c2 == G) ||
      (c1 == A && c2 == C && c3 == G)){ return false; }

  // A?GC || AG?C
  if ((c0 == A && c2 == G && c3 == C) ||
      (c0 == A && c1 == G && c3 == C)){ return false; }

  return true;
}

long search(int n, const ACGT last3[])
{
  const long M = 1000000007ULL;
  ACGT a[4] = {A, C, G, T};

  long ret = memo[n][last3[0]][last3[1]][last3[2]];
  if (ret > 0){ return ret; }

  if (n == 0){ return 1; }

  ret = 0;
  if (ret > 0){ return ret; }

  for (int i = 0; i < 4; i++){
    ACGT c = a[i];
    ACGT last4[4] = {last3[0], last3[1], last3[2], c};
    if (good(last4)){
      ACGT new_last3[3] = {last3[1], last3[2], c};
      ret = (ret + search(n-1, new_last3)) % M;
    }
  }

  memo[n][last3[0]][last3[1]][last3[2]] = ret;
  return ret;
}



int main()
{
  int n;
  cin >> n;

  ACGT ttt[3] = {T, T, T};
  cout << search(n, ttt) << endl;
}

