const int mod = 1e9 + 7;
const int kmax = 510000;

long long fact[kmax], fact_inv[kmax], inv[kmax];

int gcd(int a, int b)
{
    if (!b) {
        return a;
    }

    return gcd(b, a % b);
}

void init_comb()
{
    fact[0] = fact[1] = 1;
    fact_inv[0] = fact_inv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < kmax; i++) {
        fact[i] = fact[i - 1] * i % mod;
        inv[i] = mod - inv[mod % i] * (mod / i) % mod;
        fact_inv[i] = fact_inv[i - 1] * inv[i] % mod;
    }
}

long long comb(int n, int r)
{
    if (n < r) {
        return 0;
    }

    if (n < 0 || r < 0) {
        return 0;
    }

    return fact[n] * (fact_inv[r] * fact_inv[n - r] % mod) % mod;
}

int main()
{
    int n;
    std::cin >> n;

    std::vector<std::unordered_map<std::string, long long>> dp(n + 1);

    auto is_ok = [](std::string last_four) {
        for (int i = 0; i < 4; i++) {
            std::string t = last_four;
            if (i < 3) {
                std::swap(t[i], t[i + 1]);
            }

            if (t.find("AGC") != std::string::npos) {
                return false;
            }
        }
        return true;
    };
    auto dfs = [&](auto f, int idx, std::string last_three) -> long long {
        if (idx == n) {
            return 1;
        }

        if (dp[idx].find(last_three) != dp[idx].end()) {
            return dp[idx][last_three];
        }

        long long value = 0;
        for (auto c : { 'A', 'C', 'G', 'T' }) {

            if (is_ok(last_three + c)) {
                value += f(f, idx + 1, last_three.substr(1, 2) + c) % mod;
                value %= mod;
            }
        }

        dp[idx][last_three] = value;
        return value;
    };

    std::cout << dfs(dfs, 0, "TTT") << std::endl;
}

