int dp[2000][4][4][4], mod = 1e9+7;
signed main(){
  int n;cin >> n;
  rep(i,4)rep(j,4)dp[2][i][j][1] = 1;
  repi(i,3,n+1)rep(j,4)rep(k,4)rep(l,4)rep(m,4){
    // AGC, ACG, GAC
    if(j == 1 and k == 2 and l == 0)continue;
    if(j == 1 and k == 2 and m == 0)continue;
    if(j == 2 and k == 1 and l == 0)continue;
    if(j == 1 and k == 0 and l == 2)continue;
    if(j == 1 and l == 2 and m == 0)continue;
    dp[i][j][k][l] += dp[i-1][k][l][m];
    dp[i][j][k][l] %= mod;
  }
  int ans = 0;
  rep(j,4)rep(k,4)rep(l,4){ans += dp[n][j][k][l];ans %= mod;}
  cout << ans << endl;
  return 0;
}

