bool good(string buf) {
    if (buf.find("agc")!=string::npos) return false;
    for (int i=0; i<3; i++) {
	swap(buf[i],buf[i+1]);
	if (buf.find("agc")!=string::npos) return false;
	swap(buf[i],buf[i+1]);
    }
    return true;
}


ll dfs(int i, string last3) {
    if (i==n) return 1;
    if (mp.count({i,last3})) return mp[{i,last3}];

    ll res=0;
    string lets="actg";
    for (char c: lets) {
	string buf=last3+string(1,c);
	if (good(buf)) {
	    res += dfs(i+1,buf.substr(1));
	    res %= mod;
	}
    }
    res %= mod;
    return mp[{i,last3}]=res;
}

