int n;
int mem[N][5][5][5];

int go(int idx , int lst1 , int lst2 , int lst3){
    if(idx == n)
        return 1;
    if(~mem[idx][lst1][lst2][lst3])
        return mem[idx][lst1][lst2][lst3];
    int cnt = 0;
    for(int i = 1; i <= 4; i++){
        if(i == 3 && lst1 == 2 && lst2 == 1) continue;
        if(i == 3 && lst1 == 1 && lst2 == 2) continue;
        if(i == 3 && lst2 == 2 && lst3 == 1) continue;
        if(i == 3 && lst1 == 2 && lst3 == 1) continue;
        if(i == 2 && lst1 == 3 && lst2 == 1) continue;

        cnt += go(idx + 1 , i , lst1 , lst2);
        cnt %= mod;
    }
    return mem[idx][lst1][lst2][lst3] = cnt;
}

