  for (int i = 1; i < N; ++i) {
    for (const auto& p : dp[i - 1]) {
      for (const char* c : C) {
        string cand = p.first;
        cand.push_back(c[0]);
        if (cand.size() > 4) {
          cand.erase(cand.begin());
        }

        if (IsGood(cand)) {
          Add(dp[i][cand], p.second);
        }
      }
    }
  }

  int result = 0;
  for (const auto& p : dp[N - 1]) {
    Add(result, p.second);
  }

  cout << result << '\n';

  return 0;
}

