ll rec(ll n, ll a, ll b, ll c) {
	if (dp[n][a][b][c] + 1) return dp[n][a][b][c];
	ll tmp = 0;
	if (a == 0 && b == 1 && c == 2) return dp[n][a][b][c] = 0;
	if (a == 0 && b == 2 && c == 1) return dp[n][a][b][c] = 0;
	if (a == 1 && b == 0 && c == 2) return dp[n][a][b][c] = 0;
	REP(i, 4) {
		if (i == 0 && a == 1 && b == 2) continue;
		if (i == 0 && a == 2 && b == 1) continue;
		if (i == 1 && a == 0 && b == 2) continue;
		if (i == 0 && a == 1 && c == 2) continue;
		if (i == 0 && b == 1 && c == 2) continue;
		tmp = (tmp + rec(n - 1, i, a, b)) % MOD;
	}
	return dp[n][a][b][c] = tmp;
}

