ll dfs(ll n, ll a, ll b){ //先頭の二文字がa,bのとき
  if( n == 2){ return 1;} //列abしかない
  if( dp[n][a][b] != -1){ return dp[n][a][b];}//メモ化

  ll res = 0;

  for(ll p = 0; p < 4; p++){
      res += dfs( n - 1,b,p ); res %= MOD;} 

     if( a == 0 && b == 2){ res -= dfs( n - 1, 2, 1);}
else if( a == 2 && b == 0){ res -= dfs( n - 1, 0, 1);}
else if( a == 0 && b == 1){ res -= dfs( n - 1, 1, 2);}

 res = ( MOD + res) % MOD;

return dp[n][a][b] = res;  }




