#define MOD 1000000007
#define A 0
#define T 1
#define G 2
#define C 3 

using namespace std;

typedef long long ll;

int N;
ll dp[105][4][4][4]; //dp[i][j][k][l]: i文字目までの組み合わせのうち、i-3文字目がj、i-2文字目がk、i-1文字目がlであるものの数

int main(void) {
    scanf("%d", &N);

    rep(i, 0, 4) {
      rep(j, 0, 4) {
        rep(k, 0, 4) {
          if (i == A && j == G && k == C) continue; //AGCは無視
          if (i == A && j == C && k == G) continue; //ACGは無視
          if (i == G && j == A && k == C) continue; //GACは無視
          dp[3][i][j][k] = 1; //3までの文字列のうち条件を満たさないものをカウント
        }
      }
    }

    rep(i, 4, N+1) {
      rep(j, 0, 4) { //i-3番目の文字
        rep(k, 0, 4) { //i-2番目の文字
          rep(l, 0, 4) { //i-1番目の文字
            rep(m, 0, 4) { //今付加する文字
              /*
              jklにmの文字を付加したいとき、
              klmがAGC, ACG, GACを満たさない必要があり
              jklmがA?GC, AG?Cを満たさない必要がある
              逆にこれらを満たさない場合、klmが最後3文字となり、jklの組み合わせをklmの組み合わせに足せば良い
               */
              if (k == A && l == G && m == C) continue; //AGCは無視
              if (k == A && l == C && m == G) continue; //ACGは無視
              if (k == G && l == A && m == C) continue; //GACは無視
              if (j == A && l == G && m == C) continue; //A?GCは無視
              if (j == A && k == G && m == C) continue; //AG?Cは無視
              dp[i][k][l][m] += dp[i-1][j][k][l];
              dp[i][k][l][m] %= MOD;
            }
          }
        }
      }
    }
    ll ans = 0;
    rep(i, 0, 4) {
      rep (j, 0, 4) {
        rep(k, 0, 4) {
          ans += dp[N][i][j][k];
          ans %= MOD;
        }
      }
    }


  printf("%lld\n", ans);

	return 0;
}

