const ll MOD = 1000000007;

int N;
set<string> forbid;
string chars[4] = {"A", "G", "C", "T"};
typedef tuple<int, string> key;
map<key, ll> M;

void make(string S)
{
  if ((int)S.size() < 4)
  {
    for (auto i = 0; i < 4; i++)
    {
      make(S + chars[i]);
    }
  }
  else
  {
    for (auto i = 0; i < 4; i++)
    {
      string T = S;
      if (i < 3)
      {
        swap(T[i], T[i + 1]);
      }
      for (auto i = 0; i < 2; i++)
      {
        if (T.substr(i, 3) == "AGC")
        {
          forbid.insert(S);
          return;
        }
      }
    }
  }
}

bool ok(string S)
{
  return (forbid.find(S) == forbid.end());
}

ll dfs(int x, string S)
{
  if (M.find(key(x, S)) != M.end())
  {
    return M[key(x, S)];
  }
  if (x == N)
  {
    return 1;
  }
  ll ans = 0;
  for (auto i = 0; i < 4; i++)
  {
    string T = S + chars[i];
    if (ok(T))
    {
      ans += dfs(x + 1, T.substr(1, 3));
      ans %= MOD;
    }
  }
  return M[key(x, S)] = ans;
}

int main()
{
  cin >> N;
  make("");
#if DEBUG == 1
  for (auto x : forbid)
  {
    cerr << x << endl;
  }
#endif
  cout << dfs(0, "TTT") << endl;
}

