#define A 0
#define C 1
#define G 2
#define T 3

using namespace std;


int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);
	int N;
	cin >> N;
  	long const div = 1000000007;
  	//A, C, G, T
  	//AGC を部分文字列として含まない
  	//3:AGC, ACG, GACの３パターン
  	//4:AGC*, *AGC, A*GC, AG*C, GAC*, *GAC, ACG*, *ACG の３２パターン
    //  から重複するACGC, AAGC, AGAC, AGCC, GACC, GACGの被り６パターンを除く26パターン
  	//A:0, C:1, G:2, T:3
  	int comb[101][4][4][4] = {};
	for (int i=0;i<4;i++) {
        for (int j=0;j<4;j++) {
            for (int k=0;k<4;k++) {
                if (i == A && j == G && k == C) continue;
                if (i == A && j == C && k == G) continue;
                if (i == G && j == A && k == C) continue;
                comb[3][i][j][k] = 1;
            }
        }
    }
  	//動的計画法：dp
    for (int i = 3; i < N; i++) {
      for (int j = 0; j < 4; j++) {
        for (int k = 0; k < 4; k++) {
          for (int l = 0; l < 4; l++) {
            for (int m = 0; m < 4; m++) {
              if (k == A && l == G && m == C) continue;
              if (k == G && l == A && m == C) continue;
              if (k == A && l == C && m == G) continue;
              if (j == A && l == G && m == C) continue;
              if (j == A && k == G && m == C) continue;
              comb[i+1][k][l][m] += comb[i][j][k][l];
              comb[i+1][k][l][m] %= div;
            }
          }
        }
      }
    }
    long ans;
    ans = 0;
    for (int i = 0; i < 4; i++) {
      for (int j = 0; j < 4; j++) {
        for (int k = 0; k < 4; k++) {
          ans += comb[N][i][j][k];
          cerr << i << j << k << ":" <<comb[N][i][j][k] << endl;
          ans %= div;
        }
      }
    }
    cout<<ans<<endl;

  	return 0;
}

