const ll mod = 1e9 + 7;

ll dp[101][4][4][4];

bool chack(int i, int j, int k, int t){

    bool res = true;
    if((i == 0  && j == 1 && k == 2) || (j == 0 && k == 1 && t == 2))res = false;
    swap(i, j);
    if((i == 0  && j == 1 && k == 2) || (j == 0 && k == 1 && t == 2))res = false;
    swap(i, j);
    swap(j, k);
    if((i == 0  && j == 1 && k == 2) || (j == 0 && k == 1 && t == 2))res = false;
    swap(j, k);
    swap(k, t);
    if((i == 0  && j == 1 && k == 2) || (j == 0 && k == 1 && t == 2))res = false;
    return !res;
}



int main()
{
    int n;
    cin >> n;
    memset(dp, 0, sizeof(dp));
    dp[0][3][3][3] = 1;

    for(int i = 0; i < n; i++){

        for(int j = 0; j < 4; j++){

            for(int k = 0; k < 4; k++){

                for(int t = 0; t < 4; t++){

                    for(int l = 0; l < 4; l++){

                        if(chack(j,k,t,l))continue;
                        dp[i + 1][k][t][l] += dp[i][j][k][t];
                        dp[i + 1][k][t][l] %= mod;
                    }
                }
            }
        }
    }

    ll ans = 0;

    for(int i = 0; i < 4; i++){
        for(int j = 0; j < 4; j++){
            for(int k = 0; k < 4; k++){
                ans += dp[n][i][j][k];
                ans %= mod;
            }
        }
    }
    cout << ans << endl;


}

