#include <bits/stdc++.h>

using namespace std;

const int mod = (int) 1e9 + 7;

int main() {
  int n;
  cin >> n;

  if (n == 3) {
    cout << 61 << '\n';
    return 0;
  }

  auto check = [](string s) {
    assert(s.length() == 4);
    if (s.substr(0, 3) == "AGC" || s.substr(1, 3) == "AGC") {
      return false;
    }
    for (int i = 0; i < 3; i++) {
      swap(s[i], s[i + 1]);
      if (s.substr(0, 3) == "AGC" || s.substr(1, 3) == "AGC") {
        return false;
      }
      swap(s[i], s[i + 1]);
    }
    return true;
  };

  vector<string> alpha = {"A", "T", "C", "G"};
  map<string,int> dp;
  for (auto a : alpha) {
    for (auto b : alpha) {
      for (auto c : alpha) {
        dp[a + b + c]++;
      }
    }
  }

  for (int i = 0; i < n - 3; i++) {
    map<string,int> dp_new;
    for (auto c : alpha) {
      for (auto s : dp) {
        string t = s.first + c;
        if (check(t)) {
          (dp_new[t.substr(1, 3)] += s.second) %= mod;
        }
      }
    }
    swap(dp, dp_new);
  }

  int ans = 0;
  for (auto i : dp) {
    ans = (ans + i.second) % mod;
  }
  cout << ans << '\n';

  return 0;
}

