using namespace std;

int count(std::string res, int sum, int n, int length) {
  if (length == n) {
    sum++;
    sum = sum % 100000007;
    return sum;
  }

  std::string ss = "ACGT";
  if (res.size() == 0 || res.size() == 1) for (int i = 0; i < ss.size(); i++) sum = count(res + ss[i], sum, n, length + 1);
  else if (res.size() == 2) {
    char rem = 'Z';
    if (res == "AG") rem = 'C';
    else if (res == "AC") rem = 'G';
    else if (res == "GA") rem = 'C';
    for (int i = 0; i < ss.size(); i++) if (ss[i] != rem) sum = count(res + ss[i], sum, n, length + 1);
  }
  else {
    int l = res.size();
    char rem = 'Z';
    if (res[l-3] == 'A' && res[l-2] == 'G') rem = 'C';
    else if (res[l-3] == 'A' && res[l-1] == 'G') rem = 'C';
    else if (res[l-2] == 'G' && res[l-1] == 'A') rem = 'C';
    else if (res[l-2] == 'A' && res[l-1] == 'G') rem = 'C';
    else if (res[l-2] == 'A' && res[l-1] == 'C') rem = 'G';
    for (int i = 0; i < ss.size(); i++) if (ss[i] != rem) sum = count(res.substr(l-2, l) + ss[i], sum, n, length + 1);
  }
  return sum;
}

int main(void) {
  int n;
  cin >> n;
  std::string res = "";
  int sum = 0;
  sum = count(res, sum, n, 0);
  cout << sum << endl;
