std::map<std::pair<int, std::string>, long long> dp;

bool slv_ok(std::string s) {

    if(s.size() < 3) return true;

    std::string ngs;

    ngs = "AGAC";
    for(int i = 0; i < c.size(); i++) {
        ngs[2] = c[i];
        if(ngs == s) return false;
    }

    ngs = "AAGC";
    for(int i = 0; i < c.size(); i++) {
        ngs[1] = c[i];
        if(ngs == s) return false;
    }

    ngs = "AGC";
    if(s.substr(0, 3) == ngs || s.substr(1, 3) == ngs) return false;

    ngs = "ACG";
    if(s.substr(0, 3) == ngs || s.substr(1, 3) == ngs) return false;

    ngs = "GAC";
    if(s.substr(0, 3) == ngs || s.substr(1, 3) == ngs) return false;

    return true;
}

long long slv(int now, std::string s) {

    if(!slv_ok(s)) return 0;    

    if(now == 0) return 1;
    if(dp.find(std::make_pair(now, s)) != dp.end()) return dp[std::make_pair(now, s)];

    long long ret = 0;

    std::string mem = s;

    if(s.size() > 3) {
        for(int i = 0; i < 3; i++) {
            s[i] = s[i+1];
        }
        s.pop_back();
    }

    for(int i = 0; i < c.size(); i++) {
        ret = (ret + slv(now-1, s+c[i])) % 1000000007;
    }

    return dp[std::make_pair(now, mem)] = ret % 1000000007;
}

