	string res = s + c;

	int n = res.length();
	if (n <= 2) return res;

	if (contain(res)) return "";

	rep(i, 0, n - 1) {
		string tes = res;
		swap(tes[i], tes[i + 1]);
		if (contain(tes)) return "";
	}

	if (4 <= n) res = res.substr(n - 3);

	return res;
}
