long long solve(int ix)
{
	long long retval = dp[ix - 1];
	if (ix >= 3) {
		retval = (retval - dp[ix - 3] + MOD)%MOD;
	}
	if (ix - 3 > 0) retval = (retval + solve(ix - 3))%MOD;
	return retval;
}

int main()
{
	ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	cin >> n;
	dp[0] = 1;
	dp[1] = 4;
	dp[2] = 16;
	dp[3] = 61;
	for (int i = 4; i <= n; i++) {
		dp[i] = (3 * dp[i - 1]) % MOD;
		dp[i] = (dp[i] - dp[i - 3] + MOD) % MOD;
		//dp[i] = (dp[i] - dp[i - 3] + MOD) % MOD;
		dp[i] = (dp[i] - solve(i - 2) + MOD) % MOD;
		if (i >= 4) {
			dp[i] = (dp[i] - dp[i - 4] + MOD) % MOD;
			dp[i] = (dp[i] - dp[i - 4] + MOD) % MOD;
			dp[i] = (dp[i] - dp[i - 4] + MOD) % MOD;
		}
		dp[i] += solve(i);
	}
	cout << dp[n] << "\n";
	//system("pause");
	return 0;
}

