char letters[4] = {'A','C','G','T'};
string invalids[6] = {"AGC","GAC","ACG","AGGC","AGTC","ATGC"};

unordered_map<string,int> memo[100];
// checks if a 4-letter string is valid
bool isValid(string s){
	bool res = true;
	for (int i = 0; i < 6; i++){
		if (s.find(invalids[i]) != string::npos){
			res = false;
		}
	}
	return res;
}

ll dfs(int rec, int n, string s){
	if (rec == n) return 1;
	if (memo[rec].find(s) != memo[rec].end()) {
		return memo[rec][s];
	}

	ll ans = 0;
	for (int i = 0; i < 4; i++){
		string check = s+letters[i];
		if (isValid(check)){
			ans = (ans+dfs(rec+1, n, check.substr(1)))%MOD;
		}
	} 
	// memoization
	memo[rec][s] = ans;
	return ans;
}

