int main() {
    int n;
    ll mod = 1e9 + 7;
    cin >> n;
    if (n == 3) {
        cout << 61 << endl;
    }
    string src = "ATCG";
    unordered_map<string, int> cand;
    int cur_idx = 0;
    auto gen = [&](auto self, int depth, string cur) {
        if (depth == 4) {
            if (cur.find("AGC") != string::npos)
                return;
            for(int i = 1; i < 4; i++) {
                string s2 = cur;
                swap(s2[i], s2[i-1]);
                if (s2.find("AGC") != string::npos)
                    return;
            }
            // cand.insert(cur);
            cand[cur] = cur_idx++;
            return;
        }
        for(int i = 0; i < 4; i++)
            self(self, depth+1, cur+src[i]);
    };
    string tmp = "";
    gen(gen, 0, tmp);
    vector<ll> dp(cand.size(), 1);
    for(int t = 5; t <= n; t++) {
        vector<ll> nxt_dp(cand.size(), 0);
        for(auto p: cand) {
            for(char c: src) {
                auto nxt = p.first.substr(1) + c;
                if (cand.count(nxt) > 0) {
                    nxt_dp[cand[nxt]] += dp[p.second];
                    nxt_dp[cand[nxt]] %= mod;
                }
            }

        }
        swap(dp, nxt_dp);
    }
    ll ans = 0;
    for(auto& val: dp)
        ans = (ans + val) % mod;

    cout << ans << endl;
    return 0;
}

