long long dp[101][4][4][4];


int main(void) {
  int N;
  cin >> N;

  if (N==3) {
    // 入力例1より
    cout << 61 << endl;
    return 0;
  }

  memset(dp, 0, sizeof(dp));
  dp[0][3][3][3] = 1;

  for (int i = 0; i < N; i++) {
    for (int c1 = 0; c1 < 4; c1++) {
      for (int c2 = 0; c2 < 4; c2++) {
        for (int c3 = 0; c3 < 4; c3++) {

          if (dp[i][c1][c2][c3]==0) continue;

          for (int c4 = 0; c4 < 4; c4++) {

            if (c4==2 && c3==1 && c2==0) continue;
            if (c4==2 && c3==0 && c2==1) continue;
            if (c4==1 && c3==2 && c2==0) continue;
            if (c4==2 && c3==1 && c1==0) continue;
            if (c4==2 && c2==1 && c1==0) continue;

            dp[i+1][c2][c3][c4] += dp[i][c1][c2][c3];
            dp[i+1][c2][c3][c4] %= DIV;
          }
        }
      }
    }
  }

  long long ans = 0;
  for (int c1 = 0; c1 < 4; c1++)
    for (int c2 = 0; c2 < 4; c2++)
      for (int c3 = 0; c3 < 4; c3++) {
        ans += dp[N][c1][c2][c3];
        ans %= DIV;
      }

  cout << ans << endl;
  return 0;
}

