namespace rollingHashConfig {
//複数の素数を試し衝突を回避
static constexpr int N = 3;
static const  std::array<std::uint64_t, N>Ms = { 2147483647  , 4444444447, 1234567891 };	//素数
static const  std::array<std::uint64_t, N> B = { 8127,8128,114514 };
