template <class Itr>
using HuffmanVal = typename std::remove_reference<decltype(*std::declval<Itr>())>::type;

//ハフマン圧縮
template <class Itr>
std::vector<std::pair<HuffmanVal<Itr>, int>> haffman(Itr begin, Itr end) {
	std::vector<std::pair<HuffmanVal<Itr>, int>> res;
	bool first = true;
	HuffmanVal<Itr> now = {};
	int count = 0;
	for (auto itr = begin; itr != end; ++itr) {
		++count;
		if (now != *itr || first) {
			res.push_back({ now,count });
			count = 0;
		}
		first = false;
		now = *itr;
	}
	if (count > 0) {
		res.push_back({ now,count });
	}
	return res;
}

