// AGCを含むかどうか、判定する
bool containAGC(string s) { return s.find("AGC") != string::npos; }

// 入れ替えた時にAGCが入っているか、判定する
bool ok(string s) {
  bool res = true;
  res = !containAGC(s);  // AGC予防
  for (int i = 0; i < s.size() - 1; i++) {
    swap(s[i], s[i + 1]);  // 一回スワップしてみる
    if (containAGC(s)) res = false;
    swap(s[i], s[i + 1]);  // 元に戻す
  }
  return res;
}

