void solve(long long N) {
  map<string, mint<>> dp;
  dp["    "] = 1;
  string base = "AGCT";
  for (int i = 0; i < N; i++) {
    map<string, mint<>> tmp;
    for (auto elem : dp) {
      string key = elem.first;
      mint<> val = elem.second;

      for (auto c : base) {
        string next = key.substr(1, 3) + " ";
        next[3] = c;
        string a = next.substr(1, 3);
        if (a == "AGC" || a == "ACG" || a == "GAC") continue;
