        if (next.substr(0, 2) == "AG" && next[3] == 'C') continue;
        tmp[next] += val;
      }
    }
    dp = tmp;
  }
  mint<> ans = 0;
  for (auto elem : dp) ans += elem.second;
  cout << ans << endl;
}

