//AGC,ACG,GAC,AGXC,AXGC、つまり123,132,213,1203,1023を含まない
ll solve(int N){
 ll dp[N+1][5][5][5];//n文字目までいって、3文字前、2文字前、1文字前
  dp[0][0][0][0]=1;
  rep(n,N){
      rep(i,5){
          rep(j,5){
              rep(k,5){
                  rep(l,5){
                      //次の3文字はj,k,lの順
                  if(i==1&&j==2&&l==3)continue;
                  if(i==1&&k==2&&l==3)continue;
                  if(j==1&&k==2&&l==3)continue;
                  if(j==1&&k==3&&l==2)continue;
                  if(j==2&&k==1&&l==3)continue;
                  add(dp[n+1][j][k][l],dp[n][i][j][k]);
                  }
              }
          }
      }
  }

  ll res = 0;
  rrep(i,4){
      rrep(j,4){
          rrep(k,4){
              add(res,dp[N][i][j][k]);//N文字目まで行った時の直前の3文字がi,j,kの時
          }
      }
  }
  return res;
}

