struct Matrix64{
	long m[64][64];
	Matrix64() {fill(m[0], m[64], 0);}
	long& at(int i, int j) {return m[i][j];}
	const long& at(int i, int j) const {return m[i][j];}
	Matrix64 operator*(const Matrix64& other) const{
		Matrix64 out;
		for (int i = 0; i < 64; ++i){
			for (int j = 0; j < 64; ++j){
				out.at(i, j) = 0;
				for (int k = 0; k < 64; ++k){
					(out.at(i, j) += this->at(i, k)*other.at(k, j)) %= MOD;
				}
			}
		}
		return out;
	}
	Matrix64& operator=(const Matrix64& other){
		for (int i = 0; i < 64; ++i){
			for (int j = 0; j < 64; ++j){
				m[i][j] = other.at(i, j);
			}
		}
		return *this;
	}
};

Matrix64 matrixPow(const Matrix64& A, int n){
	if (n == 1){return A;}
	else if (n == 2){return A*A;}
	else if (n % 2 == 0){return matrixPow(matrixPow(A, n/2), 2);}
	else{return matrixPow(A, n-1)*A;}
}

