void solve()
{
	using A3 = array<char, 3>;

	READ(int, N);
	const char A = 'a', G = 'g', C = 'c', T = 't';
	const char AGCT[] = { A,G,C,T };

	map<A3, llong> dp = { {{T,T,T}, 1 } };
	REP(i, N)
	{
		map<A3, llong> next;
		FORE(kv : dp) REP(i, 4)
		{
			char c = AGCT[i];
			const A3 &from = kv.first;
			const A3 to = { from[1], from[2], c };
			if (from[0] == A && from[1] == G && c == C) continue;
			if (from[0] == A && from[2] == G && c == C) continue;
			if (to == A3{ A,G,C }) continue;
			if (to == A3{ A,C,G }) continue;
			if (to == A3{ G,A,C }) continue;
			next[{to}] = (next[{to}] + kv.second) % 1000000007;
		}
		dp.swap(next);
	}

	llong ans = 0;
	FORE(kv: dp)
	{
		ans = (ans + kv.second) % 1000000007;
	}

	WRITE(ans);
}

