bool Judge(std::string last){
   if(last[0]=='A' && last[3]=='C'){
      if(last[1]=='G' || last[2]=='G'){
	 return false;
      }
   }

   if(last[1]=='A' && last[2]=='G' && last[3]=='C') return false;
   if(last[1]=='G' && last[2]=='A' && last[3]=='C') return false;
   if(last[1]=='A' && last[2]=='C' && last[3]=='G') return false;

   return true;
}

long long Count(int index, std::string last){
   if(memory[index][last]>0){
      return memory[index][last];
   }
   if(index==N) return 1;

   long long count = 0;
   for(int i=0; i<4; ++i){
      char moji = 'A';
      if(i==1) moji = 'C';
      else if(i==2) moji = 'G';
      else if(i==3) moji = 'T';

      if(Judge(last+moji)){
	 std::string last_new = {last[1], last[2], moji};
	 count = (count + Count(index+1, last_new)) % MOD; 
      }
   }
   memory[index][last] = count;

   return count;
}

