vector<string> get_ptn() {
  string a = "ACGT";
  vector<string> ans(64, "***");
  rep(i, 4 * 4 * 4) {
    ans[i][0] = a[i / 16];
    ans[i][1] = a[(i / 4) % 4];
    ans[i][2] = a[i % 4];
  }

  ans.erase(find(all(ans), "AGC"));
  ans.erase(find(all(ans), "ACG"));
  ans.erase(find(all(ans), "GAC"));
  return ans;
}

signed main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(20);

  ll n;
  cin >> n;

  const auto keys = get_ptn();

  vector<map<string, ll>> dp(n + 1);
  FORm(it, keys) {
    dp[3][*it] = 1;
  }

  for (int i = 4; i <= n; i++) {
    FORm(it, keys) {
      FORm(pv, dp[i - 1]) {
        if ((*it)[0] != pv->first[1] || (*it)[1] != pv->first[2]) {
          continue;
        }
        if (pv->first[0] == 'A' && (*it)[2] == 'C') {
          if ((*it)[0] == 'G') {
            continue;
          }
          if ((*it)[1] == 'G') {
            continue;
          }
        }
        dp[i][*it] += pv->second;
        dp[i][*it] %= mod;
      }
    }
  }

  ll ans = 0;
  FORm(it, dp[n]) {
    ans = (ans + it->second) % mod;
  }

  cout << ans << endl;

  return 0;
}

