ll isOK(int n,int a4,int a3,int a2,int a1){
    if(n<1)return 0;

    if(a3==0 && a2==2 && a1==1)return 0;
    if(a3==2 && a2==0 && a1==1)return 0;
    if(a3==0 && a2==1 && a1==2)return 0;

