using namespace std;
int n;
ll memo[105][26][26][26];

bool ok(string a){
	string bad = "agc";
	if(a.find(bad)!=std::string::npos)return false;
	for(int i=0;i<sz(a)-1;i++){
		swap(a[i],a[i+1]);
		if(a.find(bad)!=std::string::npos)return false;
		swap(a[i],a[i+1]);
	}
	return true;
}
ll solve(int indx,char c1,char c2,char c3){
	if(indx==n)return 1;
	string a = "";
	a+=c1;
	a+=c2;
	a+=c3;
	//cout<<a<<endl;
	ll &ret = memo[indx][c1-'a'][c2-'a'][c3-'a'];
	if(~ret)return ret;
	ret=0;
	for(auto x: {'a','g','c','t'}){
		a.pb(x);
		if(ok(a)){
			ret+=solve(indx+1,c2,c3,x);
			ret%=MOD;
		}
		a.pop_back();
	}
	return ret;
}
