#include <bits/stdc++.h>
using namespace std;
const int MOD = 1e9 + 7;
int N;
int dp[105][50][50][50];
bool ok (string last3){
  if (last3.find("AGC") != string::npos) return false;
  for (int i = 0; i < last3.size() - 1; i++){
    swap(last3[i], last3[i + 1]);
    if (last3.find("AGC") != string::npos) return false;
    swap(last3[i], last3[i + 1]);
  }
  return true;
}
string dna = "ACTG";
int solve(int I, string last3){
  if (!ok(last3)) return 0;
  if (dp[I][last3[0] - 'A'][last3[1] - 'A'][last3[2] - 'A'] != -1) return (dp[I][last3[0] - 'A'][last3[1] - 'A'][last3[2] - 'A'] % MOD);
  if (I >= N) return 1;
  long long ans = 0;
  if (I < 3){
    for (int i = 0; i < 4; i++){
      if (last3[I] == 'z') {
        last3[I] = dna[i];
        ans += (solve(I + 1, last3) % MOD);
        last3[I] = 'z';
      }
    }
  } else {
    for (int i = 0; i < 4; i++){
      if (ok(last3 + dna[i])) {
        string bak = last3;
        last3[0] = last3[1];
        last3[1] = last3[2];
        last3[2] = dna[i];
        ans += (solve(I + 1, last3) % MOD);
        last3 = bak;
      }
    }
  }
  return (dp[I][last3[0] - 'A'][last3[1] - 'A'][last3[2] - 'A'] = (ans % MOD));
}

