bool problemIn(int i, int j, int k, int l) {
  int val1 = 100*i + 10*j + k;
  int val2 = 100*j + 10*k + l;
  if(val1 == 12 ||val2 == 12) return true;

  vector<int> A = {i, j, k, l};

  for(int i = 0;i < 3;i++) {
    swap(A[i], A[i+1]);
    int val1 = 100*A[0] + 10*A[1] + A[2];
    int val2 = 100*A[1] + 10*A[2] + A[3];
    if(val1 == 12 ||val2 == 12) return true;
    swap(A[i], A[i+1]);
  }

  return false;
}

long long NumCombinations(int N) {
  if(N == 3) return 61;

  for (size_t n = 4; n <= N; n++) {
    int count = 4;
    for (size_t i = 0; i < count; i++) {
      for (size_t j = 0; j < count; j++) {
        for (size_t k = 0; k < count; k++) {
          for (size_t l = 0; l < count; l++) {
            if (problemIn(i, j, k, l)) {
              dp[n][i][j][k][l] = 0;
            } else if (n == 4) {
              dp[n][i][j][k][l] = 1;
            } else {
              dp[n][i][j][k][l] = (dp[n-1][0][i][j][k]+dp[n-1][1][i][j][k]+dp[n-1][2][i][j][k]+dp[n-1][3][i][j][k]) % mod;
            }
          }
        }
      }
    }
  }

  long long ans = 0;
  int count = 4;
  for (size_t i = 0; i < count; i++) {
    for (size_t j = 0; j < count; j++) {
      for (size_t k = 0; k < count; k++) {
        for (size_t l = 0; l < count; l++) {
          ans = (ans + dp[N][i][j][k][l]) % mod;
        }
      }
    }
  }

  return ans;
}

