llint dfs(int idx, int a, int b, int c)
{
    if(idx == n) return 1;
    if(memo[idx][a][b][c] != -1) return memo[idx][a][b][c];

    llint rec = 0;

    rec += dfs(idx + 1, b, c, 1);
    if(!(b == 1 && c == 3)) rec += dfs(idx + 1, b, c, 2);
    if(!(b == 1 && c == 2) &&
       !(b == 2 && c == 1) &&
       !(a == 1 && c == 2) &&
       !(a == 1 && b == 2)) rec += dfs(idx + 1, b, c, 3);
    rec += dfs(idx + 1, b, c, 4);

    return memo[idx][a][b][c] = rec % MOD;
}

