const int mod = 1000000007;

bool check(int i) {
  int a[4];
  for (int j = 0; j < 4; j++) {
    a[3-j] = i % 4;
    i /= 4;
  }
  bool ok = true;
  for (int j = 0; j < 4; j++) {
    if (j) swap(a[j-1], a[j]);
    if (a[0] == 1 && a[1] == 2 && a[2] == 3) ok = false;
    if (a[1] == 1 && a[2] == 2 && a[3] == 3) ok = false;
    if (j) swap(a[j-1], a[j]);
  }
  return (ok ? true : false);
}

