  }
  dp[0][0] = 1;
  bool tabl[64][4];
  for (int i = 0; i < 64; i++) {
    for (int j = 0; j < 4; j++) {
      tabl[i][j] = (check(4 * i + j) ? true : false);
    }
  }
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < 64; j++) {
      for (int k = 0; k < 4; k++) {
