class Solution {
    using Interval = pair<int, int>;
public:
    vector<string> summaryRanges(const vector<int> &nums) {
        if (nums.empty()) return {};
        for (auto &x : nums) {
            addNums(x);
        }
        auto intervals = getIntervals();
        vector<string> res;
        for (auto &v : intervals) {
            res.push_back(toString(v));
        }
        return res;
    }

private:
    unordered_set<int> st;
    unordered_map<int, int> mp;
    void addNums(int val) {
        if (st.count(val)) return;
        int left = val;
        int right = val;
        if (val > INT_MIN && st.count(val - 1)) {
            left = mp.at(val - 1);
            mp.erase(val - 1);
        }
        if (val < INT_MAX && st.count(val + 1)) {
            right = mp.at(val + 1);
            mp.erase(val + 1);
        }
        mp[left] = right;
        mp[right] = left;
        st.insert(val);
    }
    vector<Interval> getIntervals() {
        vector<Interval> res;
        for (auto &v : mp) {
            if (v.first <= v.second) {
                res.push_back(v);
            }
        }
        sort(res.begin(), res.end());
        return res;
    }
    string toString(const Interval &i) {
        string res;
        if (i.first == i.second) {
            res = to_string(i.first);
        } else {
            res = to_string(i.first) + "->" + to_string(i.second);
        }
        return res;
    }
};

