    if (check(a, c, b)) return false;
    if (check(b, c, d)) return false;
    if (check(c, b, d)) return false;
    if (check(b, d, c)) return false;
    if (check(a, c, d)) return false;
    if (check(a, b, d)) return false;
    return true;
}

int solve(int n, int a, int b, int c) {
    if (n == 3) return 1;
    if (memo[n][a][b][c] != -1) return memo[n][a][b][c];
    int res = 0;
    for (int i = 0; i < 4; i++) if (check(i, a, b, c))
        res = (res + solve(n - 1, i, a, b)) % MD;
    return memo[n][a][b][c] = res;
}

