int N;
map<string, ll> memo[110];

bool ok (string s) {
  if ((s.substr(0, 3) == "AGC") || (s.substr(1, 3) == "AGC")) {
    return false;
  }
  if ((s.substr(0, 3) == "GAC") || (s.substr(1, 3) == "GAC")) {
    return false;
  }
  if ((s.substr(0, 3) == "ACG") || (s.substr(1, 3) == "ACG")) {
    return false;
  }
  if (s[0] == 'A' && s[1] == 'G' && s[3] == 'C') {
    return false;
  }
  if (s[0] == 'A' && s[2] == 'G' && s[3] == 'C') {
    return false;
  }

  return true;
}

ll dfs(int n, std::string str) {
  if (n == N) {
    return 1;
  }

  if (memo[n][str] != -1) {
    return memo[n][str];
  }

  vector<char> v = {'A', 'G', 'C', 'T'};

  ll ans = 0;
  for (auto curr: v) {
    string tmp = str + curr;

    if (ok(tmp)) {
      ans += dfs(n+1, str.substr(1, 3) + curr);
      ans %= MOD;
    }
  }

  memo[n][str] = ans;
  return ans;
}

