using namespace std;

int MOD = 1000000000 + 7;
int N;

char acgt[] = {'A', 'C', 'G', 'T'};

bool check3(char c0, char c1, char c2) {
    if (c0 == 'A' && c1 == 'G' && c2 == 'C') return false;
    if (c0 == 'A' && c1 == 'C' && c2 == 'G') return false;
    if (c0 == 'G' && c1 == 'A' && c2 == 'C') return false;
    return true;
}

bool check4(char c0, char c1, char c2, char c3) {
    if (c0 == 'A' && c2 == 'G' && c3 == 'C') return false;
    if (c0 == 'A' && c1 == 'G' && c3 == 'C') return false;
    return true;
}

int dfs(string s) {
    int n = s.length();
    if (n == N) return 1;
    int ret = 0;
    for (int i = 0; i < 4; i++) {
        if (n >= 2 && !check3(s[n-2], s[n-1], acgt[i])) continue;
        if (n >= 3 && !check4(s[n-3], s[n-2], s[n-1], acgt[i])) continue;
        ret += dfs(s + acgt[i]) % MOD;
    }
    return ret;
}

int main() {
    cin >> N;

    int ans = dfs("");
    cout << ans << endl;

    return 0;
}

