const int MOD = 1e9 + 7;
int N;
vector<map<string, ll>> cnt;
string S[4] = {"A", "C", "G", "T"};

bool is_valid(string s) {
    REP(i, 4) {
        string t = s;
        if (i > 0) {
            swap(t[i - 1], t[i]);
        }
        if (t.find("AGC") != string::npos) {
            return false;
        }
    }
    return true;
}

ll dfs(int i, string s) {
    if (cnt[i].count(s) > 0) {
        return cnt[i][s];
    }
    if (i == N) {
        return 1;
    }
    ll res = 0;
    REP(j, 4) {
        string t = s + S[j];
        if (is_valid(t)) {
            res = (res + dfs(i + 1, t.substr(1))) % MOD;
        }
    }
    cnt[i][s] = res;
    return res;
}

// main
int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> N;
    cnt = vector<map<string, ll>>(N + 1);
    cout << dfs(0, "ZZZ") << endl;
    return 0;
}

