//	modNの計算をするクラス
template <int mod> struct mint {
    int data;
    mint( void ) :data(0) {}
    mint( int n ) :data( n>=0 ? n%mod : (mod - (-n)%mod) %mod ) {}
    operator int() { return data; }
    friend istream &operator>>(istream&is,mint&m){int n; is>>n; m=n; return is;}
    friend ostream &operator<<(ostream&os,mint&m){os<<(int)m; return os;}
    mint operator+ ( int n ) { return (data + n) % mod; }
    mint operator+ (mint m ) { return *this + (int)m; }
    void operator+=( int n ) { data = *this +      n; }
    void operator+=(mint m ) { data = *this + (int)m; }
    mint operator* ( int n ) { return (lint)data * n % mod; }
    mint operator* (mint m ) { return *this * (int)m; }
    void operator*=( int n ) { data = *this *      n; }
    void operator*=(mint m ) { data = *this * (int)m; }
    mint operator/ ( int n ) { return *this * mint(n).inv(); }
    mint operator/ (mint m ) { return *this * m.inv(); }
    void operator/=( int n ) { data = data * mint(n).inv(); }
    void operator/=(mint m ) { data = data * m.inv(); }
    bool operator==( int n ) { return data == n; }
    bool operator==(mint m ) { return data == m.data; }
    bool operator!=( int n ) { return data != n; }
    bool operator!=(mint m ) { return data != m.data; }
    mint pow(int n){mint a=1,b=data;while(n>0){if(n&1)a*=b;b*=b;n>>=1;}return a;}
    mint pow(mint m){ return (*this).pow((int)m); }
    mint inv(){int a=data,b=mod,c=1,d=0,e;while(b){e=a/b;swap(a-=e*b,b);swap(c-=e*d,d);}return c;}
};
using mint_7 = mint<1000000007>;


int main() { cin.tie(0); ios::sync_with_stdio(false);
