/* Mod */
#define MOD 1000000007
struct mint {
  ll x;
  mint():x(0){}
  mint(ll x):x((x%MOD+MOD)%MOD){}
  // mint(ll x):x(x){}
  mint& fix() { x = (x%MOD+MOD)%MOD; return *this;}
  mint operator-() const { return mint(0) - *this;}
  mint& operator+=(const mint& a){ if((x+=a.x)>=MOD) x-=MOD; return *this;}
  mint& operator-=(const mint& a){ if((x+=MOD-a.x)>=MOD) x-=MOD; return *this;}
  mint& operator*=(const mint& a){ (x*=a.x)%=MOD; return *this;}
  mint operator+(const mint& a)const{ return mint(*this) += a;}
  mint operator-(const mint& a)const{ return mint(*this) -= a;}
  mint operator*(const mint& a)const{ return mint(*this) *= a;}
  bool operator<(const mint& a)const{ return x < a.x;}
  bool operator==(const mint& a)const{ return x == a.x;}
};
ostream & operator << (ostream & out, mint const & v) {
  out << v.x;
  return out;
}

string S = "ACGT";
int N;
ll dp[101][5][5][5];

int idx(char c) {
  if (c == 'A') return 0;
  if (c == 'C') return 1;
  if (c == 'G') return 2;
  return 3;
}

mint rec(string s = "") {
  int size = s.size();
  ll &cc = dp[size][size >= 3 ? idx(s[size-3]) : 4][size >= 2 ? idx(s[size-2]) : 4][size >= 1 ? idx(s[size-1]) : 4];
  if (~cc) return cc;
  if (size == N) {
    // cout << s << endl;
    return cc = 1;
  }
  mint count = 0;
  loop(i,0,4) {
    if (size < 2) {
      count += rec(s + S[i]);
      continue;
    }

    if (size >= 2) {
      if (s[size-2] == 'A' and s[size-1] == 'G') {
        if (S[i] != 'C') count += rec(s + S[i]);
      }
      else if (s[size-2] == 'A' and s[size-1] == 'C') {
        if (S[i] != 'G') count += rec(s + S[i]);
      }
      else if (s[size-2] == 'G' and s[size-1] == 'A') {
        if (S[i] != 'C') count += rec(s + S[i]);
      }
      else if (size >= 3 and s[size-3] == 'A' and s[size-2] != 'G' and s[size-1] == 'G') {
        if (S[i] != 'C') count += rec(s + S[i]);
      }
      else if (size >= 3 and s[size-3] == 'A' and s[size-2] == 'G' and s[size-1] != 'C') {
        if (S[i] != 'C') count += rec(s + S[i]);
      }
      else count += rec(s + S[i]);
    }
  }
  return cc = count.x;
}

void solve() {
  cin >> N;
  loop(i,0,101) loop(j,0,5) loop(k,0,5) loop(l,0,5) dp[i][j][k][l] = -1;
  cout << rec() << endl;
}
int main() {
  // cout.precision(15); cout << fixed;

  solve();

  return 0;
}

#include <bits/stdc++.h>

using namespace std;
using ll = long long;

const int MOD = 1000000007;
ll dp[101][4][4][4] = {0};

bool ng(int a, int b, int c) {
  return (a == 1 && b == 2 && c == 3);
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int N;
  cin >> N;

  // TTT
  dp[0][0][0][0] = 1;

  // T = 0, A = 1, G = 2, C = 3
  for (int i = 0; i < N; i++) {
    for (int a = 0; a < 4; a++) {
      for (int b = 0; b < 4; b++) {
        for (int c = 0; c < 4; c++) {
          for (int d = 0; d < 4; d++) {
            // AGC, GAC, ACG
            if (ng(b, c, d) || ng(c, b, d) || ng(b, d, c)) continue;
            // AXGC, AGXC
            if (ng(a, c, d) || ng(a, b, d)) continue;

            dp[i + 1][b][c][d] = (dp[i + 1][b][c][d] + dp[i][a][b][c]) % MOD;
          }
        }
      }
    }
  }
  ll res = 0;
  for (int a = 0; a < 4; a++) {
    for (int b = 0; b < 4; b++) {
      for (int c = 0; c < 4; c++) {
        res += dp[N][a][b][c];
      }
    }
  }
  cout << res << '\n';
  return 0;
}

