constexpr int MOD = 1000000007;
constexpr int INF = 1050000000;

int main() {
	int n; cin >> n;

	long long dp[100 + 1][4][4][4];
	memset(dp, 0, sizeof(dp));

	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			for (int k = 0; k < 4; k++) {
				dp[3][i][j][k] = 1;
			}
		}
	}

	dp[3][0][1][2] = 0;
	dp[3][0][2][1] = 0;
	dp[3][1][0][2] = 0;

	for (int a = 3; a < n; a++) {
		for (int i = 0; i < 4; i++) {
			for (int j = 0; j < 4; j++) {
				for (int k = 0; k < 4; k++) {
					for (int l = 0; l < 4; l++) {
						if (j == 0 && k == 1 && l == 2) continue;
						if (j == 1 && k == 0 && l == 2) continue;
						if (j == 0 && k == 2 && l == 1) continue;
						if (i == 0 && k == 1 && l == 2) continue;
						if (i == 0 && j == 1 && l == 2) continue;

						dp[a + 1][j][k][l] = (dp[a + 1][j][k][l] + dp[a][i][j][k]) % MOD;
					}
				}
			}
		}
	}
	long long ans = 0;

	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			for (int k = 0; k < 4; k++) {
				ans = (ans + dp[n][i][j][k]) % MOD;
			}
		}
	}

	cout << ans << endl;







}

