ll f(ll i, ll c, ll p)
{
    if (i == n - 1)
        return 1;
    ll &ret = dp[i][c][p];
    if (ret != -1)
        return ret;
    if (p == 'Z' || c == 'T' || (c == 'C' && has("CGT", p)) || (c == 'G' && has("CGT", p)) || (c == 'A' && has("ACT", p)))
    {
        ret = f(i + 1, 'A', c) + f(i + 1, 'C', c);
        ret %= mod;
        ret += f(i + 1, 'G', c);
        ret %= mod;
        ret += f(i + 1, 'T', c);
        ret %= mod;
        return ret;
    }
    if (c == 'C' && p == 'A')
    {
        ret = f(i + 1, 'A', c) + f(i + 1, 'C', c);
        ret %= mod;
        ret += f(i + 1, 'T', c);
    }
    else if ((c == 'G' && p == 'A') || (c == 'A' && p == 'G'))
    {
        ret = f(i + 1, 'A', c) + f(i + 1, 'G', c);
        ret %= mod;
        ret += f(i + 1, 'T', c);
    }
    ret %= mod;
    return ret;
}

