typedef long long ll;
ll MOD = 1000000000 + 7;
int N;
const int MAX_N = 100;
ll memo[MAX_N][4*4*4];
char ACGT[4] = {'A', 'C', 'G', 'T'};

bool check(string last4) {
    string s = last4;
    for (int i = 0; i < 2; i++){
        if (s.substr(i, 3) == "AGC") return false;
    }
    for (int i = 0; i < 3; i++) {
        swap(s[i], s[i+1]);
        for (int j = 0; j < 2; j++){
            if (s.substr(j, 3) == "AGC") return false;
        }
        swap(s[i], s[i+1]);
    }
    return true;
}

int ACGT_to_int(string char3) {
    int ret = 0;
    for (int i = 0; i < 3; i++){
        if (char3[i] == 'A') ret += 0 * (int)pow(4, i);
        else if (char3[i] == 'C') ret += 1 * (int)pow(4, i);
        else if (char3[i] == 'G') ret += 2 * (int)pow(4, i);
        else ret += 3 * (int)pow(4, i);
    }
    return ret;
}

ll rec(int i, string last3) {
    int j = ACGT_to_int(last3);
    if (memo[i][j] >= 0) return memo[i][j];
    if (i == N) return 1;
    int ret = 0;
    for (int k = 0; k < 4; k++){
        char c = ACGT[k];
        if (check(last3.append(1, c))){
            ret = (ret + rec(i + 1, last3.substr(1).append(1, c))) % MOD;
        }
    }
    memo[i][j] = ret;
    return ret;
}

int main() {
    cin >> N;
    memset(memo, -1, sizeof(memo));
    cout << rec(0, "TTT") << endl;
    return 0;
}

