    // dp[len][c3][c2][c1]: 長さが len で後ろから3,2,1番目がそれぞれ c3,c2,c1 であるもののうち
    //                      問題文の条件を満たす文字列の個数
    int dp[101][4][4][4] = {};
    dp[0][3][3][3] = 1;  // 0,1,2 についての制約しかないので、S は 333S だと考える
    for( int len = 0; len < N; ++len ){
        for( int c3 = 0; c3 < 4; ++c3 ){
            for( int c2 = 0; c2 < 4; ++c2 ){
                for( int c1 = 0; c1 < 4; ++c1 ){
                    // 0~3 のどの文字を足すか
                    for( int a = 0; a < 4; ++a ){
                        if( c2 == 0 and c1 == 1 and a == 2 ) continue;
                        if( c2 == 1 and c1 == 0 and a == 2 ) continue;
                        if( c2 == 0 and c1 == 2 and a == 1 ) continue;
                        if( c3 == 0 and c2 == 1 and a == 2 ) continue;
                        if( c3 == 0 and c1 == 1 and a == 2 ) continue;
                        dp[len+1][c2][c1][a] += dp[len][c3][c2][c1];
                        dp[len+1][c2][c1][a] %= MOD;
                    }
                }
            }
        }
    }

    int ans = 0;
    for( int c3 = 0; c3 < 4; ++c3 ){
        for( int c2 = 0; c2 < 4; ++c2 ){
            for( int c1 = 0; c1 < 4; ++c1 ){
                ans += dp[N][c3][c2][c1];
                ans %= MOD;
            }
        }
    }
    cout << ans << endl;

    return 0;
}

