bool good(string t)
{
    if (t.find("AGC") != string::npos)
        return false;

    FOR(i, 0, 3) {
        swap(t[i], t[i + 1]);
        if (t.find("AGC") != string::npos)
            return false;
        swap(t[i], t[i + 1]);
    }

    return true;
}

int f(int n, string tail)
{
    if (!good(tail))
        return 0;

    if (n == 0)
        return 1;

    auto key = PAIR(tail, n);
    if (dp.find(key) != dp.end())
        return dp[key];


    int ret = 0;
    string s = "ACGT";
    for (char c : s)
        {
            string newtail = tail.substr(1) + c;
            ret += f(n - 1, newtail);
            if (ret >= mod)
                ret -= mod;
        }

    return dp[key] = ret;
};

