  if(b2==0&&b1==2&&b==1) return 0;// ?ACGの場合
  if(b2==1&&b1==0&&b==2) return 0;// ?GACの場合
  if(now==N)return 1;
  //答えを再帰で求める
  long ans=0;
  for(int i=0;i<4;i++){
    ans+=judge(now+1,b2,b1,b,i);
  }
  return memo[now][b3][b2][b1][b]=ans%mod;
}
int main(){
  cin>>N;
  memset(memo,-1,sizeof(memo));
  cout<<judge(0,3,3,3,3)<<endl;
}

