const ull MOD = 1e9+7;

bool check(string s){

	string ss = s;
	if(ss.find("AGC") != string::npos){
		return false;
	}
	for(int i=0;i<s.size();++i){
		int j= i+1;
		ss = s;
		swap(ss[i],ss[j]);
		if(ss.find("AGC") != string::npos){
			return false;
		}
	}
	return true;
}

map<string,ull> ma[101];

ull dfs(ull k,string s){
	if(ma[k].find(s) != ma[k].end()) return ma[k][s];

	ull res =0;
	if( check(s) == false){
		res =  0;
	}else if(k == n){
		//cout << s << endl;
		res = 1;
	}else{
		res = 0;
		for(int i=0;i<ACGT.size();++i){
			int a = s.size()-3;
			int p = max(a,0);
			string ss = s.substr(p) + ACGT[i];
			res += dfs(k+1,ss);
			res %=MOD;
		}
	}
	res %=MOD;
	ma[k][s] = res;
	return res;
}



