                    dp[i][j] = max((ll)0,dp[i][j]);
                }else if(j%4==1&&(j/16)%4==2){
                    dp[i][j] -= dp[i-1][4*2+(j/4)%4];
                    dp[i][j] = max((ll)0,dp[i][j]);
                }

                if(j==16*0+4*2+1||j==6||j==33){
                    dp[i][j] = 0;
                }

                dp[i][j] %= 1000000007;
            }
