bool judge(std::string last4) {
  if (last4.substr(1, 3) == "AGC") return 0;

  for (int i=1; i<4; i++) {
    std::swap(last4[i-1], last4[i]);
    if (last4.substr(0, 3) == "AGC") return 0;
    if (last4.substr(1, 3) == "AGC") return 0;
    std::swap(last4[i-1], last4[i]);
  }

  return true;
}

struct Solver {
  int const N;
  std::vector<std::map<std::string, int>> cache;

  Solver(int N) : N(N), cache(N) {}

  int solv(int n=0, std::string&& last3="...") {
    if (n==N) return 1;

    if (cache[n].count(last3) > 0) return cache[n][last3];

    int& res = cache[n][last3];

    for (auto c: std::string("ACGT")) {
      std::string const last4 = last3 + c;
      if (judge(last4)) {
        res += solv(n+1, last4.substr(1, 3));
        res %= Mod;
      }
    }

    return res;
  }
};

