void solve()
{

    ll n;
    cin >> n;

    dp[0][0][0][0] = 1;
    for (int i = 0; i < n; i++)
    {
        for (int a = 0; a < 4; a++)
        {
            for (int b = 0; b < 4; b++)
            {
                for (int c = 0; c < 4; c++)
                {
                    for (int d = 0; d < 4; d++)
                    {
                        if (b == 1 && c == 2 && d == 3)
                        {
                            //AGC
                            continue;
                        }
                        if (b == 1 && c == 3 && d == 2)
                        {
                            //ACG
                            continue;
                        }
                        if (b == 2 && c == 1 && d == 3)
                        {
                            //GAC
                            continue;
                        }
                        if (a == 1 && c == 2 && d == 3)
                        {
                            //A?GC
                            continue;
                        }
                        if (a == 1 && b == 2 && d == 3)
                        {
                            //AG?C
                            continue;
                        }
                        dp[1 + 1][b][c][d] += dp[i][a][b][c];
                    }
                }
            }
        }
    }

    modint ans = 0;
    for (int a = 0; a < 4; a++)
    {
        for (int b = 0; b < 4; b++)
        {
            for (int c = 0; c < 4; c++)
            {
                ans += dp[n][a][b][c];
            }
        }
    }
    out(ans);
}

