const double pi=3.141592653589793;
const ll MOD=1e9+7;

int n;
ll dp[102][4][4][4];
int flag[102][4][4][4];

ll ddpp(int x,int y,int z,int w){
    if (flag[x][y][z][w]){
        return dp[x][y][z][w];
    }
    else{
        flag[x][y][z][w]=1;
        if (x==n){
            dp[x][y][z][w]=1;
        }
        else{
            if (z==1 && w==2){//末尾AG
                dp[x][y][z][w]=ddpp(x+1,z,w,1)+ddpp(x+1,z,w,2)+ddpp(x+1,z,w,0);
            }
            else if (z==2 && w==1){//末尾GA
                dp[x][y][z][w]=ddpp(x+1,z,w,0)+ddpp(x+1,z,w,1)+ddpp(x+1,z,w,2);
            }
            else if (z==1 && w==3){
                dp[x][y][z][w]=ddpp(x+1,1,3,1)+ddpp(x+1,1,3,0)+ddpp(x+1,1,3,3);
            }
            else if (y==1 && w==2){//AC
                dp[x][y][z][w]=ddpp(x+1,z,w,0)+ddpp(x+1,z,w,1)+ddpp(x+1,z,w,2);

            }
            else if (y==1 && z==2){
                dp[x][y][z][w]=ddpp(x+1,z,w,0)+ddpp(x+1,z,w,1)+ddpp(x+1,z,w,2);
            }
            else{
                dp[x][y][z][w]=ddpp(x+1,z,w,0)+ddpp(x+1,z,w,1)+ddpp(x+1,z,w,2)+ddpp(x+1,z,w,3);
            }
        }
        dp[x][y][z][w]%=MOD;
        return dp[x][y][z][w];
    }
}

int main() {
    cin>>n;
    ddpp(0,0,0,0);
    cout<<dp[0][0][0][0]<<endl;
    return 0;
}

