#include <algorithm>
#include <iostream>

using namespace std;

const int N = 2 + 3 + 3 + 3 + 4 + 4 + 4, A = 4, MD = 1000000007;

int tt[N][A], n;
bool eof[N];

void build(string *ss, int m) {
	static int ii[26];
	ii['A' - 'A'] = 0;
	ii['C' - 'A'] = 1;
	ii['G' - 'A'] = 2;
	ii['T' - 'A'] = 3;
	n = 2;
	for (int h = 0; h < m; h++) {
		int l = ss[h].length();
		int i = 1;
		for (int k = 0; k < l; k++) {
			int a = ii[ss[h][k] - 'A'];
			int &j = tt[i][a];
			if (j == 0)
				j = n++;
			i = j;
		}
		eof[i] = true;
	}
	fill(tt[0], tt[0] + A, 1);
	static int ff[N], qu[N];
	int head = 0, cnt = 0;
	ff[1] = 0, qu[head + cnt++] = 1;
	while (cnt) {
		int i = qu[cnt--, head++];
		int e = ff[i];
		for (int a = 0; a < A; a++) {
			int &j = tt[i][a];
			int f = tt[e][a];
			if (j == 0)
				j = f;
			else
				ff[j] = f, qu[head + cnt++] = j;
		}
	}
}

int main() {
	int l; cin >> l;
	string ss[6] = { "AGC", "ACG", "GAC", "AGGC", "AGTC", "ATGC" };
	build(ss, 6);
	static int dp[N], dq[N];
	dp[1] = 1;
	while (l--) {
		for (int i = 1; i < n; i++) {
			int x = dp[i];
			if (x == 0 || eof[i])
				continue;
			for (int a = 0; a < A; a++) {
				int j = tt[i][a];
				dq[j] = (dq[j] + x) % MD;
			}
		}
		for (int i = 0; i < n; i++)
			dp[i] = dq[i], dq[i] = 0;
	}
	int ans = 0;
	for (int i = 1; i < n; i++)
		if (!eof[i])
			ans = (ans + dp[i]) % MD;
	cout << ans << '\n';
	return 0;
}

