ll memo[100][64];
ll AGC_idx = 0 + 4 * 2 + 16 * 1;

bool ok(ll last4[]){
    ll _last4[4];

    rep(i, 4){
        rep(j, 4) _last4[j] = last4[j];
        if (i >= 1){
            _last4[i - 1] = last4[i];
            _last4[i] = last4[i - 1];
        }
        ll last4_idx1 = last4[0] + 4 * last4[1] + 16 * last4[2];
        ll last4_idx2 = last4[1] + 4 * last4[2] + 16 * last4[3];
        if (AGC_idx == last4_idx1 || AGC_idx == last4_idx2) return false;
    }    
    return true;
}

ll dfs(ll cnt, ll last3[], ll N){
    ll last3_idx = last3[0] + 4 * last3[1] + 16 * last3[2];

    if (cnt == N) return 1;
    if (memo[cnt][last3_idx] != 0) return memo[cnt][last3_idx];

    ll ret = 0;
    ll last4[4];
    rep(i, 3) last4[i] = last3[i];

    rep(c, 4){
        last4[3] = c;
        if (ok(last4)){
            ll nxt_last3[3];
            rep(j, 3) nxt_last3[j] = last4[j + 1];
            ret = (ret + dfs(cnt + 1, nxt_last3, N)) % mod;
        }
    }

    memo[cnt][last3_idx] = ret;

    return ret;

}

