int N;
map<pair<int, string>, ll> memo;

void dfs(int v, string last){
    if(v == N){
        memo[make_pair(v, last)] = 1;    
        return;
    }
    ll ret = 0;
    if(check(last, 'A')){
        string next = last;
        next.erase(next.begin());
        next += 'A';
        auto p = make_pair(v+1, next);
        if(memo[p] == 0)
            dfs(v+1, next);
        ret += memo[p];
        ret %= MOD;
    }
    if(check(last, 'G')){
        string next = last;
        next.erase(next.begin());
        next += 'G';
        auto p = make_pair(v+1, next);
        if(memo[p] == 0)
            dfs(v+1, next);
        ret += memo[p];
        ret %= MOD;
    }
    if(check(last, 'C')){
        string next = last;
        next.erase(next.begin());
        next += 'C';
        auto p = make_pair(v+1, next);
        if(memo[p] == 0)
            dfs(v+1, next);
        ret += memo[p];
        ret %= MOD;
    }
    if(check(last, 'T')){
        string next = last;
        next.erase(next.begin());
        next += 'T';
        auto p = make_pair(v+1, next);
        if(memo[p] == 0)
            dfs(v+1, next);
        ret += memo[p];
        ret %= MOD;
    }

    memo[make_pair(v, last)] = ret;
}

