typedef long long ll;
const int mod = 1000000007;

// 0:Tor未定, 1:C, 2:G, 3:A
// dp[i][j][k][l]   i桁目まで決めたとき、i桁目がkで、(i-1)桁目がjで、(i-2)桁目がlである場合の数
// 条件を満たさない場合は、0
ll dp[105][4][4][4];

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    // 場合の数を考えるときのdpテーブルの初期化
    dp[0][0][0][0] = 1;

    // dpテーブルを埋める
    for(int i = 0; i < n; ++i){
        // (i+1)桁目をTにする
        for(int j = 0; j < 4; ++j){
            for(int k = 0; k < 4; ++k){
                for(int l = 0; l < 4; ++l){
                    dp[i+1][0][j][k] = (dp[i+1][0][j][k] + dp[i][j][k][l]) % mod;
                }
            }
        }

        // (i+1)桁目をCにする(Cを入れられないのは、直前の並びが(AG, GA, AxG, AGx)のとき)
        for(int j = 0; j < 4; ++j){
            for(int k = 0; k < 4; ++k){
                // AG or GA
                if((j == 2 && k == 3) || (j == 3 && k == 2))    continue;
                for(int l = 0; l < 4; ++l){
                    // AxG or AGx
                    if((k == 2 && l == 3) || (j == 2 && l == 3))    continue;
                    dp[i+1][1][j][k] = (dp[i+1][1][j][k] + dp[i][j][k][l]) % mod;
                }
            }
        }

        // (i+1)桁目をGにする(Gを入れられないのは、直前の並びが(AC)のとき)
        for(int j = 0; j < 4; ++j){
            for(int k = 0; k < 4; ++k){
                if(j == 1 && k == 3)    continue;
                for(int l = 0; l < 4; ++l){
                    dp[i+1][2][j][k] = (dp[i+1][2][j][k] + dp[i][j][k][l]) % mod;
                }
            }
        }

        // (i+1)桁目をAにする
        for(int j = 0; j < 4; ++j){
            for(int k = 0; k < 4; ++k){
                for(int l = 0; l < 4; ++l){
                    dp[i+1][3][j][k] = (dp[i+1][3][j][k] + dp[i][j][k][l]) % mod;
                }
            }
        }
    }

    ll res = 0;
    for(int i = 0; i < 4; ++i){
        for(int j = 0; j < 4; ++j){
            for(int k = 0; k < 4; ++k){
                res = (res + dp[n][i][j][k]) % mod;
            }
        }
    }

    cout << res << endl;
}

