bool is_valid(string &s) {
  bool valid = s.find("AGC") == string::npos;
  for (int i = 1; i < s.size(); ++i) {
    swap(s[i - 1], s[i]);
    if (s.find("AGC") != string::npos) {
      valid = false;
    }
    swap(s[i - 1], s[i]);
  }

  return valid;
}

long long f(int n, string s) {
  if (!n) {
    return 1;
  }

  pair<int, string> key = {n, s};
  if (dp.count(key) == 0) {
    long long ret = 0;
