        if(prev1 == m['A'] && prev2 == m['G'] && prev3 == m['C']) return 0;
        else if(prev1 == m['A'] && prev2 == m['C'] && prev3 == m['G']) return 0;
        else if(prev1 == m['G'] && prev2 == m['A'] && prev3 == m['C']) return 0;
        else if(prev0 == m['A'] && prev2 == m['G'] && prev3 == m['C']) return 0;
        else if(prev1 == m['A'] && prev2 == m['G'] && prev4 == m['C']) return 0;

        else if(prev2 == m['A'] && prev3 == m['G'] && prev4 == m['C']) return 0;
        else if(prev2 == m['A'] && prev3 == m['C'] && prev4 == m['G']) return 0;
        else if(prev2 == m['G'] && prev3 == m['A'] && prev4 == m['C']) return 0;
        else if(prev1 == m['A'] && prev3 == m['G'] && prev4 == m['C']) return 0;
        else if(check) return 0;
        else return 1;
    }

        if(prev1 == m['A'] && prev2 == m['G'] && prev3 == m['C']) check = true;
        else if(prev1 == m['A'] && prev2 == m['C'] && prev3 == m['G']) check = true;
        else if(prev1 == m['G'] && prev2 == m['A'] && prev3 == m['C']) check = true;
        else if(prev0 == m['A'] && prev2 == m['G'] && prev3 == m['C']) check = true;
        else if(prev1 == m['A'] && prev2 == m['G'] && prev4 == m['C']) check = true;
        else if(prev2 == m['A'] && prev3 == m['G'] && prev4 == m['C']) check = true;
        else if(prev2 == m['A'] && prev3 == m['C'] && prev4 == m['G']) check = true;
        else if(prev2 == m['G'] && prev3 == m['A'] && prev4 == m['C']) check = true;
        else if(prev1 == m['A'] && prev3 == m['G'] && prev4 == m['C']) check = true;

    ll &ans = dp[idx][prev0][prev1][prev2][prev3][prev4][check];

    if(ans != -1) return ans;

    ans = 0;
    ans = (ans + rec(idx+1,prev1,prev2,prev3,prev4,m['A'],check))%MOD;
    ans = (ans + rec(idx+1,prev1,prev2,prev3,prev4,m['G'],check))%MOD;
    ans = (ans + rec(idx+1,prev1,prev2,prev3,prev4,m['C'],check))%MOD;
    ans = (ans + rec(idx+1,prev1,prev2,prev3,prev4,m['T'],check))%MOD;
    return ans;
}

