void Fill(A(&array)[N], const T &val) {
	std::fill((T*)array, (T*)(array + N), val);
}

ll N;
ll eps = 1e9 + 7;

ll epsf(ll v) {
	if (v < 0) return epsf(v + eps);
	return v % eps;
}

void solve() {
	vector<ll> A(N, 0), G(N, 0), C(N, 0), T(N, 0);
	vector<ll> AG(N, 0), GA(N, 0), AC(N, 0), AT(N, 0), AA(N, 0);
	vector<ll> ATG(N, 0), AGT(N, 0), AGG(N, 0);

	ll ans = 0;

	rep(i, N) {
		if (i == 0) {
			A[i] = 1; G[i] = 1; C[i] = 1; T[i] = 1;
			ans += 4;
			continue;
		}
		if (i == 1) {
			A[i] = ans; G[i] = ans; C[i] = ans; T[i] = ans;
			AG[i] = 1; GA[i] = 1; AC[i] = 1; AT[i] = 1; AA[i] = 1;
			ans *= 4;
			continue;
		}
		if (i == 2) {
			A[i] = ans; T[i] = ans; G[i] = ans - 1; C[i] = ans - 2;
			AG[i] = A[i - 1]; GA[i] = G[i - 1];
			AC[i] = A[i - 1] - GA[i - 1]; AT[i] = A[i - 1];
			AA[i] = A[i - 1];
			ATG[i] = AT[i - 1];
			AGT[i] = AG[i - 1];
			AGG[i] = AG[i - 1];
			ans = ans * 4 - 3;
			continue;
		}

		A[i] = ans;
		T[i] = ans;
		G[i] = epsf(ans - AC[i - 1]);
		C[i] = epsf(ans - AG[i - 1] - GA[i - 1] - ATG[i - 1] - AGT[i - 1] - AGG[i - 1]);

		AG[i] = A[i - 1];
		GA[i] = G[i - 1];
		AC[i] = epsf(A[i - 1] - GA[i - 1]);
		AT[i] = A[i - 1];
		AA[i] = A[i - 1];

		ATG[i] = AT[i - 1];
		AGT[i] = AG[i - 1];
		AGG[i] = AG[i - 1];
		ans = epsf(ans * 4 - AG[i - 1] - GA[i - 1] - AC[i - 1] - ATG[i - 1] - AGT[i - 1] - AGG[i - 1]);
	}

	cout << ans;

	return;
}

int main() {

	cin >> N;

	solve();
	cout << endl;
	return 0;
}

