              }
            }
          }
        }
      }
    }
  }

  ll n_bad=0;

  for (int i=0;i<256;++i){
    n_bad+=dp[N][i][1];
    n_bad%=mod;
  }

  ll ans=power(4,N)-ans+mod;
  ans%=mod;

  return ans;
}

