int cnt=0;

bool checkagc(int i1, int i2, int i3)
{
    if(i1==0 and i2==2 and i3==1) return 1;
    return 0;
}

bool check(int i1, int i2, int i3)
{
    if(checkagc(i1, i2, i3) or checkagc(i1, i3, i2) or checkagc(i2, i1, i3)) return 1;
    return 0;
}



int solve(int prev1, int prev2, int prev3, int ind)
{
    if(ind==n) {
        if(check(prev1, prev2, prev3)) return 0;
        return 1;
    }

    int &memo=dp[prev1][prev2][prev3][ind];
    if(memo!=-1) return memo;

    if(check(prev1, prev2, prev3)) return 0;

    int ans=0;

    for(int i=0; i<4; i++) {
        if(checkagc(prev1, prev2, i) or checkagc(prev1, prev3, i)) continue;
        ans=add(ans, solve(prev2, prev3, i, ind+1));
    }
    return memo=ans;
}

