int main(){
    int N,i,c0,c1,c2,c3,ans=0;
    cin >> N;
    for(c1=0;c1<4;c1++){
        for(c2=0;c2<4;c2++){
            for(c3=0;c3<4;c3++){
                if(c1==1 && c2==2 && c3==0) continue;
                if(c1==2 && c2==0 && c3==1) continue;
                if(c1==2 && c2==1 && c3==0) continue;
                dp[3][c1][c2][c3] = 1;
            }
        }
    }
    for(i=4;i<=N;i++){
        for(c0=0;c0<4;c0++){
            for(c1=0;c1<4;c1++){
                for(c2=0;c2<4;c2++){
                    if(c0==1 && c1==2 && c2==0) continue;
                    if(c0==2 && c1==0 && c2==1) continue;
                    if(c0==2 && c1==1 && c2==0) continue;
                    for(c3=0;c3<4;c3++){
                        if(c0==2 && c2==1 && c3==0) continue;
                        if(c0==2 && c1==1 && c3==0) continue;
                        dp[i][c0][c1][c2] += dp[i-1][c1][c2][c3];
                        dp[i][c0][c1][c2] %= MOD;
                    }
                }
            }
        }
    }
    for(c1=0;c1<4;c1++){
        for(c2=0;c2<4;c2++){
            for(c3=0;c3<4;c3++){
