bool CanConcatinate(const string& s, char c) {
  if (s.size() < 2) return true;
  if (s.size() == 2) {
    if (s == "AG" && c == 'C') return false;
    if (s == "GA" && c == 'C') return false;
    if (s == "AC" && c == 'G') return false;
    return true; 
  } else if (s.size() == 3) {
    if (s[0] == 'A' && s[2] == 'G'&& c == 'C') return false;
    if (s[0] == 'A' && s[1] == 'G'&& c == 'C') return false;
    return CanConcatinate(s.substr(1), c);
  } else {
    return CanConcatinate(s.substr(1), c);
  }
}

