    //0 means A, 1 means G, 2 means C, 3 means T;

    for(int i = 0; i < n; i++){
        for(int left = 0; left < 4; left++){
            for(int mid = 0; mid < 4; mid++){
                for(int right = 0; right < 4; right++){
                    for(int now = 0; now < 4; now++){
                        if(mid == 0  && right == 1 && now == 2) continue;
                        if(mid == 1  && right == 0 && now == 2) continue;
