                        if(left == 0 && right == 1 && now == 2) continue;
                        if(left == 0 && mid   == 1 && now == 2) continue;

                        (dp[i+1][now][right][mid] += dp[i][right][mid][left]) %= mod;

                    }
                }
            }
        }
    }

    ll ans = 0;
    for(int i = 0; i < 4; i++){
        for(int j = 0; j < 4; j++){
            for(int k = 0; k < 4; k++){
                ans += dp[n][i][j][k];
            }
        }
    }

    cout << (ans % mod) << endl;
