enum ATGC{N,A,T,G,C};
UL f(ATGC a,ATGC b,ATGC c, ATGC d){
  return ((a*5+b)*5+c)*5+d;
}

void Solve(){
  ULL M = 1000000007;
  ULL dp[101][625] = {};
  dp[0][0] = 1;
  vector<UL> NGW = {
    f(A,G,C,A),
    f(A,G,C,T),
    f(A,G,C,G),
    f(A,G,C,C),
    f(G,A,C,A),
    f(G,A,C,T),
    f(G,A,C,G),
    f(G,A,C,C),
    f(A,C,G,A),
    f(A,C,G,T),
    f(A,C,G,G),
    f(A,C,G,C),
    f(A,G,A,C),
    f(A,G,T,C),
    f(A,G,G,C),
    f(A,A,G,C),
    f(T,A,G,C),
    f(G,A,G,C),
    f(C,A,G,C),
    f(A,T,G,C),
    f(A,G,G,C),
    f(A,C,G,C),
    f(A,G,A,C),
    f(T,G,A,C),
    f(G,G,A,C),
    f(C,G,A,C),
    f(A,A,C,G),
    f(T,A,C,G),
    f(C,A,C,G),
    f(N,A,G,C),
    f(N,A,C,G),
    f(N,G,A,C),
  };
  for(UL i = 1; i <= 100; i++){
    for(UL j = 0; j < 625; j++){
      dp[i][(j*5+1)%625] += dp[i-1][j];
      dp[i][(j*5+2)%625] += dp[i-1][j];
      dp[i][(j*5+3)%625] += dp[i-1][j];
      dp[i][(j*5+4)%625] += dp[i-1][j];
    }
    for(UL NG : NGW){
      dp[i][NG] = 0;
    }
    for(UL j = 0; j < 625; j++){
      dp[i][j] %= M;
    }
  }
  ULL ans = 0;
  UL N; cin >> N;
  for(UL j = 0; j < 625; j++){
    ans += dp[N][j];
  }
  cout << ans % M << endl;
}
int main(){
  Solve(); return 0;
}

