mint cnt(int n,int a,int b,int c) {
    if(m[n][a][b][c] != linf) return m[n][a][b][c];
    mint ret = 0;
    rep(i,4) ret += cnt(n-1,i,a,b);
    if(c == 2) {
        if((a == 0 && b == 1) || (a == 1 && b == 0)) ret = 0;
        else if(a == 1 || b == 1) ret -= cnt(n-1,0,a,b);
    } else if(c == 1) {
        if(a == 0 && b == 2) ret = 0;
    }
    m[n][a][b][c] = ret;
    return ret;
}

