}

bool shaffle2(int a,int b,int c,int d) {
    if(a == 0 && b == 1 && c == 2) {
        return false;
    }
    if(a == 0 && b == 2 && c == 1 && d == 0) {
        return false;
    }
    if(a == 1 && b == 0 && c == 2 && d == 0) {
        return false;
    }
    return true;
}

bool shaffle(int a,int b,int c,int d) {
    if((!shaffle2(a,b,c,0)) || (!shaffle2(b,c,d,0))) {
        return false;
    }
    swap(a,b);
    if((!shaffle2(a,b,c,1)) || (!shaffle2(b,c,d,1))) {
        return false;
    }
    swap(a,b);
    swap(b,c);
    if((!shaffle2(a,b,c,1)) || (!shaffle2(b,c,d,1))) {
        return false;
    }
    swap(b,c);
    swap(c,d);
    if((!shaffle2(a,b,c,1)) || (!shaffle2(b,c,d,1))) {
        return false;
    }
    swap(c,d);
    return true;
}

