constexpr int mod = 1000000007;
class mint {
private:
    std::int64_t m_x;
public:
    mint(std::int64_t m_x = 0) : m_x(m_x% mod) {}
    std::int64_t get() { return m_x; }
    mint& operator+=(const mint a) {
        if ((m_x += a.m_x) >= mod) m_x -= mod;
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((m_x += mod - a.m_x) >= mod) m_x -= mod;
        return *this;
    }
    mint& operator*=(const mint a) {
        (m_x *= a.m_x) %= mod;
        return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }

    mint pow(const std::int64_t t) const {
        if (!t) return 1;
        mint a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }
    // for prime mod
    mint inv() const {
        return pow(mod - 2);
    }
    mint& operator/=(const mint a) {
        return (*this) *= a.inv();
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res /= a;
    }
};

