bool cont(string s) {
    forn(i, s.size()) {
        if (i + 2 > s.size()) return false;
        if (s.substr(i, 3) == "AGC") return true;
    }
    return false;
}

void fin(string &s) {
    if (s.size() >= 3) {
        bool ok = cont(s);
        forne(i, 1, s.size()) {
            swap(s[i], s[i - 1]);
            if (cont(s)) {
                ok = true;
                swap(s[i], s[i - 1]);
                break;
            }
            swap(s[i], s[i - 1]);
        }
        if (ok) bad.insert(s);
    }
    if (s.size() == 5) return;
    for (auto &e : good) {
        s += e;
        fin(s);
        s.pop_back();
    }
}

ll mod = 1e9 + 7, n;
map<pair<string, int>, ll> dp;

ll solve(string lst, int i) {
    if (bad.count(lst)) return 0;
    if (i == n) return 1;
    if (dp.count({lst, i}))
        return dp[{lst, i}];
    dp[{lst, i}] = 0;
    ll &cur = dp[{lst, i}];
    if (lst.size() == 5)
        lst = lst.substr(1, 4);
    for (auto &e : good) {
        lst += e;
        cur = (cur + solve(lst, i + 1)) % mod;
        assert(lst.size());
        lst.pop_back();
    }
    return cur;
}

