void Solve() {

	li(n);
	vmll a(n, 0);
	vmll g(n, 0);
	vmll c(n, 0);
	vmll t(n, 0);
	vmll ag(n, 0);
	vmll ac(n, 0);
	vmll aa(n, 0);
	vmll at(n, 0);
	vmll ga(n, 0);
	vmll aag(n, 0);
	vmll aga(n, 0);
	vmll atg(n, 0);
	vmll agt(n, 0);
	a[0] = 1;
	g[0] = 1;
	c[0] = 1;
	t[0] = 1;
	FOR(i, 0, n - 2) {
		t[i + 1] = a[i] + g[i] + c[i] + t[i];
		a[i + 1] = t[i + 1];
		g[i + 1] = t[i + 1] - ac[i];
		c[i + 1] = t[i + 1] - ag[i] - ga[i] - aag[i] - atg[i] - agt[i];
		ag[i + 1] = a[i];
		ac[i + 1] = a[i] - ga[i];
		aa[i + 1] = a[i];
		at[i + 1] = a[i];
		ga[i + 1] = g[i];
		aag[i + 1] = aa[i];
		aga[i + 1] = ag[i];
		atg[i + 1] = at[i];
		agt[i + 1] = ag[i];
	}
	sal(a[n - 1] + g[n - 1] + c[n - 1] + t[n - 1]);

}

#include <bits/stdc++.h>
using namespace std;

#define MP make_pair
#define PB push_back
#define ALL(x)      (x).begin(),(x).end()
#define REP(i,n)    for(int i=0;i<(n);i++)
#define REP1(i,n)   for(int i=1;i<(n);i++)
#define REP2(i,d,n) for(int i=(d);i<(n);i++)
#define RREP(i,n)   for(int i=(n);i>=0;i--)
#define CLR(a)      memset((a),0,sizeof(a))
#define MCLR(a)     memset((a),-1,sizeof(a))
#define RANGE(x,y,maxX,maxY) (0 <= (x) && 0 <= (y) && (x) < (maxX) && (y) < (maxY))

typedef long long LL;
typedef unsigned long long ULL;
typedef vector<int> VI;
typedef vector<VI > VVI;
typedef vector<string> VS;
typedef vector<LL> VLL;
typedef pair<int,int> PII;

const int INF = 0x3f3f3f3f;
const LL INFL = 0x3f3f3f3f3f3f3f3fLL;
const double EPS = 1e-9;

const int DX[]={1,0,-1,0},DY[]={0,-1,0,1};

const LL MOD = 1000000007;

void solve(long long N){
    map<string, LL> memo, tmp;

    REP(i, 4) memo[""] = 1LL;
    REP(i, N) {
        for (auto it = memo.begin(); it != memo.end(); ++it) {
            string now = it->first;
            string next = "";
            for(int j = (now.length() == 3 ? 1 : 0); j < now.length(); j++) {
                next += now[j];
            }

            // 'a'
            if(tmp.count(next + 'a') == 0) tmp[next + 'a'] = 0;
            tmp[next + 'a'] += it->second;
            tmp[next + 'a'] %= MOD;

            // 'c'
            if(next != "ag" && next != "ga" && !(now.length() == 3 && now[0] == 'a' && now[1] == 'g')
                && !(now.length() == 3 && now[0] == 'a' && now[2] == 'g')) {
                if(tmp.count(next + 'c') == 0) tmp[next + 'c'] = 0;
                tmp[next + 'c'] += it->second;
                tmp[next + 'c'] %= MOD;
            }

            // 'g'
            if(next != "ac") {
                if(tmp.count(next + 'g') == 0) tmp[next + 'g'] = 0;
                tmp[next + 'g'] += it->second;
                tmp[next + 'g'] %= MOD;
            }

            // 't'
            if(tmp.count(next + 't') == 0) tmp[next + 't'] = 0;
            tmp[next + 't'] += it->second;
            tmp[next + 't'] %= MOD;
        }

        memo = tmp;
        tmp.clear();
        // for(auto it = memo.begin(); it != memo.end(); it++) {
        //     cout << it->first << " : " << it->second << endl;
        // }
    }

    LL ans = 0;
    for(auto it = memo.begin(); it != memo.end(); it++) {
        ans += it->second;
        ans %= MOD;
    }

    cout << ans << endl;
}

int main(){
    long long N;
    scanf("%lld",&N);
    solve(N);
    return 0;
}

