using namespace std;

const int N=101;
const long long inf=1000000007;

int n;
vector<int>g[4][4][4];
int f[N][4][4][4];

bool check(vector<int> v)
{
	for(int i=0;i<2;++i)
	{
		if(v[i]==0&&v[i+1]==2&&v[i+2]==1)return false;
	}
	for(int j=0;j<3;++j)
	{
		swap(v[j],v[j+1]);
		for(int i=0;i<2;++i)
		{
			if(v[i]==0&&v[i+1]==2&&v[i+2]==1)return false;
		}
		swap(v[j],v[j+1]);
	}
	return true;
}

void init()
{
	for(int x=0;x<4;++x)
	{
		for(int y=0;y<4;++y)
		{
			for(int z=0;z<4;++z)
			{
				for(int c=0;c<4;++c)
				{
					vector<int>v;
					v.push_back(x);
					v.push_back(y);
					v.push_back(z);
					v.push_back(c);
					if(check(v))g[x][y][z].push_back(c);
				}
			}
		}
	}
}

int main()
{
	cin>>n;
	init();
	for(int i=0;i<4;++i)for(int j=0;j<4;++j)for(int k=0;k<4;++k)f[3][i][j][k]=1;
	f[3][0][2][1]=f[3][2][0][1]=f[3][0][1][2]=0;
	for(int num=3;num<n;++num)
	{
		for(int i=0;i<4;++i)
		{
			for(int j=0;j<4;++j)
			{
				for(int k=0;k<4;++k)
				{
					for(int s=0;s<g[i][j][k].size();++s)
					{
						int c=g[i][j][k][s];
						f[num+1][j][k][c]=(f[num][i][j][k]+f[num+1][j][k][c])%inf;
					}
				}
			}
		}
	}
	int ret=0;
	for(int i=0;i<4;++i)
	{
		for(int j=0;j<4;++j)
		{
			for(int k=0;k<4;++k)
			{
				ret=(ret+f[n][i][j][k])%inf;
			}
		}
	}
	cout<<ret;
}

