bool isvalid(ll n4,ll n3,ll n2,ll n1){
	if(n3==0 && n2==2 && n1==1)return false;
	if(n3==0 && n2==1 && n1==2)return false;
	if(n3==2 && n2==0 && n1==1)return false;
	if(n4==0 && n3==2 && n2==1)return false;
	if(n4==0 && n3==1 && n2==2)return false;
	if(n4==2 && n3==0 && n2==1)return false;
	if(n4==0 && n3==2 && n1==1)return false;
	if(n4==0 && n2==2 && n1==1)return false;
	return true;
}

Modint updatedp(ll size,ll n4,ll n3,ll n2,ll n1){
	if(!isvalid(n4,n3,n2,n1))return 0;
	if(size<=4)return 1;
	if(dp[size][n4][n3][n2][n1]!=0)return dp[size][n4][n3][n2][n1];

	Modint ans=0;
	rep(i,4){
		Modint t=updatedp(size-1,i,n4,n3,n2);
		ans+=t;
		debug(t);
	}

	return dp[size][n4][n3][n2][n1]=ans;
}


void solve() {
	scanf("%lld", &N);

	Modint ans = 0;

	dp.assign(N+1, vector<vector<vector<vector<Modint>>>>(4, vector<vector<vector<Modint>>>(4, vector<vector<Modint>>(4, vector<Modint>(4, 0)))));

	if(N==3){
		rep(b,4)rep(c,4)rep(d,4){
			ans+=updatedp(N,-1,b,c,d);
		}
	}else{
		rep(a,4)rep(b,4)rep(c,4)rep(d,4){
			ans+=updatedp(N,a,b,c,d);
		}
	}

	printf("%lld\n", ans);
}

