		dp[i] = (dp[i] - dp[i - 3] + MOD) % MOD;
		if (i >= 4) {
			dp[i] = (dp[i] - dp[i - 4] + MOD) % MOD;
			dp[i] = (dp[i] - dp[i - 4] + MOD) % MOD;
			dp[i] = (dp[i] - dp[i - 4] + MOD) % MOD;
		}
		dp[i] += solve(i);
	}
	cout << dp[n] << "\n";
	//system("pause");
	return 0;
}

