ll dp[101][6][6][6];

int main(){
    int N; cin >> N;
    dp[0][0][0][0] = 1;
    for(int i=0;i<N;i++){
        for(int a=0;a<=4;a++){
            for(int b=0;b<=4;b++){
                for(int c=0;c<=4;c++){
                    for(int d=1;d<=4;d++){
                        if(b==1 && c==3 && d==2) continue; // AGC
                        if(a==1 && c==3 && d==2) continue; // A*GC
                        if(b==3 && c==1 && d==2) continue; // GAC
                        if(b==1 && c==2 && d==3) continue; // ACG
                        if(a==1 && b==3 && d==2) continue; // AG*C

                        dp[i+1][b][c][d] += dp[i][a][b][c];
                        dp[i+1][b][c][d] %= mod;
                    }
                }
            }
        }
    }

    ll sum = 0;
    for(int i=1;i<=4;i++){
        for(int j=1;j<=4;j++){
            for(int k=1;k<=4;k++){
                sum += dp[N][i][j][k];
                sum %= mod;
            }
        }
    }
    cout << sum << endl;
}

