inline void rd(int &x){
  int k, m=0;
  x=0;
  for(;;){
    k = getchar_unlocked();
    if(k=='-'){
      m=1;
      break;
    }
    if('0'<=k&&k<='9'){
      x=k-'0';
      break;
    }
  }
  for(;;){
    k = getchar_unlocked();
    if(k<'0'||k>'9'){
      break;
    }
    x=x*10+k-'0';
  }
  if(m){
    x=-x;
  }
}
inline void wt_L(char a){
  putchar_unlocked(a);
}
inline void wt_L(int x){
  char f[10];
  int m=0, s=0;
  if(x<0){
    m=1;
    x=-x;
  }
  while(x){
    f[s++]=x%10;
    x/=10;
  }
  if(!s){
    f[s++]=0;
  }
  if(m){
    putchar_unlocked('-');
  }
  while(s--){
    putchar_unlocked(f[s]+'0');
  }
}
inline void wt_L(mint x){
  int i;
  i = (int)x;
  wt_L(i);
}
template<class S> struct AhoCorasick_Sum{
  S *sum;
  int alphabet, *failed, mem, node, **nx;
  void init(void){
    int i;
    node = 1;
    for(i=0;i<alphabet;i++){
      nx[0][i] = -1;
    }
    failed[0] = 0;
    sum[0] = 0;
  }
  void malloc(const int n, const int k){
    int i;
    malloc2d(&nx,n,k);
    malloc1d(&failed,n);
    malloc1d(&sum,n);
    node = n;
    alphabet = k;
    init();
  }
  void free(void){
    free2d(nx);
    free1d(failed);
    free1d(sum);
  }
  template<class T> void addWord(const T word[], const int len, S val){
    int i, j, k, now=0;
    for(i=0;i<len;i++){
      if(nx[now][word[i]]==-1){
        k = node++;
        nx[now][word[i]] = k;
        for(j=0;j<alphabet;j++){
          nx[k][j] = -1;
        }
        sum[k] = 0;
      }
      now = nx[now][word[i]];
    }
    sum[now] += val;
  }
  void construct(void *mem = wmem){
    int i, j, k, now, *q, qe, qs;
    q = (int*) mem;
    qs = qe = 0;
    now = 0;
    for(k=0;k<alphabet;k++){
      if(nx[now][k] != -1){
        q[qe++] = nx[now][k];
        failed[ nx[now][k] ] = now;
      }
    }
    while(qs < qe){
      now = q[qs++];
      for(k=0;k<alphabet;k++){
        if(nx[now][k] != -1){
          i = failed[now];
          while(i){
            if(nx[i][k] != -1){
              break;
            }
            i = failed[i];
          }
          if(nx[i][k] != -1){
            i = nx[i][k];
          }
          failed[ nx[now][k] ] = i;
          sum[ nx[now][k] ] += sum[i];
          q[qe++] = nx[now][k];
        }
      }
    }
  }
  template<class T> inline int next(const int n, const T c){
    int i, now;
    now = n;
    if(nx[n][c]!=-1){
      return nx[n][c];
    }
    while(now && nx[now][c]==-1){
      now=failed[now];
    }
    if(nx[now][c]!=-1){
      now = nx[now][c];
    }
    return nx[n][c] = now;
  }
}
