class RecordedPattern {
public:
	std::vector<std::string> vStrPtns;
	std::vector<unsigned long long> vPtnCnt;

	RecordedPattern() {}
	~RecordedPattern() {}


	void set(const char* szPtn, unsigned long long ptnCnt)
	{
		vStrPtns.push_back(szPtn);
		vPtnCnt.push_back(ptnCnt);
	}

	bool match(const char* szPtn, unsigned long long & ptnCnt)
	{
		bool isMatch = false;
		int strCnt = vStrPtns.size();

		for (int i = 0; i < strCnt; i++) {
			if (vStrPtns[i] == szPtn) {
				isMatch = true;
				ptnCnt = vPtnCnt[i];
				break;
			}
		}
		return isMatch;
	}
};

static RecordedPattern vRecords[100];

bool isAvailable(const std::string & targ)
{
	bool avail = true;
	int len = targ.length();

	if ((strstr(targ.c_str(), "AGC")) ||
		(strstr(targ.c_str(), "GAC")) ||
		(strstr(targ.c_str(), "ACG"))) {
		avail = false;
	}
	else if ((len > 3) && (targ.c_str()[0] == 'A') && (targ.c_str()[3] == 'C')) {
		if ((targ.c_str()[1] == 'G') || (targ.c_str()[2] == 'G')) {
			avail = false;
		}
	}
	return avail;
}

unsigned long long decideChar(int maxN, int szIdx, const char * szBfr)
{
	static const char available[] = { 'A', 'C', 'G', 'T' };
	static const int TmpSzLen = 4;

	int chkCnt = (TmpSzLen > szIdx) ? szIdx : TmpSzLen;
	char mkStr[TmpSzLen + 1] = { 0 };
	unsigned long long patternCnt = 0;

	if (szIdx >= maxN) {
		return 1;
	}


	if (vRecords[szIdx - 1].match(szBfr, patternCnt)) {
		return patternCnt;
	}

	int cpyOfs = 0;
	if (chkCnt >= TmpSzLen) cpyOfs = 1;

	for (int j = 0; j < (chkCnt - cpyOfs); j++) {
		mkStr[j] = szBfr[j + cpyOfs];
	}

	unsigned long long tmpRet = 0;
	for (int i = 0; i < charKind; i++) {
		tmpRet = 0;
		mkStr[chkCnt - cpyOfs] = available[i];

		std::string chk = mkStr;
		if (isAvailable(chk)) {
			tmpRet = decideChar(maxN, szIdx + 1, mkStr);
		}
		patternCnt += tmpRet;
	}

	vRecords[szIdx - 1].set(szBfr, patternCnt);

	return patternCnt;
}

