ll memo[101][4][4][4];

void init_memo() {
  REP(i, 101) REP(j, 4) REP(k, 4) REP(l, 4) memo[i][j][k][l] = -1;
}

ll dfs(int depth, int n, std::vector<char> three) {
  if (memo[depth][three[0]][three[1]][three[2]] != -1) {
    return memo[depth][three[0]][three[1]][three[2]];
  }
  if (depth == n) {
    return 1;
  }
  ll ret = 0;
  REP(c, 4) {
    std::vector<char> four(4); 
    four[0] = three[0];
    four[1] = three[1];
