    nthree[1] = three[2];
    nthree[2] = (char)c;
    if (check(four)) {
      ret = (ret + dfs(depth + 1, n, nthree)) % MOD;
    }
  }
  memo[depth][three[0]][three[1]][three[2]] = ret;
  return ret;
}

