bool bad3( long a, long b, long c) {
    if(a==0 && b==1 && c==2) {
        return true;
    }
    return false;
}

bool bad4( long a, long b, long c, long d) {
    if( bad3(a,b,c) || bad3(b,c,d) || bad3(b,a,c) || bad3(a,c,d) || bad3(a,b,d) || bad3(b,d,c) || bad3(a,c,b) || bad3(c,b,d)) return true;
    return false;
}

ll calc( long n ) {
    if(n<2) return 0;

    long i, k;
    for(i=0; i<n; i++) {
        for(k=0; k<64; k++) {
            dp[i][k]=0;
        }
    }

    for(k=0; k<64; k++) {
        long tmp=k;
        long a=tmp%4; tmp/=4;
        long b=tmp%4;
        long c=tmp/4;
        if(bad3(a,b,c) || bad3(b,a,c) || bad3(a,c,b)) continue;
        dp[2][k]=1;
    }

    for(i=2; i<n-1; i++) {
        for(k=0; k<64; k++) {
            long tmp=k;
            long a=tmp%4; tmp/=4;
            long b=tmp%4;
            long c=tmp/4;
            if(bad3(a,b,c)) continue;

            long d;
            for(d=0; d<4; d++) {
                if(bad4(a,b,c,d)) {
                    //printf("%ld%ld%ld%ld\n", a,b,c,d);
                    continue;
                }

                long next = b+c*4+d*16;
                dp[i+1][next] = (dp[i+1][next] + dp[i][k])%MOD;
            }
        }
    }

    ll ans = 0;
    for(k=0; k<64; k++) {
        ans = (ans + dp[n-1][k])%MOD;
    }
    return ans;
}

