        return 1;
    }

    auto cur = make_pair(i, s);

    if (memo.count(cur)) {
        return memo[cur];
    }

    ll ret = 0;

    string t = s.substr(1);
    ret = (ret + dfs(i + 1, t + 'A')) % mod;
    ret = (ret + dfs(i + 1, t + 'T')) % mod;

    if (t != "AC") {
        ret = (ret + dfs(i + 1, t + 'G')) % mod;
