template<LL mod>
struct GaloisFieldOperators {
    static LL Add(LL lhs, LL rhs) { return (lhs + rhs) % mod; };
    static LL Mul(LL lhs, LL rhs) { return (lhs * rhs) % mod; };
    static LL IdAdd() { return 0; };
    static LL IdMul() { return 1; };
    static LL Opposite(LL value) { return ((-value % mod) + mod) % mod; };
    static bool Less(LL lhs, LL rhs) { return lhs < rhs; };
    static LL Power(LL value, LL n) {
        LL res = IdMul();
        while (n > 0) {
            if (n & 1) res = Mul(res, value);
            value = Mul(value, value); n >>= 1;
        }
        return res;
    }
    static LL Reciprocal(LL value) { return Power(value, mod-2); }
};

const LL MOD = 1e9+7;
using GaloisField = AlgStruct<LL, GaloisFieldOperators<MOD>>;


