ll dp(int n){
  if (n==0){return 1;}
  else if(n==1){return 4;}
  else if(n==2){return 16;}
  else if(n==3){return 61;}
  else{return dp(n-4)*256-dp(n-4)*3-dp(n-3)*3;}
}

int main(){
  int N;cin>>N;
  ll x=dp(N);
  cout << x<< endl;
  return 0;
}

