      const char *next_ch = "AGCT";
      rep(j, 4) {
        if (CanConcatenate(e.first, next_ch[j])) {
          string s = e.first + next_ch[j];
          if (s.size() > 4) s = s.substr(1);
          dp[i+1][s] += e.second;
          dp[i+1][s] %= mod; 
        }
      }
    }
  }
  ll ans = 0;
  for (auto& e : dp[n-1]) {
    ans += e.second;
    ans %= mod;
  }
  cout << ans << endl;
  return 0;
}

