int main() {
    cin>>n;

    dp[0][0][0][0] = 1LL;

    for(int i=0;i<n;i++) {
        for(int f=0;f<5;f++) {
            for(int s=0;s<5;s++) {
                for(int l=0;l<5;l++) {
                    if(dp[i][f][s][l] == 0) continue;
                    for(int d=1;d<=4;d++) {
                        // extend with character D
                        if(check_state(s,l,d) && check2(f,s,d) && check2(f, l, d) && check2(l, s, d)) {
                            dp[i+1][s][l][d] += dp[i][f][s][l];
                            dp[i+1][s][l][d] %= mod;
                        }
                    }
                }
            }
        }
    }

    ll result = 0LL;
    for(int f=1;f<=4;f++) {
        for(int s=1;s<=4;s++) {
            for(int l=1;l<=4;l++) {
