typedef long long ll;
class Solver{
public:
    static const int MAXN=1e2+10;
    static const ll MOD=1e9+7;
    int N;
    const char s[5]="ACGT";
    ll dp[MAXN][4][4][4];
    bool check(int i,int j,int k){
        string r="";
        r+=s[i];
        r+=s[j];
        r+=s[k];
        if(r=="AGC")return false;
        return true;
    }
    void solve(){
        cin>>N;
        for(int i=0;i<4;i++){
            for(int j=0;j<4;j++){
                for(int k=0;k<4;k++){
                    if(check(i,j,k)&&check(i,k,j)&&check(j,i,k))
                    dp[3][i][j][k]=1;
                }
            }
        }
        for(int l=4;l<=N;l++){
            for(int i=0;i<4;i++){
                for(int j=0;j<4;j++){
                    for(int k=0;k<4;k++){
                        for(int u=0;u<4;u++){
                            if(check(i,j,k)&&check(i,k,j)&&check(j,i,k)&&check(u,i,k)&&check(u,j,k)){
                                dp[l][i][j][k]=(dp[l][i][j][k]+dp[l-1][u][i][j])%MOD;
                            }
                        }
                    }
                }
            }
        }
        ll ans=0;
        for(int i=0;i<4;i++){
            for(int j=0;j<4;j++){
                for(int k=0;k<4;k++){
                    ans=(ans+dp[N][i][j][k])%MOD;
                }
            }
        }
        cout<<ans;
    }
};
int main()
{
    // freopen("in.txt","r",stdin);
    (new Solver())->solve();
}

