bool contain(string s) {
	if (s.substr(0, 3) == "AGC") {
		return true;
	}
	if (s.substr(1, 3) == "AGC") {
		return true;
	}
	return false;
}

string add(string s, char c) {
	string res = s+c;
	if (contain(res)) {
		return "";
	}
	for (int i = 0; i < 4; i++) {
		string tes = res;
		swap(tes[i], tes[i+1]);
		if (contain(tes)) {
			return "";
		}
	}
	return res.substr(1);
}

