struct acgt{
    int ans[4][4][4];

    int sum(){
        int result;
        loop(i,4){
            loop(j,4){
                loop(k,4){
                    if(i == 2 && j == 0 && k == 1) continue;
                    if(i == 0 && j == 1 && k == 2) continue;
                    if(i == 0 && j == 2 && k == 1) continue;
                    result += ans[i][j][k];
                    result %= mod;
                }
            }
        }

        return result;
    };
};


acgt three(){
