                if(j == 0 and k == 2 and nd == 1) continue; // ACG
                if(i == 0 and k == 1 and nd == 2) continue; // A*GC
                if(i == 0 and j == 1 and nd == 2) continue; // AG*C
                ndp[j][k][nd] += dp[i][j][k];
