}

vector<vector<long long>> pow(vector<vector<long long>> a, int r) {
    if (r == 1) {
        return a;
    }
    if (r % 2 == 1) {
        auto b = pow(a, r-1);
        return mul(a, b);
    }
    auto b = pow(a, r/2);
    return mul(b, b);
}

