            string l2 = s.substr(1, 2);
            // +A
            dp[i + 1][base] += dp[i][j];
            dp[i + 1][base] %= MOD;
            // +C
            if (l2 != "AG" && l2 != "GA" && s != "ATG" && s != "AGG" && s != "AGT") {
                dp[i + 1][base + 1] += dp[i][j];
                dp[i + 1][base + 1] %= MOD;
            } 
            // +G
            if (l2 != "AC") {
                dp[i + 1][base + 2] += dp[i][j];
                dp[i + 1][base + 2] %= MOD;
            }
            // +T
            dp[i + 1][base + 3] += dp[i][j];
            dp[i + 1][base + 4] %= MOD;
        }
    }

    ll ans = 0;
    loop (64, i) ans = (ans + dp[N][i]) % MOD;
    cout << ans << endl;
}

int main(){
    long long N;
    scanf("%lld",&N);
    solve(N);
    return 0;
}

