ll rec_all(int n){
    if(n < 0){
        return 0;
    }
    if(n == 0){
        return 1;
    }
    if(n == 1){
        return 4;
    }
    if(n == 2){
        return 16;
    }
    if(memoall[n] != 0){
        return memoall[n];
    }
    else{
        return memoall[n] = ((rec_all(n - 1) - (rec_all(n - 3) + rec_ac(n - 1) + rec_g(n - 2) + rec_all(n - 4) * 3)) * 4 + (rec_all(n - 3) + rec_ac(n - 1) + rec_g(n - 2)) * 3 + rec_all(n - 4) * 9) % MOD;
    }
}

ll rec_ac(int n){
    if(n < 2){
        return 0;
    }
    if(memoac[n] != 0){
        return memoac[n];
    }
    else{
        return memoac[n] = rec_all(n - 2) - rec_g(n - 2);
    }
}

ll rec_g(int n){
    if(n < 1){
        return 0;
    }
    if(memog[n] != 0){
        return memog[n];
    }
    else{
        return memog[n] = rec_all(n - 1) - rec_ac(n - 1);
    }
}

