const ll MOD = 1000000007LL;
ll dp[105][4][4][4];


int main(){
  int N;
  cin >> N;

  rep(i,4){
    rep(j,4){
      rep(k,4){
        if(i==0 && j==2 && k==1) continue;
        {
          int a = i, b = j, c = k;
          swap(a,b);
          if(a==0 && b==2 && c==1) continue;
        }
        {
          int a = i, b = j, c = k;
          swap(b,c);
          if(a==0 && b==2 && c==1) continue;
        }        
        dp[2][i][j][k] = 1;
      }
    }
  }

  REP(i,2,N){
    rep(a,4){
      rep(b,4){
        rep(c,4){
          rep(x,4){
            if(b==0 && c==2 && x==1) continue;
            {
              int aa = a, bb = b, cc = c, dd = x;
              swap(aa,bb);
              if(aa==0 && bb==2 && cc==1) continue;
              if(bb==0 && cc==2 && dd==1) continue;
            }
            {
              int aa = a, bb = b, cc = c, dd = x;
              swap(bb,cc);
              if(aa==0 && bb==2 && cc==1) continue;
              if(bb==0 && cc==2 && dd==1) continue;
            }
            {
              int aa = a, bb = b, cc = c, dd = x;
              swap(cc,dd);
              if(aa==0 && bb==2 && cc==1) continue;
              if(bb==0 && cc==2 && dd==1) continue;
            }
            dp[i+1][b][c][x] += dp[i][a][b][c];
            dp[i+1][b][c][x] %= MOD;
          }
        }
      }
    }
  }

  ll ret = 0;
  rep(i,4){
    rep(j,4){
      rep(k,4){
        ret += dp[N-1][i][j][k];
        ret %= MOD;
      }
    }
  }

  cout << ret << endl;

  return 0;
}

