int dp[101][4][4][4];//dp[i + 1][ppprev][pprev][prev] : 文字列長iを作るための通り数

int main() {
    int N; cin >> N;
    rep(pprev, 4){
        rep(prev, 4){
            rep(now, 4){
                if(pprev == 0 && prev == 1 && now == 2)continue;
                if(pprev == 0 && prev == 2 && now == 1)continue;
                if(pprev == 2 && prev == 0 && now == 1)continue;
                dp[3][pprev][prev][now] = 1;
            }
        }
    }
    for(int i = 3; i < N; ++i) {
        for(int pprev = 0; pprev < 4; ++pprev) {
            for(int prev = 0; prev < 4; ++prev) {
                for(int now = 0; now < 4; ++now){
                    for(int ppprev = 0; ppprev < 4; ++ppprev) {
                    if(ppprev == 0 && prev == 2 && now == 1)continue;
                    if(ppprev == 0 && pprev == 2 && now == 1)continue;
                    if(pprev == 0 && prev == 1 && now == 2)continue;
                    if(pprev == 0 && prev == 2 && now == 1)continue;
                    if(pprev == 2 && prev == 0 && now == 1)continue;
                    dp[i + 1][pprev][prev][now] = (dp[i + 1][pprev][prev][now] + dp[i][ppprev][pprev][prev]) % MOD;
                    }
                }
            }
        }
    }

    int ans = 0;
    for(int pprev = 0; pprev < 4; ++pprev) {
        for(int prev = 0; prev < 4; ++prev) {
            for(int now = 0; now < 4; ++now){
                ans = (ans + dp[N][pprev][prev][now]) % MOD;
            }
        }
    }
    cout << ans << endl;
}

