                    dp[3][j][k][l] = 1;
                }
            }
        }
    }

    for (ll i = 3; i < N; i++) {
        for (ll j = 0; j < 4; j++) {
            for (ll k = 0; k < 4; k++) {
                for (ll l = 0; l < 4; l++) {
                    for (ll m = 0; m < 4; m++) {
                        if (k == 0 && l == 1 && m == 2) continue;
                        if (k == 1 && l == 0 && m == 2) continue;
                        if (k == 0 && l == 2 && m == 1) continue;
                        if (j == 0 && k == 1 && m == 2) continue;
                        if (j == 0 && l == 1 && m == 2) continue;
                        dp[i + 1][k][l][m] += dp[i][j][k][l];
                    }
                }
            }
        }
    }

    Mint ans = 0;
    for (ll j = 0; j < 4; j++) {
        for (ll k = 0; k < 4; k++) {
            for (ll l = 0; l < 4; l++) {
                ans += dp[N][j][k][l];
            }
        }
    }

    cout << ans << "\n";
}

