const long long int DENOMI = 1000000007;
const int A = 0b00;
const int C = 0b01;
const int G = 0b10;
const int T = 0b11;
#define U(a, b, c, d) (a << 6 | b << 4 | c << 2 | d)

#include <string>

int main()
{
	int n;
	cin >> n;
	auto dp = vector<vector<long long int>>(n + 1, vector<long long int>(1 << 6));
	for(auto i = 0; i < 1 << 6; ++i){
		if(i == 0b001001 || i == 0b000110 || i == 0b100001) continue;
		dp[3][i] = 1;
	}
	auto f = vector<bool>(1 << 8, true);
	f[U(A, A, C, G)] = f[U(A, A, G, C)] = f[U(A, C, G, A)] = f[U(A, C, G, C)] =
		f[U(A, C, G, G)] = f[U(A, C, G, T)] = f[U(A, G, A, C)] = f[U(A, G, C, A)] =
		f[U(A, G, C, C)] = f[U(A, G, C, G)] = f[U(A, G, C, T)] = f[U(A, G, G, C)] =
		f[U(A, G, T, C)] = f[U(A, T, G, C)] = f[U(C, A, C, G)] = f[U(C, A, G, C)] =
		f[U(C, G, A, C)] = f[U(G, A, C, A)] = f[U(G, A, C, C)] = f[U(G, A, C, G)] =
		f[U(G, A, C, T)] = f[U(G, A, G, C)] = f[U(G, G, A, C)] = f[U(T, A, C, G)] =
		f[U(T, A, G, C)] = f[U(T, G, A, C)] = false;
	long long int ans = 0;
	for(auto i = 4; i <= n; ++i){
		for(auto j = 0; j < 1 << 6; ++j){
			for(auto k = A; k <= T; ++k){
				int s = j << 2 | k;
				if(f[s]) dp[i][s % (1 << 6)] = (dp[i][s % (1 << 6)] + dp[i - 1][j]) % DENOMI;
			}
		}
	}
	for(auto i = 0; i < 1 << 6; ++i){
		ans = (ans + dp[n][i]) % DENOMI;
	}
	if(n < 3) cout << 0 << endl;
	else if(n == 3) cout << 61 << endl;
	else cout << ans << endl;
	return 0;
}

