ll dp[105][6][6][6]={0};
const ll mod=1e9+7;
vector<ll> out_str;
bool judge(ll a,ll b,ll c,ll d){
  if(a==1&&b==3&&c==2) return true;
  if(b==1&&c==3&&d==2) return true;
  return false;
}
void get_out(){
  for(int i=0;i<5;i++){
    for(int j=0;j<5;j++){
      for(int k=0;k<5;k++){
        for(int l=0;l<5;l++){
          ll hash=l*125+k*25+j*5+i;
          ll a=i,b=j,c=k,d=l;
          if(judge(a,b,c,d)||judge(b,a,c,d)||judge(a,c,b,d)||judge(a,b,d,c)){
            out_str.push_back(hash);
          }
        }
      }
    }
  }
}
int main(){
  ll n;
  cin>>n;
  get_out();
  dp[0][0][0][0]=1;
  for(int i=0;i<n;i++){
    for(int j=0;j<5;j++){
      for(int k=0;k<5;k++){
        for(int l=0;l<5;l++){
          for(int m=1;m<5;m++){
            ll hash=m*125+j*25+k*5+l;
            bool f=true;
            for(int ina=0;ina<out_str.size();ina++){
              if(out_str[ina]==hash){
                f=false;
              }
            }
            if(f){
              dp[i+1][m][j][k]+=dp[i][j][k][l];
              dp[i+1][m][j][k]%=mod;
            }
          }
        }
      }
    }
  }
  ll ans=0;
  for(int i=1;i<5;i++){
    for(int j=1;j<5;j++){
      for(int k=1;k<5;k++){
        ans+=dp[n][i][j][k];
        ans%=mod;
      }
    }
  }
  cout<<ans<<endl;
}

