const int MOD = 1e9 + 7;

int dp[256][1000];

inline int get(int mask, int i) {
    return (mask >> (2 * i)) & 3;
}

inline bool check(string s) {
    if (s.find("210") != string::npos) return false;
    for (size_t i = 1; i < s.size(); i++) {
        swap(s[i - 1], s[i]);
        if (s.find("210") != string::npos) return false;
        swap(s[i - 1], s[i]);
    }
    return true;
}

string by_mask(int mask) {
    string s = "";
    for (int i = 0; i < 4; i++) {
        s += '0' + get(mask, 3 - i);
    }
    return s;
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL); cout.tie(NULL);

    int n;
    cin >> n;
    for (int mask = 0; mask < 256; mask++) {
        if (get(mask, 3) == 3) {
            int a = get(mask, 0);
            int b = get(mask, 1);
            int c = get(mask, 2);
            if (check(by_mask(mask))) {
                dp[mask][3] = 1;
            } else {
                dp[mask][3] = 0;
            }
        }
    }
    for (int i = 4; i <= n; i++) {
        for (int mask = 0; mask < 256; mask++) {
            // cout << mask << endl;
            dp[mask][i] = 0;
            for (int prev = 0; prev < 4; prev++) {
            // cout << prev << " " << mask << " " << ((prev << 8 + mask) >> 2) << endl;
                if (check(string(1, '0' + prev) + by_mask(mask))) {
                    dp[mask][i] += dp[((prev << 8) + mask) >> 2][i - 1];
                }
            }
            dp[mask][i] %= MOD;
        }
    }


    int ans = 0;
    for (int mask = 0; mask < 256; mask++) {
        ans += dp[mask][n];
    }
    cout << ans % MOD;

    return 0;
}

