		int num = nary_k(i,4,k);
		//cout << pow(4,k) << "ddd" << endl;
		//cout << (i/((int)pow(4,k+1)))*4 << " "  <<i/((int)pow(4,k))<<endl;
		if(num==0){
			a[2-k]='A';
		}else if(num==1){
			a[2-k] = 'C';
		}else if(num==2){
			a[2-k] = 'G';
		}else if(num==3){
			a[2-k] = 'T';
		}else{
			cout <<"ERROR"<<endl;
			//return "d";
		}
	}
	//cout << a << endl;
	string result = a[0]+a[1]+a[2];
	return result;
}
