map<string, ll> dic;
string agcts[] = {"AA", "AC", "AG", "AT", "CA", "CC", "CG", "CT", "GA", "GC", "GG", "GT", "TA", "TC", "TG", "TT" };
char chars[] = {'A', 'C', 'G', 'T'};

void init() {
    for (auto& agct : agcts) {
        dic[agct] = 1;
    }
}

string take_3(const string& org) {
    int n = org.size();
    int take = min(3, n);
    return org.substr(n - take, take);
}

void increment() {
    map<string, ll> new_dic;

    for (auto& d: dic) {
        auto& agct = d.first;
        string first = take_3(agct);
        for (auto& c : chars) {
            new_dic[first + c] += dic[agct];
        }

        if (first == "AAG" || first ==  "ACG" || first ==  "AGG" || first ==  "ATG") {
            new_dic[first + 'C'] -= dic[agct];
        } else if (first == "AGA" || first == "AGC" || first == "AGG" || first == "AGT") {
            new_dic[first + 'C'] -= dic[agct];
        } else if (ends_with(agct, "AG")) {
            new_dic[first + 'C'] -= dic[agct];
        } else if (ends_with(agct, "GA")) {
            new_dic[first + 'C'] -= dic[agct];
        } else if (ends_with(agct, "AC")) {
            new_dic[first + 'G'] -= dic[agct];
        }
    }
    for (auto& d: new_dic) {
        auto& agct = d.first;
         new_dic[agct] %= BIG;
    }
    dic = new_dic;
}

