    for (auto& d: dic) {
        auto& agct = d.first;
        ans += dic[agct];
        ans %= BIG;
    }
    output(ans);

    return 0;
}

#include <bits/stdc++.h>

using namespace std;
using ll = long long;

const ll MAX { 110 }, A { 1 }, C { 2 }, G { 3 }, T { 4 }, MOD { 1000000007 };

ll st[MAX][2*MAX];

int encode(int a, int b, int c)
{
    return 25 * a + 5 * b + c;
}

void decode(int n, int&a, int &b, int& c)
{
    c = n % 5;
    n /= 5;

    b = n % 5;
    n /= 5;

    a = n;
}


ll dp(int idx, int N, int mask)
{
    if (idx == N)
        return 1;

    if (st[idx][mask] != -1)
        return st[idx][mask];

    int x, y, z;
    decode(mask, x, y, z);

    // A e T sempre podem ser adicionados
    ll ans = (dp(idx + 1, N, encode(y, z, T)) + dp(idx + 1, N, encode(y, z, A))) % MOD;

    // C só pode adicionado se não violar a regra (não pode formar AGC ou GAC ou AxGC)
    if (encode(0, A, G) != encode(0, y, z) and 
        encode(0, G, A) != encode(0, y, z) and
        encode(A, G, 0) != encode(x, y, 0) and
        encode(A, 0, G) != encode(x, 0, z))
            ans = (ans + dp(idx + 1, N, encode(y, z, C))) % MOD;

    // G só pode adicionado se não violar a regra (não pode formar ACG)
    if (encode(0, A, C) != encode(0, y, z))
        ans = (ans + dp(idx + 1, N, encode(y, z, G))) % MOD;

    st[idx][mask] = ans;

    return ans;
}

int solve(int N)
{
    memset(st, -1, sizeof st);

    return dp(0, N, 0);
}

int main()
{
    ios::sync_with_stdio(false);

    int N;
    cin >> N;

    auto ans = solve(N);

    cout << ans << '\n';

    return 0;
}

