    long long tmp = 0;
    for (int i = 0; i < 4; i++)
    {
        char nx = "ACGT"[i];
        if (isOk(base + nx))
        {
            tmp += dfs(pos + 1, base.substr(1) + nx);
            tmp %= m;
        }
    }
    return cnt[pos][base] = tmp;
