        }
        m[tmp] = index++;
      }
    }
  }

  for (int i = 2; i < n; i++) {
    for (auto x : m) {
      for (auto c : candidate) {
        string tmp = x.first.substr(1, 2) + c;
        if (valid(x.first.substr(0, 1), tmp)) {
          dp[i + 1][m[tmp]] += dp[i][m[x.first]];
          dp[i + 1][m[tmp]] %= MOD;
        }
      }
    }
  }
  ll sum = 0;
  for (auto x : m) {
    sum = (sum + dp[n - 1][x.second]) % MOD;
  }
  cout << sum << endl;
}

int main() {
  cin >> n;
  solve();
}

