const int mod = 1000000007;
const string cand = "ATGC";
bool valid(string last) {
	if (last.size() < 3) return true;
	for (int i = 0; i < last.size(); ++i) {
		for (int j = i + 1; j < last.size(); ++j) {
			swap(last[i], last[j]);
			if (last.substr(last.size() - 3) == string("AGC")) return false;
			swap(last[i], last[j]);
		}
	}
	return true;
}
map<string, bool> vis[109];
map<string, int> dp[109];
int solve(int limit, string last) {
	if (limit == 0) return true;
	if (vis[limit][last]) return dp[limit][last];
	int ans = 0;
	for (int i = 0; i < 4; ++i) {
		string nxt = last + cand[i];
		if (nxt.size() >= 5) nxt = nxt.substr(1);
		if (valid(nxt)) {
			ans += solve(limit - 1, nxt);
			if (ans >= mod) ans -= mod;
		}
	}
	vis[limit][last] = true;
	dp[limit][last] = ans;
	return ans;
}
int main() {
	int n;
	cin >> n;
	int ans = solve(n, string());
	cout << ans << endl;
	return 0;
}

