ll dp[110][5][5][5];

int main(){
    cin.tie(0);
    cout.tie(0);
    ios::sync_with_stdio(false);
    cin >> n;
    for(int i = 0; i < n; i++){
        if(i == 0 || i == 1){
            for(int j = 0; j < 5; j++){
                for(int k = 0; k < 5; k++){
                    for(int l = 0; l < 5; l++){
                        dp[i][j][k][l] = 0;
                    }
                }
            }
        }else if(i == 2){
            for(int j = 0; j < 5; j++){
                for(int k = 0; k < 5; k++){
                    for(int l = 0; l < 5; l++){
                        dp[i][j][k][l] = 1;
                    }
                }
            }
            dp[i][0][2][1] = 0;
            dp[i][0][1][2] = 0;
            dp[i][2][0][1] = 0;//0->A, 2->G, 1->C
        }else{
            for(int j = 0; j < 4; j++){
                for(int k = 0; k < 4; k++){
                    for(int l = 0; l < 4; l++){
                        dp[i][j][k][l] = dp[i-1][0][j][k] + dp[i-1][1][j][k] + dp[i-1][2][j][k] + dp[i-1][3][j][k];
                    }
                }
            }
            dp[i][3][2][1] -= dp[i-1][0][3][2];//A?GC
            dp[i][1][2][1] -= dp[i-1][0][1][2];//ACGC
            dp[i][2][2][1] -= dp[i-1][0][2][2];//AGGC
            dp[i][0][2][1] -= dp[i-1][0][0][2];//AAGC
            for(int j = 0; j < 4; j++){
                dp[i][0][2][1] -= dp[i-1][j][0][2];//AGC
                dp[i][0][1][2] -= dp[i-1][j][0][1];//ACG
                dp[i][2][0][1] -= dp[i-1][j][2][0];//GAC
            }
        }

        for(int j = 0; j < 4; j++){
            for(int k = 0; k < 4; k++){
                for(int l = 0; l < 4; l++){
                    dp[i][j][k][l] %= mod;
                }
            }
        }
    }
    ll ans = 0;
    for(int j = 0; j < 4; j++){
        for(int k = 0; k < 4; k++){
            for(int l = 0; l < 4; l++){
                ans += dp[n-1][j][k][l];
            }
        }
    }
    cout << ans << endl;
}

