int main() {
	int n; cin >> n;
	dp[0][3][3][3] = 1;
	int mod = 1'000'000007;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < 4; j++) {
			for (int k = 0; k < 4; k++) {
				for (int l = 0; l < 4; l++) {
					if (dp[i][j][k][l] == 0) {
						continue;
					}
					for (int a = 0; a < 4; a++) {
						if (a == 2) {
							if (j == 1 && k == 0) {
								continue;
							}
							else if (j == 0 && k == 1) {
								continue;
							}
							if (j == 1 && l == 0) {
								continue;
							}
							if (k == 1 && l == 0) {
								continue;
							}
						}
						else if (a == 1) {
							if (j == 2 && k == 0) {
								continue;
							}
						}
						dp[i + 1][a][j][k] += dp[i][j][k][l];
						dp[i + 1][a][j][k] %= mod;
					}
				}
			}
		}
	}
	int ans = 0;
	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
