int N;
map<ll, map<string,ll> > f;

bool chk(string last){
    REP(i,4){
        string con = last;
        if (i != 3) swap(con[i],con[i+1]);
        if (con.find("AGC") != string::npos){
            return false;
        }
    }

    return true;
}


ll dfs(ll depth,string last){
    if (f[depth][last] != 0) return f[depth][last];
    if (depth == N+1) return 1;
    ll ret = 0;
    string C[4] = {"A","C","G","T"};

    REP(i,4){
        if (chk(last + C[i])){
            string next = last.substr(1,2) + C[i];
            ret = ret + dfs(depth+1,next) % MOD;
        }
    }

    f[depth][last] = ret;
    return ret;

}
