using namespace std;

bool check(string tail) {
    return tail.find("AGC") == string::npos &&
           tail.find("GAC") == string::npos &&
           tail.find("ACG") == string::npos &&
           tail.find("AGGC") == string::npos &&
           tail.find("ATGC") == string::npos &&
           tail.find("AGTC") == string::npos;
}

int solve(map<pair<int, string>, int>& hist, int n, string tail) {
    auto key = make_pair(n, tail);
    if (hist.count(key)) {
        return hist[key];
    } else if (n == 0) {
        return 1;
    } else {
        int ret = 0;
        string alph = "ACGT";
        for (int i = 0; i < 4; i++) {
            char c = alph[i];
            if (check(tail + c)) {
                ret = (ret + solve(hist, n - 1, tail.substr(1, 2) + c)) %
                      1000000007;
            }
        }
        hist[key] = ret;
        return ret;
    }
}

int main() {
    int n;
    std::cin >> n;
    map<pair<int, string>, int> hist;
    cout << solve(hist, n, "xxx") << endl;
}

