#include <bits/stdc++.h>
using namespace std;
const int mod = 1000000007;
int f[2][5][5][5][5];
bool bad(int a, int b, int c){
  if(a == 1 && b == 3 && c == 2) return true;
  return false;
}
bool valid(int a, int b, int c, int d){
  bool good = true;
  good &= !bad(a, b, c);
  good &= !bad(b, c, d);
  good &= !bad(b, d, c);
  good &= !bad(a, c, b);
  good &= !bad(b, a, c);
  good &= !bad(c, b, d);
  return good;
}
int doit(int N){
  // ACGT, AGC
  f[0][0][0][0][0] = 1;
  for(int i = 0; i < N; i++){
    int from = i&1, to = 1^from;
    memset(f[to], 0, sizeof(f[to]));
    for(int j = 0; j < 5; j++){
      for(int k = 0; k < 5; k++){
        for(int l = 0; l < 5; l++){
          for(int m = 0; m < 5; m++){
            for(int n = 1; n < 5; n++){
              if(valid(k, l, m, n)){
                f[to][k][l][m][n] += f[from][j][k][l][m];
                if(f[to][k][l][m][n] >= mod) f[to][k][l][m][n] -= mod;
              }
            }
          }
        }
      }
    }
  }
  int ans = 0;
  for(int i = 0; i < 5; i++) 
    for(int j = 0; j < 5; j++)
      for(int k = 0; k < 5; k++)
        for(int l = 0; l < 5; l++){
          ans += f[N&1][i][j][k][l];
          if(ans >= mod) ans -= mod;
        }
  return ans;
}
int main(){
  int n; cin >> n;
  cout << doit(n) << endl;
  return 0;
}

