const ll none = 0;
const ll A = 1;
const ll G = 2;
const ll C = 3;
const ll T = 4;
const ll mod = (ll)(1e9) + 7;

ll n;
ll dp[5][5][5][5][105];

ll solve(ll c1, ll c2, ll c3, ll c4, ll pos);

int main() {
    for (int i = 0; i < 5; i++) {
        for (int ii = 0; ii < 5; ii++) {
            for (int iii = 0; iii < 5; iii++) {
                for (int iiii = 0; iiii < 5; iiii++) {
                    for (int j = 0; j < 105; j++) {
                        dp[i][ii][iii][iiii][j] = -1;
                    }
                }
            }
        }
    }

    cin >> n;

    cout << solve(0, 0, 0, 0, 0) << endl;

    return 0;
}

ll solve(ll c1, ll c2, ll c3, ll c4, ll pos) {
    if (dp[c1][c2][c3][c4][pos] != -1) return dp[c1][c2][c3][c4][pos];

    if (c2 == A && c3 == G && c4 == C) return 0;
    if (c1 == A && c2 == G && c4 == C) return 0;
    if (c1 == A && c3 == G && c4 == C) return 0;

    if (c2 == A && c3 == C && c4 == G) return 0;
    if (c2 == G && c3 == A && c4 == C) return 0;

    if (pos == n) return 1;

    ll ret = 0;
    for (int i = A; i <= T; i++) {
        ret += solve(c2, c3, c4, i, pos + 1);
        ret %= mod;
    }

    return dp[c1][c2][c3][c4][pos] = ret;
}

#include <iostream>
