using namespace std;


int dp[101][4][4][4];
int mod = 1e9 + 7;

int main() {

    int N;
    cin >> N;
    // A - 0, G- 1, C - 2, T - 3
    // dp[文字数][1文字前][2文字前][3文字前]
    // 長さ０の文字列は１
    // ０，１，2に関する制約しかないので，
    // Sは，３３３Sと考えても問題ない．
    dp[0][3][3][3] = 1;

    // 文字列の文字数
    for (int len = 0; len < N; len++) {
        // 最後から１文字目のもじ
        for (int c1 = 0; c1 < 4; c1++) {
            // 最後から2文字目のもじ
            for (int c2 = 0; c2 < 4; c2++) {
                // 最後から3文字目のもじ
                for (int c3 = 0; c3 < 4; c3++) {
                    // 条件に当てはまるものがない場合はcontinue;
                    if (dp[len][c1][c2][c3] == 0) continue;

                    // 新しく追加するもじ
                    for (int a = 0; a < 4; a++) {
                        // ダメな5つの条件をカットする
                        // 0 1 2 (AGC)
                        if (a == 2 and c1 == 1 and c2 == 0) continue;
                        // 1 0 2 (GAC)
                        if (a == 2 and c1 == 0 and c2 == 1) continue;
                        // 0 2 1 (ACG)
                        if (a == 1 and c1 == 2 and c2 == 0) continue;
                        // 0 * 1 2 (A*GC)
                        if (a == 2 and c1 == 1 and c3 == 0) continue;
                        // 0 1 * 2 (AG*C)
                        if (a == 2 and c2 == 1 and c3 == 0) continue;

                        // ダメな条件を抜けたら，aを足した文字列が作れる

                        // S = .... c3 c2 c1
                        // NextS = .... c2 c1 a
                        dp[len + 1][a][c1][c2] += dp[len][c1][c2][c3];
                        dp[len + 1][a][c1][c2] %= mod;

                    }
                }
            }
        }
    }
    int ans = 0;
    // 長さNの答えをまとめる
    // 最後から１文字目のもじ
    for (int c1 = 0; c1 < 4; c1++) {
        // 最後から2文字目のもじ
        for (int c2 = 0; c2 < 4; c2++) {
            // 最後から3文字目のもじ
            for (int c3 = 0; c3 < 4; c3++) {

                ans += dp[N][c1][c2][c3];
                ans %= mod;

            }
        }
    }

    cout << ans << '\n';
}

