constexpr u32 P = 1000000007;
constexpr i64 A = 0;
constexpr i64 C = 1;
constexpr i64 G = 2;
constexpr i64 T = 3;

typedef std::array<std::array<tools::int_mod<P>, 64>, 64> matrix;

matrix operator*(const matrix& lhs, const matrix& rhs) {
  matrix product;
  for (i64 i = 0; i < 64; ++i) {
    for (i64 j = 0; j < 64; ++j) {
      product[i][j] = tools::int_mod<P>(0);
      for (i64 k = 0; k < 64; ++k) {
        product[i][j] += lhs[i][k] * rhs[k][j];
      }
    }
  }
  return product;
}

matrix pow(const matrix& base, const i64 exponent) {
  if (exponent == 0) {
    matrix unit;
    for (i64 i = 0; i < 64; ++i) {
      for (i64 j = 0; j < 64; ++j) {
        unit[i][j] = tools::int_mod<P>(i == j ? 1 : 0);
      }
    }
    return unit;
  } else if (exponent % 2 == 0) {
    const matrix squared_result = pow(base, exponent / 2);
    return squared_result * squared_result;
  } else {
    return pow(base, exponent - 1) * base;
  }
}

int main() {
  i64 N;
  std::cin >> N;

  if (N == 3) {
    std::cout << 61 << std::endl;
    return 0;
  }

  matrix unit_matrix;
  for (i64 from = 0; from < 64; ++from) {
    std::fill(unit_matrix[from].begin(), unit_matrix[from].end(), tools::int_mod<P>(0));
    const std::array<i64, 3> state = {(from >> 4) & 3, (from >> 2) & 3, from & 3};
    std::unordered_set<i64> options({A, C, G, T});
    if (state[0] == A && state[1] == G && state[2] == C) options.clear();
    if (state[0] == G && state[1] == A && state[2] == C) options.clear();
    if (state[0] == A && state[1] == C && state[2] == G) options.clear();
    if (state[1] == A && state[2] == G) options.erase(C);
    if (state[1] == G && state[2] == A) options.erase(C);
    if (state[1] == A && state[2] == C) options.erase(G);
    if (state[0] == A && state[2] == G) options.erase(C);
    if (state[0] == A && state[1] == G) options.erase(C);
    for (const i64& option : options) {
      const i64 to = ((from << 2) | option) & 63;
      unit_matrix[from][to] = tools::int_mod<P>(1);
    }
  }

  const matrix matrix = pow(unit_matrix, N - 3);
  tools::int_mod<P> answer(0);
  for (i64 i = 0; i < 64; ++i) {
    for (i64 j = 0; j < 64; ++j) {
      answer += matrix[i][j];
    }
  }

