long long rec(int x, int y, int z, int i)
{
	if (dp[x][y][z][i] >= 0)
	{
		return dp[x][y][z][i];
	}
	if (i == 0)
	{
		return dp[x][y][z][i] = 1;
	}
	else if ((x == 0||y == 0)&&z == 2)
	{
		return dp[x][y][z][i] = rec(y, z, 0, i - 1) + rec(y, z, 2, i - 1) + rec(y, z, 3, i - 1);
	}
	else if (y == 2 && (x == 0 || z == 0))
	{
		return dp[x][y][z][i] = rec(y, z, 0, i - 1) + rec(y, z, 2, i - 1) + rec(y, z, 3, i - 1);
	}
	else if (y == 0 && z == 1)
	{
		return dp[x][y][z][i] = rec(y, z, 0, i - 1) + rec(y, z, 1, i - 1) + rec(y, z, 3, i - 1);
	}
	else
	{
		return dp[x][y][z][i] = rec(y, z, 0, i - 1) + rec(y, z, 1, i - 1) + rec(y, z, 2, i - 1) + rec(y, z, 3, i - 1);
	}
}

