int NN = 3;
const int MOD = 1000000007;
std::vector<std::unordered_map<std::string, int>*> memo;

bool isOK (std::string last4) {
  for(int i=0; i<4; i++) {
    std::string t = last4;
    if ( i>= 1 ) {
      char tmp = t[i-1];
      t[i-1] = t[i];
      t[i] = tmp;
    }
    if ( t.find("AGC") != std::string::npos ){
      return false;
    }
  }
  return true;
}

long long dfs(int cur, std::string last3) {

  if (memo[cur]->count(last3)) return memo[cur]->at(last3);
  if (cur == NN) return 1;

  long long  ret = 0;
  std::string S = "ATGC";
  for(int i=0; i<S.size(); i++){
    if ( isOK(last3+S[i]) ){
      ret += (dfs(cur+1, last3.substr(1,2)+S[i]) % MOD);
    }
  }
  memo[cur]->insert( {last3, ret%MOD} );
  return ret % MOD;
}


