int dp[101][4][4][4];
// ACGT 0123

int solution(int x, int n, int m, int p) {
    if (x == 3) {
        if ((n == 0 && m == 2 && p == 1) || (n == 0 && m == 1 && p == 2) || (n == 2 && m == 0 && p == 1)) return 0;
        return 1;
    }

    int& ret = dp[x][n][m][p];
    if (ret != -1) return ret;
    else {
        int res = 0;

        for (int i = 0; i < 4; i++) {
            if (i == 0 && m == 2 && p == 1) continue;
            if (i == 0 && n == 2 && p == 1) continue;
            if ((n == 0 && m == 2 && p == 1) || (n == 0 && m == 1 && p == 2) || (n == 2 && m == 0 && p == 1)) continue;

            res += solution(x - 1, i, n, m);
            res %= MOD;
        }

        return ret = res;
    }
}

