		cout << acgt[((stat >> (i * 2)) & 3)] << ", ";
	}
	cout << endl;
}

int swapStat(int stat, int x, int y)
{
	int statArr[4];
	int swappedStat = 0;

	for (int i = 0; i < 4; ++i)
	{
		statArr[i] = (stat >> (i * 2)) & 3;
	}

	swap(statArr[x], statArr[y]);

	for (int i = 0; i < 4; ++i)
	{
		swappedStat = swappedStat | (statArr[i] << (i * 2));
	}

	return swappedStat;
}

bool check(int stat)
{
	if ((stat & ((1 << 6) - 1)) == BAD_PATTERN)
	{
		return false;
	}
	if (((stat >> 2) & ((1 << 6) - 1)) == BAD_PATTERN)
	{
		return false;
	}

	for (int i = 0; i < 3; ++i)
	{
		int swappedStat = swapStat(stat, i, i + 1);
		if ((swappedStat & ((1 << 6) - 1)) == BAD_PATTERN)
		{
			return false;
		}
		if (((swappedStat >> 2) & ((1 << 6) - 1)) == BAD_PATTERN)
		{
			return false;
		}
	}

	return true;
}

int solve(int n, int prevStat)
{
	if (n == 0)
	{
		return 1;
	}

	if (dp[n][prevStat] != -1)
	{
		return dp[n][prevStat];
	}

	int ret = 0;

	for (int i = 0; i < 4; ++i)
	{
		int nextStat = ((prevStat << 2) | i) & ((1 << 8) - 1);
		if (check(nextStat))
		{
			//printStat(nextStat);
			ret = (ret + solve(n - 1, (nextStat & ((1 << 6) - 1)))) % MOD;
		}
	}

	return dp[n][prevStat] = ret;
}

int main()
{
	int n;

	cin >> n;

	for (int i = 0; i < 100; ++i)
	{
		for (int j = 0; j < (1 << 8); ++j)
		{
			dp[i][j] = -1;
		}
	}

	int ans = 0;
	for (int i = 0; i < (1 << 6); ++i)
	{
		if (i == ((0 << 4) | (2 << 2) | (1 << 0))) continue;
		if (i == ((0 << 4) | (1 << 2) | (2 << 0))) continue;
		if (i == ((2 << 4) | (0 << 2) | (1 << 0))) continue;
		ans = (ans + solve(n - 3, i)) % MOD;
	}

	cout << ans << endl;


	return 0;
}

