                        //末尾4文字が?ACGになるときはダメ
                        if(next == 1 && c1 == 2 && c2 == 0) {
                            continue;
                        }
                        //末尾4文字がA?GCになるときはダメ
                        if(next == 2 && c1 == 1 && c3 == 0) {
                            continue;
                        }
                        //末尾4文字がAG?Cになるときはダメ
                        if(next == 2 && c2 == 1 && c3 == 0) {
                            continue;
                        }

                        //それ以外のときはok
                        dp[i+1][next][c1][c2] += dp[i][c1][c2][c3];
                        dp[i+1][next][c1][c2] %= mod;
                    }
                }
            }
        }
    }

    //求める答えは長さnのときの場合の数の総数
    int ans = 0;
    rep(c1, 4) {
        rep(c2, 4) {
            rep(c3, 4) {
                ans += dp[n][c1][c2][c3];
                ans %= mod;
            }
        }
    }

    cout << ans << endl;
    return 0;
}

