int N;

ll solve(int n, int p3, int p2, int p1) {
    ll& ret = dp[n][p3][p2][p1];

    if (n >= N) return 1;
    if (ret >= 0) return ret;

    ret = 0;
    rep(p, 4) {
        if (ng(p2, p1, p) or ng(p2, p, p1) or ng(p1, p2, p)) continue;
        if (ng(p3, p1, p) or ng(p3, p2, p)) continue;
        ret += solve(n+1, p2, p1, p) % mod;
    }
    return ret;
}

