bool ok(int last4) {

		//AGCはだめ
		int a[4];
		int t = last4;
		for (int i = 3; i >= 0; i--) {
			a[i] = t% 4;
			t /= 4;
		}
		for (int j = 0; j < 4; j++) {
			int b[4];
			for (int i = 0; i < 4; i++) {
				b[i] = a[i];
			}
			if (j > 0) {
				b[j - 1] = a[j];
				b[j] = a[j - 1];
			}

			if (b[0]*4*4+b[1]*4+b[2] == AGC) {
				return false;
			}
			if (b[1]*4*4+b[2]*4+b[3] == AGC) { 
				return false; 
			}
		}
	return true;
}

long long func(int n,int last3) {
	if (dp[n][last3] != -1) {
		return dp[n][last3];
	}
	else if(n==N){
		return 1;
	}
	else {
		long long ret = 0;
		for (int i = 0; i < 4; i++) {
			if (ok(last3 * 4 + i)) {
				ret = (ret + func(n + 1, (last3 % (4 * 4)) * 4 + i))%MOD;
			}
			dp[n][last3] = ret;
		}
		return ret;
	}
}

