	int n = sz(s);
	for (int i = 0; i + 2 < n; ++i) {
		if (s[i] == 'A' && s[i + 1] == 'G' && s[i + 2] == 'C') {
			return 1;
		}  
	} 
	return 0;
}

int bad(string s) {
	int n = sz(s);
	if (bad_w(s)) {
		return 1;
	} 
	for (int i = 0; i + 1 < n; ++i) {
		swap(s[i], s[i + 1]);
		if (bad_w(s)) {
			return 1;
		} 
		swap(s[i], s[i + 1]);
	}  
	return 0;
}

