struct aho_corasick {
	vector<vector<int>> succ;
	vector<int> fail, accept;
	char from, to;

	aho_corasick(char from_ = 'a', char to_ = 'z') : from(from_), to(to_), succ(1, vector<int>(to_ - from_ + 1)), accept(1) {}

	void add(string s) {
		int u = 0;
		for (char c : s) {
			c -= from;
			if (succ[u][c] == 0) {
				succ[u][c] = succ.size();
				succ.push_back(vector<int>(to - from + 1));
				accept.push_back(0);
			}
			u = succ[u][c];
		}
		accept[u]++;
	}

	void build() {
		queue<int> q;
		for (int c = 0; c <= to - from; c++) {
			if (succ[0][c] != 0) {
				q.push(succ[0][c]);
			}
		}
		fail.resize(succ.size());
		while (!q.empty()) {
			int u = q.front(); q.pop();
			for (int c = 0; c <= to - from; c++) {
				int v = succ[u][c];
				if (v != 0) {
					q.push(v);
					fail[v] = succ[fail[u]][c];
				} else {
					succ[u][c] = succ[fail[u]][c];
				}
			}
			accept[u] += accept[fail[u]];
		}
	}

  int next(int k, char c) {
    return succ[k][c - from];
  }
};

int main() {
  aho_corasick ac;
  ac.add("agc");
  ac.add("gac");
  ac.add("acg");

  ac.add("aagc");
  ac.add("acgc");
  ac.add("aggc");
  ac.add("atgc");

  ac.add("agac");
  ac.add("agcc");
  ac.add("aggc");
  ac.add("agtc");

  ac.build();

  static mint dp[101][1000];
