  int N=si();
  REP(i,N)REP(j,ac.succ.size())REP(k,4){
    int l=ac.next(j,"acgt"[k]);
    if(ac.accept[l]>0)continue;
    dp[i+1][l]+=dp[i][j];
  }
  mint ans=0;
  REP(i,ac.succ.size())ans+=dp[N][i];
  pi(ans.n);br();
}

