            if (k == A && l == C && m == G) continue;
            dp[i+1][k][l][m] += dp[i][j][k][l];
        }
    }

    ModInt<MOD> ans = 0;
    rep(i, 4) rep(j, 4) rep(k, 4) ans += dp[n][i][j][k];
    cout << ans << endl;
