                        if (j == G && k == A && l == C) continue;
                        if (m == A && k == G && l == C) continue;
                        if (m == A && j == G && l == C) continue;
                        dp[i+1][j][k][l] += dp[i][m][j][k];
                        dp[i+1][j][k][l] %= mod;
                    }
                }
            }   
        }
    }

    ll ans = 0;
