template <typename T, typename... Args>
auto vectors(std::size_t n, Args... args) {
  return std::vector<decltype(vectors<T>(args...))>(n, vectors<T>(args...));
}

bool check_AGC(int c3, int c2, int c1) {
  return (c3 == 0 and c2 == 2 and c1 == 3) ? true : false;
}

bool check_AGC_neighbor(int c2, int c1, int c0, int c) {
  return (check_AGC(c2, c1, c0) or check_AGC(c1, c2, c0) or
          check_AGC(c2, c0, c1) or check_AGC(c1, c0, c) or
          check_AGC(c0, c1, c) or check_AGC(c1, c, c0) or
          check_AGC(c2, c0, c) or check_AGC(c2, c1, c))
             ? true
             : false;
}

int main() {
  // Input
  int N;
  std::cin >> N;
  assert(3 <= N and N <= 100);

  // Initialization
  // {'A': 0, 'T': 1, 'G': 2, 'C': 3}
  auto dp = vectors<llong>(1 + N + 1, 4, 4, 4, 0LL);

  // Initial condition
  for (int c2 = 0; c2 < 4; ++c2) {
    for (int c1 = 0; c1 < 4; ++c1) {
      for (int c0 = 0; c0 < 4; ++c0) {
        if (check_AGC(c2, c1, c0) or check_AGC(c1, c2, c0) or
            check_AGC(c2, c0, c1))
          continue;
        dp[3][c2][c1][c0] = 1;
      }
    }
  }

  // DP main
  for (int i = 3; i <= N; ++i) {
    for (int c2 = 0; c2 < 4; ++c2) {
      for (int c1 = 0; c1 < 4; ++c1) {
        for (int c0 = 0; c0 < 4; ++c0) {
          for (int c = 0; c < 4; ++c) {
            if (check_AGC_neighbor(c2, c1, c0, c))
              continue;
            chadd(dp[i + 1][c1][c0][c], dp[i][c2][c1][c0]);
          }
        }
      }
    }
  }

  // Output
  llong res = 0LL;
  for (int c2 = 0; c2 < 4; ++c2) {
    for (int c1 = 0; c1 < 4; ++c1) {
      for (int c0 = 0; c0 < 4; ++c0) {
        res += dp[N][c2][c1][c0];
        res %= MOD;
      }
    }
  }
  std::cout << res << std::endl;

  return 0;
}

