//A*Bの計算
mat mul(mat &A, mat &B)
{
    mat C(A.size(), vec(B[0].size()));
    for (ll i = 0; i < A.size(); i++)
    {
        for (ll k = 0; k < B.size(); k++)
        {
            for (ll j = 0; j < B[0].size(); j++)
            {
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
            }
        }
    }
    return C;
}

//A^nの計算
mat pow(mat A, ll n)
{
    mat B(A.size(), vec(A.size()));
    for (ll i = 0; i < A.size(); i++)
    {
        B[i][i] = 1;
    }
    while (n > 0)
    {
        if (n & 1)
            B = mul(B, A);
        A = mul(A, A);
        n >>= 1;
    }
    return B;
}
