vector<T> make_vec(size_t a){
    return vector<T>(a);
}
template<class T, class... Ts>
auto make_vec(size_t a, Ts... ts){
  return vector<decltype(make_vec<T>(ts...))>(a, make_vec<T>(ts...));
}

int main(){
    int n;
    cin >> n;

    auto dp = make_vec<ll>(n+1,5,5,5);
    dp[0][0][0][0] = 1;

    //dp[i][3文字前][2文字前][1文字前]
    //dp[i+1][2文字前][1文字前][今回の]

    for(int s = 0; s < n; ++s){
        for(int i = 0; i < 5; ++i){
            for(int j = 0; j < 5; ++j){
                for(int k = 0; k < 5; ++k){
                    for(int l = 1; l < 5; ++l){
                        if(i == 1 && j == 2 && k == 3)continue;
                        if(i == 1 && k == 2 && l == 3)continue;
                        if(j == 1 && k == 2 && l == 3)continue;
                        if(j == 2 && k == 1 && l == 3)continue;
                        if(j == 1 && k == 3 && l == 2)continue;
                        dp[s+1][j][k][l] += dp[s][i][j][k];
                        dp[s+1][j][k][l] %= MOD;
                    }
                }
            }
        }
    }

    //nのやつ足す
    ll res = 0;
    for(int i = 1; i < 5; ++i){
        for(int j = 1; j < 5; ++j){
            for(int k = 1; k < 5; ++k){
                res += dp[n][i][j][k];
                res %= MOD;
            }
        }
    }


    cout << res << endl;



    return 0;    
}

