	lint gcd(lint a, lint b) {
		while (1) {
			if (a < b) swap(a, b);
			if (!b) break;
			a %= b;
		}
		return a;
	}

	lint lcm(lint a, lint b)
	{
		return a / gcd(a, b) * b;
	}

	const ulint mod = 1000000007;
	const double pi = 3.141592653589793238462;
	const lint intmax = 9223372036854775807;

	lint FactMod(lint n) {
		if (n == 0)
		{
			return 1;
		}
		lint ans = 1;
		while (n > 1) {
			ans *= n;
			n--;
			ans %= mod;
		}
		return ans;
	}

	lint _PowMod(lint x, lint y, lint _mod)
	{
		if (x <= 1)
		{
			return x;
		}
		if (y == 0)
		{
			return 1;
		}
		else if (y == 1)
		{
			return x % _mod;
		}
		else if (y % 2 == 0)
		{
			lint tmp = _PowMod(x, y / 2, _mod);
			return tmp * tmp % _mod;
		}
		else
		{
			lint tmp = _PowMod(x, y / 2, _mod);
			return (tmp * tmp % _mod) * x % _mod;
		}
	}

	lint PowMod(lint x, lint y)
	{
		return _PowMod(x, y, mod);
	}

	auto getModInv(lint N)
	{
		return PowMod(N, mod - 2);
	}

	lint nCrMod(lint n, lint r, lint start)
	{
		if (n < r || n < 0 || r < 0)
		{
			return 0;
		}
		r = min(r, n - r);
		lint a = start;
		for (lint i = n; i >= n - r + 1; i--)
		{
			a *= i;
			a %= mod;
		}

		a *= getModInv(FactMod(r));
		a %= mod;
		return a;
	}

	lint nHrMod(lint n, lint r, lint start)
	{
		return nCrMod(n + r - 1, r, start);
	}

	auto lcmMod(lint a, lint b)
	{
		return (((a * getModInv(gcd(a,b))) % mod) * b) % mod;
	}

