    for (int i = 0; i < n; i++)
    {
        //最後から１文字目
        for (int j = 0; j < 4; j++)
        {
            //最後から2文字目
            for (int k = 0; k < 4; k++)
            {
                //最後から3文字目
                for (int l = 0; l < 4; l++)
                {
                    if (dp[i][j][k][l] == 0)
                        continue;
                    for (int a = 0; a < 4; a++)
                    {
                        //AGC
                        if (a == 2 && j == 1 && k == 0)
                            continue;
                        //GAC
                        if (a == 2 && j == 0 && k == 1)
                            continue;
