long An(int n) {
	if (n == 3) {
		return 4;
	}
	else if (n == 4) {
		return 15;
	}
	else {
		return Pn(n - 2) - Bn(n - 2);
	}
}

long Bn(int n) {
	if (n == 3) {
		return 3;
	}
	else if (n == 4) {
		return 15;
	}
	else {
		return Pn(n - 2) - An(n - 1);
	}
}

long Cn(int n) {
	if (n == 3) {
		return 3;
	}
	if (n == 4) {
		return 12;
	}
	else if (n == 5) {
		return 48;
	}
	else {
		return Pn(n - 3);
	}
}

