// 文字数 最後から3,2,1番目の文字,のDP配列
// A -> 0
// G -> 1
// C -> 2
// T -> 3
int dp[100][4][4][4];

int main() {

  int N;
  cin >> N;

  int mod = 1000000007;

  // TはNGパターンに対して意味を持たないので、
  // 初期条件で1としても問題がない
  dp[0][3][3][3] = 1;

  for (int len = 0; len < N; len++) {
    // 最後から1番目の文字
    for (int c1 = 0; c1 < 4; c1++) {
      // 最後から2番目の文字
      for (int c2 = 0; c2 < 4; c2++) {
        // 最後から3番目の文字
        for (int c3 = 0; c3 < 4; c3++) {
          // 当てはまるものがなければスキップ
          if (dp[len][c3][c2][c1] == 0) continue;

          // 1文字足す
          for (int a = 0; a < 4; a++) {
            // AGC(012)
            if (a == 2 && c1 == 1 && c2 == 0) continue;
            // GAC(102)
            if (a == 2 && c1 == 0 && c2 == 1) continue;
            // ACG(021)
            if (a == 1 && c1 == 2 && c2 == 0) continue;
            // AxGC(0x12)
            if (a == 2 && c1 == 1 && c3 == 0) continue;
            // AGxC(01x2)
            if (a == 2 && c2 == 1 && c3 == 0) continue;

            dp[len + 1][c2][c1][a] += dp[len][c3][c2][c1];
            dp[len + 1][c2][c1][a] %= mod;
          }
        }
      }
    }
  }

  int ans = 0;
  // 最後から1番目の文字
  for (int c1 = 0; c1 < 4; c1++) {
    // 最後から2番目の文字
    for (int c2 = 0; c2 < 4; c2++) {
      // 最後から3番目の文字
      for (int c3 = 0; c3 < 4; c3++) {
        ans += dp[N][c3][c2][c1];
        ans %= mod;
      }
    }
  }
  cout << ans << endl;
  return 0;
}

