#define A 0
#define C 1
#define G 2
#define T 3
#define N_MAX 110
#define MOD 1000000007

int N;
long long int memo[101][4][4][4];

long long int func(int index, int p, int q, int r)
{
	if (A == p && G == q && C == r){
		return 0;
	}
	else if (A == p && C == q && G == r){
		return 0;
	}
	else if (G == p && A == q && C == r){
		return 0;
	}

	if (N == index + 3){
		return 1;
	}

	if (-1 != memo[index][p][q][r]){
		return memo[index][p][q][r];
	}

	long long int ret = 0;
	if (A == p && G == q){
		ret = (ret + func(index + 1, q, r, A)) % MOD;
		ret = (ret + func(index + 1, q, r, G)) % MOD;
		ret = (ret + func(index + 1, q, r, T)) % MOD;
	}
	else if (A == p && G == r){
		ret = (ret + func(index + 1, q, r, A)) % MOD;
		ret = (ret + func(index + 1, q, r, G)) % MOD;
		ret = (ret + func(index + 1, q, r, T)) % MOD;
	}
	else{
		ret = (ret + func(index + 1, q, r, A)) % MOD;
		ret = (ret + func(index + 1, q, r, C)) % MOD;
		ret = (ret + func(index + 1, q, r, G)) % MOD;
		ret = (ret + func(index + 1, q, r, T)) % MOD;
	}

	return memo[index][p][q][r] = ret;
}

void solv()
{
	scanf("%d", &N);

	for (int i = 0; i <= N; i++){
		for (int j = 0; j < 4; j++){
			for (int k = 0; k < 4; k++){
				fill(memo[i][j][k], memo[i][j][k] + 4, -1);
			}
		}
	}

	long long int ret = 0;
	for (int i = A; i <= T; i++){
		for (int j = A; j <= T; j++){
			for (int k = A; k <= T; k++){
				ret = (ret + func(0, i, j, k)) % MOD;
			}
		}
	}

	printf("%lld", ret);
	return;
}

