using point = complex<double>;
using ll = int64_t;

const ll MOD = 1000000007LL;
int my_main(int argc, char** argv)
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N;

    const std::vector<char> base = {
        'A',
        'C',
        'G',
        'T',
        'X'
    };


    auto index = [&base](char a) -> int {
        for (int i = 0; i < base.size(); i++) {
            if (base[i] == a)
                return i;
        }
        abort();
    };

    // 0 ~ 120 にマップする
    auto encode = [base, index](const std::vector<char>& s) {
        int ret = 0;
        for (int i = 0; i < s.size(); i++) {
            ret = ret * base.size() + index(s[i]);
        }
        return ret;
    };
    //// 0 ~ 24 にマップする
    //auto encode = [index, &base](char a, char b) -> int {
    //    return index(a) * base.size() + index(b);
    //};

    int lastIndex = encode({ 'X', 'X', 'X' });
    // ll dp[110][lastIndex+1];
    vector<vector<ll>> dp(110, vector<ll>(lastIndex + 1, 0));
    dp[0][encode({ 'X', 'X', 'X' })] = 1;

    // XXXXXXX A
    // XXXXXXX C
    // XXXXXXX G
    // XXXXXXX T

    // dp[i][encode(a, b)] = i の長さの文字列で、最後が ab なものの数でかつ、違反文字列ではない
    // dp[i+1][encode(b, c)] += dp[i][encode(a, b)] で、かつ abc が違反文字列ではない

    // AGTC ATGC
    for (int i = 1; i <= N; i++) {
        for (char a : base) {
            for (char b : base) {
                for (char c : base) {
                    for (char d : base) {
                        // We can't add 'X'
                        if (d == 'X')
                            continue;

                        string s;
                        s += a;
                        s += b;
                        s += c;
                        s += d;

                        bool invalid = (s.find("AGC") != string::npos);
                        for (int i = 0; i < 3; i++) {
                            swap(s[i], s[i + 1]);
                            if (s.find("AGC") != string::npos)
                                invalid = true;
                            swap(s[i], s[i + 1]);
                        }
                        if (invalid)
                            continue;

                        //dump(s);

                        dp[i][encode({ b, c, d })] += dp[i - 1][encode({ a, b, c })];
                        dp[i][encode({ b, c, d })] %= MOD;
                    }
                }
            }
        }
    }

    // dp[N][encode(a, b)] = N の長さの文字列で、最後が ab なものの数でかつ、違反文字列ではない
    ll ans = 0;
    for (char a : base) {
        for (char b : base) {
            for (char c : base) {
                ans += dp[N][encode({ a, b, c })];
                ans %= MOD;
            }
        }
    }
    cout << ans << endl;

    return 0;
}

