template<typename superType, class Operators>
struct Ring {

   superType x;

   template<typename... Args> Ring(Args... args) : x(args...) {}

   template<typename... Args>
   decltype(auto) operator[](Args... args)
   {
      return x.operator[](args...);
   }


   Ring& operator=(const Ring& value) & = default;

   template<typename... Args> static Ring id_add(Args... args) { return Operators::IdAdd(args...); }
   template<typename... Args> static Ring id_mul(Args... args) { return Operators::IdMul(args...); }

   Ring operator+() const { return *this; }
   Ring operator-() const { return Operators::Opposite(x); }

   Ring operator+=(const Ring& rhs) { x = Operators::Add(x, rhs.x); return *this; }
   Ring operator-=(const Ring& rhs) { *this += -rhs; return *this; }
   Ring operator*=(const Ring& rhs) { x = Operators::Mul(x, rhs.x); return *this; }

   const Ring operator+(const Ring& rhs) const { return Ring(*this) += rhs; }
   const Ring operator-(const Ring& rhs) const { return Ring(*this) -= rhs; }
   const Ring operator*(const Ring& rhs) const { return Ring(*this) *= rhs; }

   Ring power(int n) const { return Operators::Power(x, n); }

   bool operator<(const Ring& rhs) const { return Operators::Less(x, rhs.x); }
   bool operator>(const Ring& rhs) const { return rhs < *this; }
   bool operator<=(const Ring& rhs) const { return !(*this > rhs); }
   bool operator>=(const Ring& rhs) const { return !(*this < rhs); }
   bool operator==(const Ring& rhs) const { return !(*this < rhs) && !(*this > rhs); }
   bool operator!=(const Ring& rhs) const { return !(*this == rhs); }
};

template<typename superType, class Operators>
auto& operator<<(ostream& s,const Ring<superType, Operators>& a){ s << a.x; return s; }


template<typename superType, class Operators>
struct Field : Ring<superType, Operators> {

   using BaseRing = Ring<superType, Operators>;

   template<typename... Args> Field(Args... args) : BaseRing(args...) {}

   template<typename... Args>
   decltype(auto) operator[](Args... args)
   {
      return BaseRing::operator[](args...);
   }

   Field& operator=(const Field& value) & = default;

   template<typename... Args> static Field id_add(Args... args) { return BaseRing::id_add(args...); }
   template<typename... Args> static Field id_mul(Args... args) { return BaseRing::id_mul(args...); }

   Field operator+() const { return BaseRing::operator+(); }
   Field operator-() const { return BaseRing::operator-(); }
   Field reciprocal() const { return Operators::Reciprocal(this->x); }

   Field operator+=(const Field& rhs) { return *this = BaseRing::operator+=(rhs); }
   Field operator-=(const Field& rhs) { return *this = BaseRing::operator-=(rhs); }
   Field operator*=(const Field& rhs) { return *this = BaseRing::operator*=(rhs); }
   Field operator/=(const Field& rhs) { return *this *= rhs.reciprocal(); }

   const Field operator+(const Field& rhs) const { return Field(*this) += rhs; }
   const Field operator-(const Field& rhs) const { return Field(*this) -= rhs; }
   const Field operator*(const Field& rhs) const { return Field(*this) *= rhs; }
   const Field operator/(const Field& rhs) const { return Field(*this) /= rhs; }

   Field power(int n) const { return BaseRing::power(n); }

   bool operator<(const Field& rhs) const { return BaseRing::operator<(rhs); }
   bool operator>(const Field& rhs) const { return BaseRing::operator>(rhs); }
   bool operator<=(const Field& rhs) const { return BaseRing::operator<=(rhs); }
   bool operator>=(const Field& rhs) const { return BaseRing::operator>=(rhs); }
   bool operator==(const Field& rhs) const { return BaseRing::operator==(rhs); }
   bool operator!=(const Field& rhs) const { return BaseRing::operator!=(rhs); }

};

template<typename superType, class Operators>
