ll Nsum(DP A)
{
	ll ans = 0;
	int i, j, k;
	DP A_next;
	if (A.len == 3)
	{
		for (i = 0; i < 4; i++)
		{
			for (j = 0; j < 4; j++)
			{
				for (k = 0; k < 4; k++)
				{
					ans += A.sum[i][j][k];
					ans = ans % 1000000007;
				}
			}
		}
		return ans;
	}
	else
	{
		A_next.len = A.len - 1;
		for (i = 0; i < 4; i++)
		{
			for (j = 0; j < 4; j++)
			{
				for (k = 0; k < 4; k++)
				{
					A_next.sum[i][j][k] = 0;
					if ((i != 1 || j != 2 || k != 3) && (i != 2 || j != 1 || k != 3) && (i != 1 || j != 3 || k != 2))
					{
						A_next.sum[i][j][k] += A.sum[0][i][j];
						if ((j != 2 || k != 3) && (i != 2 || k != 3))
							A_next.sum[i][j][k] += A.sum[1][i][j];
						A_next.sum[i][j][k] += A.sum[2][i][j];
						A_next.sum[i][j][k] += A.sum[3][i][j];
						A_next.sum[i][j][k] = A_next.sum[i][j][k] % 1000000007;
					}
				}
			}
		}
		ans = Nsum(A_next);
	}

}

