ll dp[105][5][5][5];

const ll MOD = 1e9 + 7;

bool check(int x, int y, int z)
{
    return x == 0 && y == 1 && z == 2;
}

bool checkswap(int j, int k, int l)
{
    return (check(j, k, l) || check(k, j, l) || check(j, l, k));
}

ll binpow(ll a, ll b)
{
    if (!b)
        return 1;
    if (b % 2)
        return a * binpow(a, b - 1) % MOD;
    return binpow(a * a % MOD, b / 2);
}

int solve()
{
    int n;
    if (!(cin >> n))
        return 1;
    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 4; j++)
            for (int k = 0; k < 4; k++)
                if (!checkswap(i, j, k))
                    dp[3][i][j][k] = 1;
    for (int i = 3; i < n; i++)
    {
        for (int j = 0; j < 4; j++)
            for (int k = 0; k < 4; k++)
                for (int l = 0; l < 4; l++)
                    for (int m = 0; m < 4; m++)
                    {
                        if (!checkswap(k, l, m) && !check(j, l, m) && !check(j, k, m))
                            dp[i + 1][k][l][m] = (dp[i + 1][k][l][m] + dp[i][j][k][l]) % MOD;
                    }
    }
    ll ans = 0;
    for (int i = 0; i < 4; i ++)
        for (int j = 0; j < 4; j++)
            for (int k = 0; k < 4; k++)
                ans += dp[n][i][j][k];
