ll MOD = 1000000007;

int dp[101][4][4][4]; // 

int main(){
    int N;
    cin >> N;

    // A: 0
    // G: 0
    // C: 2
    // T: 3

    // 長さ0の文字列は1である。
    // 0,1,2に関する制約しかないので、
    // Sは333Sと考えても問題ない。
    dp[0][3][3][3] = 1;

    // 文字列の文字数
    for (int len=0;len<N;++len) {
        // 最後から1文字目の文字
        for (int c1=0;c1<4;++c1) {
            // 最後から2文字目の文字
            for (int c2=0;c2<4;++c2) {
                // 最後から3文字目の文字
                for (int c3=0;c3<4;++c3) {
                    // 条件に当てはまるものはない。計算量を削減できる。
                    if (dp[len][c1][c2][c3] == 0) continue;

                    for (int a=0;a<4;++a) {
                        // だめな5つの条件をかっとする。
                        if (a == 2 && c1 == 1 && c2 == 0) continue;
                        if (a == 2 && c1 == 0 && c2 == 1) continue;
                        if (a == 2 && c1 == 2 && c2 == 0) continue;
                        if (a == 2 && c1 == 1 && c3 == 0) continue;
                        if (a == 2 && c2 == 1 && c3 == 0) continue;

                        // S = ...... c3 c2 c1
                        // nextS = ...... c2 c1 a
                        dp[len + 1][a][c1][c2] += dp[len][c1][c2][c3];
                        dp[len + 1][a][c1][c2] %= MOD;
                    }
                }
            }
        }
    }

    int ans = 0;
    for (int c1=0;c1<4;++c1) {
        for (int c2=0;c2<4;++c2) {
            for (int c3=0;c3<4;++c3) {
                ans += dp[N][c1][c2][c3];    
            }
        }
    }

    cout << ans  << endl;
}

