        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                for (int p = 0; p < 4; p++) {
                    if (pan(i, j, p)) {
                        dp[3][i][j][p] = 1;
                    }
                }
            }
