                    for (int p = 0; p < 4; p++) {
                        //dp[k][i][j][p]
                        if (pan(i, j, p)) {
                            for (int q = 0; q < 4; q++) {
                                if (pan(q, i, j) && pan1(q, j, p) && pan1(q, i, p)) {
                                    dp[k][i][j][p] = (dp[k][i][j][p] + dp[k - 1][q][i][j]) % mod;
                                } 
                            }
                        }
                    }
                }
            }
