const long long M = 1000000007l;

long long mod(long long val)
{
    long long res = val % M;
    if (res < 0) res += M;
    return res;
}

long long mpow(long long x, long long n)
{
    long long ans = 1;
    while(n != 0){
        if (n & 1) ans = ans * x % M;
        x = x * x % M;
        n = n >> 1;
    }

    return ans;
}

