    out += a2 * a3;

    // 4
    mint b1 = pow(4, (N - 4));
    mint b2 = max(b1.x, 0LL);
    mint b3 = (N - 2);
    out += b2 * b3;

    mint t1 = pow(4, N);
    mint ans = t1 - out;
    cout << ans.x << endl;
}

