bool isok(char t4, char t3, char t2, char t1)
{
    if (t4 == 'A' and t3 == 'G' and t1 == 'C')
        return false;

    if (t4 == 'A' and t2 == 'G' and t1 == 'C')
        return false;

    if ((t4 == 'A' and t3 == 'G' and t2 == 'C') or (t3 == 'A' and t2 == 'G' and t1 == 'C'))
        return false;
    if ((t4 == 'G' and t3 == 'A' and t2 == 'C') or (t3 == 'G' and t2 == 'A' and t1 == 'C'))
        return false;
    if ((t4 == 'A' and t3 == 'C' and t2 == 'G') or (t3 == 'A' and t2 == 'C' and t1 == 'G'))
        return false;

    return true;
}

int N;
string S = "AGCT";
map<string, LL> dp[1000];

string code(char p1, char p2, char p3)
{
    string s = "";
    return s + p1 + p2 + p3;
}

LL rec(int depth, char p1, char p2, char p3)
{
    if (dp[depth].find(code(p1, p2, p3)) != dp[depth].end())
        return dp[depth][code(p1, p2, p3)];

    if (depth == N)
        return 1;

    LL ret = 0;
    for (auto c : S)
        if (isok(p1, p2, p3, c))
            ret = (ret + rec(depth + 1, p2, p3, c)) % mod;

    dp[depth][code(p1, p2, p3)] = ret;
    return ret;
}

void solve()
{
    cin >> N;
    cout << rec(0, '\0', '\0', '\0') << endl;
}

