long Cn(int);//A?BC
long Dn(int);//AB?C

long ADn(int);//ABAC
long CDn(int);//ABBC

long Pn(int);//true

long An(int n) {
	if (n == 3) {
		return 4;
	}
	else if (n == 4) {
		return 15;
	}
	else {
		return Pn(n - 2) - Bn(n - 2);
	}
}

long Bn(int n) {
	if (n == 3) {
		return 3;
	}
	else if (n == 4) {
		return 15;
	}
	else {
		return Pn(n - 2) - An(n - 1);
	}
}

long Cn(int n) {
	if (n == 3) {
		return 3;
	}
	if (n == 4) {
		return 12;
	}
	else if (n == 5) {
		return 48;
	}
	else {
		return Pn(n - 3);
	}
}

long Dn(int n) {
	if (n == 3) {
		return 3;
	}
	if (n == 4) {
		return 12;
	}
	else if (n == 48) {
		return 15;
	}
	else {
		return Pn(n - 3);
	}
} 

long ADn(int n) {
	if (n == 3) {
		return 1;
	}
	if (n == 4) {
		return 4;
	}
	else if (n == 5) {
		return 16;
	}
	else {
		return Pn(n - 3);
	}
}

long CDn(int n) {
	if (n == 3) {
		return 1;
	}
	if (n == 4) {
		return 4;
	}
	else if (n == 5) {
		return 16;
	}
	else {
		return Pn(n - 3);
	}
}
long Pn(int n) {
	if (n == 3) {
		return 61;
	}
	else {
		return 4 * Pn(n - 1) - (An(n - 1) + Bn(n - 1) + Cn(n - 1) + Dn(n - 1) - ADn(n - 1) - CDn(n - 1) );
	}

}
