signed main() {
	cin >> n;
	dp[0][3][3][3] = 1;
	for (int i = 1; i <= n; i++) {//i個目まで見て
		rep(j, 4) {//3個前
			rep(k, 4) {//2個前
				rep(l, 4) {//1個前
					if (j == 0 && k == 2 && l == 1)continue;//AGC〇
					if (j == 2 && k == 0 && l == 1)continue;//GAC〇
					if (j == 0 && k == 1 && l == 2)continue;//ACG〇
					rep(m, 4) {//今見てるやつ
						if (k == 0 && l == 2 && m == 1)continue;//〇AGC
						if (k == 2 && l == 0 && m == 1)continue;//〇GAC
						if (k == 0 && l == 1 && m == 2)continue;//〇ACG
						if (j == 0 && k == 2 && m == 1)continue;//AG〇C
						if (j == 0 && l == 2 && m == 1)continue;//A〇GC
						dp[i][k][l][m] += dp[i - 1][j][k][l];
						dp[i][k][l][m] %= MOD;
					}
				}
			}
		}
	}
	int ans = 0;
	rep(i, 4) {
		rep(j, 4) {
			rep(k, 4) {
				if (i == 0 && j == 2 && k == 1)continue;
				if (i == 2 && j == 0 && k == 1)continue;
				if (i == 0 && j == 1 && k == 2)continue;
				ans += dp[n][i][j][k];
				ans %= MOD;
			}
		}
	}
	cout << ans << endl;
	return 0;
}

