int main(void){
    char AGCT[] = {'A', 'C', 'G', 'T'};
    int N; cin >> N;

    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            for (int k = 0; k < 4; k++) {
                if (i == 0 && j == 2 && k == 1) continue; // AGC
                if (i == 0 && j == 1 && k == 2) continue; // ACG
                if (i == 2 && j == 0 && k == 1) continue; // GAC
                dp[3][i][j][k] = 1;
            }
        }
    }

    for (int len = 4; len <= N; len++) {
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                for (int k = 0; k < 4; k++) {
                    for (int l = 0; l < 4; l++) {
