                        if (j == 0 && k == 1 && l == 2) continue; // ?ACG
                        if (j == 2 && k == 0 && l == 1) continue; // ?GAC
                        if (i == 0 && j == 2 && l == 1) continue; // AG?C
                        if (i == 0 && k == 2 && l == 1) continue;// A?GC
                        dp[len][j][k][l] += dp[len-1][i][j][k];
                        dp[len][j][k][l] %= MOD;
                    }
                }
            }
        }
    }

    long long ans = 0;
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            for (int k = 0; k < 4; k++) {
                ans += dp[N][i][j][k];
                ans %= MOD;
            }
        }
