bool ok(string s){
  if(s[1] == 'A' && s[2] == 'G' && s[3] == 'C') return false;
  if(s[0] == 'A' && s[2] == 'G' && s[3] == 'C') return false;
  if(s[0] == 'A' && s[1] == 'G' && s[3] == 'C') return false;
  if(s[2] == 'A' && s[1] == 'G' && s[3] == 'C') return false;
  if(s[1] == 'A' && s[3] == 'G' && s[2] == 'C') return false;
  return true;
}

int h(char s){
  if(s == 'A') return 0;
  if(s == 'G') return 1;
  if(s == 'C') return 2;
  return 3;
}
void g(int cur, string s, int ret){
  memo[cur][h(s[0])][h(s[1])][h(s[2])] = ret;
}
int f(int cur, string s){
  return memo[cur][h(s[0])][h(s[1])][h(s[2])];
}

int dfs(int cur, string last3){
  if(f(cur, last3) != INF) return f(cur, last3);
  if(cur == N){
    return 1;
  }
  int ret = 0;
  string A[] = {"A", "C", "G", "T"};
  for(string c : A){
    if(ok(last3+c)){
      ret = (ret+dfs(cur+1, (last3.substr(1)+c)))%MOD;
    }
  }
  g(cur, last3, ret);
  return ret;
}

