int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	Int N;
	cin >> N;

	auto dp = make_vec(N + 1, 4, 4, 4,mint(0));


	//AGCTが0123に対応
	for (Int i = 0; i < 4; i++) {
		for (Int j = 0; j < 4; j++) {
			for (Int k = 0; k < 4; k++) {
				if (i == 0 && j == 1 && k == 2)continue;
				if (i == 0 && j == 2 && k == 1)continue;
				if (i == 1 && j == 0 && k == 2)continue;
				dp[3][i][j][k] = 1;
			}
		}
	}

	for (Int n = 3; n < N; n++) {
		for (Int i = 0; i < 4; i++) {
			for (Int j = 0; j < 4; j++) {
				for (Int k = 0; k < 4; k++) {
					for (Int l = 0; l < 4; l++) {
						if (i == 0 && j == 1 && l == 2)continue;
						if (i == 0 && k == 1 && l == 2)continue;
						if (j == 0 && k == 1 && l == 2)continue;
						if (j == 1 && k == 0 && l == 2)continue;
						if (j == 0 && k == 2 && l == 1)continue;
						dp[n + 1][j][k][l] += dp[n][i][j][k];
					}
				}
			}
		}
	}

	mint ans = 0;
	for (Int i = 0; i < 4; i++) {
		for (Int j = 0; j < 4; j++) {
			for (Int k = 0; k < 4; k++) {
				ans += dp[N][i][j][k];
			}
		}
	}

	cout << ans << "\n";
}

