		if(ng(b, c, d) || ng(b, d, c) || ng(c, b, d)) continue;
		if(ng(a, c, d) || ng(a, b, d)) continue;
		add(dp[i+1][b][c][d], dp[i][a][b][c]);
	}
	int64_t ans = 0;
	for(int i = 0; i < n; i++) for(int a = 0; a < 4; a++) for(int b = 0; b < 4; b++) for(int c = 0; c < 4; c++) {
		add(ans, dp[n][a][b][c]);
	}
	cout << ans << endl;
}
int main() {
	dp[0][0][0][0] = 1;
	cin >> n;
	solve();
	return 0;
}

