int dp[101][4][4][4];

int main()
{
	int n;
	cin >> n;

	dp[0][3][3][3] = 1;

	rep(len, n)
	{
		rep(i, 4)
		{
			rep(j, 4)
			{
				rep(k, 4)
				{
					if (dp[len][i][j][k] == 0)
					{
						continue;
					}

					rep(a, 4)
					{
						if (a == 2 && (i == 0) && (j == 1)) continue;
						if (a == 2 && (i == 1) && (j == 0)) continue;
						if (a == 1 && (i == 2) && (j == 0)) continue;
						if (a == 2 && (i == 1) && (k == 0)) continue;
						if (a == 2 && (j == 1) && (k == 0)) continue;

						dp[len+1][a][i][j] += dp[len][i][j][k];
						dp[len+1][a][i][j] %= MOD;
					}
				}
			}
		}
	}
	int ans = 0;

	rep(i, 4)
	{
		rep(j, 4)
		{
			rep(k, 4)
			{
				ans += dp[n][i][j][k];
			}
		}
	}

	cout << ans << endl;

	return 0;
}

