ll N, mod = 1000000007;
map<pair<int, string>, ll> memo;
vector<char> acgt = vector<char> { 'A', 'C', 'G', 'T' };

bool is_agc(string last4) {
  rep(i, 4) {
    string s = last4;
    if(i<3) swap(s[i], s[i+1]);
    rep(j, 2) if(s[j] == 'A' && s[j+1] == 'G' && s[j+2] == 'C') return true;
  }
  return false;
}

ll dfs(int cur, string last3) {
  auto memo_itr = memo.find(make_pair(cur, last3));
  if(memo_itr != memo.end()) return memo_itr->second;
  if(cur==N) return 1ll;
  ll res = 0ll;
  for(const char& c : acgt) {
    if(!is_agc(last3+c)) res = (res + dfs(cur+1, (last3+c).substr(1))) % mod;
  }
  return memo[make_pair(cur, last3)] = res;
}

void solve() {
  cout << dfs(0, "TTT") << endl;
  return;
}

int main() {
  cin >> N;
  solve();
  return 0;
}

