typedef long long ll;
const ll mod = 1000000000+9;
ll mod_pow(ll N, ll P, ll M){
    if(P==0) return 1;
    if(P%2==0){
        ll t = mod_pow(N, P/2, M);
        return t*t % M;
    }
    return N * mod_pow(N, P-1, M);
}

