bool isNG(int x, int y, int z)
{
    return (x == A && y == G && z == C);
}

bool isNG(int a, int b, int c, int d)
{
    return
        isNG(b, c, d) ||
        isNG(c, b, d) ||
        isNG(b, d, c) ||

        isNG(a, c, d) ||
        isNG(a, b, d) ||

        isNG(a, b, c) ||
        isNG(b, a, c) ||
        isNG(a, c, b);
}

i64 slv(int idx, int a, int b, int c)
{
    if (idx >= N) {
        return 1;
    }
    int &ret = dp[idx][a][b][c];
    if (~ret) return ret;

    ret = 0;
    for (int x = 0; x <= 3; ++x) {
        if (!isNG(a, b, c, x)) ret = (ret + slv(idx + 1, b, c, x)) % MOD;
    }

    return ret;
}

