using namespace std;
using large = long long;
constexpr int M = 1'000'000'007;
enum { A, C, G, T };

int pack(int x, int y, int z) {
    return x * 16 + y * 4 + z;
}


int main()
{
    int n;
    cin >> n; // 100

    auto dp = vector<array<large, 64>>(n + 1);
    for (auto& x : dp[3])
        x = 1;
    dp[3][pack(A, G, C)] = 0;
    dp[3][pack(A, C, G)] = 0;
    dp[3][pack(G, A, C)] = 0;

    for (int i = 3; i <= n; ++i) {
        assert(dp[i][pack(A, G, C)] == 0);
        assert(dp[i][pack(A, C, G)] == 0);
        assert(dp[i][pack(G, A, C)] == 0);
        if (i == n) break;

        // Add 'A'
        for (auto x : {A, C, G, T}) {
            for (auto y : {A, C, G, T}) {
                for (auto z : {A, C, G, T}) {
                    dp[i + 1][pack(y, x, A)] += dp[i][pack(z, y, x)];
                }
                dp[i + 1][pack(y, x, A)] %= M;
            }
        }

        // Add 'C'
        for (auto x : {A, C, G, T}) {
            for (auto y : {A, C, G, T}) {
                if ((x == A && y == G) || (x == G && y == A)) {
                    continue;
                }
                for (auto z : {A, C, G, T}) {
                    if (z == A && (x == G || y == G))
                        continue;
                    dp[i + 1][pack(y, x, C)] += dp[i][pack(z, y, x)];
                }
                dp[i + 1][pack(y, x, C)] %= M;
            }
        }

        // Add 'G'
        for (auto x : {A, C, G, T}) {
            for (auto y : {A, C, G, T}) {
                if (x == C && y == A) {
                    continue;
                }
                for (auto z : {A, C, G, T}) {
                    dp[i + 1][pack(y, x, G)] += dp[i][pack(z, y, x)];
                }
                dp[i + 1][pack(y, x, G)] %= M;
            }
        }

        // Add 'T'
        for (auto x : {A, C, G, T}) {
            for (auto y : {A, C, G, T}) {
                for (auto z : {A, C, G, T}) {
                    dp[i + 1][pack(y, x, T)] += dp[i][pack(z, y, x)];
                }
                dp[i + 1][pack(y, x, T)] %= M;
            }
        }
   }

    cout << (accumulate(dp[n].begin(), dp[n].end(), 0LL) % M) << endl;
    return 0;
}

