//A:1 C:2 G:3 T:4
bool check(vector<int> v) {
	for (int i = 0; i < 2; i++) {
		if (v[i] == 1 && v[i+1] == 3 && v[i+2] == 2) return false;
	}
	for (int j = 0; j < 3; j++) {
		swap(v[j],v[j+1]);
		for (int i = 0; i < 2; i++) {
			if (v[i] == 1 && v[i+1] == 3 && v[i+2] == 2) return false;
		}
		swap(v[j],v[j+1]);
	}
	return true;
}
void init(){
	for (int i = 1; i <= 4; i++) {
		for (int j = 1; j <= 4; j++) {
			for (int k = 1; k <= 4; k++) {
				for (int l = 1; l <= 4; l++) {
					vector<int> vec;
					vec.push_back(i); vec.push_back(j); vec.push_back(k); vec.push_back(l);
					if (check(vec)) g[i][j][k].push_back(l);
				}
			}
		}
	}
	for (int i = 1; i <= 4; i++) {
		for (int j = 1; j <= 4; j++) {
			for (int k = 1; k <= 4; k++) {
				f[3][i][j][k] = 1;
			}
		}
	}
	f[3][1][3][2] = f[3][3][1][2] = f[3][1][2][3] = 0;
}

int main() {
	scanf("%d",&n);
	init();
	for (int i = 3; i < n; i++) {
		for (int j = 1; j <= 4; j++) {
			for (int k = 1; k <= 4; k++) {
				for (int l = 1; l <= 4; l++) {
					for (int sz = 0; sz < g[j][k][l].size(); sz++) {
						int c = g[j][k][l][sz];
						f[i+1][k][l][c] = (f[i+1][k][l][c] + f[i][j][k][l])%mod;
					}
				}
			}
		}
	}
	int ret = 0;
	for (int i = 1; i <= 4; i++) {
		for (int j = 1; j <= 4; j++) {
			for (int k = 1; k <= 4; k++) {
				ret = (ret+f[n][i][j][k])%mod;
			}
		}
	}
	printf("%d\n",ret);
	return 0;
}

