struct mint {
    ll x;
    mint(ll x=0):x((x%MOD+MOD)%MOD){}
    mint operator-() const { return mint(-x);}
    mint& operator+=(const mint a) {if ((x+=a.x)>=MOD) x-=MOD; return *this;}
    mint& operator-=(const mint a) {if ((x+=MOD-a.x)>=MOD) x-=MOD; return *this;}
    mint& operator*=(const mint a) {(x*=a.x)%=MOD; return *this;}
    mint operator+(const mint a) const {mint res(*this); return res+=a;}
    mint operator-(const mint a) const {mint res(*this); return res-=a;}
    mint operator*(const mint a) const {mint res(*this); return res*=a;}
    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t>>1);
        a *= a;
        if (t&1) a *= *this;
        return a;
    }

    // for prime mod
    mint inv() const { return pow(MOD-2);}
    mint& operator/=(const mint a) { return (*this) *= a.inv();}
    mint operator/(const mint a) const {mint res(*this); return res/=a;}
};

int f(string s) {
	map<char, int> m;
	m['A'] = 0;
	m['C'] = 1;
	m['G'] = 2;
	m['T'] = 3;
	int ret = 0;
	rep(i, s.size()) ret += pow(4, s.size() - i - 1) * m[s[i]];
	return ret;
}

int main() {
	int n;
	cin >> n;
	mint dp[101][64];
	rep(i, 64) dp[3][i] = 1;
	dp[3][f("AGC")] = 0;
	dp[3][f("ACG")] = 0;
	dp[3][f("GAC")] = 0;
	for(int i = 4; i <= n; i++) {
		rep(j, 64) dp[i][j] = 0;
		rep(j, 64) {	// old 3 chars
			rep(k, 4) {	// new char to be added
				if((j >> 2) == f("AG") && k == f("C")) {
					continue;	// skip for AG?C
				}
				if((j >> 4) == f("A") && (j % 4) == f("G") && k == f("C")) {
					continue;	// skip for A?GC
				}
				dp[i][(j << 2) % 64 + k] += dp[i - 1][j];
			}
		}
		dp[i][f("AGC")] = 0;
		dp[i][f("ACG")] = 0;
		dp[i][f("GAC")] = 0;
	}
	mint ans = 0;
	rep(i, 64) ans += dp[n][i];
	cout << ans.x << endl;
}

