bool isNotValid(string lastFour) {
    return (lastFour[0] == 'A' && lastFour[1] == 'G' && lastFour[3] == 'C') || (lastFour[0] == 'A' && lastFour[2] == 'G' && lastFour[3] == 'C');
}

ll dfs(int curLen, string lastThree) {
    if (memo[curLen].find(lastThree) != memo[curLen].end()) return memo[curLen].at(lastThree);
    if (curLen == n) return 1;
    ll ret = 0;
    for (auto& o : orig) {
        string next = lastThree+o;
        if (!isNotValid(next) && next.substr(1, 3) != "AGC" && next.substr(1, 3) != "GAC" && next.substr(1, 3) != "ACG") ret += dfs(curLen+1, next.substr(1, 3));
    }
    memo[curLen].insert({ lastThree, ret % mod });
    return ret % mod;
}

