lint rec(int n,int a,int b,int c)
{
	if(dp[n][a][b][c]!=-1)
		return dp[n][a][b][c];

	lint ret=0;
	if(n==N)
	{
		ret=1;
		if(a==A && b==G && c==C)
			ret=0;
		else if(a==A && b==C && c==G)
			ret=0;
		else if(a==G && b==A && c==C)
			ret=0;
		dp[n][a][b][c]=ret;
		return ret;
	}

	if(a==A && b==G && c==C)
		ret=0;
	else if(a==A && b==C && c==G)
		ret=0;
	else if(a==G && b==A && c==C)
		ret=0;
	else if((a==A && c==G) || (a==A && b==G))
	{
		for(int i=0;i<4;i++)
		{
			if(i==C)
				continue;
			ret+=rec(n+1,b,c,i);
			ret%=mod;
		}
	}
	else
	{
		for(int i=0;i<4;i++)
		{
			ret+=rec(n+1,b,c,i);
			ret%=mod;
		}
	}

	dp[n][a][b][c]=ret;
	return ret;
}

