            if(j == 0 && i == 2 && nxt == 1) continue;
            if(j == 1 && i == 0 && nxt == 2) continue;
            if(k == 0 && i == 1 && nxt == 2) continue;
            if(k == 0 && j == 1 && nxt == 2) continue;

            dp[len + 1][nxt][i][j] += dp[len][i][j][k];
            dp[len + 1][nxt][i][j] %= MOD;
          }
        }
      }
    }
  }
  ll ans = 0;
  REP(i, 4){
    REP(j, 4){
      REP(k, 4){
        ans += dp[n][i][j][k];
        ans %= MOD;
      }
    }
  }
  cout << ans << endl;
  return 0;
}

