        if((i ==0 && j == 1 && k ==2) || (i ==1 && j == 0 && k ==2) || (i ==0 && j == 2 && k ==1)){
            dp[3][i][j][k] = 0;
        }else{
            dp[3][i][j][k] = 1;
            sum[3] += dp[3][i][j][k];
        }
    }}}

    for(int s = 4; s <= 100;s++){
        rep0(i,3){rep0(j,3){rep0(k,3){
            dp[s][i][j][k] = 0;
            if(k == 0 || k == 3){
                rep0(l,3) dp[s][i][j][k] += dp[s-1][l][i][j]; 
            }else if(k == 1){
                if(i == 0 && j == 2);
                else rep0(l,3) dp[s][i][j][k] += dp[s-1][l][i][j];
            }else if(k == 2){
                if((i == 0 && j == 1) || (i == 1 && j == 0));
