                    rep0(l,3){
                        if(l == 0) continue;
                        dp[s][i][j][k] += dp[s-1][l][i][j];
                    }
                }else{
                    rep0(l,3) dp[s][i][j][k] += dp[s-1][l][i][j];
                }
            }
            sum[s] += dp[s][i][j][k];
        }}}
    }

    ll mod = 1e9 + 7;
