using namespace std;

// 多次元 vector 生成
template <class T>
vector<T> make_vec(size_t a)
{
	return vector<T>(a);
}
template <class T, class... Ts>
auto make_vec(size_t a, Ts... ts)
{
	return vector<decltype(make_vec<T>(ts...))>(a, make_vec<T>(ts...));
}

void execute()
{
	int N;
	cin >> N;
	//AGC ACG GAC AxGC AGxC
	//vector<vector<vector<vector<lint>>>> DP(N + 1, vector<vector<vector<lint>>>(5, vector<vector<lint>>(5, vector<lint>(5, 0))));
	auto DP = make_vec<lint>(N + 1, 5, 5, 5);
	DP[0][0][0][0] = 1;

	for (int i = 0; i < N; i++)
	{
		for (int current = 1; current < 5; current++)
		{
			for (int b1 = 0; b1 < 5; b1++)
			{
				for (int b2 = 0; b2 < 5; b2++)
				{
					if (current == 1 && b1 == 2 && b2 == 3)
						continue;
					if (current == 1 && b1 == 3 && b2 == 2)
						continue;
					if (current == 2 && b1 == 1 && b2 == 3)
						continue;

					for (int b3 = 0; b3 < 5; b3++)
					{
						if (current == 1 && b2 == 2 && b3 == 3)
							continue;
						if (current == 1 && b1 == 2 && b3 == 3)
							continue;
						DP[i + 1][current][b1][b2] += DP[i][b1][b2][b3];
						DP[i + 1][current][b1][b2] %= INV;
					}
				}
			}
		}
	}

	int ans = 0;
	for (int current = 0; current < 5; current++)
	{
		for (int b1 = 0; b1 < 5; b1++)
		{
			for (int b2 = 0; b2 < 5; b2++)
			{
				ans += DP[N][current][b1][b2];
				ans %= INV;
			}
		}
	}

	cout << ans << endl;
	return;
}

