const ll MOD = 1e9 + 7;

bool check(string mask) {
  if (mask.find("AGC") != string::npos) return false;
  for (int i = 0; i + 1 < mask.size(); i++) {
    swap(mask[i], mask[i + 1]);
    if (mask.find("AGC") != string::npos) {
      return false;
    }
    swap(mask[i], mask[i + 1]);
  }
  return true;
}

int main() {
#ifdef DEBUG
  ifstream cin("in.txt");
#endif
  int N;
  while (cin >> N) {
    const int threshold = 3;
    const string alpha = "ATCG";
    map<string, ll> dp;
    dp[""] = 1;
    for (int t = 0; t < N; t++) {
      map<string, ll> ndp;
      for (auto& entry : dp) {
        string mask = entry.fst;
        ll ways = entry.snd;
        for (char c : alpha) {
          string newMask = mask + c;
          if (check(newMask)) {
            (ndp[newMask.size() > threshold ? newMask.substr(newMask.size() - threshold) : newMask] += ways) %= MOD;
          }
        }
      }
      dp = ndp;
    }
    ll res = 0;
    for (auto& entry : dp) res = (res + entry.snd) % MOD;
    cout << res << endl;
  }
  return 0;
}

