ll mod = 1000000007;

int main () {
    ll N;

    cin >> N;

    for (int j = 0; j < 4; j++) {
        for (int k = 0; k < 4; k++) {
            for (int l = 0; l < 4; l++) {
                if (j == 0 && k == 2 && l == 1) continue;
                if (j == 0 && k == 1 && l == 2) continue;
                if (j == 2 && k == 0 && l == 1) continue;
                dp[3][j][k][l] = 1;
            }
        }
    }

    for (int i = 3; i < N; i++) {
        for (int j = 0; j < 4; j++) {
            for (int k = 0; k < 4; k++) {
                for (int l = 0; l < 4; l++) {
                    for (int m = 0; m < 4; m++) {
                        if (k == 0 && l == 2 && m == 1) continue;
                        if (k == 0 && l == 1 && m == 2) continue;
                        if (k == 2 && l == 0 && m == 1) continue;
                        if (j == 0 && l == 2 && m == 1) continue;
                        if (j == 0 && k == 2 && m == 1) continue;
                        (dp[i + 1][k][l][m] += dp[i][j][k][l]) %= mod;
                    }
                }
            }
        }
    }

    ll ans = 0;
    for (int j = 0; j < 4; j++) {
        for (int k = 0; k < 4; k++) {
            for (int l = 0; l < 4; l++) {
                (ans += dp[N][j][k][l]) %= mod;
            }
        }
    }

    cout << ans << endl;

    return 0;

}

