using namespace std;

typedef long long ll;

ll dp[105][4][4][4];
int n;
string oni[4] = {"A", "C", "G", "T"};
const ll mod = (ll)1e9 + 7;

string nadi(string s, int poc){
	string ret = "";
	for(int i = poc ; i < poc + 3 ; ++i){
		ret += s[i];
	}
	return ret;
}

bool dobar(string s){
	if(nadi(s, 0) == "AGC" || nadi(s, 1) == "AGC")
		return 0;
	return 1;
}

bool provjeri(string s){
	for(int i = 0 ; i < 3 ; ++i){
		swap(s[i], s[i + 1]);
		if(!dobar(s))
			return 0;
		swap(s[i], s[i + 1]);
	}
	return dobar(s);
}

int main(){
ios_base::sync_with_stdio(false);
cin.tie(0);
cout.tie(0);
cin >> n;
for(int i = 0 ; i < 4 ; ++i){
	for(int j = 0 ; j < 4 ; ++j){
		for(int v = 0 ; v < 4 ; ++v){
			dp[2][i][j][v] = 1;
		}
	}
}
dp[2][0][2][1]--;
dp[2][0][1][2]--;
dp[2][2][0][1]--;
for(int i = 3 ; i < n ; ++i){
	for(int j = 0 ; j < 4 ; ++j){
		for(int v = 0 ; v < 4 ; ++v){
			for(int l = 0 ; l < 4 ; ++l){
				for(int w = 0 ; w < 4 ; ++w){
					string s = oni[j] + oni[v] + oni[l] + oni[w];
					if(provjeri(s)){
						dp[i][v][l][w] = (dp[i][v][l][w] + dp[i - 1][j][v][l]) % mod;
					}
				}
			}
		}
	}
}
ll sol = 0;
for(int i = 0 ; i < 4 ; ++i){
	for(int j = 0 ; j < 4 ; ++j){
		for(int v = 0 ; v < 4 ; ++v){
			sol = (sol + dp[n - 1][i][j][v]) % mod;
		}
	}
}
cout << sol << endl;

return 0;
}

