#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

int main(){
    int n;
    cin >> n;

    vector<vector<vector<vector<long long int>>>> 
    dp(n+1, 
        vector<vector<vector<long long int>>>(4, 
            vector<vector<long long int>>(4, 
                vector<long long int>(4)
            )
        )
    );
    //d[n][a1][a2][a3] = number of n letters ending with [a3 a2 a1]
    dp[0][0][0][0] = 1;
    for(int i=0; i<n; i++){
        for(int a1=0; a1<4; a1++){// 1 = A, 2 = C, 3 = G, 0 = T
            for(int a2=0; a2<4; a2++){
                for(int a3=0; a3<4; a3++){
                    for(int b=0; b<4; b++){
                        if(b == 2 && a1 == 3 && a2 == 1) continue;// ?AGC
                        if(b == 2 && a1 == 1 && a2 == 3) continue;// ?GAC
                        if(b == 3 && a1 == 2 && a2 == 1) continue;// ?ACG
                        if(b == 2 && a2 == 3 && a3 == 1) continue;// AG?C
                        if(b == 2 && a1 == 3 && a3 == 1) continue;// A?GC
                        dp[i+1][b][a1][a2] += dp[i][a1][a2][a3];
                        dp[i+1][b][a1][a2] %= MOD;
                    }
                }
            }
        }
    }
    long long int answer = 0;
    for(int a1=0; a1<4; a1++){
        for(int a2=0; a2<4; a2++){
            for(int a3=0; a3<4; a3++){
                answer += dp[n][a1][a2][a3];
                answer %= MOD;
            }
        }
    }
    cout << answer << endl;
    return 0;
}

