constexpr ll p = 1000000007ll;
constexpr int GENOM_EMPTY = 0;
constexpr int GENOM_A = 1;
constexpr int GENOM_T = 2;
constexpr int GENOM_G = 3;
constexpr int GENOM_C = 4;

vector<vector<ll>> mltm(const vector<vector<ll>> &a, const vector<vector<ll>> &b) {
    ull m = a.size(), q = b.size(), r = b[0].size();
    vector<vector<ll>> c(m, vector<ll>(r, 0));
    REP(i, m) REP(j, r) {
        REP(k, m) {
            c[i][j] += a[i][k] * b[k][j] % p;
            c[i][j] %= p;
        }
    }
    return c;
}

vector<vector<ll>> powm(const vector<vector<ll>> &a, const ll n) {
    if (n == 0) {
        vector<vector<ll>> r(a.size(), vector<ll>(a[0].size(), 0));
        REP(i, a.size()) r[i][i] = 1;
        return r;
    } else if (n == 1) {
        return a;
    } else if (n % 2 == 0) {
        vector<vector<ll>> t = powm(a, n/2);
        return mltm(t, t);
    } else if (n % 2 == 1) {
        vector<vector<ll>> t = powm(a, n/2);
        return mltm(mltm(t, t), a);
    }
}

