using namespace std;

class Solution {
public:
    int solve(int n) {
        const long long MOD = 1000000007;
        string t = "AGC";
        string A = "ACGT";

        int MX = 4;
        auto good = [&](string& s) {
            if (s.length() < 3) {
                return true;
            }
            if (s.length() <= MX) {
                if (s.find(t) != string::npos) {
                    return false;
                }
                int n = s.length();
                for (int i = 0; i + 1 < n; ++i) {
                    swap(s[i], s[i + 1]);
                    if (s.find(t) != string::npos) {
                        return false;
                    }
                    swap(s[i], s[i + 1]);
                }
                return true;
            }
            return false;
        };

        vector<string> que;
        que.emplace_back("");

        for (int i = 0; i < que.size(); ++i) {
            string s = que[i];
            // cout << s << endl;
            for (auto c : A) {
                string ns = s + c;
                if (good(ns)) {
                    que.emplace_back(ns);
                }
            }
        }
        int m = que.size();
        vector<vector<int>> nexts(m, vector<int>(4, -1));
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < A.length(); ++j) {
                string ns = que[i];
                ns += A[j];
                if (ns.length() > MX) {
                    ns = ns.substr(1);
                }
                for (int k = 0; k < m; ++k) {
                    if (que[k] == ns) {
                        nexts[i][j] = k;
                        break;
                    }
                }
            }
        }
        vector<long long> dp(m + 1, 0);
        dp[0] = 1;

        auto ndp = dp;
        for (int i = 0; i < n; ++i) {
            fill(ndp.begin(), ndp.end(), 0);
            for (int j = 0; j < m; ++j) {
                if (dp[j] == 0) {
                    continue;
                }
                for (int k = 0; k < A.length(); ++k) {
                    int nj = nexts[j][k];
                    if (nj >= 0 && nj < m) {
                        (ndp[nj] += dp[j]) %= MOD;
                    }
                }
            }
            swap(dp, ndp);
        }

        long long res = 0;
        for (int i = 0; i < m; ++i) {
            res += dp[i];
        }
        res %= MOD;
        return res;
    }
};

