                        if(a == 1 && b == 2 && d == 3) {
                            continue;
                        }
                        if(b == 1 && c == 2 && d == 3) {
                            continue;
                        }
                        if(b == 2 && c == 1 && d == 3) {
                            continue;
                        }
                        if(b == 1 && c == 3 && d == 2) {
                            continue;
                        }
                        add(dp[i + 1][b][c][d], dp[i][a][b][c]);
                    }
                }
            }
        }
    }
    long long res = 0;
    rep(i, 1, 5) {
        rep(j, 1, 5) {
            rep(k, 1, 5) { add(res, dp[N][i][j][k]); }
        }
    }
    return res;
}
