ll dp[101][445];
ll solve(int N, int n, int last3){
    if(n == 0)
    return 1;
    if(dp[n][last3] != -1)
    return dp[n][last3];
    ll so = 0;
    for(int i = 1; i <= 4; i++){
        if(i == 2){
            if(last3 % 100 != 13){
                int temp =  last3 % 100;
                temp = temp * 10 + 2;
                so += solve(N, n-1, temp);
            }
        }
        else if(i == 3){
            if(last3 % 100 != 21 && last3 % 100 != 12 && last3 != 112 && last3 != 122 && last3 != 132 && last3 != 142 && last3 != 121 && last3 != 122 && last3 != 123 && last3 != 124){
                int temp =  last3 % 100;
                temp = temp * 10 + 3;
                so += solve(N, n-1, temp);
            }
        }
        else{
                int temp =  last3 % 100;
                temp = temp * 10 + i;
                so += solve(N, n-1, temp);
        }
        so %= mod;
    }
    return dp[n][last3] = so;
}
