struct UnionFind {
	vi par, sz;
	int component;
	UnionFind(int n) :par(n), sz(n, 1) {
		rep(i, n) {
			par[i] = i;
		}
		component = n;
	}

	int root(int x) {
		return x == par[x] ? x : par[x] = root(par[x]);
	}

	void unite(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y)return;
		if (sz[x] < sz[y])swap(x, y);
		par[y] = x;
		sz[x] += sz[y];
		component--;
	}

	bool same(int x, int y) {
		return root(x) == root(y);
	}

	int size(int x) {
		return sz[root(x)];
	}

};

