}

bool ok(string s){
  string s4;
  if(s.size()<3){
    return true;
  }else if(s.size()==3){
    if(s=="AGC"||s=="GAC"||s=="ACG"){
    return false;
  }
  }else{
    s4 = s.substr(s.size()-4,4);
  }
  if(agc(s4)){
        return false;
  }
  for(int i=0;i<3;i++){
    string str = s4;
    str[i]=s4[i+1];
    str[i+1]=s4[i];
    if(agc(str)){
        return false;
    }
  }
  return true;
}

int f_count(string s,int count){
