  string s3;
  if(s.size() >=3)s3 = s.substr(s.size()-3,3);
  if(s.size()<N){

    for(int i=0;i<memo.size();i++){
      if(memo[i].first==s.size() && s3==memo[i].second.first &&s.size()>=3){
        return memo[i].second.second;
      }
    }

    if(ok(s)){
      ans += f_count(s+"A",count)%MOD;
      ans += f_count(s+"C",count)%MOD;
      ans += f_count(s+"G",count)%MOD;
      ans += f_count(s+"T",count)%MOD;
      memo.push_back(make_pair(s.size(),make_pair(s3,ans)));
      //cout << s3 <<" " << s.size() << endl;
      return ans;
