          }
        }
      }
    }
  }
  mint res = 0;
  for(int i = 1; i < 5; ++i) {
    for(int j = 1; j < 5; ++j) {
      for(int k = 1; k < 5; ++k) {
        res += dp[N][i][j][k];
      }
    }
  }
  cout << res << endl;
}

