constexpr int getStride(int nStates){
    --nStates;
    int stride = 0;
    while(nStates != 0){
        ++stride;
        nStates >>= 1;
    }
    return stride;
}
constexpr int nStates = 4;
constexpr int stride = getStride(nStates);

constexpr int nElements = 3;
using State = std::array<int, nElements>;

using T = int;
T toID(const State &S){
    T id = 0;
    for(int i=0; i<nElements; ++i){
        id <<= stride;
        id |= S[i];
    }
    return id;
}
State toState(T id){
    State S;
    for(int i=0; i<nElements; ++i){
        S[nElements-1 - i] = id&((1<<stride)-1);
        id >>= stride;
    }
    return S;
}

int main(int argc, char *argv[]){
    constexpr long long mod = 1000000000LL + 7LL;
    constexpr std::array<State, 3> allBanned = {State{0,1,2},State{1,0,2},State{0,2,1}};
    constexpr std::array<State, 16> cBanned =  {State{0,0,1},State{1,0,1},State{2,0,1},State{3,0,1},
                                                State{0,0,1},State{0,1,1},State{0,2,1},State{0,3,1},
                                                State{0,1,0},State{0,1,1},State{0,1,2},State{0,1,3},
                                                State{0,1,0},State{1,1,0},State{2,1,0},State{3,1,0}};
    constexpr std::array<State, 4> gBanned =   {State{0,0,2},State{1,0,2},State{2,0,2},State{3,0,2}};

    int N;
    std::cin >> N;

    static long long dp[128][64];
    for(int j=0; j<64; ++j){
        auto S = toState(j);
        if(std::find(allBanned.begin(),allBanned.end(),S) == allBanned.end()){
            dp[2][j] = 1LL;
        }
    }

    for(int i=3; i<N; ++i){
        for(int j=0; j<64; ++j){
            auto S = toState(j);
            for(int k=0; k<4; ++k){
                auto id = toID(State{S[1],S[2],k});
                bool isBanned = false;
                switch(k){
                case 1:
                    if(std::find(gBanned.begin(),gBanned.end(),S) != gBanned.end()){
                        isBanned = true;
                    }
                    break;
                case 2:
                    if(std::find(cBanned.begin(),cBanned.end(),S) != cBanned.end()){
                        isBanned = true;
                    }
                    break;
                }
                dp[i][id] += isBanned ? 0LL : dp[i-1][j];
                dp[i][id] %= mod;
            }
        }
    }

    long long sum = 0LL;
    for(int i=0; i<64; ++i){
        sum += dp[N-1][i];
        sum %= mod;
    }

    std::cout << sum << std::endl;

    return 0;
}

