const int MOD = 1000000007, INF = 1111111111; 
using namespace std;
typedef long long lint;

lint powmod(int a,int n, int mod = MOD) {
	lint res = 1;
	while (n > 0) {
		if (n & 1) res = res * a % mod;
		a = a * a % mod;
		n >>= 1;
	}
	return res;
}

class Combi {
private:
	vector<lint> fac, inv, finv;

	void init(int N) {
		fac[0] = fac[1] = 1; inv[1] = 1; finv[0] = finv[1] = 1;

		for (int i = 2; i < N; i++) {
			fac[i] = fac[i - 1] * i % MOD;
			inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
			finv[i] = finv[i - 1] * inv[i] % MOD;
		}
	}

public:
	Combi(int N = 100000) : fac(N + 1), inv(N + 1), finv(N + 1) { init(N + 1); }

	lint Cmod(int n, int k) {
		if (n < k) return 0;
		if (n < 0 || k < 0) return 0;
		return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
	}

	lint Pmod(int n, int k) {
		if (n < k) return 0;
		if (n < 0 || k < 0) return 0;
		return fac[n] * finv[n - k] % MOD;
	}
};

int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int N;
	cin >> N;

	Combi Combi(N);
	lint sum1, sum2, sum3;

	// AGC, ACG, GACを含む文字列の数
	sum1 = Combi.Cmod(N / 3 + N % 3, N / 3) * powmod(3, N / 3) % MOD * powmod(4, N % 3) % MOD;

	// ATGC, AGGC, AGTCを含み、GACGを含まない文字列の数
	sum2 = N > 3 ? Combi.Cmod(N / 4 + N % 4, N / 4) * powmod(3 - 1, N / 4) % MOD * powmod(4, N % 4) % MOD : 0;

	// AGACG, ACGACを含む文字列の数（上の文字列の被り）
	sum3 = N > 4 ? Combi.Cmod(N / 5 + N % 5, N / 5) * powmod(2, N / 5) % MOD * powmod(4, N % 5) % MOD : 0;

	DMP(sum1);
	DMP(sum2);
	DMP(sum3);

	cout << (powmod(4, N) - ((sum1 + sum2) % MOD - sum3 + MOD) % MOD + MOD) % MOD;

	return 0;
}

