const int INF = 1e9;
const int MOD = 1e9 + 7;

ll repeatSquaring(ll n, ll p)
{
  if (p == 0)
    return 1;
  if (p % 2 == 0)
  {
    ll t = repeatSquaring(n, p / 2);
    return (t * t) % MOD;
  }
  return (n * repeatSquaring(n, p - 1)) % MOD;
}

int main()
{
  ll n;
  cin >> n;

  ll ans = repeatSquaring(4, n);
  ll res = 0;
  if (n == 3)
    res = 3;
  else
  {
    res = (3 * ((n - 3 + 1) * repeatSquaring(4, n - 3) % MOD)) % MOD;
    res = (res + (2 * ((n - 4 + 1) * repeatSquaring(4, n - 4) % MOD) % MOD)) % MOD;
  }
  ans -= res;
  if (ans < 0)
    ans += MOD;
  cout << ans << endl;

  return 0;
}

