// DPの問題
// DP=計算をまとめるテクニック　まとめ方を知らなかったのでDPを思いつかなかったのが敗因
//「状態」を考えることが重要
//問題を分解する思考が必要だった　条件を満たす文字Sに'A'~'T'を足しても成立するのか？
//足しても成立するかどうかは、足したものを含まないで末尾3文字が分かれば良い
// A~Tは0,1,2,3と数字にして扱いやすいようにしよう。A 0    G 1    C 2    T 3
// 012,021,102,01*2,0*12の5パターン

long long dp
    [101][4][4]
    [4];  //キャッシュ効率も悪くなるのでvectorではなく生配列で　動的に設定できないので101

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int N;
  cin >> N;

  //文字数　最後から3文字目、2文字目、1文字目の四つの「状態」をまとめあげる
  //文字数0の状態数は1　Tつまり3は文字制約に関係ないので333Sとして考えれば良い
  dp[0][3][3][3] = 1;
  // iは文字列の文字数
  // jは最後から1文字目　kは最後から2文字目　lは最後から3文字目 渡すdp
  for (int len = 0; len < N; len++) {
    for (int c1 = 0; c1 < 4; c1++) {
      for (int c2 = 0; c2 < 4; c2++) {
        for (int c3 = 0; c3 < 4; c3++) {
          //早くするためだけ　だいたい早くなるので入れる癖をつけるといい
          if (dp[len][c1][c2][c3] == 0) continue;

          //新しく末尾に追加する文字
          for (int a = 0; a < 4; a++) {
            dp[len + 1][a][c1][c2] += dp[len][c1][c2][c3];

            // 1を追加 // 021パターン
            if (a == 1 && c1 == 2 && c2 == 0) {
              dp[len + 1][a][c1][c2] -= dp[len][c1][c2][c3];
            }

            // 2を追加 // 012,102,01*2,0*12の5パターン
            if (a == 2) {
              if ((c1 == 1 && c2 == 0) || (c1 == 0 && c2 == 1) ||
                  (c3 == 0 && c2 == 1) || (c3 == 0 && c1 == 1)) {
                dp[len + 1][a][c1][c2] -= dp[len][c1][c2][c3];
              }
            }
          }
        }
      }
    }
  }
  long long rep = 0;
  for (int c1 = 0; c1 < 4; c1++) {
    for (int c2 = 0; c2 < 4; c2++) {
      for (int c3 = 0; c3 < 4; c3++) {
        rep += dp[N][c1][c2][c3];
      }
    }
  }
  long long mod = 1'000'000'007;
  cout << rep % mod << '\n';
}

