int INF=1<<29;
ll mod=1000000007;

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);

	ll N;
	cin>>N;
	ll dp[N+1][4][4][4];
	for(int i=0;i<N+1;i++){
		for(int j=0;j<4;j++){
			for(int k=0;k<4;k++){
				for(int l=0;l<4;l++){
					dp[i][j][k][l]=0;
				}
			}
		}
	}

	for(int i=0;i<4;i++){
		for(int j=0;j<4;j++){
			for(int k=0;k<4;k++){
				if(i==0 && j==1 && k==2) continue;
				if(i==0 && j==2 && k==1) continue;
				if(i==1 && j==0 && k==2) continue;
				dp[3][i][j][k]=1;
			}
		}
	}

	for(int i=4;i<=N;i++){
		for(int j=0;j<4;j++){
			for(int k=0;k<4;k++){
				for(int l=0;l<4;l++){
					for(int m=0;m<4;m++){
						if(j==0 && k==1 && l==2) continue;
						if(j==0 && k==2 && l==1) continue;
						if(j==1 && k==0 && l==2) continue;
						if(m==0 && k==1 && l==2) continue;
						if(m==0 && j==1 && l==2) continue;
						dp[i][j][k][l]+=dp[i-1][m][j][k];
						dp[i][j][k][l]%=mod;
					}
				}
			}
		}
	}

	ll Ans=0;
	for(int i=0;i<4;i++){
		for(int j=0;j<4;j++){
			for(int k=0;k<4;k++){
				Ans+=dp[N][i][j][k];
				Ans%=mod;
			}
		}
	}
	cout<<Ans<<endl;
	return 0;
}

