bool isValid(string s) {
	if(s.size() < 3) {
		return true;
	} else if(s.size() == 3) {
		return s != "AGC" && s != "ACG" && s != "GAC";
	} else {
		bool ret = isValid(s.substr(0,3));
		ret &= isValid(s.substr(1,3));
		ret &= ((s.substr(0,1) + s.substr(2,2)) != "AGC");
		ret &= ((s.substr(0,2) + s.substr(3,1)) != "AGC");
		return ret;
	}
}

map<string, ll> dp[101];
ll solve(int pos, string s) {
	if(pos == n) return 1;

	map<string, ll>& p = dp[pos];
	if(p.find(s) != p.end()) {
		return p[s];
	}
	p[s] = 0;
	for(char c : "ACGT") {
		if(c == '\0') break;
		string ns = s + string(1,c);
		if(isValid(ns)) { 
			p[s] += solve(pos+1, ns.substr(1));
			p[s] %= MOD;
		}
	}
	return p[s];
}

