/*
 * ダメなパターン.
 * AGC
 * GAC
 * ACG
 * A*GC
 * AG*C
 *
 * 前2つと今回だけ見ればよさそう.
 */
int N;
enum {
  A = 1,
  C,
  G,
  T
};
ll dp[110][5][5][5];

ll rec(int n=0, int n_3 = 0, int n_2 = 0, int n_1 = 0) {
  ll &cc = dp[n][n_3][n_2][n_1];
  if (~cc) return cc;
  if (n==N) {
    return cc = 1;
  }
  ll num = 0;
  loop(i,1,5) {
    // AGC
    if (n_2 == A and n_1 == G and i == C) continue;
    // GAC
    if (n_2 == G and n_1 == A and i == C) continue;
    // ACG
    if (n_2 == A and n_1 == C and i == G) continue;
    // A*GC
    if (n_3 == A and n_1 == G and i == C) continue;
    // AG*C
    if (n_3 == A and n_2 == G and i == C) continue;
    madd(num, rec(n+1, n_2, n_1, i));
  }
  return cc = num;
}
void solve() {
  cin >> N;
  memset(dp, -1, sizeof(dp));
  cout << rec() << endl;
}
int main() {
  // cout.precision(15); cout << fixed;

  solve();

  return 0;
}

