	for (int i = A+1; i <= C; i++) {
		if (S[i - 1] == '#' && S[i] == '#') {
			AC = false; break;
		}
	}
	// BからDにいけるか
	bool BD = true;
	for (int i = B + 1; i <= D; i++) {
		if (S[i - 1] == '#' && S[i] == '#') {
			AC = false; break;
		}
	}
	//追い抜く必要がある
	bool oinuki = false;
	if (D < C) {
		// Bの位置で追い越せるか
		if (S[B - 1] == '.' && S[B + 1] == '.') {
			oinuki = true;
		}
		// Cの位置で追い越せるか
		else if (S[C - 1] == '.' && S[C + 1] == '.') {
			oinuki = true;
		}
		else if(B+2<=D) {
			// 3連続する'.'があるか
			for (int i = B + 2; i <= D; i++) {
				if (S[i - 2] == '.' && S[i - 1] == '.' && S[i] == '.') oinuki = true;
			}
			}
		else {
			// #B.Dみたいなとき
			if (S[B+1] == '.' && S[B+2]=='.') {
				oinuki = true;
			}
		}
		if (AC && BD && oinuki) Yes;
		else No;
	}
	else {
		if (AC && BD) Yes;
		else No;
	}


	return 0;
}

