constexpr int mod = 1e9+7;

ll dp[104][4][4][4];
bool isOk[4][4][4][4];
bool isAGC(int a, int b, int c, int d){
  return (a==1&&b==2&&c==3) || (b==1&&c==2&&d==3);
}

void calcOk(){
  REP(i, 4){
    REP(j, 4){
      REP(k, 4){
        REP(l, 4){
          bool ans = true;
          int s[] = {i, j, k, l};
          ans &= !isAGC(s[0], s[1], s[2], s[3]);
          REP(m, 3){
            swap(s[m], s[m+1]);
            ans &= !isAGC(s[0], s[1], s[2], s[3]);
            swap(s[m],s[m+1]);
          }
          isOk[i][j][k][l] = ans;
        }
      }
    }
  }
}
int main(){
  int N;
  cin >> N;
  dp[0][0][0][0] = 1;
  calcOk();
  REP(i, N){
    REP(j, 4){
      REP(k, 4){
        REP(l, 4){
          REP(m, 4){
            if(isOk[j][k][l][m]){
              dp[i+1][k][l][m] += dp[i][j][k][l];
              dp[i+1][k][l][m] %= mod;
            }
          }
        }
      }
    }
  }
  ll ans = 0;
  REP(i, 4){
    REP(j, 4){
      REP(k, 4){
        ans += dp[N][i][j][k];
        ans %= mod;
      }
    }
  }
  cout << ans << endl;

  return 0;
}

