using namespace std;
#pragma warning (disable: 4996)

bool used[256];
int N, mod = 1000000007;
int dp[109][64];

void init() {
	for (int i = 0; i < 256; i++) {
		int col[4], s = 1;
		for (int j = 0; j < 4; j++) { col[j] = (i / s) % 4; s *= 4; }
		for (int j = 0; j <= 3; j++) {
			if (j != 3) swap(col[j], col[j + 1]);
			if (col[0] == 0 && col[1] == 1 && col[2] == 2) used[i] = true;
			if (col[1] == 0 && col[2] == 1 && col[3] == 2) used[i] = true;
			if (j != 3) swap(col[j], col[j + 1]);
		}
	}
}

int main() {
	init();
	cin >> N;
	if (N == 3) {
		cout << "61" << endl;
	}
	else {
		for (int i = 0; i < 64; i++) dp[3][i] = 1;
		for (int i = 4; i <= N; i++) {
			for (int j = 0; j < 64; j++) {
				if (dp[i - 1][j] == 0) continue;
				for (int k = 0; k < 4; k++) {
					int val = j + 64 * k;
					if (used[val] == true) continue;
					dp[i][val / 4] += dp[i - 1][j];
					dp[i][val / 4] %= mod;
				}
			}
		}
		int sum = 0;
		for (int i = 0; i < 64; i++) { sum += dp[N][i]; sum %= mod; }
		cout << sum << endl;
	}
	return 0;
}

