            count.at((i%16)*4+numbcha('T')).at(n+1)+=count.at(i).at(n);
        }

        for(int i=0;i<64;i++){
            count.at(i).at(n+1)%=mod;
        }
    }

    long ans=0;

    for(int i=0;i<64;i++){
        ans+=count.at(i).at(N);
    }
    ans%=mod;


    //出力
    cout<<ans<<endl;
}

