const int MOD = 1000000007;
// T A G C = 0 1 2 3

bool is_ng(int d, int a, int b) {
    if(d == 1 && a == 2 && b == 3) return true;
    return false;
}

void calc(vector<vector<vector<vector<long long>>>> &v, int n, int a, int b, int c) {
    for(int d = 0; d < 4; d++) {
        if(is_ng(b, c, d) || is_ng(c, b, d) || is_ng(b, d, c)) continue;
        if(is_ng(a, c, d) || is_ng(a, b, d)) continue;
        v[n+1][b][c][d] += v[n][a][b][c]  % MOD;
    }
}

int main() {
    int N;
