    vector<vector<vector<vector<long long>>>> v(N+1, vector<vector<vector<long long>>>(4, vector<vector<long long>>(4, vector<long long>(4, 0))));
    v[0][0][0][0] = 1;

    for(int n = 0; n < N; n++) {
        for(int a = 0; a < 4; a++) {
            for(int b = 0; b < 4; b++) {
                for(int c = 0; c < 4; c++) {
                    calc(v, n , a, b, c);
                }
            }
        }
    }
    long long count = 0;
    for(int a = 0; a < 4; a++) {
        for(int b = 0; b < 4; b++) {
            for(int c = 0; c < 4; c++) {
                count += v[N][a][b][c] % MOD;
            }
        }
    }

    cout << count % MOD << endl;
}

