bool judge(ll i,ll o,ll t,ll h){
	if(i==0&o==1&t==2) return false;
	if(i==0&o==2&t==1) return false;
	if(i==1&o==0&t==2) return false;
	if(o==0&t==1&h==2) return false;
	if(o==0&t==2&h==1) return false;
	if(o==1&t==0&h==2) return false;
	if(i==0&o==1&h==2) return false;
	if(i==0&t==1&h==2) return false;
	return true;
}

ll solve(ll i,ll o,ll t,ll h){
	if(i==0) return 1;
	if(m[i][o][t][h]>0) return m[i][o][t][h];
	ll l=0;
	FOR(j,0,3){
		if(judge(j,o,t,h)){
			l=(l+solve(i-1,j,o,t))%MOD;
		}
	}
	return m[i][o][t][h]=l;
}

