bool inline chk1(int a, int b, int c) {
    if ((a == 1 && b == 2 && c == 3) ||
        (a == 2 && b == 1 && c == 3) ||
        (a == 1 && b == 3 && c == 2))  return 0;
    return 1;
}

bool inline chk2(int a, int b, int c, int d) {
    if ((a == 1 && b == 2 && d == 3) ||
        (a == 1 && c == 2 && d == 3))  return 0;
    return 1;
}

bool inline chk(int a, int b, int c, int d) {
    return chk1(a, b, c) && chk1(b, c, d) && chk2(a, b, c, d);
}

int main() {
    ios_base::sync_with_stdio(0);
    cin >> n;
    dp[0][0][0][0][0] = 1;
    cont (i, n) {
        cont (a, 4) {
            if (i <= 1) {
                if (i == 1) {
                    dp[1][0][0][0][a] = 1;
                }
                continue;
            }
            cont (b, 4) {
                if (i <= 2) {
                    if (i == 2) {
                        dp[2][0][0][a][b] = 1;
                    }
                    continue;
                }
                cont (c, 4) {
                    if (i <= 3) {
                        if (i == 3 && chk1(a, b, c)) {
                            dp[3][0][a][b][c] = 1;
                        }
                        continue;
                    }
                    cont (d, 4) {
                        if (i <= 4) {
                            if (i == 4 && chk(a, b, c, d)) {
                                dp[4][a][b][c][d] = 1;
                            }
                            continue;
                        }
                        if (chk(a, b, c, d)) {
                            cont (p, 4) {
                                if (chk(p, a, b, c)) {
                                    dp[i][a][b][c][d] += dp[i - 1][p][a][b][c];
                                    dp[i][a][b][c][d] %= mod;
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    loop (a, 5) {
        loop (b, 5) {
            loop (c, 5) {
                loop (d, 5) {
                    ans += dp[n][a][b][c][d];
                    ans %= mod;
                }
            }
        }
    }
    cout << ans << endl;
}

