	for (int i = 1; i <= N; i++) {
		for (int j = 0; j < 4; j++) {
			for (int k = 0; k < 4; k++) {
				for (int l = 0; l < 4; l++) {
					if (dp[i - 1][j][k][l] == 0) continue;
					for (int m = 0; m < 4; m++) {
						if ((k == 0) && (l == 1) && (m == 2)) continue;
						if ((k == 0) && (l == 2) && (m == 1)) continue;
						if ((k == 1) && (l == 0) && (m == 2)) continue;
						if ((j == 0) && (l == 1) && (m == 2)) continue;
						if ((j == 0) && (k == 1) && (m == 2)) continue;
						dp[i][k][l][m] += dp[i - 1][j][k][l];
						dp[i][k][l][m] %= mod;
					}
				}
			}
		}
	}

	int ans = 0;
	for (int j = 0; j < 4; j++) {
		for (int k = 0; k < 4; k++) {
			for (int l = 0; l < 4; l++) {
				ans += dp[N][j][k][l];
				ans %= mod;
			}
		}
	}

	cout << ans << endl;

	return 0;
}

