signed main() {

	int N;
	cin >> N;

	// dp[i][XYZ] -> dp[i+1][YZW]
	int dp[128][64] = {};
	for (int i = 0; i < 64; i++) dp[3][i] = 1;
	dp[3][f(A, G, C)] = dp[3][f(A, C, G)] = dp[3][f(G, A, C)] = 0;

	int MOD = 1000000007;

	for (int i = 3; i < N; i++) {
		for (int j = 0; j < 64; j++) {
			if (j == f(A, G, C) || j == f(A, C, G) || j == f(G, A, C)) continue;
			int X = j >> 4, Y = (j >> 2) & 0b11, Z = j & 0b11;
			for (int W = 0; W < 4; W++) {
				if (
					f(X, Z, W) == f(A, G, C) ||
					f(X, Y, W) == f(A, G, C) ||
					f(Y, Z, W) == f(A, G, C) ||
					f(Y, Z, W) == f(A, C, G) ||
					f(Y, Z, W) == f(G, A, C)
					) 
					continue;
				dp[i + 1][f(Y, Z, W)] += dp[i][j];
			}
		}
		for (int j = 0; j < 64; j++) dp[i + 1][j] %= MOD;
	}

	int ans = 0;
	for (int j = 0; j < 64; j++) ans += dp[N][j];

