bool ch(string& s)
{
	string t = s;
	if (t.length() == 4) {
		if ((t[0] == 'A' && t[1] == 'G' && t[2] == 'C') ||
			(t[1] == 'A' && t[2] == 'G' && t[3] == 'C')) {
				return false;
		}
		reps(i, 1, 4) {
			swap(t[i], t[i-1]);
			if ((t[0] == 'A' && t[1] == 'G' && t[2] == 'C') ||
				(t[1] == 'A' && t[2] == 'G' && t[3] == 'C')) {
					return false;
			}
			swap(t[i], t[i-1]);
		}
	} else if (t.length() <= 3) {
		if (t == "AGC") return false;
		if (t == "ACG") return false;
		if (t == "GAC") return false;
	}
	if (s.length() == 4) {
		s.erase(s.begin(), s.begin()+1);
	}
	return true;
}

