           (c1 == G && c2 == A) ||
           (c1 == G && c3 == A) ||
           (c3 == A && c2 == G)
         ) )
    {
        ret += dfs(i+1, C, c1, c2);
        ret %= MOD;
    }

    // T を入れる
    ret += dfs(i+1, T, c1, c2);
    ret %= MOD;

    return ret;
}

