int DP[101][256];
bool valid(int s) {
  int a[4] = { s >> 6, (s >> 4) & 3, (s >> 2) & 3, s & 3 };

  if (a[0] == 1 && a[1] == 2 && a[2] == 3) return false;
  if (a[1] == 1 && a[2] == 2 && a[3] == 3) return false;
  for (int i = 1; i < 4; ++i) {
    int b[4];
    for (int k = 0; k < 4; ++k) b[k] = a[k];
    swap(b[i - 1], b[i]);
    if (b[0] == 1 && b[1] == 2 && b[2] == 3) return false;
    if (b[1] == 1 && b[2] == 2 && b[3] == 3) return false;
  }
  return true;
}

