  DP[0][0] = 1;
  for (int i = 0; i < n; ++i) {
    for (int s = 0; s < 256; ++s) {
      for (int k = 0; k < 4; ++k) {
        int t = ((s << 2) | k) & 255;
        if (!valid(t)) continue;
        DP[i + 1][t] += DP[i][s];
        DP[i + 1][t] %= mod;
      }
    }
  }

  int sum = 0;
  for (int s = 0; s < 256; ++s) {
    sum = (sum + DP[n][s]) % mod;
  }
