const int mod = 1e9+7;

ll memo[100][5][5][5];
int n;
string s="AGCT";
map<char,int> hsh;

ll go(int pos,int oh,int ah,int oo){
    if(pos==n) return 1;
    if(memo[pos][oh][ah][oo]!=-1){
        return memo[pos][oh][ah][oo];
    }
    ll ans=0;
    for(auto it:s){
        if(oh==0){
            ans+=go(pos+1,hsh[it],ah,oo);
        }
        else if(ah==0){
            ans+=go(pos+1,oh,hsh[it],oo);
        }
        else if(oo==0){
            if(it!='C'&&it!='G'){
                ans+=go(pos+1,oh,ah,hsh[it]);
            }
            else{
                if(it=='C'){
                    if((oh==1&&ah==2)||(oh==2&&ah==1)) continue;
                    ans+=go(pos+1,oh,ah,hsh[it]);
                }
                else{
                    if(oh==1&&ah==3) continue;
                    ans+=go(pos+1,oh,ah,hsh[it]);
                }
            }
        }
        else{
            if(it!='C'&&it!='G'){
                ans+=go(pos+1,ah,oo,hsh[it]);
            }
            else{
                if(it=='G'){
                    if(ah==1&&oo==3) continue;
                    ans+=go(pos+1,ah,oo,hsh[it]);
                }
                else{
                    if((ah==1&&oo==2)||(ah==2&&oo==1)) continue;
                    if(oh==1&&ah==2&&(oo==2||oo==1||oo==4)) continue;
                    if(oh==1&&ah==4&&oo==2) continue;
                    ans+=go(pos+1,ah,oo,hsh[it]);
                }
            }

        }
        ans%=mod;
    }
    return memo[pos][oh][ah][oo]=ans;
}

