  vector<vector<vector<vector<mint>>>> dp(N+1,vector<vector<vector<mint>>>(4,vector<vector<mint>>(4,vector<mint>(4,0))));
  dp[0][1][1][1] = 1;
  for(int i = 0; i < N; ++i){
    for(int j = 0; j < 4; ++j){
      for(int k = 0; k < 4; ++k){
        for(int l = 0; l < 4; ++l){
          for(int m = 0; m < 4; ++m){
