              continue;
            if(k == 2 and l == 0 and m == 3)//GAC
              continue;
            if(k == 0 and l == 3 and m == 2)//ACG
              continue;
            dp[i+1][k][l][m] += dp[i][j][k][l];
          }
        }
      }
