bool ok(vector<int> a) {
	auto ch = [](vector<int> a) {
		for (int i = 0; i + 3 <= (int)(a.size()); i++) {
			if (a[i] == 0 && a[i + 1] == 1 && a[i + 2] == 2) {
				return false;
			}
		}
		return true;
	};
	if (!ch(a)) return false;
	for (int i = 0; i + 1 < (int)a.size(); i++) {
		swap(a[i], a[i + 1]);
		if (!ch(a)) return false;
		swap(a[i], a[i + 1]);
	}
	return true;
}

