long long dp[101][4][4][4];
const long long mod = 1E9 + 7;

int main(void)
{
	int N;
	cin >> N;

	// A : 0
	// G : 1
	// C : 2
	// T : 3

	// seed
	dp[0][3][3][3] = 1;
	// len文字目
	for (int len = 0; len < N; len++) {
		// 3つ前の文字
		for (int c3 = 0; c3 < 4; c3++) {
			// 2つ前の文字
			for (int c2 = 0; c2 < 4; c2++) {
				// 1つ前の文字
				for (int c1 = 0; c1 < 4; c1++) {
					if (dp[len][c3][c2][c1] == 0)
						continue;

					// 末尾に加える文字
					for (int c0 = 0; c0 < 4; c0++) {
						// 条件を満たさない
						// ... 0 1 2
						if (c2 == 0 && c1 == 1 && c0 == 2) continue;
						// ... 0 2 1
						if (c2 == 0 && c1 == 2 && c0 == 1) continue;
						// ... 1 0 2
						if (c2 == 1 && c1 == 0 && c0 == 2) continue;
						// ... 0 ? 1 2
						if (c3 == 0 && c1 == 1 && c0 == 2) continue;
						// ... 0 1 ? 2
						if (c3 == 0 && c2 == 1 && c0 == 2) continue;

						dp[len + 1][c2][c1][c0] += dp[len][c3][c2][c1];
						dp[len + 1][c2][c1][c0] %= mod;
					}
				}
			}
		}
	}

	long long ans = 0;
	for (int c3 = 0; c3 < 4; c3++) {
		for (int c2 = 0; c2 < 4; c2++) {
			for (int c1 = 0; c1 < 4; c1++) {
				ans += dp[N][c3][c2][c1];
				ans %= mod;
			}
		}
	}

	cout << ans << endl;

	return 0;
}

