bool ng(int x1, int x2, int x3, int x4) {
	int x[] = { x1,x2,x3,x4 };

	for (int i = 0; i < 4; ++i) {
		if (x[0] == 0 && x[1] == 1 && x[2] == 2)
			return true;
		if (x[1] == 0 && x[2] == 1 && x[3] == 2)
			return true;
		if (i != 0)
			std::swap(x[i - 1], x[i]);
		if (i != 3)
			std::swap(x[i], x[i + 1]);
	}

	return false;
}

