const ll MOD = 1e9 + 7;
int N;
string P = "ACGT";
vector<map<string, ll>> dp;

ll dfs(int n, string res) {
    if (res.size() >= 3 && (
        (res[n - 3] == 'A' && res[n - 2] == 'G' && res[n - 1] == 'C') ||
        (res[n - 3] == 'A' && res[n - 2] == 'C' && res[n - 1] == 'G') ||
        (res[n - 3] == 'G' && res[n - 2] == 'A' && res[n - 1] == 'C'))) return 0;

    if (res.size() >= 4 && (
        (res[n - 4] == 'A' && res[n - 2] == 'G' && res[n - 1] == 'C') ||
        (res[n - 4] == 'A' && res[n - 3] == 'G' && res[n - 1] == 'C'))) return 0;

    if (n >= N) return 1;    

    assert(n == res.size());
    if (n >= 4) {
        string last4 = res.substr(n - 4, 4);
        if (dp[n].count(last4) > 0) return dp[n][last4];
    }

    ll ret = 0;
    REP(i, 4) {
        ret += dfs(n + 1, res+P[i]);
        ret %= MOD;
    }

    if (n >= 4) {
        string last4 = res.substr(n - 4, 4);
        dp[n][last4] = ret;
    }

    return ret;
}

