bool is_allowed(vector<int> vs) {
    assert(vs.size() == 4);
    auto check = [&]() {
        if (vs[0] == 0 && vs[1] == 1 && vs[2] == 2) {
            return false;
        }
        if (vs[1] == 0 && vs[2] == 1 && vs[3] == 2) {
            return false;
        }
        return true;
    };
    if (!check()) {
        return false;
    }
    for (int i = 0; i < 3; ++i) {
        swap(vs[i], vs[i+1]);
        if (!check()) {
            return false;
        }
        swap(vs[i], vs[i+1]);
    }
    return true;
}

vector<vector<int>> all_allowed() {
