    forbidden.at(i) = true;
  }
  for (int i = 32; i < 48; i++) { // AGXC
    if (i % 4 == 1) {
      forbidden.at(i) = true;
    }
  }
  for (int i = 0; i < 4; i++) { // XAGC
    forbidden.at(64 * i + 9) = true;
  }
  for (int i = 0; i < 4; i++) { // AXGC
    forbidden.at(16 * i + 9) = true;
  }
  for (int i = 132; i < 136; i++) { // GACX
    forbidden.at(i) = true;
  }
  for (int i = 0; i < 4; i++) { // XGAC
    forbidden.at(64 * i + 33) = true;
  }
  for (int i = 24; i < 28; i++) { // ACGX
    forbidden.at(i) = true;
  }
  for (int i = 0; i < 4; i++) { // XACG
    forbidden.at(64 * i + 6) = true;
  }
  vector<vector<int64_t>> dp(n + 1, vector<int64_t>(256));
  for (int i = 0; i < 256; i++) {
