int A=0;
int C=1;
int G=2;
int T=3;

class Vertex{
public:
    int a, b, c;
    int count;
    Vertex(int aa, int bb, int cc, int cnt){
        a=aa;
        b=bb;
        c=cc;
        count=cnt;
    }

    bool operator==(const Vertex &v) const{
        if(a == v.a && b == v.b && c == v.c){
            return true;
        }
        return false;
    }

    inline bool operator!=(const Vertex& v) const{
        return !(*this == v);
    }
};


vector<Vertex> next_vertex(Vertex v){
    vector<Vertex> vv;
    if(v.a==A && v.b==C && v.c==G){
        return vv;
    }
    if(v.a==A && v.c==C){
        vv.push_back(Vertex(v.b, v.c, A, v.count));
        vv.push_back(Vertex(v.b, v.c, C, v.count));
        vv.push_back(Vertex(v.b, v.c, T, v.count));
        return vv;
    }
    if(v.a==A && v.b==C){
        vv.push_back(Vertex(v.b, v.c, A, v.count));
        vv.push_back(Vertex(v.b, v.c, C, v.count));
        vv.push_back(Vertex(v.b, v.c, T, v.count));
        return vv;
    }
    if(v.b==A && v.c==C){
        vv.push_back(Vertex(v.b, v.c, A, v.count));
        vv.push_back(Vertex(v.b, v.c, C, v.count));
        vv.push_back(Vertex(v.b, v.c, T, v.count));
        return vv;
    }
    vv.push_back(Vertex(v.b, v.c, A, v.count));
    vv.push_back(Vertex(v.b, v.c, C, v.count));
    vv.push_back(Vertex(v.b, v.c, G, v.count));
    vv.push_back(Vertex(v.b, v.c, T, v.count));
    return vv;
}

int main(){
    long N;
    cin>>N;

    vector<int> a;
    for(int i=0; i<4; ++i){
        a.push_back(i);
    }
    vector<Vertex> now, next;
    for(int i=0; i<4; ++i){
        for(int j=0; j<4; ++j){
            for(int k=0; k<4; ++k){
                if(i==0 && j==1 && k==2){
                }else if(i==0 && j==2 && k==1){
                }else if(i==1 && j==0 && k==2){
                }else{
                    now.push_back(Vertex(a[i], a[j], a[k], 1));
                    next.push_back(Vertex(a[i], a[j], a[k], 0));
                }
            }
        }
    }


    for(int i=3; i<N; ++i){
        for(int j=0; j<now.size(); ++j){
            vector<Vertex> nn = next_vertex(now[j]);
        for(int l=0; l<nn.size(); ++l){
            for(int k=0; k<next.size(); ++k){
                if(nn[l] == next[k]){
                    next[k].count += nn[l].count;
                    next[k].count %= MOD;
                }
            }
        }
        }

        now = next;
        for(int j=0; j<next.size(); ++j){
            next[j].count = 0;
        }
    }

    long ans=0;
    for(int i=0; i<now.size(); ++i){
        ans+=now[i].count;
        ans%=MOD;
    }
    cout<<ans<<endl;

    return 0;
}

