const ll mod = static_cast<int>(1e9 + 7);

ll dp[4][4][4][110];

int main() {
	int N;
	cin >> N;

	for (int i = 0; i < 4; ++i) {
		for (int j = 0; j < 4; ++j) {
			for (int k = 0; k < 4; ++k) {
				if (i == 0 && j == 2 && k == 1) {
					dp[i][j][k][3] = 0;
				}
				else if (i == 0 && j == 1 && k == 2) {
					dp[i][j][k][3] = 0;
				}
				else if (i == 2 && j == 0 && k == 1) {
					dp[i][j][k][3] = 0;
				}
				else {
					dp[i][j][k][3] = 1;
				}
			}
		}
	}

	for (int m = 4; m <= N; ++m) {
		for (int i = 0; i < 4; ++i) {
			for (int j = 0; j < 4; ++j) {
				for (int k = 0; k < 4; ++k) {
					for (int l = 0; l < 4; ++l) {
						if (j == 0 && k == 2 && l == 1) {
							dp[j][k][l][m] += 0;
						}
						else if (j == 0 && k == 1 && l == 2) {
							dp[j][k][l][m] += 0;
						}
						else if (j == 2 && k == 0 && l == 1) {
							dp[j][k][l][m] += 0;
						}
						else if (i == 0 && k == 2 && l == 1) {
							dp[j][k][l][m] += 0;
						}
						else if (i == 0 && j == 2 && l == 1) {
							dp[j][k][l][m] += 0;
						}
						else {
							dp[j][k][l][m] += dp[i][j][k][m - 1];
							dp[j][k][l][m] %= mod;
						}
					}
				}
			}
		}
	}

	ll ans = 0;
	for (int i = 0; i < 4; ++i) {
		for (int j = 0; j < 4; ++j) {
			for (int k = 0; k < 4; ++k) {
				ans += dp[i][j][k][N];
				ans %= mod;
			}
		}
	}
	cout << ans << endl;
}

