        if(a==0&&b==2&&d==1) continue; //AG?C;
        if(a==0&&c==2&&d==1) continue; //A?GC;

        tmp += dfs(now+1,b,c,d);
        tmp %=MOD;
    }
    dp[now][a][b][c] = tmp;
    return tmp;
}

