ll dfs(ll n, ll a, ll b, ll c){ //先頭の3文字がa,b,cのとき
  if( n == 3){ return 1;} //ベース 列abcの一通りしかありえない
  if( a == 0 && b == 2 && c == 0){ return 0;} //AGC自身を含むときは当然0返す
  if( a == 2 && b == 0 && c == 1){ return 0;} //GAC
  if( a == 0 && b == 1 && c == 2){ return 0;} //ACG
  if( dp[n][a][b][c] != -1){ return dp[n][a][b][c];}//メモ化

  ll res = 0;

  for(ll p = 0; p < 4; p++){
      res += dfs( n - 1,b,c,p ); res %= MOD;} 

  //0b2型のときはb21を避けないといけない
   if( a == 0 && c == 2){ 
       res -= dfs(n - 1, b, 2,1); res = ( MOD + res) % MOD; } 
  //02c型のときは2c1を避けないといけない
   if( a == 0 && b == 2){ 
       res -= dfs(n - 1, 2, c,1); res = ( MOD + res) % MOD; }

  return dp[n][a][b][c] = res;}




