unsigned long long ans(int len){
	for(int i = 0;i < 4;++i){
		for(int j = 0;j < 4;++j){
			for(int k = 0;k < 4;++k){
				if(i == 0 and j == 1 and k == 2)continue;
				if(i == 1 and j == 0 and k == 2)continue;
				if(i == 0 and j == 2 and k == 1)continue;
				dp[i][j][k] = 1;
			}
		}
	}
