						if(j == 0 and k == 2 and l == 1)continue;
						if(i == 0 and j == 1 and k == 2)continue;//
						if(j == 0 and k == 1 and l == 2)continue;
						tmp[j][k][l] = (tmp[j][k][l] + dp[i][j][k]) % tomod;
					}
				}
			}
		}
