		memset(tmp, 0, sizeof(tmp));
	}
	for(int i = 0;i < 4;++i){
		for(int j = 0;j < 4;++j){
			for(int k = 0;k < 4;++k){
				res = (res + dp[i][j][k]) % tomod;
			}
		}
	}
