int n, memo[105][5][5][5], bigmod = 1000000007, temp;

int dp(int pos, int prv3, int prv2, int prv1) {
	int ret = 0, a[5], x, y;
	bool valid;
	if (pos == n)
		return 1;
	if (memo[pos][prv3][prv2][prv1] != -1)
		return memo[pos][prv3][prv2][prv1];
	a[0] = prv3;
	a[1] = prv2;
	a[2] = prv1;
	for (int i = 1; i < 5; i++) {
		a[3] = i;
		x = 0;
		for (int j = 1; j < 4; j++)
			x = (10 * x) + a[j];
		if (x == 132)
			continue;
		valid = true;
		for (int j = 0; j < 3; j++) {
			temp = a[j];
			a[j] = a[j + 1];
			a[j + 1] = temp;
			x = 0;
			for (int k = 0; k < 3; k++)
				x = (10 * x) + a[k];
			y = 0;
			for (int k = 1; k < 4; k++)
				y = (10 * y) + a[k];
			temp = a[j];
			a[j] = a[j + 1];
			a[j + 1] = temp;
			if ((x == 132) || (y == 132)) {
				valid = false;
				break;
			}
		}
		if (valid)
			ret = (ret + dp(pos + 1, prv2, prv1, i)) % bigmod;
	}
	memo[pos][prv3][prv2][prv1] = ret;
	return ret;
}

