bool is_ng(int a,int b,int c,int d){
  bool t = (b==0&&c==2&&d==1);
  t |= (b==2&&c==0&&d==1);
  t |= (b==0&&c==1&&d==2);
  t |= (a==0&&c==2&&d==1);
  t |= (a==0&&b==2&&d==1);
  return t;
}

void add(int&a,int&b){
  a=(a%md+b%md)%md;
}

