        dp[i + 1][k][l][m] %= MOD;
      }
    }
  }

  for (int j = 0; j < 4; ++j) for (int k = 0; k < 4; ++k) for (int l = 0; l < 4; ++l) {
    ans += dp[n][j][k][l];
    ans %= MOD;
  }

  printf("%lld\n", ans);

  return 0;
}

