bool modeq(int a, int b, int mod) {
    return a % mod == b % mod;
}

int ch2i(char ch) {
    if(ch == 'T') return 0;
    if(ch == 'A') return 1;
    if(ch == 'C') return 2;
    if(ch == 'G') return 3;
    return 0;
}

int get_id(char ch1, char ch2, char ch3) {
    int res = 0;
    res += ch2i(ch1);
    res = res << 2;
    res += ch2i(ch2);
    res = res << 2;
    res += ch2i(ch3);
    return res;
}

int get_nextid(int id, char next) {
    int res = id % 16;
    res = res << 2;
    return res + ch2i(next);
}

int solve() {
    for(int i = 0; i <= N; ++i)
        for(int j = 0; j < 64; ++j)
            dp[i][j] = 0;

    dp[0][0] = 1;

    for(int i = 0; i < N; ++i)
        for(int j = 0; j < 64; ++j) {
            if(modeq(j, get_id(' ', 'A', 'C'), 16)) {
                    dp[i + 1][get_nextid(j, 'A')] = (dp[i + 1][get_nextid(j, 'A')] + dp[i][j]) % R;
                    dp[i + 1][get_nextid(j, 'C')] = (dp[i + 1][get_nextid(j, 'C')] + dp[i][j]) % R;
                    dp[i + 1][get_nextid(j, 'T')] = (dp[i + 1][get_nextid(j, 'T')] + dp[i][j]) % R;
            } else if(
                modeq(j, get_id(' ', 'A', 'G'), 16) || 
                modeq(j, get_id(' ', 'G', 'A'), 16) ||

                j == get_id('A', 'A', 'G') || 
                j == get_id('A', 'C', 'G') || 
                j == get_id('A', 'G', 'G') || 
                j == get_id('A', 'T', 'G') || 

                j == get_id('A', 'G', 'A') || 
                j == get_id('A', 'G', 'C') || 
                j == get_id('A', 'G', 'G') || 
                j == get_id('A', 'G', 'T') ) 
                {
                    dp[i + 1][get_nextid(j, 'A')] = (dp[i + 1][get_nextid(j, 'A')] + dp[i][j]) % R;
                    dp[i + 1][get_nextid(j, 'G')] = (dp[i + 1][get_nextid(j, 'G')] + dp[i][j]) % R;
                    dp[i + 1][get_nextid(j, 'T')] = (dp[i + 1][get_nextid(j, 'T')] + dp[i][j]) % R;

            } else {
                    dp[i + 1][get_nextid(j, 'A')] = (dp[i + 1][get_nextid(j, 'A')] + dp[i][j]) % R;
                    dp[i + 1][get_nextid(j, 'C')] = (dp[i + 1][get_nextid(j, 'C')] + dp[i][j]) % R;
                    dp[i + 1][get_nextid(j, 'G')] = (dp[i + 1][get_nextid(j, 'G')] + dp[i][j]) % R;
                    dp[i + 1][get_nextid(j, 'T')] = (dp[i + 1][get_nextid(j, 'T')] + dp[i][j]) % R;
            }
        }

    int res = 0;
    for(int j = 0; j < 64; ++j)
        res = (res + dp[N][j]) % R;
    return res;
}

int main(int argc, char **argv) {
    scanf("%d", &N);

    printf("%d\n", solve());
}

