  if(ng(b,a,c)||ng(a,c,d))return false;
  if(ng(a,c,b)||ng(c,b,d))return false;
  if(ng(a,b,d)||ng(b,d,c))return false;
  return true;
}

ll f(int idx,int a,int b,int c){
  if(~dp[idx][a][b][c])return dp[idx][a][b][c];
  if(!check(a,b,c,-1))return 0;
  if(!idx)return 1;
  ll res=0;
  for(int i=0;i<4;i++)if(check(i,a,b,c))res+=f(idx-1,i,a,b);
  return dp[idx][a][b][c]=res%MOD;
}

