    // A: 0
    // G: 1
    // C: 2
    // T: 3

    // 長さ0の文字列は1である。
    // 0,1,2に関する制約しかないので、
    // Sは333Sと考えても問題ない。
    dp[0][3][3][3] = 1;

    // 文字列の文字数
    for (int len=0;len<N;++len) {
        rep(c1, 4)rep(c2, 4)rep(c3, 4) {
            // 条件に当てはまるものはない。計算量を削減できる。
