bool agc(string &s, int i){
  if (s[i] == 'A' && s[i+1] == 'G' && s[i+2] == 'C') return true;
  return false;
}

bool check(string &s){
  // sがAGCを含んでいたりどこか隣接する所を入れ替えてAGCができるようならアウト
  // 大丈夫ならtrueを返す
  int n = s.size();
  // 部分文字列として含むならアウト
  for (int i=0; i+3<=s.size(); i++){
    if (agc(s, i)) return false;
  }
  // どこか隣接するところを入れ替えて、部分文字列としてAGCを含むようになればアウト
  for (int i=0; i+1<s.size(); i++){
    swap(s[i], s[i+1]);
    bool dame = false;
    for (int j=0; j+3<=s.size(); j++) if (agc(s, j)) dame = true;
    swap(s[i], s[i+1]);
    if (dame) return false;
  }
  // これらのチェックを乗り越えたならtrue
  return true;
}

int main() {
  int N; cin >>N;
  // 1桁目：4で割った余りが
  // 2桁目：4で割って4で割った余りが
  // 3桁目：16で割って4で割った余りが
  // 4桁目：64で割って4で割った余りが
  // 0:A, 1:C, 2:G, 3:T とする。
  string ss = "ACGT";
  vector<string> pattern(64);
  for (int i=0; i<64; i++){
    string t = "aaa";
    int j = i;
    t[2] = ss[j%4]; j /= 4;
    t[1] = ss[j%4]; j /= 4;
    t[0] = ss[j%4];
    pattern[i] = t;
  }
  vector<vector<bool>> transition(64, vector<bool>(64, false));
  // transition[i][j] := pattern[i] から pattern[j]への遷移が可能かどうか
  for (int i=0; i<64; i++){
    for (int j=0; j<64; j++){
      string t1 = pattern[i];
      string t2 = pattern[j];
      if (t1[1] != t2[0] || t1[2] != t2[1]) continue; // そもそもそうならない
      string tmp = "aaaa";
      tmp[0] = t1[0]; tmp[1] = t1[1]; tmp[2] = t1[2]; tmp[3] = t2[2];
      if (check(tmp)) transition[i][j] = true;
    }
  }
  vector<vector<ll>> dp(N, vector<ll>(64, 0));
  // dp[i][j] := s[i]から3文字とったやつがjになるようなやつ
  // N文字のうち隣接3文字はN-2コある。
  for (int i=0; i<64; i++){
    if (check(pattern[i])) dp[0][i] = 1;
  }
  for (int i=0; i<N-1; i++){
    for (int j=0; j<64; j++){
      // string t1 = pattern[j];
      for (int k=0; k<64; k++){
        // string t2 = pattern[k];
        if (!transition[j][k]) continue;
        dp[i+1][k] += dp[i][j];
        dp[i+1][k] %= MOD;
      }
    }
  }
  ll res = 0;
  for (int j=0; j<64; j++){
    res += dp[N-3][j];
    res %= MOD;
  }
  cout <<res <<endl;
}

