using namespace std;
typedef long long ll;
const ll MOD = 1000000007;

int N;
ll dp[101][4][4][4];
//dp[i][j][k][l]: i文字目(1-index)を考えるとき、
//i文字目がj、i - 1文字目がk、i - 2文字目がlのときの組み合わせの総和
//j, kは 0 -> A  1 -> T  2 -> G  3 -> C

int main() {
	cin >> N;

	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			for (int k = 0; k < 4; k++) {
				if ((i == 0 && j == 2 && k == 3) ||
					(i == 0 && j == 3 && k == 2) ||
					(i == 2 && j == 0 && k == 3)) {
					continue;
				}
				dp[3][i][j][k] = 1;
			}
		}
	}

	for (int i = 4; i <= N; i++) {
		for (int j = 0; j < 4; j++) {
			for (int k = 0; k < 4; k++) {
				for (int l = 0; l < 4; l++) {

					//A -> 0  T -> 1  G -> 2  C -> 3
					if (j == 2 && k == 0 && l == 3)continue;//GAC
					if (j == 0 && k == 2 && l == 3)continue;//AGC
					if (j == 0 && k == 3 && l == 2)continue;//ACG

					for (int m = 0; m < 4; m++) {
						if ((j == 0 && l == 2 && m == 3) ||
							(j == 0 && k == 2 && m == 3)) {
							//上から順にA?GC, AG?C これらをはじく
							continue;
						}
						dp[i][j][k][l] += dp[i - 1][k][l][m];
					}
					dp[i][j][k][l] %= MOD;
				}
			}
		}
	}

	ll ans = 0;
	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			for (int k = 0; k < 4; k++) {
				if (i == 2 && j == 0 && k == 3)continue;//GAC
				if (i == 0 && j == 2 && k == 3)continue;//AGC
				if (i == 0 && j == 3 && k == 2)continue;//ACG
				ans += dp[N][i][j][k];
			}
		}
	}

	cout << ans % MOD << endl;

	return 0;
}

