  dp[0][3][3][3] = 1;

  for(int len = 0; len <= n; ++len)
  {
    for(int i1 = 0; i1 < 4; ++i1) 
    {
      for(int i2 = 0; i2 < 4; ++i2) 
      {
        for(int i3 = 0; i3 < 4; ++i3) 
        {
          if (dp[len][i1][i2][i3].x == 0) continue;

          for(int c = 0; c < 4; ++c)
          {
            // cut
            if (c == 2 && i1 == 1 && i2 == 0) continue;
            if (c == 1 && i1 == 2 && i2 == 0) continue;
            if (c == 2 && i1 == 0 && i2 == 1) continue;
            if (c == 2 && i2 == 1 && i3 == 0) continue;
            if (c == 2 && i1 == 1 && i3 == 0) continue;

            dp[len + 1][c][i1][i2] += dp[len][i1][i2][i3];
          }
        }
      }
    }
  }
  mint ans = 0;
  for(int i1 = 0; i1 < 4; ++i1) 
  {
    for(int i2 = 0; i2 < 4; ++i2) 
    {
      for(int i3 = 0; i3 < 4; ++i3) 
      {
        ans += dp[n][i1][i2][i3];
      }
    }
  }

  cout << ans;
}

