bool hantei2(string S) {
	for (int i = 0; i < (int)S.size() - 2; i++) {
		if (S.substr(i, 3) == "AGC") return true;
	}
	return false;
}

bool hantei(string S) {
	if (hantei2(S) == true) return false;
	for (int i = 0; i < S.size(); i++) {
		string T = S;
		swap(T[i], T[i + 1]);
		if (hantei2(T) == true) return false;
	}
	return true;
}

bool check(int pos, int t) {
	int cp[6] = { 1, 4, 16, 64, 256 };

	string S1 = "", S2 = "AGCT";
	for (int i = 0; i < 5; i++) {
		int p = (t / cp[i]) % 4;
		if (i >= 5 - pos) S1 += S2[p];
	}
	if (hantei(S1) == false) return false;
	return true;
}

int main() {
