	dp[0][0] = 1;
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < 1024; j++) {
			if (dp[i][j] == 0) continue;
			for (int k = 0; k < 4; k++) {
				int t = (j / 4) + k * 256;
				if (check(i + 1, t) == false) continue;
				dp[i + 1][t] += dp[i][j];
				dp[i + 1][t] %= mod;
			}
		}
	}

	int sum = 0;
	for (int i = 0; i < 1024; i++) { sum += dp[N][i]; sum %= mod; }
	cout << sum << endl;
	return 0;
}

