            (dp[p + 1][l][k][j] += dp[p][k][j][i]) %= 1000000007;
          }
  }
  int ans = 0;
  for (int i = 0; i < 4; ++i)
    for (int j = 0; j < 4; ++j)
      for (int k = 0; k < 4; ++k)
        (ans += dp[n][k][j][i]) %= 1000000007;
