const ll MAX_N=100,MOD=1e9+7;
//dpで解く。n番目の文字を決めるにあたって重要なのはそれより前の3文字分の情報だけである
//dp[n][m]=長さnで問題の条件を満たすもので最後の3文字がm(A,C,G,Tをそれぞれ0,1,2,3とみなし、文字列を4進数の整数にエンコードしたもの)となる文字列の個数
//と定義する
ll N,dp[MAX_N+1][4*4*4],agc[3]={0,2,1};
bool isagc(ll *ary){
    //aryはある文字列のACGTを数字で置き換えた配列
    //部分文字列にAGCを含みか判定する
    REP(i,2){
        bool flg=true;
        REP(j,3){
            if(ary[i+j]!=agc[j]){
                flg=false;
            }
        }
        if(flg)
            return true;
    }
    return false;
}
bool chk(ll m){
    //mは長さ4文字の文字列をエンコードしたもの
    //mが条件を満たしているか判定する
    ll ary[4];  //mをデコードする
    REP(i,4){
        ary[3-i]=m%4;
        m/=4;
    }
    //AGCを含むか判定する
    if(isagc(ary)){
        return false;
    }
    ll ary2[4];
    //swapしてもAGCを含まないか判定する
    REP(i,3){
        REP(j,4){
            ary2[j]=ary[j];
        }
        swap(ary2[i],ary2[i+1]);
        if(isagc(ary2)){
            return false;
        }
    }
    return true;
}
int main(){
    cin>>N;
    ll pw4=4*4*4;
    //dpテーブル初期化
    REP(i,4*4*4){
        if(i==0*16+2*4+1 || i==0*16+1*4+2 || i==2*16+0*4+1)continue;    //条件を満たさない文字列
        dp[3][i]=1;
    }
    //配るdp
    FOR(i,3,N){
        REP(j,4*4*4){
            //dp[i][j]からの遷移を考える
            REP(k,4){
                //k=i+1番目の文字
                if(chk(j*4+k)){
                    //kをi+1番目の文字にしてもokなら
                    ll j2=(j*4+k)%pw4;    //遷移先の状態
                    dp[i+1][j2]+=dp[i][j];
                    dp[i+1][j2]%=MOD;
                }
            }
        }
    }
    ll ans=0;
    REP(i,4*4*4){
        ans+=dp[N][i];
        ans%=MOD;
    }
    cout<<ans<<endl;
}

