    for (int i = 0; i < 64; i++) {
        dp[3][i] = 1;
    }
    int u[3];
    dp[3][u[0] = 0 * 16 + 1 * 4 + 2] = 0;
    dp[3][u[1] = 1 * 16 + 0 * 4 + 2] = 0;
    dp[3][u[2] = 0 * 16 + 2 * 4 + 1] = 0;

    for (int k = 4; k <= n; k++) {
        for (int i = 0; i < 64; i++) {
            for (int h = 0; h < 4; h++) {
                int v = h * 64 + i;
                int w0 = v & ~(3 * 16);
                int w1 = v & ~(3 * 4);
                if (w0 == 0 * 64 + 1 * 4 + 2) continue;
                if (w1 == 0 * 64 + 1 * 16 + 2) continue;
                dp[k][i] += dp[k - 1][v / 4];
            }
            dp[k][i] %= P;
        }
        dp[k][u[0]] = 0;
        dp[k][u[1]] = 0;
        dp[k][u[2]] = 0;
    }

    ll r = 0;
    for (int i = 0; i < 64; i++) {
        r += dp[n][i];
    }
