        REP(s2,4){
            REP(s1,4){
                if(s3==a&&s2==g&&s1==c){
                    dp[3][s3][s2][s1] = 0;
                }
                else if(s3==g&&s2==a&&s1==c){
                    dp[3][s3][s2][s1] = 0;
                }
                else if(s3==a&&s2==c&&s1==g){
                    dp[3][s3][s2][s1] = 0;
                }
                else{
                    dp[3][s3][s2][s1] = 1;
                }
            }
        }
    }

    FOR(i,4,n+1){
