ll MOD = pow(10,9) + 7;
vector<vector<pair<vector<char>, ll>>> memo(101);
vector<char> c{'A','C','G','T'};

bool ok(vector<char> last4){
	if(last4[1] == 'A' && last4[2] == 'G' && last4[3] == 'C'
	|| last4[1] == 'G' && last4[2] == 'A' && last4[3] == 'C'
	|| last4[1] == 'A' && last4[2] == 'C' && last4[3] == 'G'
	|| last4[0] == 'A' && last4[2] == 'G' && last4[3] == 'C'
	|| last4[0] == 'A' && last4[1] == 'G' && last4[3] == 'C'){
		return false;
	}
	return true;
}

ll dfs(int cur, vector<char> last3 , int N){
	if(cur == N){
		return 1;
	}
	for(int i(0);i<memo[cur].size();++i){
		if(equal(last3.cbegin(), last3.cend(), memo[cur][i].first.cbegin())){
			return memo[cur][i].second;
		}
	}
	ll ret = 0;
	for(int i(0);i<4;++i){
		vector<char> last4 = last3;
		last4.push_back(c[i]);
		if(ok(last4)){
			last4.erase(last4.begin());
			ret = ( ret + dfs(cur + 1, last4, N)) % MOD;
		}
	}
	memo[cur].push_back(make_pair(last3, ret));
	return ret;
}

