const ll MOD  = 1e9 + 7;
const ll LINF = 1LL << 62;
const int INF = 1e9 + 7;

int main(){
    ll n;
    cin >> n;

    // dp[i] : i文字で条件を満たす個数
    ll dp[n+1];
    dp[0] = 1;
    dp[1] = 4;
    dp[2] = 16;
    dp[3] = 61;

    for(ll i = 4; i <= n; ++i){
        //条件を満たすと予想される個数
        dp[i] = dp[i-1] * 4;
        //dp[i-1]までは成り立つが，i文字目にCが入ると成り立たなくなる個数が11
        //dp[i-1]までは成り立つが，i文字目にGが入ると成り立たなくなる個数が３
        dp[i] -= dp[i-4] * 14;
        //MODで負の数に対応するための処理
        dp[i] = (dp[i]+20*MOD) % MOD;
    }

    cout << dp[n] << endl;
}

