int main()
{
	int N;
	cin >> N;

	vector<vector<vector<vector<ll>>>> dp(N + 1, vector<vector<vector<ll>>>(4, vector<vector<ll>>(4, vector<ll>(4))));
	dp[0][3][3][3] = 1;
	auto mod = (ll)1e9 + 7;

	for (auto i = 0; i < N; ++i)
	{
		for (auto j = 0; j < 4; ++j)
		{
			for (auto k = 0; k < 4; ++k)
			{
				for (auto l = 0; l < 4; ++l)
				{
					for (auto m = 0; m < 4; ++m)
					{
						if (m == 2)
						{
							if (l == 1 && k == 0)
							{
								continue;
							}
							if (l == 0 && k == 1)
							{
								continue;
							}
							if (k == 1 && j == 0)
							{
								continue;
							}
							if (l == 1 && j == 0)
							{
								continue;
							}
						}
						else if (m == 1 && l == 2 && k == 0)
						{
							continue;
						}
						dp[i + 1][m][l][k] += dp[i][l][k][j];
						dp[i + 1][m][l][k] %= mod;
					}
				}
			}
		}
	}

	auto ans = 0ll;
	for (auto j = 0; j < 4; ++j)
	{
		for (auto k = 0; k < 4; ++k)
		{
			for (auto l = 0; l < 4; ++l)
			{
				ans = (ans + dp[N][j][k][l]) % mod;
			}
		}
	}
	cout << ans << endl;

	return 0;
}

