int main(){
    int n;
    cin >> n;
    // A C G T
    vector<vector<vector<int>>> s(4, vector<vector<int>>(4, vector<int>(4, 1)));
    s[0][2][1] = 0; // AGC
    s[0][1][2] = 0; // ACG
    s[2][0][1] = 0; // GAC
    for(int m = 3; m < n; m++){
        vector<vector<vector<int>>> st(4, vector<vector<int>>(4, vector<int>(4, 0)));
        for (int i = 0; i < 4; i++){
            for (int j = 0; j < 4; j++){
                for (int k = 0; k < 4; k++){
                    st[j][k][0] += s[i][j][k];
                    st[j][k][3] += s[i][j][k];
                    st[j][k][0] %= MOD;
                    st[j][k][3] %= MOD;
                    // AG?C, A?GC, ?AGC, ?GAC
                    if ((i == 0 & j == 2) | (i == 0 & k == 2) | (j == 0 & k == 2) | (j == 2 & k == 0)){
                        st[j][k][2] += s[i][j][k];
                        st[j][k][2] %= MOD;
                    }
                    // ?ACG
                    else if (j == 0 & k == 1){
                        st[j][k][1] += s[i][j][k];
                        st[j][k][1] %= MOD;
                    }
                    else{
                        st[j][k][1] += s[i][j][k];
                        st[j][k][2] += s[i][j][k];
                        st[j][k][1] %= MOD;
                        st[j][k][2] %= MOD;
                    }
                }
            }
        }
        s = st;
    }
    int ans = 0;
    for (int i = 0; i < 4; i++){
        for (int j = 0; j < 4; j++){
            for (int k = 0; k < 4; k++){
                ans += s[i][j][k];
                ans %= MOD;
            }
        }
    }
    cout << ans << endl;
}

