const ll mod = 1e9 + 7;

int main(){
  ll N;
  cin >> N;
  ll a[N+1], g[N+1], t[N+1], c[N+1];
  a[0] = 0, g[0] = 0,  t[0] = 0, c[0] = 0;
  a[1] = 1, g[1] = 1,  t[1] = 1, c[1] = 1;
  a[2] = 4, g[2] = 4,  t[2] = 4, c[2] = 4;
  for(int i = 3; i <= N; i++){
    g[i] = ((t[i-1] + c[i-1]) % mod + (g[i-1] + a[i-1] - c[i-2]) % mod) % mod;
    c[i] = ((a[i-1] + g[i-1])% mod + (t[i-1] + c[i-1])% mod)% mod;
    t[i] = ((a[i-1] + g[i-1]) % mod + (t[i-1] + c[i-1]) % mod) % mod;
    a[i] = ((a[i-1] + t[i-1] + g[i-1]) % mod + (-c[i-2] -3*c[i-3] + c[i-1] -g[i-2]) % mod) % mod;
  }
  ll ans = (a[N] + g[N] + t[N] + c[N]) % mod;
  cout << ans << endl;
  return 0;
}

