        if (i == CH_A && j == CH_G && k == CH_C) dp[3][i][j][k] = 0;
        else if (i == CH_A && j == CH_C && k == CH_G) dp[3][i][j][k] = 0;
        else if (i == CH_G && j == CH_A && k == CH_C) dp[3][i][j][k] = 0;
        else dp[3][i][j][k] = 1;
    }}}
    rep (x, 4, n + 1) {
        rep (i, 4) { rep (j, 4) { rep (k, 4) {
            if (i == CH_A && j == CH_G && k == CH_C) dp[x][i][j][k] = 0;
