using namespace std;

using ll = long long;

ll mod = 1000000007;

int n;

map<pair<int, string>, ll> memo;

ll dfs(int i, string s) {
    if (i == n) {
        return 1;
    }

    auto t = make_pair(i, s);

    if (memo.count(t)) {
        return memo[t];
    }

    ll ret = 0;

    if (s.size() <= 1) {
        ret = (ret + dfs(i + 1, s + 'A')) % mod;
        ret = (ret + dfs(i + 1, s + 'G')) % mod;
        ret = (ret + dfs(i + 1, s + 'T')) % mod;
        ret = (ret + dfs(i + 1, s + 'C')) % mod;
    } else if (s.size() == 2) {
        ret = (ret + dfs(i + 1, s + 'A')) % mod;
        ret = (ret + dfs(i + 1, s + 'T')) % mod;

        if (s != "AC") {
            ret = (ret + dfs(i + 1, s + 'G')) % mod;
        }

        if (s != "AG" && s != "GA") {
            ret = (ret + dfs(i + 1, s + 'C')) % mod;
        }
    } else {
        string t = s.substr(1);
        ret = (ret + dfs(i + 1, t + 'A')) % mod;
        ret = (ret + dfs(i + 1, t + 'T')) % mod;

        if (t != "AC") {
            ret = (ret + dfs(i + 1, t + 'G')) % mod;
        }

        if (t != "AG" && t != "GA" && !(s[0] == 'A' && s[1] == 'G') && !(s[0] == 'A' && s[2] == 'G')) {
            ret = (ret + dfs(i + 1, t + 'C')) % mod;
        }
    }

    return memo[t] = ret;
}

