template<typename T, class Operators>
struct Ring {

   T x;

   Ring() : x(T()) {}
   Ring(T value) : x(value) { }

   Ring& operator=(const Ring& value) & = default;

   static Ring id_add() { return Operators::IdAdd(); }
   static Ring id_mul() { return Operators::IdMul(); }

   Ring operator+() const { return *this; }
   Ring operator-() const { return Operators::Minus(x); }

   Ring operator+=(const Ring& rhs) { x = Operators::Add(x, rhs.x); return *this; }
   Ring operator-=(const Ring& rhs) { *this += -rhs; return *this; }
   Ring operator*=(const Ring& rhs) { x = Operators::Mul(x, rhs.x); return *this; }

   const Ring operator+(const Ring& rhs) const { return Ring(x) += rhs; }
   const Ring operator-(const Ring& rhs) const { return Ring(x) -= rhs; }
   const Ring operator*(const Ring& rhs) const { return Ring(x) *= rhs; }

   Ring power(int n) const { return Operators::Power(x, n); }

   bool operator<(const Ring& rhs) const { return Operators::Less(x, rhs.x); }
   bool operator>(const Ring& rhs) const { return rhs < *this; }
   bool operator<=(const Ring& rhs) const { return !(*this > rhs); }
   bool operator>=(const Ring& rhs) const { return !(*this < rhs); }
   bool operator==(const Ring& rhs) const { return !(*this < rhs) && !(*this > rhs); }
   bool operator!=(const Ring& rhs) const { return !(*this == rhs); }
};

template<typename T, class Operators>
auto& operator<<(ostream& s,const Ring<T, Operators>& a){ s << a.x; return s; }


template<typename T, class Operators>
struct Field : Ring<T, Operators> {

   using BaseRing = Ring<T, Operators>;

   Field() : BaseRing() {}
   Field(T value) : BaseRing(value) { }
   Field(const BaseRing& value) : BaseRing(value) { }

   Field& operator=(const Field& value) & = default;

   static Field id_add() { return BaseRing::id_add(); }
   static Field id_mul() { return BaseRing::id_mul(); }

   Field operator+() const { return BaseRing::operator+(); }
   Field operator-() const { return BaseRing::operator-(); }
   Field inverse() const { return Operators::Inverse(this->x); }

   Field operator+=(const Field& rhs) { return *this = BaseRing::operator+=(rhs); }
   Field operator-=(const Field& rhs) { return *this = BaseRing::operator-=(rhs); }
   Field operator*=(const Field& rhs) { return *this = BaseRing::operator*=(rhs); }
   Field operator/=(const Field& rhs) { return *this *= rhs.inverse(); }

   const Field operator+(const Field& rhs) const { return Field(*this) += rhs; }
   const Field operator-(const Field& rhs) const { return Field(*this) -= rhs; }
   const Field operator*(const Field& rhs) const { return Field(*this) *= rhs; }
   const Field operator/(const Field& rhs) const { return Field(*this) /= rhs; }

   Field power(int n) const { return BaseRing::power(n); }

   bool operator<(const Field& rhs) const { return BaseRing::operator<(rhs); }
