                            dp[i][d][a][b] += dp[i-1][a][b][c];
                            dp[i][d][a][b] %= mod;
                        }
                    }
                }
            }
        }
    }
    ll ans = 0;
    REP(a, 0, 4){
        REP(b, 0, 4){
            REP(c, 0, 4){
                ans += dp[n][a][b][c];
                ans %= mod;
            }
        }
    }
    //cout << dp[n][1][2][0] << endl;
    cout << ans << endl;
}

