int ss2i(string ss) {
	int i = 0;
	for (int j = 0; j < 3; j++)
	{
		int a;
		switch (ss[j])
		{
		case 'A':
			a = 0;
			break;
		case 'C':
			a = 1;
			break;
		case 'G':
			a = 2;
			break;
		case 'T':
			a = 3;
			break;
		default:
			break;
		}
		i += a;
		i *= 4;
	}
	i /= 4;
	return i;
}

string i2ss(int i) {
	string ss = "";
	for (int j = 0; j < 3; j++)
	{
		const int r = i % 4;
		ss += r2c[r];
		i /= 4;
	}
	reverse(ss.begin(), ss.end());
	return ss;
}

void make_r2c() {
	r2c[0] = 'A';
	r2c[1] = 'C';
	r2c[2] = 'G';
	r2c[3] = 'T';
}

void make_i2ni() {
	for (int i = 0; i < NCOMBINATION; i++)
	{
		string ss = i2ss(i);
		for (int r = 0; r < 4; r++)
		{
			const string nss = ss + r2c[r];
			bool is_legal = true;
			for (int k = 0; k < 2; k++)
				if (nss.substr(k, 3) == "AGC")
					is_legal = false;
			for (int j = 0; j < 3; j++)
			{
				string nnss = nss;
				swap(nnss[j], nnss[j + 1]);
				for (int k = 0; k < 2; k++)
					if (nnss.substr(k, 3) == "AGC")
						is_legal = false;
			}
			if (is_legal) {
				const int ni = ss2i(nss.substr(1, 3));
				i2ni[i].push_back(ni);
			}
		}
	}
}

