inline bool bad(int a,int b,int c,int d){
    if (        b==1 && c==2 && d==3) return true;
    if (a==1         && c==2 && d==3) return true;
    if (        b==2 && c==1 && d==3) return true;
    if (        b==1 && c==3 && d==2) return true;
    if (a==1 && b==2         && d==3) return true;
    return false;
}

ll solve(int N) {
    ll dp[101][625][2];
    memset(dp, 0, sizeof(dp));
    dp[0][0][0] = 1;
    for (int i=0;i<N;i++){
        for (int a=0;a<5;a++) for (int b=0;b<5;b++) for (int c=0;c<5;c++) for (int d=0;d<5;d++) {
            int abcd = ((a*5+b)*5+c)*5+d;
            for (int e=1; e<5; ++e) {
                int bcde = ((b*5+c)*5+d)*5+e;
                bool _bad = bad(b,c,d,e);
                for (int j=0;j<2;j++){
                    (dp[i+1][bcde][j || _bad] += dp[i][abcd][j]) %= MOD;
                }
            }
        }
    }
    ll ans = 0;
    for (int i=0;i<625;i++) {
        (ans += dp[N][i][1]) %= MOD;
    }
    return SUB(POW(4,N), ans);
}

int main() {
    int N; cin >> N;
    cout << solve(N) << endl;
    return 0;
}

