bool check(string last3, const char &next) {
    if (next == 'G') {
        if (last3[1] == 'A' && last3[2] == 'C') return false;
    } else if (next == 'C') {
        if (last3[1] == 'G' && last3[2] == 'A') return false;
        if ((last3[0] == 'A' || last3[1] == 'A') && (last3[2] == 'G' || last3[1] == 'G')) return false;
    }
    return true;
}

LL recurse(const string &last3, int cur_n, int max_n, vector<unordered_map<string, LL>> &memo) {
    if (cur_n == max_n) {
        return 1;
    }

    auto itr = memo[cur_n].find(last3);
    if ( itr != memo[cur_n].end()) {
        return itr->second;
    }

    LL ret = 0;
    REP(i, 4) {
        char next = "ACGT"[i];
        if (check(last3, next)) {
            ret = (ret + recurse(last3.substr(1, 2) + next, cur_n + 1, max_n, memo)) % MOD;
        }
    }

    memo[cur_n][last3] = ret;
    return ret;
}

