	dp[0][3][3][3] = 1;

	for (int len = 0; len < N; len++) {

		for (int i = 0; i < 4; i++) {
			for (int j = 0; j < 4; j++) {
				for (int k = 0; k < 4; k++) {

					if (dp[len][i][j][k] == 0) continue;

