						if (j == 2 && k == 0 && add == 1) continue;
						if (i == 0 && k == 2 && add == 1) continue;
						if (i == 0 && j == 2 && add == 1) continue;

						dp[len + 1][j][k][add] += dp[len][i][j][k];
						dp[len + 1][j][k][add] %= MOD;
					}
				}
			}
		}
	}

	lint ans = 0;
	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
