    }
    if((f == 1 && g == 2 && h == 3) || (g == 1 && h == 2 && j == 3))return dp[v][f][g][h][j] = 0;
    if((f == 2 && g == 1 && h == 3) || (g == 2 && h == 1 && j == 3))return dp[v][f][g][h][j] = 0;
