    int res = 0;
    if(v == 0){
        for(int i = 1; i <= 4; i++){
            res += dfs(v + 1, f, i, h, j);
            res %= mod;
        }
    }
    else if(v == 1){
        for(int i = 1; i <= 4; i++){
            res += dfs(v + 1, f, g, i, j);
