typedef long long ll;
ll MOD = 1000000007;

// a^p
// 2^3 = 2 * 2^2
// 2^2 = 2 * (2^1)
// 2^1 = 2
ll modpow(ll a, ll p, ll mod) {
  if (p == 0) return 1;

  if (p % 2 == 0) {
    ll half = modpow(a, p / 2, mod) % mod;
    return half * half % mod;
  } else {
    return a * modpow(a, p - 1, mod) % mod;
  }
}

// nCa を求める
ll modCombination(ll n, ll a, ll mod) {
  if (n - a < a) {
    return modCombination(n, n - a, mod);
  }

  ll denominator = 1;  // 分母
  ll numerator = 1;    // 分子

  for (ll i = 0; i < a; i++) {
    denominator *= a - i;
    numerator *= n - i;
    denominator %= mod;
    numerator %= mod;
  }

  return numerator * modpow(denominator, mod - 2, mod) % mod;
}

class UnionFind {
 private:
  vector<ll> parents;

 public:
  UnionFind(ll n) : parents(n, -1) {}

  bool issame(ll x, ll y) { return root(x) == root(y); }

  bool merge(ll x, ll y) {
    if (issame(x, y)) return false;

    ll rx = root(x);
    ll ry = root(y);
    if (parents[rx] > parents[ry]) swap(rx, ry);
    // サイズ情報を更新
    parents[rx] += parents[ry];
    // yの親を更新
    parents[ry] = rx;

    return true;
  }

  ll size(ll x) { return -parents[root(x)]; }

 private:
  ll root(ll x) {
    if (parents[x] < 0) return x;
    // 根の親の値に木の(-)サイズの情報を入れる
    return parents[x] = root(parents[x]);
  }
};

int main() {
  ll N;
  cin >> N;

  // AGC
  // ACG
  // GAC
  // A*GC
  // AG*C

  // 0: dummy
  // 1: A
  // 2: G
  // 3: C
  // 4: T
  ll dp[101][5][5][5];

  memset(&dp, 0, sizeof(dp));

  // dp[n][i][j][k]
  // n文字目まで考える
  // k: 直前の文字
  // j: kのひとつ前の文字
  // i: jのひとつ前の文字
  dp[0][0][0][0] = 1;
  for (ll n = 0; n < N; n++) {
    for (ll i = 0; i < 5; i++) {
      for (ll j = 0; j < 5; j++) {
        for (ll k = 0; k < 5; k++) {
          // 文字列 ijk に l を加える
          for (ll l = 1; l < 5; l++) {
            // AGC
            if (j == 1 && k == 2 && l == 3) continue;
            // ACG
            if (j == 1 && k == 3 && l == 2) continue;
            // GAC
            if (j == 2 && k == 1 && l == 3) continue;
            // A*GC
            if (i == 1 && k == 2 && l == 3) continue;
            // AG*C
            if (i == 1 && j == 2 && l == 3) continue;

            dp[n + 1][j][k][l] += dp[n][i][j][k];
            dp[n][j][k][l] %= MOD;
          }
        }
      }
    }
  }

  ll ans = 0;
  for (ll i = 1; i < 5; i++) {
    for (ll j = 1; j < 5; j++) {
      for (ll k = 1; k < 5; k++) {
        ans += dp[N][i][j][k];
      }
    }
  }

  cout << ans % MOD << endl;
  return 0;
}

