            dp[n+1][G][C][G] = (dp[n+1][G][C][G] + dp[n][C][G][k])%mod;
            dp[n+1][C][C][G] = (dp[n+1][C][C][G] + dp[n][C][G][k])%mod;
            dp[n+1][T][C][G] = (dp[n+1][T][C][G] + dp[n][C][G][k])%mod;
        }else if(i==A && j==C){
            dp[n+1][A][A][C] = (dp[n+1][A][A][C] + dp[n][A][C][k])%mod;
            dp[n+1][C][A][C] = (dp[n+1][C][A][C] + dp[n][A][C][k])%mod;
            dp[n+1][T][A][C] = (dp[n+1][T][A][C] + dp[n][A][C][k])%mod;
        }else{
            for(int l = 0; l<4; l++){
                dp[n+1][l][i][j] = (dp[n+1][l][i][j] + dp[n][i][j][k])%mod;
            }
        }
    }

    ll ans = 0;
    for(int i=0; i<4; i++)for(int j=0; j<4; j++)for(int k=0; k<4; k++){
        ans = (ans + dp[N][i][j][k])%mod;
    }
    cout << ans << endl;
}

