	if (S.substr(0, 3) == "012" || S.substr(1, 3) == "012") return true;
	for (int i = 0; i < 3; i++) {
		swap(S[i], S[i + 1]);
		if (S.substr(0, 3) == "012" || S.substr(1, 3) == "012") return true;
		swap(S[i], S[i + 1]);
	}
	return false;
}

