// _ = 0, A = 1, C = 2, G = 3, T = 4
vector<int> Next(const int b1, const int b2, const int b3) {
    vector<int> res;
    if (b2 == 0 || b3 == 0) res = {1, 2, 3, 4};
    else if (b1 == 1 && b2 == 3) res = {1, 3, 4};
    else if ((b2 == 1 && b3 == 3) || (b2 == 3 && b3 == 1)) res = {1, 3, 4};
    else if (b2 == 1 && b3 == 2) res = {1, 2, 4};
    else if (b1 == 1 && b3 == 3) res = {1, 3, 4};
    else res = {1, 2, 3, 4};

    return res;
}

int Rec(int idx, int b1, int b2, int b3) {
    if (idx == n) return 1;
    if (dp[idx][b1][b2][b3] != -1) return dp[idx][b1][b2][b3];

    int &cnt = dp[idx][b1][b2][b3] = 0;
    vector<int> nxt = Next(b1, b2, b3);
    for (int d : nxt) (cnt += Rec(idx + 1, b2, b3, d)) %= MOD;

    return cnt % MOD;
}

