                        if (t == "GC" && A[a] == "A")
                            continue;
                        string r = A[a] + A[b];
                        if (r == "AG" && A[j] == "C")
                            continue;
                        dp[i][j][c][b] += dp[i - 1][c][b][a];
                        dp[i][j][c][b] %= MOD;
                    }
                }
            }
        }
    }

    ll ans = 0;
    REP(i, 4) {
        REP(j, 4) {
            REP(k, 4) {
                ans += dp[N][i][j][k];
                ans %= MOD;
            }
        }
    }

    cout << ans << endl;
    return 0;
}

