ll rec(string S, int len, int N)
{
    if(len==N) return 1;

    int n = num(S, len);
    if(table[n] >= 0) return table[n];

    ll ans = 0;
    string sub2;
    // string sub2,sub3;
    if(len >= 3)
    {
        sub2 = S.substr(1,2);
        // sub2 = S.substr(len-2, 2);
        // sub3 = S.substr(len-3, 3);
        ans += rec(sub2 + 'A', len + 1, N);
        if(sub2 != "AG" && sub2 != "GA" && !(S[0] == 'A' && S[1] == 'G') && !(S[0] == 'A' && S[2] == 'G') )
            ans += rec(sub2 + 'C', len + 1, N);
        if(sub2 != "AC")
            ans += rec(sub2 + 'G', len + 1, N);
        ans += rec(sub2 + 'T', len + 1, N);
    }
    else if(len >= 2)
    {
        // sub2 = S.substr(len-2, 2);
        ans += rec(S + 'A', len + 1, N);
        if(S != "AG" && S != "GA")
            ans += rec(S + 'C', len + 1, N);
        if(S != "AC")
            ans += rec(S + 'G', len + 1, N);
        ans += rec(S + 'T', len + 1, N);
    }
    else
    {
        ans += rec(S + 'A', len + 1, N);
        ans += rec(S + 'C', len + 1, N);
        ans += rec(S + 'G', len + 1, N);
        ans += rec(S + 'T', len + 1, N);
    }

    return table[n] = ans % (ll)(pow(10,9) + 7);
}

// 3桁までの文字列 → 数字
int num(string S, int len)
{
    int size = (int)S.length();
    int ans = 0;
    for(int i= 0; i < size; i++)
    {
        ans += pow(4,size - i - 1) * cnum(S[i]);
    }
    ans += pow(4, 3) * len;
    return ans;
}

int cnum(char c)
{
    switch (c) {
        case 'A':
            return 0;
            break;
        case 'C':
            return 1;
            break;
        case 'G':
            return 2;
            break;
        case 'T':
            return 3;
            break;

        default:
            return -1;
            break;
    }
}

