using namespace std;
#define REP(i, a, n) for (int i = ((int)a); i < ((int)n); i++)
#define lli long long int
#define MOD 1'000'000'007
enum
{
    A = 0,
    C = 1,
    G = 2,
    T = 3
};
/*
方針:
アウトになるのは
?AG+C
?GA+C
A?G+C
AG?+C
?AC+G
の5パターン
->最後4文字から考える
*/
int N;
int ans;
int solve()
{

    int memo[101][4][4][4];
    REP(j, 0, 4)
    REP(k, 0, 4)
    REP(l, 0, 4)
    {
        //AGC
        if (j == A && k == G && l == C)
            continue;
        //GAC
        if (j == G && k == A && l == C)
            continue;
        //ACG
        if (j == A && k == C && l == G)
            continue;
        memo[3][j][k][l] = 1;
    }
    REP(length, 0, N)
    REP(i, 0, 4)
    REP(j, 0, 4)
    REP(k, 0, 4)
    REP(l, 0, 4)
    {
        //?AGC
        if (j == A && k == G && l == C)
            continue;
        //A?GC
        if (i == A && k == G && l == C)
            continue;
        //GA?C
        if (j == G && k == A && l == C)
            continue;
        //?ACG
        if (j == A && k == C && l == G)
            continue;
        //AG?C
        if (i == A && j == G && l == C)
            continue;
        memo[length + 1][j][k][l] += memo[length][i][j][k];
        memo[length + 1][j][k][l] %= MOD;
    }
    REP(i, 0, 4)
    REP(j, 0, 4)
    REP(k, 0, 4)
    {
        ans += memo[N][i][j][k];
    }
}
int main()
{
    cin >> N;
    solve();
    cout << ans << endl;
    return 0;
}

