const int mod = (int) 1e9 + 7;

int id(char c) {
  if (c == 'A') return 0;
  if (c == 'C') return 1;
  if (c == 'G') return 2;
  if (c == 'T') return 3;
  return 4;
}

char what(int id) {
  if (id == 0) return 'A';
  if (id == 1) return 'C';
  if (id == 2) return 'G';
  if (id == 3) return 'T';
  return '@';
}

// ACGT@

int n;
int memo[100][6][6][6];

int go(int i, int l1, int l2, int l3) {
  if (i == n) return 1;
  if (memo[i][l1][l2][l3] != -1) return memo[i][l1][l2][l3];
  int ans = 0;
  for (int x = 0; x < 4; x++) {
    if (x == id('C') && l1 == id('G') && l2 == id('A')) continue;
    if (x == id('G') && l1 == id('C') && l2 == id('A')) continue;
    if (x == id('C') && l1 == id('A') && l2 == id('G')) continue;
    if (x == id('C') && l2 == id('G') && l3 == id('A')) continue;
    if (x == id('C') && l1 == id('G') && l3 == id('A')) continue;
    ans = (1ll * ans + go(i + 1, x, l1, l2)) % mod;
  }
  return memo[i][l1][l2][l3] = ans;
}

int main() {
  cin >> n;
  memset(memo, -1, sizeof memo);
  cout << go(0, 4, 4, 4) << endl;
  return 0;
}

