const int mod = 1e9 + 7;
const int inf = 2e18;
const int ninf = -2e18;

int takemod(int a){return ((a%mod)+mod)%mod;}

int pow(int a, int b, int m)
{
	int ans = 1;
	a %= m;
	while (b)
	{
		if (b & 1)
			ans = (ans * a) % m;
		b /= 2;
		a = (a * a) % m;
	}
	return ans;
}

int modinv(int a){return takemod( pow( takemod(a), mod-2,mod ) );}


map<pair<int,string>,int> dp;
int n;

bool isValid(string s){
	for(int i = 0; i <= 3; i++){
		string tmp = s;
		if(i >= 1){
			swap(tmp[i], tmp[i - 1]);
		}
		if(tmp.substr(0, 3) == "AGC" || tmp.substr(1, 3) == "AGC"){
			return false;
		} 
	}
	return true;
}

int add(int a, int b){
	return (a + b) % mod;
}

int solve(int i, string s){
	pair<int, string> curr = {i, s};
	if(dp.count(curr)) return dp[curr];
	if(i == n) return 1;

	string tmp = "ACGT";
	int ans = 0;
	for(auto it : tmp){
		string nxt = s + it;
		if(isValid(nxt)){
			ans = add(ans, solve(i + 1, nxt.substr(1,3)));
		}
	}
	return dp[curr] = ans;
}

