struct unionfind {
    vector<int> par;
    vector<int> siz;
    vector<int> es;
    int n, trees;//連結グループの数(親の種類)
    unionfind(int n) : n(n), trees(n) {        par.resize(n);        siz.resize(n);        es.resize(n);        for (int i = 0; i < n; i++) {            par[i] = i;            siz[i] = 1;        }    }
    int root(int x) { if (par[x] == x) { return x; } else { return par[x] = root(par[x]); }}
    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        es[x]++;
        if (x == y) return;
        if (siz[x] > siz[y]) swap(x, y);
        trees--;
        par[x] = y;
        siz[y] += siz[x];
        es[y] += es[x];
    }
    bool same(int x, int y) { return root(x) == root(y); }
    int size(int x) { return siz[root(x)]; }
    int esize(int x) { return es[root(x)]; }
    vi sizes(){        vi cou(n);        vi ret;        ret.reserve(n);        rep(i, n){            cou[root (i)]++;        }        rep(i, n){            if(cou[i])ret.push_back(cou[i]);        }        return ret;    }
    //つながりを無向グラフと見なし、xが閉路に含まれるか判定
    bool close(int x) { return esize(x) >= size(x); }
    V<vi> sets() {        vi ind(n, -1);        int i = 0;        vvi(res, trees);        rep(j, n) {            int r = root(j);            if (ind[r] == -1)ind[r] = i++;            res[ind[r]].push_back(j);        }        rep(i, trees) {            int r = root(res[i][0]);            if (res[i][0] == r)continue;            rep(j, 1, sz(res[i])) {                if (res[i][j] == r) {                    swap(res[i][0], res[i][j]);                    break;                }            }        }        return res;    }
};//@formatter:off


