        string t = temp;
        if(i>=1) swap(t[i-1],t[i]);
        if((t[0]=='A' && t[1]=='G' && t[2]=='C') || (t[1]=='A' && t[2]=='G' && t[3]=='C')){
            return false; // ダメな文字列が出現
