int rec(int cur, string atgc){
    if(dp[cur][atgc]) return dp[cur][atgc];
    if(cur==N) return 1;


    int ret = 0;
    for(char r : res){
        string temp = atgc + r;
        if(check(temp)){
            temp.erase(temp.begin());
            ret = (ret + rec(cur+1,temp)) % MOD;
        }
    }

    return dp[cur][atgc] = ret;
}

