  // dp[n][i][j][k]
  // n文字目まで考える
  // k: 直前の文字
  // j: kのひとつ前の文字
  // i: jのひとつ前の文字
  dp[0][0][0][0] = 1;
  for (ll n = 0; n < N; n++) {
    for (ll i = 0; i < 5; i++) {
