            // GAC
            if (j == 2 && k == 1 && l == 3) continue;
            // A*GC
            if (i == 1 && k == 2 && l == 3) continue;
            // AG*C
            if (i == 1 && j == 2 && l == 3) continue;

            dp[n + 1][j][k][l] += dp[n][i][j][k];
            dp[n][j][k][l] %= MOD;
          }
        }
      }
    }
  }

  ll ans = 0;
  for (ll i = 1; i < 5; i++) {
    for (ll j = 1; j < 5; j++) {
      for (ll k = 1; k < 5; k++) {
        ans += dp[N][i][j][k];
      }
    }
  }

  cout << ans % MOD << endl;
  return 0;
}

