int sub(char c1, char c2, char c3, int n, int N, int count){
    if(n==N){
        return 1;
    }
    if(c2=='A'&&c3=='C'){
        return count + sub('A','C','A',n+1, N,count) +  sub('A','C','T',n+1, N,count)+ sub('A','C','C',n+1, N,count);
    }
    if(c2=='A'&&c3=='G'){
        return count + sub('A','G','A',n+1, N,count) +  sub('A','G','T',n+1, N,count)+ sub('A','G','G',n+1, N,count);
    }
    if(c2=='G'&&c3=='A'){
        return count + sub('A','G','A',n+1, N,count) +  sub('A','G','T',n+1, N,count)+ sub('A','G','G',n+1, N,count);
    }
    if(c1=='A'&&c3=='G'){
        return count + sub(c2,'G','A',n+1, N,count) +  sub(c2,'G','T',n+1, N,count)+ sub(c2,'G','G',n+1, N,count);
    }
    if(c1=='A'&&c2=='G'){
        return count + sub('G',c3,'A',n+1, N,count) +  sub('G',c3,'T',n+1, N,count)+ sub('G', c3, 'G',n+1, N,count);
    }
    return count + sub(c2, c3, 'A', n+1, N,count) +  sub(c2, c3, 'C', n+1, N,count)+ sub(c2, c3, 'G',n+1, N,count)+ sub(c2, c3, 'T',n+1, N,count);
}

