bool judge(string S) {
	if (S.size() <= 2) return true;
	if (S.substr(0, 3) == "agc"){
		return false;
	}
	if (S.size() >= 4 and S.substr(1, 3) == "agc") {
		return false;
	}
	REP(i, S.size()-1) {
		string T = S;
		swap(T[i], T[i+1]);
		if (T.substr(0, 3) == "agc"){
			return false;
		}
		if (T.size() >= 4 and T.substr(1, 3) == "agc") {
			return false;
		}
	}
	return true;
}

void solve() {
	int N; cin >> N;

	set<string> ng_str = { "agc", "acg", "gac" };

	unordered_map<string, mint> memo;
	string agct = "agct";
	memo[""] = 1;

	REP(i, N) {
		unordered_map<string, mint> nxt;
		for (auto& a : memo) {
			for (auto c : agct) {
				string tar = a.first + c;
				if (judge(tar)) {
					if (tar.size() >= 4) {
						tar = tar.substr(1, 3);
					}
					nxt[tar] += a.second;
				}
			}
		}
		swap(memo, nxt);
	}

	mint res = 0;
	for (auto& a : memo) {
		res += a.second;
	}
	cout << res << endl;
}

