inline bool check(int a, int b, int c){
	return a == 0 && b == 1 && c == 2;
}

inline int getState(int mask, int nc){
	vector<int> vec;
	for(int i = 0; i < 3; i++){
		vec.push_back(mask%4);
		mask /= 4;
	}
	reverse(vec.begin(), vec.end());
	vec.push_back(nc);
	if(check(vec[0], vec[1], vec[2]))return -1;
	if(check(vec[1], vec[2], vec[3]))return -1;
	if(check(vec[1], vec[0], vec[2]))return -1;
	if(check(vec[0], vec[2], vec[3]))return -1;
	if(check(vec[0], vec[2], vec[1]))return -1;
	if(check(vec[2], vec[1], vec[3]))return -1;
	if(check(vec[0], vec[1], vec[3]))return -1;
	if(check(vec[1], vec[3], vec[2]))return -1;
	return vec[1]*16 + vec[2]*4 + vec[3];
}

