bool is_AGC(int a,int b,int c){
    if(a==1&&b==2&&c==3) return 1;
    else return 0;
}

bool four_ok(int a,int b,int c,int d){
    int m[4]={a,b,c,d};
    if(is_AGC(m[0],m[1],m[2])||is_AGC(m[1],m[2],m[3])) return 0;
    for(int i=0;i<3;i++){
        swap(m[i],m[i+1]);
        if(is_AGC(m[0],m[1],m[2])||is_AGC(m[1],m[2],m[3])) return 0;
        swap(m[i],m[i+1]);
    }
    return 1;
}

