int main() {
    std::ifstream in("input.txt");
    std::cin.rdbuf(in.rdbuf());

    int n;
    cin >> n;

    const int mod = 1000000007;

    vector<vector<long long>> dp(64, vector<long long>(n, 0));

    for (int i = 0; i < 64; ++i)
    {
        if (i == 0b001001 || i == 0b100001 || i == 0b000110)
        {
            continue;
        }
        dp[i][0] = 1;
    }


    for (int i = 1; i < n - 1; ++i)
    {
        for (int j = 0; j < 64; ++j)
        {
            int first = (j >> 4) & 0x3;
            int second = (j >> 2) & 0x3;
            int third = j & 0x3;

            for (int k = 0; k < 4; ++k)
            {
                if (k == 1)
                {
                    if ((second == 0 && third == 2) || (second == 2 && third == 0) || (first == 0 && second == 2) || (first == 0 && third == 2))
                    {
                        continue;
                    }
                }
                else if (k == 2)
                {
                    if (second == 0 && third == 1)
                    {
                        continue;
                    }
                }
                int next = ((j & 0xF) << 2) | k;
                dp[next][i] += dp[j][i - 1];
                dp[next][i] %= mod;
            }
        }
    }

    long long ret = 0;

    for (int i = 0; i < 64; ++i)
    {
        ret += dp[i][n - 3];
        ret %= mod;
    }

    cout << ret << endl;


    return 0;
}

