const int MOD = 1e9 + 7;

int dp[MAX_N][4][4][4];

int main()
{
	int N;
	cin >> N;

	// A -> 0
	// G -> 1
	// C -> 2
	// T -> 3

	dp[0][3][3][3] = 1;

	// 文字列の文字数
	for (int len = 0; len < N; len++) {
		// 最後から1文字目の文字
		for (int i = 0; i < 4; i++) {
			// 最後から2文字目の文字
			for (int j = 0; j < 4; j++) {
				// 最後から3文字目の文字
				for (int k = 0; k < 4; k++) {
					// 条件に当てはまるものがない
					if (dp[len][i][j][k] == 0)
						continue;

					for (int a = 0; a < 4; a++) {
						if (a == 2 && i == 1 && j == 0)
							continue;
						if (a == 2 && i == 0 && j == 1)
							continue;
						if (a == 1 && i == 2 && j == 0)
							continue;
						if (a == 2 && i == 1 && k == 0)
							continue;
						if (a == 2 && j == 1 && k == 0)
							continue;

						dp[len + 1][a][i][j] +=
						    dp[len][i][j][k];
						dp[len + 1][a][i][j] %= MOD;
					}
				}
			}
		}
	}

	int ans = 0;

	for (int i = 0; i < 4; i++) {
		for (int j = 0; j < 4; j++) {
			for (int k = 0; k < 4; k++) {
				ans += dp[N][i][j][k];
				ans %= MOD;
			}
		}
	}

	cout << ans << endl;

	return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const int mod=1e9+7;
map<char,int> m={{'A',1},{'G',2},{'C',3},{'T',4},{'*',5}};
vector<int> AGCT={'A','G','C','T'};
int n,dp[110][9][9][9];
bool chk(vector<int> C)
{
  return C[0]=='A' and C[1]=='G' and C[2]=='C';
}
int solve(int idx,int c3,int c2,int c1)
{
  if(idx>=n) return !chk({c3,c2,c1});
  if(dp[idx][m[c3]][m[c2]][m[c1]]!=-1) return dp[idx][m[c3]][m[c2]][m[c1]];
  int ret=0;
  for(char now:AGCT)
  {
    vector<int> t={c3,c2,c1,now};
    bool ok=true;
    if(chk({c3,c2,c1}) || chk({c2,c1,now})) ok=false;
    for(int i=0;i<AGCT.size()-1;i++)
    {
      vector<int> tt=t;
      swap(tt[i],tt[i+1]);
      if(chk({tt[0],tt[1],tt[2]}) || chk({tt[1],tt[2],tt[3]})) ok=false;
    }
    if(ok)
    {
      int val=solve(idx+1,c2,c1,now);
      ret=(ret%mod+val%mod)%mod;
      if(ret<0) ret+=mod;
    }
  }
  return dp[idx][m[c3]][m[c2]][m[c1]]=ret;
}
int main()
{
  cin>>n;
  memset(dp,-1,sizeof(dp));
  cout<<solve(0,'*','*','*')<<endl;
  return 0;
}

