const int A=0,G=1,C=2,T=3;
long long dp[111][4][4][4];
int main(){
    int n;
    cin>>n;
    int mod=1000000007;
    dp[0][A][G][C]=1;
    for(int i=0 ; i<n ; ++i){
        for(int j=0 ; j<4 ; ++j){
            for(int k=0 ; k<4 ; ++k){
                for(int l=0 ; l<4 ; ++l){
                    for(int m=0 ; m<4 ; ++m){
                        if(k==A && l==G && m==C)continue;
                        if(k==G && l==A && m==C)continue;
                        if(k==A && l==C && m==G)continue;
                        if(j==A && l==G && m==C)continue;
                        if(j==A && k==G && m==C)continue;
                        (dp[i+1][k][l][m] += dp[i][j][k][l]) %= mod;
                    }
                }
            }
        }
    }
    long long ans=0;
    for(int i=0 ; i<4 ; ++i){
        for(int j=0 ; j<4 ; ++j){
            for(int k=0 ; k<4 ; ++k){
                ans += dp[n][i][j][k];
            }            
        }
    }
    cout<<ans%mod<<endl;
    return 0;
}

