            if((s2 == 0 && s3 == 2 && new_ == 1) || (s2 == 0 && s3 == 1 && new_ == 2) || (s2 == 2 && s3 == 0 && new_ == 1) || (s1 == 0 && s3 == 2 && new_ == 1) || (s1 == 0 && s2 == 2 && new_ == 1)) continue;
            dp[i+1][s2][s3][new_] += dp[i][s1][s2][s3];
        }
    }

    modint ans = 0;
    REP(i, 4) REP(j, 4) REP(k, 4) ans += dp[n][i][j][k];

