const long long MOD = 10e9 + 7;

// a 0, t 1, g 2 , c 3

int memo[105][4][4][4];

bool check(int prev[3], int cur){
	if (prev[1] == 0 && prev[2] == 2 && cur == 3){
		return false;
	}
	if (prev[1] == 2 && prev[2] == 0 && cur == 3){
		return false;
	}
	if (prev[1] == 0 && prev[2] == 3 && cur == 2){
		return false;
	}
	if (prev[0] == 0 && prev[2] == 2 && cur == 3){
		return false;
	}
	if (prev[0] == 0 && prev[1] == 2 && cur == 3){
		return false;
	}

	return true;
}

bool check3(int prev[3]){
	if (prev[0] == 0 && prev[1] == 2 && prev[2] == 3){
		return false;
	}
	if (prev[0] == 2 && prev[1] == 0 && prev[2] == 3){
		return false;
	}
	if (prev[0] == 0 && prev[1] == 3 && prev[2] == 2){
		return false;
	}
	return true;
}

long long calc(int k, int N, int prev[3]){
	long long ret = 0;

	if(memo[k][prev[0]][prev[1]][prev[2]] != -1){
		return memo[k][prev[0]][prev[1]][prev[2]];
	}

	for (int i = 0; i < 4; i++){
		if(check(prev, i)){
			if (k == N){
				ret += 1;
				ret %= MOD;
			} else {
				int prev_n[3] = {prev[1], prev[2], i};
				ret += calc(k + 1, N, prev_n);
				ret %= MOD;
			}
		}
	}
	memo[k][prev[0]][prev[1]][prev[2]] = ret;
	return ret;
}

int main(){
	int N;
	cin >> N;

	if(N == 3){
		cout << 61 << endl;
		return 0;
	}

	for (int i = 0; i < 105; i++){
		for (int j = 0; j < 4; j++){
			for (int k = 0; k < 4; k++){
				for (int l = 0; l < 4; l++){
					memo[i][j][k][l] = -1;
				}
			}
		}
	}

	long long ans = 0;
	for (int j = 0; j < 4; j++){
		for (int k = 0; k < 4; k++){
			for (int l = 0; l < 4; l++){
				int prev[3] = {j, k, l};
				if(check3(prev)){
					ans += calc(4, N, prev);
					ans %= MOD;
				}
			}
		}
	}

	cout << ans << endl;
	return 0;
}

