        s.pb(cp[j]);
        s.pb(cp[k]);
        s.pb(cp[l]);
        string sp;
        for(char x : s)
            if(x != ',') sp.pb(x);
        if(m.find(sp) == m.end()) m[sp] = cnt++;
    }
