bool judge(string s){
    if(SIZE(s) < 3) return false;
    if(SIZE(s) == 3) return s == "AGC" || s == "GAC" || s == "ACG";
    if(s[0] == 'A' && s[2] == 'G' && s[3] == 'C') return true;
    if(s[0] == 'A' && s[1] == 'G' && s[3] == 'C') return true;
    if(s == "AGTC") return true;
    string subl = s.substr(0, 3);
    string subr = s.substr(1, 3);
    if(subl == "AGC" || subl == "GAC" || subl == "ACG") return true;
    if(subr == "AGC" || subr == "GAC" || subr == "ACG") return true;
    return false;
}


int solve(int k = 0, bool t = false, string s = ""){
    if(k == N) return !t;
    int& ret = mem[k][t][m[s]];
    if(ret != -1) return ret;
    ret = 0;
    string sp;
    if(SIZE(s) < 3) sp = s;
    else sp = s.substr(1, 2);
    rep(i, 0, 4) ret = ADD(ret, solve(k+1, t||judge(s+c[i]), sp+c[i]));
    return ret%MOD;
}


