bool is_taboo(string s)
{
    if (s.find("agc") != string::npos)
    {
        return true;
    }

    for (int i = 0; i < s.size() - 1; i++)
    {
        char c1 = s[i];
        char c2 = s[i + 1];
        s[i] = c2;
        s[i + 1] = c1;
        if (s.find("agc") != string::npos)
        {
            return true;
        }
        s[i] = c1;
        s[i + 1] = c2;
    }

    return false;
}

signed main()
{
    int N;
    cin >> N;

    //dp[i] ... size N string number of ans
    vector<map<string, int>> dp(N + 1);

    for (int i = 1; i <= N; i++)
    {
        if (i == 1)
        {
            for (int j = 0; j < 4; j++)
            {
                string add = "";
                dp[i][add + agct[j]] = 1;
            }
        }
        else if (i <= 5)
        {
            for (const auto x : dp[i - 1])
            {
                auto key = x.first;
                auto value = x.second;
                for (int j = 0; j < 4; j++)
                {
                    string sadd = key + agct[j];
                    if (!is_taboo(sadd))
                    {
                        if (dp[i].find(sadd) == dp[i].end())
                        {
                            dp[i][sadd] = dp[i - 1][key];
                        }
                        else
                        {
                            dp[i][sadd] += dp[i - 1][key];
                        }
                    }
                }
            }
        }
        else
        {
            for (const auto x : dp[i - 1])
            {
                auto key = x.first;
                auto value = x.second;
                for (int j = 0; j < 4; j++)
                {
                    string sadd = key + agct[j];
                    sadd = sadd.substr(1);
                    if (!is_taboo(sadd))
                    {
                        if (dp[i].find(sadd) == dp[i].end())
                        {
                            dp[i][sadd] = dp[i - 1][key];
                        }
                        else
                        {
                            dp[i][sadd] += dp[i - 1][key];
                        }
                        dp[i][sadd] %= INF;
                    }
                }
            }
        }
    }
    int ans = 0;
    for (const auto x : dp[N])
    {
        auto key = x.first;
        auto value = x.second;
        ans += value;
        ans %= INF;
    }

    cout << ans << endl;
}

