ll modpow(ll x, ll y) {
	if (y == 0) return 1;
	else if (y == 1) {
		return x % MOD;
	}
	else if (y % 2 == 0) {
		ll dst = modpow(x, y / 2);
		return dst * dst % MOD;
	}
	else if (y % 2 == 0) {
		ll dst = modpow(x, y / 2);
		return dst * dst * x % MOD;
	}
}

