bool checked[101][5][5][5][5];
mint dp[101][5][5][5][5];

mint dfs(int N, int idx, int c1, int c2, int c3, int c4) {
    // 0: None, 1: A, 2: G, 3: C, 4: T
    if (idx == N - 1) {
        return 1;
    }
    if (checked[idx][c1][c2][c3][c4]) {
        return dp[idx][c1][c2][c3][c4];
    }
    checked[idx][c1][c2][c3][c4] = true;
    rep(i, 1, 5) {
        if (c2 == 1 && c1 == 2 && i == 3) {
            // AGC
            continue;
        }
        if (c2 == 1 && c1 == 3 && i == 2) {
            // ACG
            continue;
        }
        if (c2 == 2 && c1 == 1 && i == 3) {
            // GAC
            continue;
        }
        if (c3 == 1 && c1 == 2 && i == 3) {
            // A?GC
            continue;
        }
        if (c3 == 1 && c2 == 2 && i == 3) {
            // AG?C
            continue;
        }
        dp[idx][c1][c2][c3][c4] += dfs(N, idx + 1, i, c1, c2, c3);
    }
    return dp[idx][c1][c2][c3][c4];
}

