    rep(i, 0, N) rep(j, 0, 5) rep(k, 0, 5) rep(l, 0, 5) rep(m, 0, 5) {
        dp[i][j][k][l][m] = 0;
        checked[i][j][k][l][m] = false;
    }
    mint ans = 0;
    rep(i, 1, 5) {
        ans += dfs(N, 0, i, 0, 0, 0);
    }
    cout << ans << endl;
    return 0;
}

