    }
    Z[0] = n;
    return Z;
}

//---------------------------------------------------------------
// 二部グラフ判定(O(E))  edge -> リスト
//---------------------------------------------------------------
bool is_bipartite(vvll edge)
{
    ll N = edge.size();
    vll color(N, -1);
    color[0] = 0;
    queue<ll> Q;
    Q.push(0);
    while (!Q.empty())
    {
        ll now = Q.front();
        Q.pop();

        for (int i : edge[now])
        {
            if (color[i] == -1)
            {
                color[i] = (color[now] == 0 ? 1 : 0);
                Q.push(i);
            }
            else if (color[i] == color[now])
            {
                return false;
            }
        }
    }
    return true;
}

//---------------------------------------------------------------
// セグメント木
//---------------------------------------------------------------
class SegmentTree
{
public:

    const ll SEG_LEN = 1 << 19;
    vector<ll> seg;
    ll s;
    ll E;

    SegmentTree(ll N, ll e) : seg(SEG_LEN * 2, e) {
        s = N;
        E = e;
    }

    ll func(ll a, ll b)
    {
        return a + b;
    }

    void set(ll p, ll to)
    {
        ll pos = p + SEG_LEN;
        seg[pos] = to;
        while (true)
        {
            pos /= 2;
            if (pos <= 0) break;

            seg[pos] = func(seg[pos * 2], seg[pos * 2 + 1]);
        }
    }

    void add(ll p, ll d)
    {
        ll pos = p + SEG_LEN;
        seg[pos] += d;
        while (true)
        {
            pos /= 2;
            if (pos <= 0) break;

            seg[pos] = func(seg[pos * 2], seg[pos * 2 + 1]);
        }
    }

    ll get(ll left, ll right)
    {
        left += SEG_LEN;
        right += SEG_LEN + 1;

        ll ret = E;

        while (left < right)
        {
            while (left % 2 == 1)
            {
                ret = func(ret, seg[left]);
                left++;
            }
            while (right % 2 == 1)
            {
                ret = func(ret, seg[right - 1]);
                right--;
            }

            left /= 2;
            right /= 2;
        }

        return ret;
    }

};

//---------------------------------------------------------------
// ダブリング
//---------------------------------------------------------------
class Doubling
{
public:

    ll M = 100;
    vvll doubling;

    Doubling(vll to) : doubling(M, vll(to.size(), -1))
    {
        ll N = to.size();
        for (int i = 0; i < N; i++) doubling[0][i] = to[i];
        for (int i = 1; i < M; i++)
            for (int j = 0; j < N; j++)
                doubling[i][j] = doubling[i - 1][doubling[i - 1][j]];
    }

    ll destination(ll from, ll K)
    {
        vbool bits = to_bitlist(K);
        ll now = from;
        for (int i = 0; i < bits.size(); i++)
        {
            if (bits[i])
            {
                now = doubling[i][now];
            }
        }
        return now;
    }

};

