    const ll M=1LL<<(2*3);
    vector<vector<ll>> dp(n+1,vector<ll>(M,0));
    vector<vector<ll>> edge(M,vector<ll>(M,0));
    for(int t=0;t<M;t++){
        for(int h=0;h<4;h++){
            string s;
            for(int j=0;j<3;j++){
                s.push_back(cul(t>>(2*j)&3));
            }
            s.push_back(cul(h));
            bool j=judge(s);
            for(int i=0;i<3;i++){
