const ll mod = 1000000007;
const int A = 0, C = 1, G = 2, T = 3;
int main() {
  int n;
  cin >> n;
  ll dp[n][4][4][4];
  rep(i, n) rep(j, 4) rep(k, 4) rep(l, 4) dp[i][j][k][l] =
    0LL;
  rep(j, 4) rep(k, 4) rep(l, 4) dp[2][j][k][l] = 1LL;
  dp[2][A][C][G] = 0LL;
  dp[2][G][A][C] = 0LL;
  dp[2][A][G][C] = 0LL;

  rep(i, n) {
    if(i < 3) continue;
    rep(j, 4) rep(k, 4) rep(l, 4) dp[i][k][l][A] =
      (dp[i][k][l][A] + dp[i - 1][j][k][l]) % mod;

    rep(j, 4) rep(k, 4) rep(l, 4) {
      if(j == A && k == G) continue;
      if(j == A && l == G) continue;
      if(k == G && l == A) continue;
      if(k == A && l == G) continue;
      dp[i][k][l][C] =
        (dp[i][k][l][C] + dp[i - 1][j][k][l]) % mod;
    }

    rep(j, 4) rep(k, 4) rep(l, 4) {
      if(k == A && l == C) continue;
      dp[i][k][l][G] =
        (dp[i][k][l][G] + dp[i - 1][j][k][l]) % mod;
    }

    rep(j, 4) rep(k, 4) rep(l, 4) {
      dp[i][k][l][T] =
        (dp[i][k][l][T] + dp[i - 1][j][k][l]) % mod;
    }
  }

  ll ans = 0;
  rep(j, 4) rep(k, 4) rep(l, 4) ans =
    (ans + dp[n - 1][j][k][l]) % mod;
  cout << ans << endl;
  return 0;
}

