using namespace std;
typedef long long ll;
const ll MOD = 1e9 + 7;

bool check(ll a, ll b, ll c) {
    bool f = 1;
    if(a == 0 && b == 2 && c == 1) f = 0;
    if(a == 0 && b == 1 && c == 2) f = 0;
    if(a == 2 && b == 0 && c == 1) f = 0;
    return f;
}

bool check2(ll a, ll b, ll c, ll d) {
    bool f = 1;
    if(a == 0 && b == 2 && d == 1) f = 0;
    if(a == 0 && c == 2 && d == 1) f = 0;
    return f;
}

int main() {
    ll n, i, j, k, l, m;
    cin >> n;
    ll dp[n + 1][4][4][4];
    for(i = 0; i <= n; i++) {
        for(j = 0; j < 4; j++) {
            for(k = 0; k < 4; k++) {
                for(l = 0; l < 4; l++) {
                    dp[i][j][k][l] = 0;
                }
            }
        }
    }

    for(j = 0; j < 4; j++) {
        for(k = 0; k < 4; k++) {
            for(l = 0; l < 4; l++) {
                if(check(j, k, l)) {
                    dp[3][j][k][l] = 1;
                }
            }
        }
    }

    for(i = 4; i <= n; i++) {
        for(j = 0; j < 4; j++) {
            for(k = 0; k < 4; k++) {
                for(l = 0; l < 4; l++) {
                    for(m = 0; m < 4; m++) {
                        if(check(j, k, l) && check(m, j, k) && check2(m, j, k, l)) {
                            dp[i][j][k][l] = (dp[i][j][k][l] + dp[i - 1][m][j][k]) % MOD;
                        }
                    }
                }
            }
        }
    }

    ll ret = 0;
    for(j = 0; j < 4; j++) {
        for(k = 0; k < 4; k++) {
            for(l = 0; l < 4; l++) {
                if(check(j, k, l)) ret = (ret + dp[n][j][k][l]) % MOD;
            }
        }
    }
    cout << ret << endl;
    return 0;
}

