                        dp[i+1][oago][last][next] = (dp[i+1][oago][last][next] + cur)%mod;
                    }
                }
            }
        }
    }

    int ans = 0;
    for(int i = 0; i < 4; ++i) {
        for(int j = 0; j < 4; ++j) {
            for(int k = 0; k < 4; ++k) {
                ans = (ans + dp[n][i][j][k])%mod;
            }
        }
    }

    cout << ans << endl;

