int N;
int M = pow(10, 9) + 7;
vector<map<string, int> > memo; // vector としてグローバルに宣言しておく

// 末尾 4 文字の検索
// ひっくり返しも込みで 'AGC' を含んでしまっていたら false を返す
bool top(string last4){
    string t;
    char tmp;
    int f;
    for(int i = 0; i < 4; i++){
        t = last4; // last4 で初期化
        if(i >= 1){ // ひっくり返す
            tmp = t[i];
            t[i] = t[i-1];
            t[i-1] = tmp;
        }
        f = t.find("AGC");
        if(f != -1) return false; 
    }
    return true;  
}

int dfs(int cur, string last3){
    int ret;
    string S = "ACGT";

    // 記録済みならそれを返す
    if(memo[cur].find(last3) != memo[cur].end())
        return memo[cur][last3];

    // 検索位置が最深部に到達したら終了
    if(cur == N)
        return 1;

    ret = 0;

    // 再帰の開始
    for(int i = 0; i < 4; i++){
        if(top(last3+S[i])) ret = (ret + dfs(cur + 1, last3.substr(1, 2) + S[i])) % M;
    }

    memo[cur][last3] = ret;

    return ret;
}

