    cin >> N;

    // 空の map を所定回数 push_back しておくことで長さを初期化できる
    // 初期化して memo の長さを N + 1 にしておく
    map<string, int> init;
    for(int i = 0; i < N + 1; i++) memo.push_back(init);

    cout << dfs(0, "TTT") << "\n";

    return 0;
}

