bool agc(string s){
  if((s[0]=='A'&&s[1]=='G'&&s[2]=='C')||
    (s[1]=='A'&&s[2]=='G'&&s[3]=='C')){
    return true;
  }
  return false;
}

bool ok(string s){
  string s4;
  if(s.size()<3){
    return true;
  }else if(s.size()==3){
    if(s=="AGC"||s=="GAC"||s=="ACG"){
    return false;
  }
  }else{
    s4 = s.substr(s.size()-4,4);
  }
  if(agc(s4)){
        return false;
  }
  for(int i=0;i<3;i++){
    string str = s4;
    str[i]=s4[i+1];
    str[i+1]=s4[i];
    if(agc(str)){
        return false;
    }
  }
  return true;
}

int f_count(string s,int count){
  int ans=count;
  string s3;
  if(s.size() >=3)s3 = s.substr(s.size()-3,3);
  if(s.size()<N){

    for(int i=0;i<memo.size();i++){
      if(memo[i].first==s.size() && s3==memo[i].second.first &&s.size()>=3){
        return memo[i].second.second;
      }
    }

    if(ok(s)){
      ans = (ans + f_count(s+"A",count)) % MOD;
      ans = (ans + f_count(s+"C",count)) % MOD;
      ans = (ans + f_count(s+"G",count)) % MOD;
      ans = (ans + f_count(s+"T",count)) % MOD;
      if(s.size() >=3)memo.push_back(make_pair(s.size(),make_pair(s3,ans)));
