    bool ret = s.find("AGC") == string::npos;
    int n = s.length();
    for (int i = 0; i < n - 1; i++) {
        swap(s[i], s[i+1]);
        ret &= s.find("AGC") == string::npos;
        swap(s[i], s[i+1]);
    }
    return ret;
}

int main(void) {
    int n;
    cin >> n;
    vector<map<string, int>> dp(2);
    string acgt = "ACGT";

    dp[1][""] = 1;
    for (int i = 0; i < n; i++) {
        dp[i % 2].clear();
        for (auto p: dp[1 - i % 2]) {
            string s = p.first;
            for (auto c: acgt) {
                string t = s + c;
                if (check(t)) {
                    if (t.length() > 3) {
                        t = t.substr(1, 3);
                    }
                    dp[i % 2][t] = (dp[i % 2][t] + p.second) % MOD;
                }
            }
        }
    }

    int ans = 0;
    for (auto p: dp[1 - n % 2]) {
        // printf("%s %d\n", p.first.c_str(), p.second);
        ans = (ans + p.second) % MOD;
    }
    cout << ans << endl;
    return 0;
}

