enum CharKinds
{
	charA = 0,
	charC,
	charG,
	charT,

	charKind,
};

unsigned long long decideChar(int maxN, int szIdx, const char * szBfr)
{
	static const int TmpSzLen = 3;

	int chkCnt = (TmpSzLen > szIdx) ? szIdx : TmpSzLen;
	//char mkStr[charKind][TmpSzLen + 1] = { 0 };
	char mkStr[TmpSzLen + 1] = { 0 };

	if (szIdx >= maxN) {
		return 1;
	}

	char addable[] = { 'A', 'C', 'G', 'T' };
	if (chkCnt >= 2) {
		if (szBfr[chkCnt - 2] == 'A') {
			if (szBfr[chkCnt - 1] == 'G') {
				addable[charC] = 0;
			}
			else if (szBfr[chkCnt - 1] == 'C') {
				addable[charG] = 0;
			}
		}
		else if ((szBfr[chkCnt - 2] == 'G') && (szBfr[chkCnt - 1] == 'A')) {
			addable[charC] = 0;
		}
	}

	int cpOfs = 0;
	if (chkCnt >= 3) {
		if (szBfr[chkCnt - 3] == 'A') {
			if ((szBfr[chkCnt - 2] == 'G') || (szBfr[chkCnt - 1] == 'G')) {
				addable[charC] = 0;
			}
		}
		cpOfs = 1;
	}

	unsigned long long patternCnt = 0;
	for (int i = 0; i < charKind; i++) {
		if(addable[i] != 0) {
			for (int j = 0; j < (chkCnt - cpOfs); j++) {
				mkStr[j] = szBfr[j + cpOfs];
			}
			mkStr[chkCnt - cpOfs] = addable[i];

			patternCnt += decideChar(maxN, szIdx + 1, mkStr);
		}
	}
	return patternCnt;
}

static void D_WeLikeAGC()
{
	const char addable[] = { 'A', 'C', 'G', 'T' };
	int N = 0;

	scanf(" %d", &N);

	char buff[4] = { 0 };
	unsigned long long pattern = 0;

	for (int i = 0; i < charKind; i++) {
		buff[0] = addable[i];
		pattern += decideChar(N, 1, buff);
	}

	printf("%llu\n", pattern % 1000000007);
}

