            for (int j = 0; j < 5; ++j) {
                 for (int k = 0; k < 5; ++k) {
                     for (int l = 1; l < 5; ++l) {
                         if (i == A && j == G && l == C) continue; //AG*C  * = k
                         if (i == A && k == G && l == C) continue; //A*GC  * = j
                         if (j == A && k == G && l == C) continue; //AGC
                         if (j == G && k == A && l == C) continue; //GAC
                         if (j == A && k == C && l == G) continue; //ACG
                         add(dp[n+1][j][k][l], dp[n][i][j][k]);
                     }
                }
            }
        }
    }
    long long res = 0;
    for (int i = 1; i < 5; ++i)
        for (int j = 1; j < 5; ++j)
            for (int k = 1; k < 5; ++k)
                add(res, dp[N][i][j][k]);
    return res;
}

