			char temp = s[i];
			s[i] = s[i - 1]; s[i - 1] = temp;
		}

		if (s.substr(0, 3) == "AGC" or s.substr(1, 3) == "AGC"){
			return false;
		}
		if (i >= 1){
			char temp = s[i];
			s[i] = s[i - 1]; s[i - 1] = temp;
		}

	}
	return true;
}

int solve(string k, int n)
{
	if (dp.count(make_pair(k, n)) == 0){
		if (n == 0){
			dp[{k, n}] = 1;
		} else {
			int ans = 0;
			for (int i = 0; i < 4; i++){
				if (ok(k, a[i])){
					ans = (ans + solve(k.substr(1, 2) + a[i], n - 1)) % MOD;
				}
			}
			dp[{k,n}] = ans;
		}
	}
	return dp[{k,n}];
}

