int64_t const MOD = 1e9+7;
enum {
 // one char
 kA = 0, kC = 1, kG = 2, kT = 3,
 // 3 char NG patterns
 kAGC = 9, kGAC = 0x21, kACG = 6,
 // 4 char NG patterns
 kA_GC = 9, kAG_C = 0x21,
 // mask for 4 char NG patterns
 kX_XX = 0xcf, kXX_X = 0xf3,
 kMask = 0x3f
};

int const MAXPAT = 64;
int const MAXN = 100;
int N;
int64_t dp[MAXN+1][MAXPAT];

int main() {
  std::cin >> N;
  for(int i = 3; i <= N; ++i) std::fill(dp[i], dp[i]+MAXPAT, (int64_t)0);
  // N=3
  std::fill(dp[3], dp[3]+MAXPAT, 1);
  dp[3][kAGC] = dp[3][kGAC] = dp[3][kACG] = 0;
  // N>=4
  for(int i = 4; i <= N; ++i) {
    // for A,T
    for(int p = 0; p < MAXPAT; ++p) {
      int np = (p<<2)&kMask;
      (dp[i][np+kA] += dp[i-1][p]) %= MOD;
      (dp[i][np+kT] += dp[i-1][p]) %= MOD;
    }
    // for G
    for(int p = 0; p < MAXPAT; ++p) {
      int np = (p<<2)&kMask;
      if(np+kG == kACG) continue;
      (dp[i][np+kG] += dp[i-1][p]) %= MOD;
    }
    // for C
    for(int p = 0; p < MAXPAT; ++p) {
      int np = (p<<2) + kC;
      if((np&kX_XX) == kA_GC) continue;
      if((np&kXX_X) == kAG_C) continue;
      np &= kMask;
      if(np == kAGC || np == kGAC) continue;
      (dp[i][np] += dp[i-1][p]) %= MOD;
    }
  }
  int64_t ans = 0;
  for(int p = 0; p < MAXPAT; ++p) (ans += dp[N][p]) %= MOD;
  std::cout << ans << std::endl;
  return 0;
}

