bool Check(const ACGT *prev_char, ACGT now_char)
{
	//AGC
	if ((prev_char[0] == A && prev_char[1] == G && prev_char[2] == C) ||
	    (prev_char[1] == A && prev_char[2] == G && now_char == C)) {
		return false;
	}

	//GAC
	if ((prev_char[0] == G && prev_char[1] == A && prev_char[2] == C) ||
	    (prev_char[1] == G && prev_char[2] == A && now_char == C)) {
		return false;
	}

	//ACG
	if ((prev_char[0] == A && prev_char[1] == C && prev_char[2] == G) ||
		  (prev_char[1] == A && prev_char[2] == C && now_char == G)) {
		return false;
	}

	//A*GC || AG*C
	if ((prev_char[0] == A && prev_char[2] == G && now_char == C) ||
	    (prev_char[0] == A && prev_char[1] == G && now_char == C )) {
		return false;
	}

	return true;
}

DWORD rec(int n, ACGT *prev_char)
{
	if (n == 0) return 1;

	if (dp[n][prev_char[0]][prev_char[1]][prev_char[2]] != -1) {
		return dp[n][prev_char[0]][prev_char[1]][prev_char[2]];
	}


	DWORD ret = 0;
	ACGT now_char[C_NUM] = {A, C, G, T};
	REP(i, 0, C_NUM) {
		if (Check(prev_char, now_char[i])) {
			ACGT next_prev[C_NUM - 1] = {prev_char[1], prev_char[2], now_char[i]};
			ret = (ret + rec(n - 1, next_prev)) % MOD;
		}
	}

	dp[n][prev_char[0]][prev_char[1]][prev_char[2]] = ret;
	return ret;
}

