string acgt = "ACGT";
ll mod = 1e9+7;
ll n;
ll dfs(int depth, string s){
    if(depth == n){return 1;}
    ll ret = 0;
    for(int i = 0;i < 4;i++){
        string ss = s + acgt[i];
        if(depth >= 3){
            string t = ss.substr(ss.size()-4,4);
            if(t[0] == 'A' && t[3] == 'C' && (t[1] == 'G' || t[2] == 'G')){
                continue;
            }
        }
        if(depth >= 2){
            string t = ss.substr(ss.size()-3,3);
            if(t == "AGC" || t == "GAC" || t == "ACG"){
                continue;
            }
        }
        string t = s + acgt[i];
        if(depth >= 2)t = t.substr(t.size()-3,3);

        auto p = make_pair(depth,t);
        if(memo.count(p) == 0)memo[p] = dfs(depth+1, s + acgt[i]);
        ret += memo[p];
        ret %= mod;

    }
    return ret;
}
