    for(int i=0; i<4; i++){
        for(int j=0; j<4; j++){
            for(int k=0; k<4; k++){

            dp[0][i][j][k]=0;
            dp[1][i][j][k]=0;
            dp[2][i][j][k]=0;
            dp[3][i][j][k]=1;

