                        dp[n][x][i][j] += dp[n-1][i][j][k];
                    }
                }
            }
        }

        //条件を満たさない場合を除外
        //n文字目がA
        dp[n][0][3][2] -= dp[n-1][3][2][0];
        //n文字目がT
        dp[n][1][3][2] -= dp[n-1][3][2][0];

        //n文字目がG
        dp[n][2][3][2] -= dp[n-1][3][2][0];
