            dp[n][3][i][2] -= dp[n-1][i][2][0];
        }


        for(int i=0; i<4; i++){
            for(int j=0; j<4; j++){
                for(int k=0; k<4; k++){
                    dp[n][i][j][k] += MOD;
                    dp[n][i][j][k] %= MOD;
                }
            }
        }
    }

    ll ans = 0;
    for(int i=0; i<4; i++){
        for(int j=0; j<4; j++){
            for(int k=0; k<4; k++){
                ans += dp[N][i][j][k];
                ans %= MOD;
            }
        }
    }

    cout<<ans<<endl;
    return 0;
}

