using namespace std;

bool is_allowed(vector<int> vs) {
    assert(vs.size() == 4);
    auto check = [&]() {
        if (vs[0] == 0 && vs[1] == 1 && vs[2] == 2) {
            return false;
        }
        if (vs[1] == 0 && vs[2] == 1 && vs[3] == 2) {
            return false;
        }
        return true;
    };
    if (!check()) {
        return false;
    }
    for (int i = 0; i < 3; ++i) {
        swap(vs[i], vs[i+1]);
        if (!check()) {
            return false;
        }
        swap(vs[i], vs[i+1]);
    }
    return true;
}

vector<vector<int>> all_allowed() {
    vector<vector<int>> all;
    for (int a = 0; a < 4; ++a) {
        for (int b = 0; b < 4; ++b) {
            for (int c = 0; c < 4; ++c) {
                for (int d = 0; d < 4; ++d) {
                    vector<int> xs = {a, b, c, d};
                    if (is_allowed(xs)) {
                        all.push_back(xs);
                    }
                }
            }
        }
    }
    return all;
}

long long prime = 1000000007;

vector<vector<long long>> mul(vector<vector<long long>>& a, vector<vector<long long>>& b) {
    auto t0 = clock();
    assert (a[0].size() == b.size());
    int m = (int) a.size(), n = (int) b.size(), p = (int) b[0].size();
    // (m x n) * (n x p)
    vector<vector<long long>> c(m, vector<long long>(p, 0LL));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < p; ++j) {
            long long s = 0;
            for (int k = 0; k < n; ++k) {
                s += (a[i][k] * b[k][j]) % prime;
            }
            c[i][j] = s % prime;
        }
    }
    cout << "simple mul time: " << (clock() - t0) << " -- " << m << ", " << n << ", " << p << endl;
    return c;
}

vector<vector<long long>> pow(vector<vector<long long>> a, int r) {
    if (r == 1) {
        return a;
    }
    if (r % 2 == 1) {
        auto b = pow(a, r-1);
        return mul(a, b);
    }
    auto b = pow(a, r/2);
    return mul(b, b);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    if (n == 3) {
        cout << 61 << endl;
        return 0;
    }
    map<vector<int>, int> mapping;
    for (auto& xs : all_allowed()) {
        mapping[xs] = (int) mapping.size();
    }
    vector<vector<long long>> mat(mapping.size(), vector<long long>(mapping.size(), 0));
    for (auto& ys : all_allowed()) {
        for (int a = 0; a < 4; ++a) {
            vector<int> xs(ys.begin()+1, ys.end());
            xs.push_back(a);
            if (is_allowed(xs)) {
                ++mat[mapping[ys]][mapping[xs]];
            }
        }
    }
    vector<vector<long long>> u(mapping.size(), vector<long long>(1, 1LL));
    auto t0 = clock();
    vector<vector<long long>> v = u;
    if (n > 4) {
        auto x = pow(mat, n-4);
        v = mul(x, u);
    }
    cout << "pow time = " << (clock() - t0) << endl;
    assert (v[0].size() == 1);
    long long result = 0;
    for (auto& p : v) {
        result += p[0];
    }
    cout << (result % prime) << endl;
    return 0;
}

