    vector<int> col(4); int s = 1;
    for (int j = 0; j < 4; ++j){
      col[j] = (mask / s) % 4;
      s = s * 4;
    }
    for (int j = 0; j < 4; ++j){
      if (j != 3) swap(col[j], col[j + 1]);
      if (col[0] == 1 && col[1] == 2 && col[2] == 0) used[mask] = true;
