ll dp[110][4][4][4];//A0 C1 G2 T3

ll dfs(int size,int i,int j,int k){
  if(dp[size][i][j][k]!=-1) return dp[size][i][j][k];
  if(size==3){
    if(i==0 && j==1 && k==2) return dp[3][i][j][k]=0;
    if(i==0 && j==2 && k==1) return dp[3][i][j][k]=0;
    if(i==1 && j==0 && k==2) return dp[3][i][j][k]=0;
    return dp[3][i][j][k]=1;
  }
  ll sum=0;
  for(int l=0;l<4;l++){
    if(i==0 && j==1 && k==2) continue;
    if(i==0 && j==2 && k==1) continue;
    if(i==1 && j==0 && k==2) continue;
    if(i==0 && k==1 && l==2) continue;
    if(i==0 && j==1 && l==2) continue;
    sum+=dfs(size-1,j,k,l);
    sum%=MOD;
  }

  return dp[size][i][j][k]=sum;
}

