	Vec<Vec<ll>> dp(N);
	for(int i=0;i<N;i++) dp[i].resize(4 * 4 * 4);
	for(int i=0;i<4;i++){
		for(int j=0;j<4;j++){
			for(int k=0;k<4;k++){
				dp[2][i * 16 + j * 4 + k] = 1;
				if(i == 0 && j == 1 && k == 2) dp[2][i * 16 + j * 4 + k] = 0;
				if(i == 1 && j == 0 && k == 2) dp[2][i * 16 + j * 4 + k] = 0;
				if(i == 0 && j == 2 && k == 1) dp[2][i * 16 + j * 4 + k] = 0;
			}
		}
	}

	for(int t=2;t+1<N;t++){
		for(int i=0;i<4;i++){
			for(int j=0;j<4;j++){
				for(int k=0;k<4;k++){
					ll me = dp[t][i * 16 + j * 4 + k];
					// (i , j, k) -> (j, k, n)
					for(int n=0;n<4;n++){
						if(i == 0 && k == 1 && n == 2) continue; // A*GC
						if(j == 0 && k == 1 && n == 2) continue; // *AGC
						if(j == 1 && k == 0 && n == 2) continue; // *GAC
						if(j == 0 && k == 2 && n == 1) continue; // *ACG
						if(i == 0 && j == 1 && n == 2) continue; // AG*C
						dp[t+1][j * 16 + k * 4 + n] += me; if(dp[t+1][j * 16 + k * 4 + n] >= mod) dp[t+1][j * 16 + k * 4 + n] -= mod;
					}
				}
			}
		}
	}

	ll ans = 0;
	for(int i=0;i<4;i++){
		for(int j=0;j<4;j++){
			for(int k=0;k<4;k++){
				ans += dp[N-1][i * 16 + j * 4 + k];
				if(ans >= mod) ans -= mod;
			}
		}
	}

	cout << ans << endl;

    return 0;
}

