const string agct = "AGCT";

int N;
vector<map<string, int>> memo;

int dfs(string s, int idx) {
    // cout << "# " << s << ", idx : " << idx << endl;
    if (idx == N) return 1;
    if (memo[idx].count(s)) return memo[idx][s];

    int ret = 0;
    for (auto c : agct) {
        string next = s + c;
        bool ok = true;
        REP(i, 0, 4) {
            string tmp = next;
            if (i > 0) swap(tmp[i], tmp[i - 1]);
            if (tmp.find("AGC") != string::npos) ok = false;
        }
        if (ok) ret = (ret + dfs(s.substr(1) + c, idx + 1)) % MOD;
        // cout << "--> " << next << " : " << ((ok) ? "OK" : "NG") << endl;
    }
    return memo[idx][s] = ret;
}

