using namespace std;

int N;
int okCnt;

bool ng(string s) { 
  if (s.size() < 3 || s.size() != N) {
    return false;
  } else if (s.size() == 3) {
    char ss[3];
    for (int i = 0; i < s.size(); i++) {
      ss[i] = s.at(i);
    }
    if ((ss[0] == 'A' && ss[1] == 'G' && ss[2] == 'C') ||
        (ss[0] == 'A' && ss[1] == 'C' && ss[2] == 'G') || 
        (ss[0] == 'G' && ss[1] == 'A' && ss[2] == 'C')) {
          return true;
    }
  } else {
    char ss[4];
    for (int i = 0; i < 4; i++) {
      ss[3 - i] = s.at((s.size() - 1) - i);
    }
    if ((ss[0] == 'A' && ss[1] == 'G' && ss[2] == 'C') ||
        (ss[0] == 'A' && ss[1] == 'C' && ss[2] == 'G') || 
        (ss[0] == 'G' && ss[1] == 'A' && ss[2] == 'C') || 
        (ss[1] == 'A' && ss[2] == 'G' && ss[3] == 'C') ||
        (ss[1] == 'A' && ss[2] == 'C' && ss[3] == 'G') || 
        (ss[1] == 'G' && ss[2] == 'A' && ss[3] == 'C') || 
        (ss[0] == 'A' && ss[1] == 'G' && ss[3] == 'C') || 
        (ss[0] == 'A' && ss[2] == 'G' && ss[3] == 'C')) {
          return true;
    }
  }
  return false;
}

bool next(string s) {
  if (ng(s)) {
    return false;
  } else {
    if (s.size() < N) {
      return true;
    } else if (s.size() == N) {
      okCnt++;
      return false;
    } else {
      return false;
    }
  }
}

void rep(string s) {
  if (next(s + "A")) rep(s + "A");
  if (next(s + "C")) rep(s + "C");
  if (next(s + "G")) rep(s + "G");
  if (next(s + "T")) rep(s + "T");
}

int main() {
  cin >> N;
  string s;
  rep(s);
  cout << okCnt << endl;
}

