          } else if (x == 1 && y == 2) {
            // xGA
            for (int j = 0; j < 3; ++j) {
              dp[i + 1][j][x][y] += dp[i][x][y][z];
            }
          } else if (y == 2 && z == 1) {
            // AGx
            for (int j = 0; j < 3; ++j) {
              dp[i + 1][j][x][y] += dp[i][x][y][z];
            }
          } else {
            for (int j = 0; j < 4; ++j) {
              dp[i + 1][j][x][y] += dp[i][x][y][z];
            }
          }
          dp[i + 1][j][x][y] %= MOD;
        }
      }
    }
  }
  int result = 0;
  for (int i = 0; i < 4; ++i) {
    for (int j = 0; j < 4; ++j) {
      for (int k = 0; k < 4; ++k) {
        result = (result + dp[n][i][j][k]) % MOD;
      }
    }
  }
  cout << result;
  return 0;
}

