ll solve(int n) {
    rep(i, 4) {
        rep(j, 4) { dp[i][j][2] = 1; }
    }
    repc2(i, 3, 100) {
        rep(p1, 4) {
            rep(p2, 4) {
                rep(j, 4) { dp[p1][p2][i] += dp[j][p1][i - 1]; }
                if (p1 == G && p2 == C) {
                    dp[G][C][i] -= dp[A][G][i - 1];
