                    if (dp[G][C][i] < 0) dp[G][C][i] += M;
                    dp[G][C][i] %= M;
                    dp[G][C][i] -= dp[A][C][i - 2];
                    if (dp[G][C][i] < 0) dp[G][C][i] += M;
                    dp[G][C][i] %= M;
