void make_string(string S)
{
  if (S.size() == 4)
  {
    for (auto k = 0; k < 2; k++)
    {
      string s = S.substr(k, 3);
      if (s == "AGC")
      {
        forbid.insert(S);
        return;
      }
    }
    for (auto l = 0; l < 3; l++)
    {
      string T = S;
      swap(T[l], T[l + 1]);
      for (auto k = 0; k < 2; k++)
      {
        string s = T.substr(k, 3);
        if (s == "AGC")
        {
          forbid.insert(S);
          return;
        }
      }
    }
    return;
  }
  for (auto x : C)
  {
    make_string(S + x);
  }
}

int main()
{
  cin >> N;
  make_string("");
  M[0]["TTT"] = 1;
  for (auto i = 0; i < N; i++)
  {
    for (auto e : M[i])
    {
      string S = e.first;
      ll cnt = e.second;
      if (cnt == 0)
      {
        break;
      }
      for (auto x : C)
      {
        string T = S + x;
        string U = T.substr(1, 3);
        if (forbid.find(T) == forbid.end())
        {
          if (M[i + 1].find(U) == M[i + 1].end())
          {
            M[i + 1][U] = cnt;
          }
          else
          {
            M[i + 1][U] += cnt;
            M[i + 1][U] %= MOD;
          }
        }
      }
    }
  }
  ll ans = 0;
  for (auto x : M[N])
  {
    ans += x.second;
    ans %= MOD;
  }
  cout << ans << endl;
}

