ll solve(ll in, ll p1, ll p2, ll p3) {
    if(in == n+1) return 1;
    if(dp[in][p1][p2][p3] != -1) return dp[in][p1][p2][p3];

    ll i, res(0);

    if((p2 == 1 && p1 == 3) || (p2 == 3 && p1 == 1) || (p2 == 1 && p1 == 2)) {
        for1(i, 3) {
            if(i != p1 && i != p2) continue;
            res = (res + solve(in+1, i, p1, p2)) % mod;
        }
        res = (res + solve(in+1, 4, p1, p2)) % mod;
    }
    else if((p3 == 1 && p2 == 3) || (p3 == 1 && p1 == 3)) {
        for1(i, 4) {
            if(i == 2) continue;
            res = (res + solve(in+1, i, p1, p2)) % mod;
        }
    }
    else {
        for1(i, 4) {
            res = (res + solve(in+1, i, p1, p2)) % mod;
        }
    }

    return dp[in][p1][p2][p3] = res;
}

