constexpr long long int INF = std::numeric_limits<long long int>::max();
constexpr long long int MAGIC = 1000000007;
#define int long long int

map<string, int> prev_memo;
set<string> NG;

char c[4] = {'A', 'G', 'C', 'T'};

int N;

void init() {
  const string AGC = "AGC";
  vector<string> v = {"AGC"};
  for (auto x : c) {
    v.push_back(x + AGC);
    v.push_back(AGC + x);
    for (auto y : c) {
      v.push_back(x + AGC + y);
      v.push_back(string({x, y}) + AGC);
      v.push_back(AGC + x + y);
    }
  }

  for (const auto &str : v) {
    NG.emplace(str);
    for (int i = 1; i < str.size(); i++) {
      string s = str;
      swap(s[i - 1], s[i]);
      NG.emplace(s);
    }
  }

  for (auto x : c) {
    for (auto y : c) {
      prev_memo[string({x, y})] = 1;
    }
  }
}

void solve() {
  // int x;
  // cout << endl;
  init();
  cin >> N;

  for (int i = 2; i < N; i++) {
    map<string, int> memo;
    for (auto p : prev_memo) {
      for (auto cc : c) {
        string key = p.first + cc;
        if (NG.count(key) == 0) {
          if (key.size() == 5) {
            int &m = memo[key.substr(1, 4)];
            m = (m + p.second) % MAGIC;
          } else {
            int &m = memo[key];
            m = (m + p.second) % MAGIC;
          }
        }
      }
    }
    prev_memo = memo;
  }

  int ans = 0;
  for (auto p : prev_memo) {
    ans = (ans + p.second) % MAGIC;
  }

  cout << ans << endl;
}

signed main() {
  solve();
  return 0;
}

