    for (int a=0;a<4;++a){
      for (int b=0;b<4;++b){
        for (int c=0;c<4;++c){
          for (int d=0;d<4;++d){
            int abcd=((a*4+b)*4+c)*4+d;
            for (int e=0;e<4;++e){
              int bcde=((b*4+c)*4+d)*4+e;
              bool bcde_=bad(b,c,d,e);
              for (int j=0;j<2;++j){
                (dp[i+1][bcde][bcde_|j]+=dp[i][abcd][j])%=mod;
              }
            }
          }
        }
      }
    }
  }

  ll n_bad=0;

  for (int i=0;i<256;++i){
    (n_bad+=dp[N][i][1])%=mod;
  }

  ll ans=(power(4,N)-n_bad+mod);
  ans%=mod;
  return ans;
}

