int main(){

  int n;
  cin>>n;

  //0:A
  //1:C
  //2:G
  //3:T
  //求める文字列の先頭にTを3つ付け加えるとしても答えは変わらない。
  dp[0][3][3][3]=1;

  REP(len,n){
    REP(i,4){
      REP(j,4){
        REP(k,4){
          REP(a,4){
            if(a==1 && j==0 && k==2)continue;//AGCが部分文字列として出てきてしまう時
            if(a==1 && j==2 && k==0)continue;//GACが部分文字列として出てきてしまう時
            if(a==2 && j==0 && k==1)continue;//ACGが部分文字列として出てきてしまう時
            if(a==1 && i==0 && k==2)continue;//A?GCが部分文字列として出てきてしまう時
            if(a==1 && i==0 && j==2)continue;//AG?Cが部分文字列として出てきてしまう時
            dp[len+1][j][k][a] += dp[len][i][j][k];
            dp[len+1][j][k][a] %= i_7;
          }
        }
      }
    }
  }

  long long ans=0;
  REP(i,4){
    REP(j,4){
      REP(k,4){
        ans += dp[n][i][j][k];
        ans %= i_7;
      }
    }
  }

  cout<<ans<<endl;    
  return 0;
}

