  memset(dp,-1,sizeof(dp));
  int n;cin>>n;
  ll ans=0;
  for(int i=0;i<64;i++){
    int a=i%4,b=(i/4)%4,c=(i/16)%4;
    if(check(a,b,c,-1))ans+=f(n,a,b,c);
  }
  cout<<ans%MOD<<endl;
}

