// モジュール
constexpr ll p = 1000000007ll;
constexpr int GENOM_EMPTY = 0;
constexpr int GENOM_A = 1;
constexpr int GENOM_T = 2;
constexpr int GENOM_G = 3;
constexpr int GENOM_C = 4;

// 処理内容
int main() {

    ll n;
    cin >> n;

    vector<vector<ll>> dp(n+1, vector<ll>(125, 0));

    REP(i, 125) dp[0][i] = 1;

    RANGE(i, 0, n-1) {
        int jend;
        switch (i) {
            case 0: jend = 1; break;
            case 1: jend = 5; break;
            case 2: jend = 25; break;
            default: jend = 125; break;
        }
        REP(j, jend) {
            int pre3 = j / 25;
            int pre2 = (j % 25) / 5;
            int pre1 = j % 5;
            int next = (j % 25) * 5;
            dp[i+1][next + GENOM_A] += dp[i][j];
            dp[i+1][next + GENOM_A] %= p;
            dp[i+1][next + GENOM_T] += dp[i][j];
            dp[i+1][next + GENOM_T] %= p;
            if (!(
                pre2 == GENOM_A &&
                pre1 == GENOM_C
            )) {
                dp[i+1][next + GENOM_G] += dp[i][j];
                dp[i+1][next + GENOM_G] %= p;
            }
            if (!(
                pre2 == GENOM_G &&
                pre1 == GENOM_A
            ) && !(
                pre2 == GENOM_A &&
                pre1 == GENOM_G
            ) && !(
                pre3 == GENOM_A &&
                pre2 != GENOM_EMPTY &&
                pre1 == GENOM_G
            ) && !(
                pre3 == GENOM_A &&
                pre2 == GENOM_G &&
                pre1 != GENOM_EMPTY
            )) {
                dp[i+1][next + GENOM_C] += dp[i][j];
                dp[i+1][next + GENOM_C] %= p;
            }
        }
    }

    ll ans = 0;
    REP(j, 125) {
        ans += dp[n][j];
        ans %= p;
    }

    cout << ans << endl;

}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int N = 105;
const ll m = (ll)1e9 + 7;
int n;
ll dp[N][5][5][5];

// 0 -> A, 1 -> C, 2 -> G, 3 -> T

ll add(ll a , ll b) {
   return ((a % m) + (b % m)) % m;
}

int cantGoTo3(int oneBefore , int twoBefore) {
   if (oneBefore == 2 && twoBefore == 0) return 1;
   else if (oneBefore == 0 && twoBefore == 2) return 1;
   else if (oneBefore == 1 && twoBefore == 0) return 2;
   else return -1;
}

int cantGoTo4(int oneBefore , int twoBefore , int threeBefore) {
   if (oneBefore == 2 && twoBefore == 0) return 1;
   else if (oneBefore == 0 && twoBefore == 2) return 1;
   else if (oneBefore == 1 && twoBefore == 0) return 2;
   else if (threeBefore == 0 && twoBefore == 3 && oneBefore == 2) return 1;
   else if (threeBefore == 0 && twoBefore == 2 && oneBefore == 2) return 1;
   else if (threeBefore == 0 && twoBefore == 1 && oneBefore == 2) return 1;
   else if (threeBefore == 0 && twoBefore == 2 && oneBefore == 0) return 1;
   else if (threeBefore == 0 && twoBefore == 2 && oneBefore == 3) return 1;
   else return -1;
}

ll f(int curr , int prv , int prv2 , int prv3) {
   if (curr > n) return 1;
   ll &sol = dp[curr][prv][prv2][prv3];
   if (sol != -1) return sol;
   sol = 0;
   if (prv == 4) {
      for (int v = 0 ; v < 4 ; v++) {
         sol = add(sol , f(curr + 1 , v , 4 , 4));
      }
   } else if (prv2 == 4) {
      for (int v = 0 ; v < 4 ; v++) {
         sol = add(sol , f(curr + 1 , v , prv , 4));
      }
   } else if (prv3 == 4) {
      int x = cantGoTo3(prv , prv2);
      for (int v = 0 ; v < 4 ; v++) {
         if (v != x) {
            sol = add(sol , f(curr + 1 , v , prv , prv2));
         }
      }
   } else {
      int x = cantGoTo4(prv , prv2 , prv3);
      for (int v = 0 ; v < 4 ; v++) {
         if (v != x) {
            sol = add(sol , f(curr + 1 , v , prv , prv2));
         }
      }
   }
   return sol;
}

