}

#include <bits/stdc++.h>
using namespace std;

const int MAX_N = 100;
const int64_t MOD = 1e9 + 7;
int n;
int64_t dp[MAX_N + 1][4][4][4];

void solve() {
    dp[0][0][0][0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int a = 0; a < 4; a++) {
            for (int b = 0; b < 4; b++) {
                for (int c = 0; c < 4; c++) {
                    for (int d = 0; d < 4; d++) {
                        if ((b == 1 && c == 2 && d == 3) || // AGC*
                        (b == 1 && c == 3 && d == 2) ||     // ACG*
                        (b == 2 && c == 1 && d == 3) ||     // GAC*
                        (a == 1 && b == 2 && d == 3) ||     // AG*C
                        (a == 1 && c == 2 && d == 3)) {     // A*GC
                            continue;
                        }
                        dp[i][b][c][d] = (dp[i][b][c][d] + dp[i - 1][a][b][c]) % MOD;
                    }
                }
            }
        }
    }

    int64_t ans = 0;
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            for (int k = 0; k < 4; k++) {
                ans = (ans + dp[n][i][j][k]) % MOD;
            }
        }
    }

    cout << ans << endl;
}

int main() {
    cin >> n;
    solve();
}

