        char t=s[i];
        s[i]=s[i+1];
        s[i+1]=t;
        if (check2(s)==0) return 0;
        t=s[i];
        s[i]=s[i+1];
        s[i+1]=t;
    }

    return 1;
}

ll dp(int n,string S)
{
    if (n<=3)
    {
        if (S=="AGC" || S=="ACG" || S=="GAC") return 0;
        return 1;
    }
    if (flag[n][h(S)]==1)
        return f[n][h(S)];
    flag[n][h(S)]=1;
    f[n][h(S)]=0;

    for (int i=0; i<4; ++i)
    {
        if (check(c[i]+S))
        {
            f[n][h(S)]+=dp(n-1,c[i]+S.substr(0,2));
            f[n][h(S)]%=M;
        }
    }

    return f[n][h(S)];
}


