bool is_safe(ll x){  // AGCにならないことを確認する
	bool ans=true;
	ll a[4];  // a[0]が一番右
	rep(i,4){
		a[i]=x%4;
		x/=4;
	}
	if(a[3]==1 && a[2]==2 && a[1]==3)ans=false;  // AGC*
	if(a[2]==1 && a[3]==2 && a[1]==3)ans=false;  // GAC*
	if(a[3]==1 && a[1]==2 && a[2]==3)ans=false;  // ACG*
	if(a[2]==1 && a[1]==2 && a[0]==3)ans=false;  // *AGC
	if(a[1]==1 && a[2]==2 && a[0]==3)ans=false;  // *GAC
	if(a[2]==1 && a[0]==2 && a[1]==3)ans=false;  // *ACG
	if(a[3]==1 && a[1]==2 && a[0]==3)ans=false;  // A*CG
	if(a[3]==1 && a[2]==2 && a[0]==3)ans=false;  // AC*G
	return ans;
}

