ll memo[101][4][4][4];

ll dfs(int length, int a, int b, int c, int n) {
  ll ret = 0;
  if (length == n) return 1;
  if (memo[length][a][b][c]) return memo[length][a][b][c];
  REP(d, 4) {
    if (b == 0 && c == 1 && d == 2) continue;
    if (b == 1 && c == 0 && d == 2) continue;
    if (b == 0 && c == 2 && d == 1) continue;
    if (a == 0 && b == 1 && d == 2) continue;
    if (a == 0 && c == 1 && d == 2) continue;
    ret += dfs(length + 1, b, c, d, n);
  }
  return memo[length][a][b][c] = ret % MOD;
}

