// 深さ優先探索
vector<bool> seen;
void gdfs(const Graph &G, int v) {
    seen[v] = true; // v を訪問済にする

    // v から行ける各頂点 next_v について
    for (auto next_v : G[v]) {
       if (seen[next_v]) continue; // next_v が探索済だったらスルー
       gdfs(G, next_v); // 再帰的に探索
    }
}

