bool valid(int a, int b, int c, int d) {

    if(a == 0 && b == 1 && c == 2) return false; //AGCX
    if(a == 1 && b == 0 && c == 2) return false; //GACX
    if(a == 0 && b == 2 && c == 1) return false; //ACGX
    if(a == 0 && b == 1 && d == 2) return false; //AGXC

    if(b == 0 && c == 1 && d == 2) return false; //XAGC
    if(b == 1 && c == 0 && d == 2) return false; //XGAC
    if(b == 0 && c == 2 && d == 1) return false; //XACG
    if(a == 0 && c == 1 && d == 2) return false; //AXCG -> was missing this one

    return true;
}

ll dag(int ind, int a, int b, int c) {

    if(dp[ind][a][b][c] != -1) return dp[ind][a][b][c];

    if(ind == n) {
        return 1;
    }

    ll ans = 0;

    for(int i = 0; i < 4; ++i) {
        if(valid(a,b,c,i)) {
            ans += dag(ind+1,b,c,i);
            ans %= mod;
        }
    }

    dp[ind][a][b][c] = ans;
    return ans;
}

