int n;
vector<map<string, int>> memo;

int dfs(string s, int idx) {
  if (idx == n) return 1;
  if (memo[idx].count(s)) return memo[idx][s];

  int ret = 0;
  for (auto c : agct) {
    string next = s + c;
    bool ok = true;
    rep(i, 4) {
      string t = next;
      if (i > 0) swap(t[i], t[i - 1]);
      if (t.find("AGC") != string::npos) ok = false;
    }
    if (ok) ret = (ret + dfs(s.substr(1) + c, idx + 1)) % mod;

  }
  return memo[idx][s] = ret;
}

