	cin >> N;

	rep(i, 0, 4)dp[0][i] = 1;
	rep(i, 1, N)
	{
		int t = 0;
		rep(j, 0, 4)
		{
			t += dp[i - 1][j];
			t %= MOD;
		}
		rep(j, 0, 4)
		{
			dp[i][j] = t;
		}
		if (2 <= i)
		{
			dp[i][1] = (dp[i][1] + MOD - (dp[i - 2][0] + dp[i - 2][2])) % MOD;
			dp[i][2] = (dp[i][2] + MOD - dp[i - 2][0]) % MOD;
			if (3 <= i)
			{
				dp[i][2] += dp[i - 3][2];
				dp[i][2] %= MOD;
			}
		}
		if (3 <= i)
		{
			dp[i][1] = (dp[i][1] + MOD - (dp[i - 3][0] * 3));
		}
	}

	int ans = 0;
	rep(i, 0, 4)
	{
		ans += dp[N - 1][i];
	}

	cout << ans % MOD << endl;

	return 0;
}

