#include <bits/stdc++.h>

#define REP(i, n) for (int i = 0; i < n; i++)
#define FOR(i, n, m) for (int i = n; i < m; i++)
#define ll long long int

using namespace std;

ll DIV = 1000000007;

int main()
{
  int n;
  cin >> n;
  ll result = 0LL;
  ll dp[105][4][4][4] = {};

  REP(i,4) {
    REP(j,4) {
      REP(k,4) {
        dp[3][i][j][k] = 1;
        if (i == 0 && j == 1 && k == 2) {
          dp[3][i][j][k]--;
        }
        if (i == 0 && j == 2 && k == 1)
        {
          dp[3][i][j][k]--;
        }
        if (i == 2 && j == 0 && k == 1)
        {
          dp[3][i][j][k]--;
        }
      }
    }
  }

  FOR(m,4,n+1) {
    REP(i,4) {
      REP(j,4) {
        REP(k,4) {
          REP(l,4) {
            if ((j == 0 && k == 1 && l == 2) || (j == 2 && k == 0 && l == 1) || (j == 0 && k == 2 && l == 1)) {
              continue;
            } else if ((i == 0 && k == 2 && l == 1) || (i == 0 && j == 2 && l == 1)) {
              continue;
            } else {
              dp[m][j][k][l] += dp[m-1][i][j][k]%DIV;
            }
          }
        }
      }
    }
  }

  REP(i, 4) {
    REP(j, 4) {
      REP(k, 4 ){
        result = (result + dp[n][i][j][k])%DIV;
      }
    }
  }

  cout << result << endl;

}

