#define MOD   ((ll)(1e9) + 7LL)

char chr(int i)
{
    if (i == 0) return 'A';
    if (i == 1) return 'C';
    if (i == 2) return 'G';
    if (i == 3) return 'T';
    assert(false);
}

bool pass(int i, int j, int k)
{
    string key; key += chr(i); key += chr(j); key += chr(k);
    bool ret = true;

    if (key == "AGC") ret = false;
    if (key == "GAC") ret = false;
    if (key == "ACG") ret = false;
    return ret;
}

bool pass4(int a, int b, int c, int d)
{
    string key; key += chr(a); key += chr(b); key += chr(c); key += chr(d);
    bool ret = true;

    if (key == "AACG") ret = false;
    if (key == "CACG") ret = false;
    if (key == "GACG") ret = false;
    if (key == "TACG") ret = false;
    if (key == "AAGC") ret = false;
    if (key == "CAGC") ret = false;
    if (key == "GAGC") ret = false;
    if (key == "TAGC") ret = false;
    if (key == "AGAC") ret = false;
    if (key == "AGCC") ret = false;
    if (key == "AGGC") ret = false;
    if (key == "AGTC") ret = false;
    if (key == "AAGC") ret = false;
    if (key == "ACGC") ret = false;
    if (key == "AGGC") ret = false;
    if (key == "ATGC") ret = false;
    if (key == "AGAC") ret = false;
    if (key == "CGAC") ret = false;
    if (key == "GGAC") ret = false;
    if (key == "TGAC") ret = false;
    return ret;
}

void update(ll dp[4][4][4])
{
    ll dp_orig[4][4][4];
    memcpy(dp_orig, dp, sizeof(ll) * 4LL * 4LL * 4LL);
    memset(dp, 0, sizeof(ll) * 4LL * 4LL * 4LL);

    rep (i, 4) rep (j, 4) rep (k, 4) rep (nc, 4) {
        if (pass4(i, j, k, nc)) {
            dp[j][k][nc] += dp_orig[i][j][k];
            dp[j][k][nc] %= MOD;
        }
    }
}

void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll n; llin(n);

    ll dp[4][4][4];
    memset(dp, 0, sizeof(dp));
    rep (i, 4) rep (j, 4) rep (k, 4) if (pass(i, j, k)) dp[i][j][k] = 1LL;

    srep (cnt, 4, n+1) update(dp);

    ll ans = 0LL;
    rep (i, 4) rep (j, 4) rep (k, 4) {
        ans += dp[i][j][k];
        ans %= MOD;
    }

    cout << ans << endl;
}

