const int mod = 1000000007;

int dp[101][4][4][4];   /* dp[i][c1][c2][c3] : 長さiで末尾3文字がc3,c2,c1のときの条件を満たす文字列の総数
                           ただし、'A' = 0, 'G' = 1, 'C' = 2, 'T' = 3 と対応している */

int main() {
    int n;
    cin >> n;

    //dp[0][3][3][3] = 1;
    //i文字目まで決める
    rep(i, n) {
        //i文字目を全通り試す
        rep(c1, 4) {
            //i-1文字目を全通り試す
            rep(c2, 4) {
                //i-2文字目を全通り試す
                rep(c3, 4) {

                    if(dp[i][c1][c2][c3] == 0) {
                        continue;
                    }

                    //i+1文字目に置く文字を全通り試す
                    rep(next, 4) {

                        //末尾4文字が?AGCになるときはダメ
                        if(next == 2 && c1 == 1 && c2 == 0) {
                            continue;
                        }
                        //末尾4文字が?GACになるときはダメ
                        if(next == 2 && c1 == 0 && c2 == 1) {
                            continue;
                        }
                        //末尾4文字が?ACGになるときはダメ
                        if(next == 1 && c1 == 2 && c2 == 0) {
                            continue;
                        }
                        //末尾4文字がA?GCになるときはダメ
                        if(next == 2 && c1 == 1 && c3 == 0) {
                            continue;
                        }
                        //末尾4文字がAG?Cになるときはダメ
                        if(next == 2 && c2 == 1 && c3 == 0) {
                            continue;
                        }

                        //それ以外のときはok
                        dp[i+1][next][c1][c2] += dp[i][c1][c2][c3];
                        dp[i+1][next][c1][c2] %= mod;
                    }
                }
            }
        }
    }

    //求める答えは長さnのときの場合の数の総数
    int ans = 0;
    rep(c1, 4) {
        rep(c2, 4) {
            rep(c3, 4) {
                ans += dp[n][c1][c2][c3];
                ans %= mod;
            }
        }
    }

    cout << ans << endl;
    return 0;
}

