int main() {
	cin.tie(0);
    ios::sync_with_stdio(false);

    ll mod = pow(10, 9) + 7LL;

    int N;
    cin >> N;

    vector<vector<ll> > dp(N, vector<ll>(4));

    for(int i = 0; i < 4; i++) {
        dp[0][i] = 1;
        dp[1][i] = 4;
        dp[2][i] = 16;
    }

    dp[2][1] -= 2;
    dp[2][2] -= 1;

    for(int i = 3; i < N; i++) {
        for(int j = 0; j < 4; j++) {
            for(int k = 0; k < 4; k++) {
                dp[i][j] += dp[i - 1][k];
                dp[i][j] %= mod;
            }
        }

        dp[i][1] -= (dp[i - 3][0] * 3) % mod;
        if(dp[i][1] < 0) dp[i][1] += mod;
        dp[i][1] -= (dp[i - 3][0] * 2) % mod;
        if(dp[i][1] < 0) dp[i][1] += mod;
        dp[i][1] -= (dp[i - 2][2] - dp[i - 3][0]) % mod;
        if(dp[i][1] < 0) dp[i][1] += mod;
        dp[i][1] -= (dp[i - 2][0] - dp[i - 3][0]) % mod;
        if(dp[i][1] < 0) dp[i][1] += mod;

        dp[i][2] -= (dp[i - 2][0] - dp[i - 3][2]) % mod;
        if(dp[i][2] < 0) dp[i][2] += mod;
    }

    ll count = 0;

    for(int i = 0; i < 4; i++) {
        count += dp[N - 1][i];
        count %= mod;
    }

    cout << count << endl;
}

