bool judge(int x, int y, int z)
{
    if (x == 0 && y == 2 && z == 1)
    {
        return true;
    }
    else
    {
        return false;
    }
}

int main()
{
    int N;
    cin >> N;

    // cout << dfs(1, N, -1, -1, -1) << endl;

    long long ans;

    vector<vector<vector<long long>>> count(4, vector<vector<long long>>(4, vector<long long>(4, 1)));
    vector<vector<vector<long long>>> prev_count(4, vector<vector<long long>>(4, vector<long long>(4, 1)));
    count[0][2][1] = 0;
    count[0][1][2] = 0;
    count[2][0][1] = 0;

    for (int x = 0; x < N - 3; x++)
    {
        for (int i = 0; i < 4; i++)
        {
            for (int j = 0; j < 4; j++)
            {
                for (int k = 0; k < 4; k++)
                {
                    prev_count[i][j][k] = count[i][j][k];
                    count[i][j][k] = 0;
                }
            }
        }

        for (int i = 0; i < 4; i++)
        {
            for (int j = 0; j < 4; j++)
            {
                for (int k = 0; k < 4; k++)
                {
                    for (int l = 0; l < 4; l++)
                    {
                        if (judge(i, j, k) ||
                            judge(i, k, j) ||

                            judge(j, k, l) ||
                            judge(k, j, l) ||
                            judge(j, l, k) ||

                            judge(i, k, l) ||
                            judge(i, j, l))
                        {
                            continue;
                        }
                        count[j][k][l] += prev_count[i][j][k];
                        count[j][k][l] %= MOD;
                    }
                }
            }
        }
    }

    ans = 0;
    for (int i = 0; i < 4; i++)
    {
        for (int j = 0; j < 4; j++)
        {
            for (int k = 0; k < 4; k++)
            {
                ans += count[i][j][k];
                ans %= MOD;
            }
        }
    }
    cout << ans << endl;
}

