long long solve(int idx,int l1,int l2,int l3)
{
    if(idx == n)
        return !isBad(l1,l2,l3,0);
    if(dp[idx][l1][l2][l3] != -1)
        return dp[idx][l1][l2][l3];
    long long C = 0;
    for(int i = 1;i <= 4;i++)
    {
        if(isBad(l1,l2,l3,i))
            continue;
        if(l1 == 0 && l2 == 0 && l3 == 0)
            C += solve(idx + 1,i,0,0) % MOD;
        else if(l2 == 0 && l3 == 0)
            C += solve(idx + 1,l1,i,0) % MOD;
        else if(l3 == 0)
            C += solve(idx + 1,l1,l2,i) % MOD;
        else
            C += solve(idx + 1,l2,l3,i) % MOD;
    }
    return dp[idx][l1][l2][l3] = C % MOD;
}
