	for (int i=1;i<=4;i++)
		for (int j=1;j<=4;j++)
			for (int k=1;k<=4;k++)
				dp[3][i][j][k]=1;
	dp[3][1][3][2]=0;
	dp[3][3][1][2]=0;
	dp[3][1][2][3]=0;

	cin>>n;
	//用刷表法更自然,用(i-2,i-1,i)推导出(i-1,i,i+1) 
	for (int i=3;i<n;i++)
		for (int j=1;j<=4;j++)	//i-2
			for (int k=1;k<=4;k++)	//i-1
				for (int l=1;l<=4;l++) {	//i

					if (dp[i][j][k][l]==0) continue;

					for (int m=1;m<=4;m++) {	//i+1
