						if (j==1 && k==3 && m==2) continue; //AG*C

						dp[i+1][k][l][m]=(dp[i+1][k][l][m]+dp[i][j][k][l])%MOD;
					}
				}

	int ans=0;
	for (int i=1;i<=4;i++)
		for (int j=1;j<=4;j++)
			for (int k=1;k<=4;k++)
