void exgcd(int a,int b,int &g,int &x,int &y)
{
	if(b==0)g=a,x=1,y=0;
	else exgcd(b,a%b,g,y,x),y-=a/b*x;
}

int inv(int a)
{
	int g,x,y;
	exgcd(a,mod,g,x,y);
	return(x+mod)%mod;
}

int C(int n,int m)
{
	return (long long)fac[n]*inv(fac[m])%mod*inv(fac[n-m])%mod;
}

int f(int n,int m)
{
	return C(n+m-2,n-1);
}

