            if (c0 == 1 && c1 == 2 && c2 == 0) continue;
            if (c0 == 2 && c1 == 1 && c3 == 0) continue;
            if (c0 == 2 && c2 == 1 && c3 == 0) continue;

            dp[s + 1][c0][c1][c2] += dp[s][c1][c2][c3];
            dp[s + 1][c0][c1][c2] %= mod;
          }
        }
      }
    }
  }

  int ans = 0;
  for (int i = 0; i < 4; i ++) {
    for (int j = 0; j < 4; j ++) {
      for (int k = 0; k < 4; k ++) {
        ans += dp[n][i][j][k];
        ans %= mod;
      }
    }
  }

  cout << ans << endl;
}

