    return false;
  if(j == 0 && k == 1 && l == 2) // ACGx
    return false;
  if(j == 2 && k == 0 && l == 1) // GACx
    return false;
  if(j == 0 && l == 2 && m == 1) // AxGC
    return false;
  if(k == 0 && l == 2 && m == 1) // xAGC
    return false;
  if(k == 2 && l == 0 && m == 1) // xGAC
    return false;
  if(k == 0 && l == 1 && m == 2) // xACG
    return false;
  if(j == 0 && k == 2 && m == 1) // AGxC
    return false;
  return true;
}

