bool stg(string s)
{
    int n = s.size();
    for (int i = 0; i < n - 1; ++i)
    {
        swap(s[i], s[i + 1]);
        for (int j = 0; j <= n - 3; ++j)
        {
            if (s[j] == '0' && s[j + 1] == '1' && s[j + 2] == '2')
                return false;
        }
        swap(s[i], s[i + 1]);
    }
    for (int j = 0; j <= n - 3; ++j)
    {
        if (s[j] == '0' && s[j + 1] == '1' && s[j + 2] == '2')
            return false;
    }
    return true;
}

int main()
{
    cin >> n;
    for (int j = 0; j < 4; ++j)
    {
        for (int k = 0; k < 4; ++k)
        {
            for (int t = 0; t < 4; ++t)
            {
                string s;
                s += (j + '0');
                s += (k + '0');
                s += (t + '0');
                if (stg(s))
                    dp[3][j][k][t] = 1;
            }
        }
    }
    for (int i = 3; i < n; ++i)
    {
        for (int j = 0; j < 4; ++j)
        {
            for (int k = 0; k < 4; ++k)
            {
                for (int t = 0; t < 4; ++t)
                {
                    for (int f = 0; f < 4; ++f)
                    {
                        string s;
                        s += (j + '0');
                        s += (k + '0');
                        s += (t + '0');
                        s += (f + '0');
                        if (stg(s))
                            dp[i + 1][k][t][f] = (dp[i + 1][k][t][f] + dp[i][j][k][t]) % M;
                    }
                }
            }
        }
    }
    int ans = 0;
    for (int j = 0; j < 4; ++j)
        for (int k = 0; k < 4; ++k)
            for (int t = 0; t < 4; ++t)
                ans = (ans + dp[n][j][k][t]) % M;
    cout << ans << endl;
    return 0;
}

