		digit_dp[i][0][0][1] -= digit_dp[i - 1][0][2][0] + digit_dp[i - 1][1][2][0];//GAC
		for (int j = 0; j < 2; ++j){
			for (int k = 0; k < 4; ++k){
				for (int l = 0; l < 4; ++l) digit_dp[i][j][k][l] %= MOD;
