    dp[0][0][0][0] = 1;

    // dpテーブルを埋める
    for(int i = 0; i < n; ++i){
        // (i+1)桁目をTにする
        for(int j = 0; j < 4; ++j){
            for(int k = 0; k < 4; ++k){
                for(int l = 0; l < 4; ++l){
                    dp[i+1][0][j][k] = (dp[i+1][0][j][k] + dp[i][j][k][l]) % mod;
                }
            }
        }

        // (i+1)桁目をCにする(Cを入れられないのは、直前の並びが(AG, GA, AxG, AGx)のとき)
        for(int j = 0; j < 4; ++j){
