        for(int j = 0; j < 4; ++j){
            for(int k = 0; k < 4; ++k){
                if(j == 1 && k == 3)    continue;
                for(int l = 0; l < 4; ++l){
                    dp[i+1][2][j][k] = (dp[i+1][2][j][k] + dp[i][j][k][l]) % mod;
                }
            }
        }

        // (i+1)桁目をAにする
        for(int j = 0; j < 4; ++j){
            for(int k = 0; k < 4; ++k){
                for(int l = 0; l < 4; ++l){
                    dp[i+1][3][j][k] = (dp[i+1][3][j][k] + dp[i][j][k][l]) % mod;
