ll mod = 1e9 + 7LL;

void solve(ll dp[101][85][85][85], const V<char> &chars, const set<string> &ngs,
           ll previdx)
{
    ll idx = previdx + 1LL;

    for (auto pppc : chars) {
        for (auto ppc : chars) {
            for (auto pc : chars) {
                for (auto nowc : chars) {
                    string nows;
                    nows = ""; nows += ppc; nows += pc; nows += nowc;
                    if (ngs.find(nows) != ngs.end()) continue;

                    nows = ""; nows += pppc; nows += pc; nows += nowc;
                    if (nows == "AGC") continue;

                    nows = ""; nows += pppc; nows += ppc; nows += nowc;
                    if (nows == "AGC") continue;

                    debug_printf("previdx=%lld ppc=%c pc=%c nowc=%c\n",
                                 previdx, ppc, pc, nowc);

                    dp[idx][ppc][pc][nowc] += dp[previdx][pppc][ppc][pc];
                    dp[idx][ppc][pc][nowc] %= mod;
                }
            }
        }
    }
}

