{
    ll n; llin(n);

    V<char> chars;
    chars.pb('A'); chars.pb('C'); chars.pb('G'); chars.pb('T');

    set<string> ngs;
    ngs.insert("AGC"); ngs.insert("ACG"); ngs.insert("GAC");

    static ll dp[101][85][85][85];
    memset(dp, 0, sizeof(dp));
    for (auto a : chars) for (auto b : chars) for (auto c : chars) {
        string s; s += a; s += b; s += c;
        if (ngs.find(s) != ngs.end()) continue;
