                        if(j == 1 && l == 2 && m == 3) continue; // A*GC
                        if(k == 1 && l == 2 && m == 3) continue; // *AGC
                        if(k == 1 && l == 3 && m == 2) continue; // *ACG
                        if(k == 2 && l == 1 && m == 3) continue; // *GAC
                        dp[i+1][k][l][m] += dp[i][j][k][l];
                        dp[i+1][k][l][m] %= mod;
                    }
                }
            }
        }
    }
    ll ans = 0;
    rep(i, 1, 5){
        rep(j, 1, 5){
            rep(k, 1, 5) {
                ans += dp[n][i][j][k];
                ans %= mod;
            }
        }
    }
    cout << ans << endl;
    return 0;
}

