using vi = vector<long long>;
using vvi = vector<vi>;
using vvvi = vector<vvi>;
using vvvvi = vector<vvvi>;

int main() {
  const int MOD = 1000000007;
  int N; cin >> N;
  // dp[len][i][j][k] := 条件を満たし、末尾が ijk である長さ len の文字列の総数
  vvvvi dp(N+1, vvvi(4, vvi(4, vi(4, 0))));
  // A -> 0, G -> 1, C -> 2, T -> 3
  dp.at(0).at(3).at(3).at(3) = 1;  // 初期状態 TTT としておく
  for (int len = 0; len < N; len++) {
    for (int i = 0; i < 4; i++) {
      for (int j = 0; j < 4; j++) {
        for (int k = 0; k < 4; k++) {
          if (dp.at(len).at(i).at(j).at(k) == 0) continue;
          // 末尾に 0, 1, 2, 3 を追加
          for (int s = 0; s < 4; s++) {
            if (j == 0 && k == 2 && s == 1) continue;  // ACG
            if (j == 0 && k == 1 && s == 2) continue;  // AGC
            if (j == 1 && k == 0 && s == 2) continue;  // GAC
            if (i == 0 && j == 1 && s == 2) continue;  // AG?C
            if (i == 0 && k == 1 && s == 2) continue;  // A?GC
            dp.at(len+1).at(j).at(k).at(s) += dp.at(len).at(i).at(j).at(k);
            dp.at(len+1).at(j).at(k).at(s) %= MOD;
          }
        }
      }
    }
  }
  long long ans = 0;
  for (int i = 0; i < 4; i++) {
    for (int j = 0; j < 4; j++) {
      for (int k = 0; k < 4; k++) {
        ans += dp.at(N).at(i).at(j).at(k);
        ans %= MOD;
      }
    }
  }
  cout << ans << endl;
}

