char chars[4] = {'A', 'C', 'G', 'T'};

int encode(string s) {
    int res = 0;
    int digit = 1;
    rep(i, 3) {
        int x;
        if (s[i] == 'A') x = 0;
        else if (s[i] == 'C') x = 1;
        else if (s[i] == 'G') x = 2;
        else x = 3;
        res += digit * x;
        digit *= 4;
    }
    return res;
}

string decode(int index) {
    string res;
    int digit = 3;
    while (digit--) {
        int i = index % 4;
        res.push_back(chars[i]);
        index /= 4;
    }
    // cout << res << endl;
    return res;
}

