ll memo[105][5][5][5];  // 0: " ", 1: "A", 2: "C", 3: "G", 4: "T"

bool agc(int cur, vector<int>& last) {
  int l = sz(last);
  if (last[l - 2] == 1 && last[l - 1] == 2 && cur == 3) return false;
  if (last[l - 2] == 1 && last[l - 1] == 3 && cur == 2) return false;
  if (last[l - 2] == 2 && last[l - 1] == 1 && cur == 3) return false;

  if (l == 3) return true;
  if (cur != 3) return true;
  if (last[l - 3] == 1 && (last[l - 1] == 2 || last[l - 2] == 2)) return false;
  return true;
}

ll dfs(int n, vector<int>& last) {
  int l = sz(last);
  if (memo[n][last[l - 3]][last[l - 2]][last[l - 1]] >= 0)
    return memo[n][last[l - 3]][last[l - 2]][last[l - 1]];
  if (!n) return 1;

  ll ret = 0;
  rep(i, 1, 5) {
    if (!agc(i, last)) continue;
    last.pb(i);
    ret += dfs(n - 1, last);
    last.pop_back();
  }

  return memo[n][last[l - 3]][last[l - 2]][last[l - 1]] = ret % MOD;
};

int main(int argc, char* argv[]) {
  long long N;
  scanf("%lld", &N);
  Fill(memo, ll(-1));

  vector<int> last{0, 0, 0};
  ll ans = dfs(N, last);
  put(ans);
  return 0;
}

