int N;
bool isOK(string S){
	string AGC = "AGC";
	if(search(S.begin(), S.end(), AGC.begin(), AGC.end()) != S.end()) return false;
	swap(S[0],S[1]);
	if(search(S.begin(), S.end(), AGC.begin(), AGC.end()) != S.end()) return false;
	swap(S[0],S[1]);
	swap(S[1],S[2]);
	if(search(S.begin(), S.end(), AGC.begin(), AGC.end()) != S.end()) return false;
	swap(S[1],S[2]);
	swap(S[2],S[3]);
	if(search(S.begin(), S.end(), AGC.begin(), AGC.end()) != S.end()) return false;
	return true;
}
map<pair<int,string>, LL> dp;
LL solve(int now, string mae){
	if(now == N) return 1;
	if(dp.count(MP(now,mae)) == 1) return dp[MP(now,mae)];
	LL ans = 0;
	if(isOK(mae+"A")) ans += solve(now+1, mae.substr(1,2)+"A");
	if(isOK(mae+"G")) ans += solve(now+1, mae.substr(1,2)+"G");
	if(isOK(mae+"C")) ans += solve(now+1, mae.substr(1,2)+"C");
	if(isOK(mae+"T")) ans += solve(now+1, mae.substr(1,2)+"T");
	return dp[MP(now,mae)] = ans % MOD;
}

