ll dp[110][4][4][4];

ll rec(int n, int i, int j, int k){
    if(dp[n][i][j][k] != -1) return dp[n][i][j][k];
    if(n == 3){
        if(k == 0 && j == 1 && i == 2) return dp[n][i][j][k] = 0;
        if(k == 1 && j == 0 && i == 2) return dp[n][i][j][k] = 0;
        if(k == 0 && j == 2 && i == 1) return dp[n][i][j][k] = 0;
        return dp[n][i][j][k] = 1;
    }

    ll SUM = 0;
    rep(l, 0, 4){
        if(k == 0 && j == 1 && i == 2) continue;
        if(k == 1 && j == 0 && i == 2) continue;
        if(k == 0 && j == 2 && i == 1) continue;
        if(l == 0 && j == 1 && i == 2) continue;
        if(l == 0 && k == 1 && i == 2) continue;
        SUM += rec(n-1, j, k, l);
        SUM %= MOD;
    }
    //cerr << SUM << endl;

    return dp[n][i][j][k] = SUM;
}

