    map<char, int> mp = {ci('T', 0), ci{'A', 1}, ci{'C', 2}, ci{'G', 3}};
    vector<int> masks(5), forbidden_nums(5);
    const int l6 = (1 << 6) - 1;
    rep(i, 5) {
        int m = 0;
        rep(j, 4) {
            m <<= 2;
            if (forbidden_strs.at(i).at(j) != '?') m |= 3;
        }
        masks.at(i) = m;
    }
    rep(i, 5) {
        int num = 0;
        rep(j, 4) {
            num <<= 2;
            if (forbidden_strs.at(i).at(j) != '?') num |= mp[forbidden_strs.at(i).at(j)];
        }
        forbidden_nums.at(i) = num;
    }

    auto is_ok = [&](int num){
        rep(i, 5) if ((num & masks.at(i)) == forbidden_nums.at(i)) return false;
        return true;
    };

    //dp[i][j] 条件を満たすi番目の末尾6文字がj
    vector<vector<ModInt>> dp(n + 1, vector<ModInt>(1 << 6));
    dp[0][0] = 1;
    rep(i, n) rep(j, 1 << 6) rep(c, 4) {
        int num = j << 2 | c;
        if (is_ok(num)) dp[i + 1][num & l6] += dp[i][j];
    }

    ModInt ans = 0;
    rep(i, 1 << 6) ans += dp[n][i];
    cout << ans << endl;
}

