typedef long long ll;

const ll MOD = 1e9 + 7;
const int N = (1e2) + 5;
int memo[N][4][4][4];

int DP(int n, int c, int b, int a) {
  if (n == 3) return 1;
  int& ret = memo[n][c][b][a];
  if (ret != -1) return ret;
  ret = 0;
  for (int i = 0; i < 4; ++i) {
    if (i == 0 and c == 1 and b == 2 and a == 1) continue;
    if (i == 0 and c == 2 and b == 2 and a == 1) continue;
    if (i == 0 and c == 3 and b == 2 and a == 1) continue;
    if (i == 0 and c == 2 and b == 0 and a == 1) continue;
    if (i == 0 and c == 2 and b == 2 and a == 1) continue;
    if (i == 0 and c == 2 and b == 3 and a == 1) continue;
    if (i == 0 and c == 2 and b == 1) continue;
    if (i == 0 and c == 1 and b == 2) continue;
    if (i == 2 and c == 0 and b == 1) continue;
    ret += DP(n - 1, i, c, b);
    ret %= MOD;
  }
  return ret;
}

