      for (int k = 0; k < 4; ++k) {
        if (i == 0 and j == 2 and k == 1) continue;
        if (i == 0 and j == 1 and k == 2) continue;
        if (i == 2 and j == 0 and k == 1) continue;
        ans += DP(n, i, j, k);
        ans %= MOD;
      }
    }
  }
  printf("%d\n", ans);
  return 0;
}

