using namespace std;

bool check(string &s) {
  if (s.find("AGC") != string::npos) {
    return false;
  }

  for (int i = 1; i < s.size(); ++i) {
    swap(s[i], s[i - 1]);
    if (s.find("AGC") != string::npos) {
      return false;
    }
    swap(s[i], s[i - 1]);
  }

  return true;
}

const int md = 1e9 + 7;

int solve(string s, int n, map<pair<string, int>, int> &memo) {
  auto memo_key = make_pair(s, n);
  if (memo.count(memo_key) > 0) {
    return memo[memo_key];
  }

  if (!check(s)) {
    return 0;
  }

  if (n == 0) {
    return 1;
  }

  vector<char> next_chs{'A', 'C', 'G', 'T'};
  int ans = 0;
  for (auto next_ch : next_chs) {
    string s2;
    if (s.size() > 3) {
      copy(s.begin() + s.size() - 3, s.end(), back_inserter(s2));
    } else {
      copy(s.begin(), s.end(), back_inserter(s2));
    }

    s2 += next_ch;
    ans = (ans + solve(s2, n - 1, memo)) % md;
  }

  return memo[memo_key] = ans % md;
}

int main(int argc, const char *argv[]) {
  int n;
  cin >> n;

  map<pair<string, int>, int> memo;
  int ans = solve("", n, memo);
  cout << ans << '\n';

  return 0;
}

