int dp[101][4][4][4]; //[現文字数][最後から1文字目][2文字目][3文字目]


int main() {
    int N;
    cin >> N;

    //A=0, G=1, C=2, T=3
    //長さ0の文字列をカウントしてスタート。必ず条件を満たす3文字(ここではTTT)が
    //先頭にあると仮定することで、長さ0の文字列の状態を1つ作る
    dp[0][3][3][3] = 1;

    //AGCTのいずれかを末尾に加えた場合のdpを求めていく
    for(int len=0; len<N; len++) {

        //現在の最後から1文字目
        for(int i=0; i<4; i++) {

            //現在の最後から2文字目
            for(int j=0; j<4; j++) {

                //現在の最後から3文字目
                for(int k=0; k<4; k++) {

                    //現在の最後から3文字を見たとき、条件を満たす文字列が存在しない場合、無視する
                    if(dp[len][i][j][k] == 0) continue;

                    //新しく末尾に追加する文字
                    for(int a=0; a<4; a++) {

                        if(a==2 && i==1 && j==0) continue; //AGC
                        if(a==2 && i==0 && j==1) continue; //GAC
                        if(a==1 && i==2 && j==0) continue; //ACG
                        if(a==2 && i==1 && k==0) continue; //A?GC
                        if(a==2 && j==1 && k==0) continue; //AG?C

                        dp[len+1][a][i][j] += dp[len][i][j][k];
                        dp[len+1][a][i][j] %= MOD;
                    }
                }
            }
        }
    }
    int ans = 0;
    for(int i=0; i<4; i++) {
        for(int j=0; j<4; j++) {
            for(int k=0; k<4; k++) {
                ans += dp[N][i][j][k];
                ans %= MOD;
            }
        }
    }
    cout << ans << endl;

    return 0;
}

