const int C = 1;
const int G = 2;
const int T = 3;

ll cache[100][4][4][4];

/**
 * AGC
 * GAC
 * ACG
 * A?GC
 * AG?C
 */
ll calc(int remain, int c1, int c2, int c3) {
    if (remain == 0) {
        return 1;
    }
    if (cache[remain][c1][c2][c3] > 0) {
        return cache[remain][c1][c2][c3];
    }

    //CG それぞれ利用可能なときtrue
    bool fc, fg;
    fc = fg = true;
    if (c2 == A && c3 == G || c2 == G && c3 == A) {
        fc = false;
    } else if (c2 == A && c3 == C) {
        fg = false;
    } else if (c1 == A && c3 == G || c1 == A && c2 == G) {
        fc = false;
    }
    ll ret = 0;
    ret = (ret + calc(remain - 1, c2, c3, A)) % MOD;
    if (fc) {
        ret = (ret + calc(remain - 1, c2, c3, C)) % MOD;
    }
    if (fg) {
        ret = (ret + calc(remain - 1, c2, c3, G)) % MOD;
    }
    ret = (ret + calc(remain - 1, c2, c3, T)) % MOD;
    cache[remain][c1][c2][c3] = ret;
    return ret;
}

int main()
{
    int N;
    cin >> N;
    int ans = calc(N, T, T, T);
    cout << ans << endl;
    return 0;
}

