int pwr(int a, ll p) {
    if (p == 0) return 1;
    if (p & 1) return mul(a, pwr(a, p - 1));
    return pwr(mul(a, a), p / 2);
}
int inv(int a) { return pwr(a, mod - 2); }

int dp[100][5][5][5], n;

bool test(int* v)
{
    int bad[4] = {0, 2, 1};
    for (int i = 0; i < 2; ++i)
    {
        int cnt = 0;
        for (int j = 0; j < 3; ++j)
            if (v[i + j] == bad[j])
                cnt++;
        if (cnt == 3)
            return true;
    }
    return false;
}

int f(int k, int a, int b, int c)
{
    if (k == n) return 1;
    if (dp[k][a][b][c] != -1) return dp[k][a][b][c];
    int sol = 0;
    for (int i = 0; i < 4; ++i)
    {
        int v[4] = {a, b, c, i};
        bool bad = test(v);
        for (int i = 0; i < 3; ++i)
        {
            swap(v[i], v[i + 1]);
            if (test(v))
                bad = true;
            swap(v[i], v[i + 1]);
        }
        if (!bad)
            adds(sol, f(k + 1, b, c, i));
    }
    return dp[k][a][b][c] = sol;
}

