void solve()
{
	using A3 = array<char, 3>;

	READ(int, N);

	const char A = 'a', G = 'g', C = 'c', T = 't';
	const char AGCT[] = { A,G,C,T };

	struct Node
	{
		A3 a;
		bool operator <(const Node& o) const { return a < o.a; }
	};
	map<Node, llong> dp;

	REP(i, 4) REP(j, 4) REP(k, 4)
	{
		A3 a = { AGCT[i], AGCT[j], AGCT[k] };
		if (a == A3{ A,G,C }) continue;
		if (a == A3{ A,C,G }) continue;
		if (a == A3{ G,A,C }) continue;
		dp[{a}] = 1;
	}
	REP(i, N - 3)
	{
		map<Node, llong> next;
		FORE(kv : dp) REP(i, 4)
		{
			char c = AGCT[i];
			const A3 &from = kv.first.a;
			A3 a = { from[1], from[2], c };
			if (a == A3{ A,G,C }) continue;
			if (a == A3{ A,C,G }) continue;
			if (a == A3{ G,A,C }) continue;
			if (from[0] == A && from[1] == G && c == C) continue;
			if (from[0] == A && from[2] == G && c == C) continue;

			next[{a}] = (next[{a}] + kv.second) % 1000000007;
		}
		dp.swap(next);
	}

	llong ans = 0;
	FORE(kv: dp)
	{
		ans = (ans + kv.second) % 1000000007;
	}

	WRITE(ans);

}

