template <ll MOD>
class mod_int {
   public:
    ll val;
    constexpr mod_int(const ll x = 0) noexcept : val(x % MOD) {}
    constexpr ll &value() noexcept { return val; }
    constexpr const ll &value() const noexcept { return val; }
    constexpr mod_int operator+(const mod_int r) const noexcept { return mod_int(*this) += r; }
    constexpr mod_int operator-(const mod_int r) const noexcept { return mod_int(*this) -= r; }
    constexpr mod_int operator*(const mod_int r) const noexcept { return mod_int(*this) *= r; }
    constexpr mod_int operator/(const mod_int r) const noexcept { return mod_int(*this) /= r; }
    constexpr mod_int &operator+=(const mod_int r) noexcept {
        val += r.val;
        if (val >= MOD) {
            val -= MOD;
        }
        return *this;
    }
    constexpr mod_int &operator-=(const mod_int r) noexcept {
        if (val < r.val) {
            val += MOD;
        }
        val -= r.val;
        return *this;
    }
    constexpr mod_int &operator*=(const mod_int r) noexcept {
        val = val * r.val % MOD;
        return *this;
    }
    constexpr mod_int &operator/=(mod_int r) noexcept {
        ll exp = MOD - 2;
        while (exp) {
            if (exp % 2) {
                *this *= r;
            }
            r *= r;
            exp /= 2;
        }
        return *this;
    }
};
