		{
			curr_res[str] = 0;
		}
		else
		{
			curr_res[str] = 1;
		}
	}

	auto cond = [](const auto& str)
	{
		return (str[0] == 'A' && str[2] == 'G' && str[3] == 'C') ||
			(str[1] == 'A' && str[2] == 'G' && str[3] == 'C') ||
			(str[1] == 'G' && str[2] == 'A' && str[3] == 'C') ||
			(str[1] == 'A' && str[2] == 'C' && str[3] == 'G') ||
			(str[0] == 'A' && str[1] == 'G' && str[3] == 'C');
	};
	for (ll i = 4; i <= N; ++i)
	{
		prev_res = curr_res;
		for (ll j = 0; j < 64; ++j)
		{
			string str;
			str += cands[j % 4];
			str += cands[(j / 4) % 4];
			str += cands[(j / 16) % 4];
			curr_res[str] = 0;
		}
		for (ll j = 0; j < cands.size(); ++j)
