			for (auto iter = prev_res.begin(); iter != prev_res.end(); ++iter)
			{
				auto str = iter->first + cands[j];
				if (!cond(str))
				{
					curr_res[str.substr(1, 3)] += prev_res[iter->first];
				}
			}
		}
