  In(N);

  map<char, int64_t> c_to_i;
  c_to_i[' '] = 0;
  c_to_i['A'] = 1;
  c_to_i['G'] = 2;
  c_to_i['C'] = 3;
  c_to_i['T'] = 4;

  auto dp = MakeNdVector(N + 1, 5, 5, 5, Mi(0));

  dp[0][0][0][0] = 1;

  rep(n, N) {
    rep(i, 5) {           // 3文字前
      rep(j, 5) {         // 2文字前
        rep(k, 5) {       // 1文字前
          rep(l, 1, 5) {  // 次の文字

            if (i == c_to_i['A'] && j == c_to_i['G'] &&
                l == c_to_i['C']) {  // AG*C
              continue;
            }
            if (i == c_to_i['A'] && k == c_to_i['G'] &&
                l == c_to_i['C']) {  // AG*C
              continue;
            }
            if (j == c_to_i['A'] && k == c_to_i['G'] &&
                l == c_to_i['C']) {  // *AGC
              continue;
            }
            if (j == c_to_i['G'] && k == c_to_i['A'] &&
                l == c_to_i['C']) {  // *GAC
              continue;
            }
            if (j == c_to_i['A'] && k == c_to_i['C'] &&
                l == c_to_i['G']) {  // *ACG
              continue;
            }

            dp[n + 1][j][k][l] += dp[n][i][j][k];
          }
        }
      }
    }
  }
  Mi ans = 0;
  rep(i, 1, 5) {
    rep(j, 1, 5) {
      rep(k, 1, 5) { ans += dp[N][i][j][k]; }
    }
  }

  cout << ans << endl;

  return EXIT_SUCCESS;
