const int MOD = 1e9 + 7;

ll repeatSquaring(ll n, ll p)
{
  if (p == 0)
    return 1;
  if (p % 2 == 0)
  {
    ll t = repeatSquaring(n, p / 2);
    return (t * t) % MOD;
  }
  return (n * repeatSquaring(n, p - 1)) % MOD;
}

int main()
{
  ll n;
  cin >> n;

  ll ans = repeatSquaring(4, n);
  ll res = 0;
  ll num[110] = {};
  num[3] = 3;
  for (ll i = 4; i <= 105; ++i)
  {
    num[i] = (3 * ((i - 3 + 1) * (repeatSquaring(4, i - 3) - num[i - 3] + MOD) % MOD) % MOD) % MOD;
    num[i] = (num[i] + (2 * ((i - 4 + 1) * (repeatSquaring(4, i - 4) - num[i - 4] + MOD) % MOD) % MOD) % MOD) % MOD;
  }
  res = num[n];
  ans -= res;
  if (ans < 0)
    ans += MOD;
  cout << ans << endl;

  return 0;
}

