constexpr LL mod = 1e9 + 7;

int main() {

    int N;
    cin >> N;

    vector<vector<vector<vector<LL>>>>
            dp(N + 1,
               vector<vector<vector<LL>>>(4,
                                          vector<vector<LL>>(4,
                                                             vector<LL>(4, 0))));

    dp[0][3][3][3] = 1;

    for (int i = 0; i < N; i++) {
        for (int c1 = 0; c1 < 4; c1++) {
            for (int c2 = 0; c2 < 4; c2++) {
                for (int c3 = 0; c3 < 4; c3++) {
                    if (dp[i][c1][c2][c3] == 0) continue;
                    for (int a = 0; a < 4; a++) {
                        if (c1 == 0 && c2 == 1 && c3 == 2) continue;
                        if (c1 == 0 && c2 == 2 && c3 == 1) continue;
                        if (c1 == 1 && c2 == 0 && c3 == 2) continue;
                        if (c2 == 0 && c3 == 1 && a == 2) continue;
                        if (c2 == 0 && c3 == 2 && a == 1) continue;
                        if (c2 == 1 && c3 == 0 && a == 2) continue;
                        if (c1 == 0 && c2 == 1 && a == 2) continue;
                        if (c1 == 0 && c3 == 1 && a == 2) continue;
                        dp[i + 1][c2][c3][a] += dp[i][c1][c2][c3];
                        dp[i + 1][c2][c3][a] %= mod;
                    }
                }
            }
        }
    }

    LL ans = 0;
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            for (int k = 0; k < 4; k++) {
                ans += dp[N][i][j][k];
                ans %= mod;
            }
        }
    }


    cout << ans;

    return 0;
}

