bool good(int p,int q,int r,int s) {
    if(q == 0 && r == 2 && s == 3) return false;
    if(q == 0 && r == 3 && s == 2) return false;
    if(q == 2 && r == 0 && s == 3) return false;
    if(p == 0 && r == 2 && s == 3) return false;
    if(p == 0 && q == 2 && s == 3) return false;
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int N;
    cin >> N;
    ll ans = 0;
    for(int a = 0;a < 4;a++) {
        for(int b = 0;b < 4;b++) {
            for(int c = 0;c < 4;c++) {
                dp[3][a][b][c] = good(-1, a, b, c);
                if(N == 3) ans += dp[3][a][b][c];
            }
        }
    }
    for(int i = 4;i <= N;i++) {
        for(int a = 0;a < 4;a++) {
            for(int b = 0;b < 4;b++) {
                for(int c = 0;c < 4;c++) {
                    ll &cur = dp[i][a][b][c];
                    cur = 0;
                    for(int d = 0;d < 4;d++) {
                        if(good(d, a, b, c))
                            cur += dp[i - 1][d][a][b];
                    }
                    cur %= MOD;
                    if(i == N) ans += cur;
                }
            }
        }
    }
    cout << ans % MOD << endl;
    return 0;
}

