int DP[101][4][4][4];


int main() {
	int N;
	cin >> N;

	DP[0][1][1][1] = 1;

	int mod = 1000000007;

	//文字列の文字数
	for (int len = 0; len < N; len++)
	{
		//len -1文字目
		for (int i = 0; i < 4; i++)
		{
			//len-2文字目
			for (int j = 0; j < 4; j++)
			{
				//len-3文字目
				for (int k = 0; k < 4; k++)
				{
					if (DP[len][i][j][k] == 0) continue;

					//新しく追加する文字(len文字目)
					for (int l = 0; l < 4; l++) {
						if (l == 3 && i == 2 && j == 0) continue;
						if (l == 3 && i == 0 && j == 2) continue;
						if (l == 2 && i == 3 && j == 0) continue;
						if (l == 3 && i == 2 && k == 0) continue;
						if (l == 3 && j == 2 && k == 0) continue;

						DP[len + 1][l][i][j] += DP[len][i][j][k];
						DP[len + 1][l][i][j] %= mod;
					}
				}
			}
		}
	}
	long long ans = 0;
	//i-1文字目
	for (int i = 0; i < 4; i++)
	{
		//i-2文字目
		for (int j = 0; j < 4; j++)
		{
			//i-3文字目
			for (int k = 0; k < 4; k++)
			{
				ans += DP[N][i][j][k];
			}
		}
	}
	ans %= mod;

	cout << ans << endl;
}

