ll Tx(int n) { // nは残りの長さ
	if (n == 1) {
		return 4;
	}
	if (tdp[n] != 0) {
		return tdp[n];
	}
	tdp[n] = (Ax(n - 1) + Cx(n - 1) + Gx(n - 1) + Tx(n - 1)) % mod;
	return (Ax(n - 1) + Cx(n - 1) + Gx(n - 1) + Tx(n - 1)) % mod;
}
