std::vector<std::map<std::string, ull>> dp;
const std::vector<char> ACGT{'A', 'C', 'G', 'T'};
constexpr ull INF = 1000'000'007;

ull recursion(ui n, std::string str)
{
  assert(str.size() == 3);

  if(dp[n].count(str))
    return dp[n][str];

  if(!n)
    return 1;

  auto judge = [](std::string str){
    assert(str.size() == 4);
    if(str.find("AGC") != str.npos
    || str.find("GAC") != str.npos
    || str.find("ACG") != str.npos)
    {
      return false;
    }
    if(str[0] == 'A'
    && str[3] == 'C')
    {
      if(str[1] == 'G'
      || str[2] == 'G')
        return false;
    }
    return true;
  };

  ull res{};
  for(char c : ACGT)
  {
    std::string s = str + c;
    if(judge(s))
    {
      res = (res + recursion(n - 1, s.substr(1, 3))) % INF;
    }
  }
  dp[n][str] = res;
  return res;
}

