const int mod = 1'000'000'007;

int main() {

	int N;
	cin >> N;

	// 0:A, 1:G, 2:C, 3:T
	int dp[105][4][4][4];

	dp[0][3][3][3] = 1;

	for (int n = 0; n < N; n++) {

		//最後から1文字目の文字
		for (int c1 = 0; c1 < 4; c1++) {

			//最後から2文字目の文字
			for (int c2 = 0; c2 < 4; c2++) {

				//最後から3文字目の文字
				for (int c3 = 0; c3 < 4; c3++) {

					if (dp[n][c1][c2][c3] == 0) continue;
					//最後に追加する文字
					for (int a = 0; a < 4; a++) {
						if (a == 2 && c1 == 1 && c2 == 0) continue;
						if (a == 2 && c1 == 0 && c2 == 1) continue;
						if (a == 1 && c1 == 2 && c2 == 0) continue;
						if (a == 2 && c1 == 1 && c3 == 0) continue;
						if (a == 2 && c2 == 1 && c3 == 0) continue;

						dp[n + 1][a][c1][c2] += dp[n][c1][c2][c3];
						dp[n + 1][a][c1][c2] %= mod;

					}

				}
			}
		}
	}

	int ans = 0;

	for (int c1 = 0; c1 < 4; c1++) {

		//最後から2文字目の文字
		for (int c2 = 0; c2 < 4; c2++) {

			//最後から3文字目の文字
			for (int c3 = 0; c3 < 4; c3++) {

				ans += dp[N][c1][c2][c3];
				ans %= mod;

			}
		}
	}

	cout << ans << endl;

	return 0;

}

