int num(char S) {

	if (S == 'A') {
		return 1;
	}
	else if (S == 'C') {
		return 2;
	}
	else if (S == 'G') {
		return 3;
	}
	else if (S == 'T') {
		return 4;
	}
	return INF;
}
int index(string S) {
	int mul = 5;
	int len = S.size();
	int ans = 0;
	for (int i =0;i<len;++i){
		int ter = num(S[i]);
		ans = ans * mul + ter;
	}
	return ans;
}
void solve() {
	int N;
	cin >> N;

	map<int, int> NG;
	vector<pair<string, string>> NGList;
	NGList.push_back(pair<string, string>("AG", "C"));
	NGList.push_back(pair<string, string>("GA", "C"));
	NGList.push_back(pair<string, string>("AC", "G"));

	NGList.push_back(pair<string, string>("AAG","C"));
	NGList.push_back(pair<string, string>("CAG", "C"));
	NGList.push_back(pair<string, string>("GAG", "C"));
	NGList.push_back(pair<string, string>("TAG", "C"));

	NGList.push_back(pair<string, string>("AGA", "C"));
	NGList.push_back(pair<string, string>("CGA", "C"));
	NGList.push_back(pair<string, string>("GGA", "C"));
	NGList.push_back(pair<string, string>("TGA", "C"));

	NGList.push_back(pair<string, string>("AAC", "G"));
	NGList.push_back(pair<string, string>("CAC", "G"));
	NGList.push_back(pair<string, string>("GAC", "G"));//こない
	NGList.push_back(pair<string, string>("TAC", "G"));

	NGList.push_back(pair<string, string>("AAG", "C"));
	NGList.push_back(pair<string, string>("ACG", "C"));//こないね
	NGList.push_back(pair<string, string>("AGG", "C"));
	NGList.push_back(pair<string, string>("ATG", "C"));

	NGList.push_back(pair<string, string>("AGA", "C"));
	NGList.push_back(pair<string, string>("AGG", "C"));
	NGList.push_back(pair<string, string>("AGC", "C"));
	NGList.push_back(pair<string, string>("AGT", "C"));

	vector<pair<string, string>>::iterator itr;
	for (itr = NGList.begin(); itr != NGList.end(); itr++) {
		pair<string, string> temp = *itr;
		NG[index(temp.first)] = index(temp.second);
	}
	vector<vector<LL>>dp(N + 1, vector<LL>(130,0));
	dp[0][0] = 1;
	string LOOP = "ACGT";
	int mul = 5;
	int mod = 125;
	for (int i = 0; i < N; ++i) {
		for (int k = 0; k <= index("TTT"); ++k) {
			if (dp[i][k] == 0)continue;
			for (int j = 0; j < 4; ++j) {
				int ter = num(LOOP[j]);
				if (NG[k] == ter) {
					continue;
				}
				int next = (k*mul + ter) % mod;
				dp[i+1][next] += dp[i][k];
				dp[i + 1][next] %= MOD;
			}
		}
	}
	LL ans = 0;
	for (int k = 0; k < mod; ++k) {
		ans += dp[N][k];
		ans %= MOD;
	}
	cout << ans << endl;
}

