const int md = (1.0e+9) + 7;
vector<int> vec(101, -1);
vector<int> vecg(101, -1);

long long calc(int N);
long long calcg(int N);

long long calc(int N) {
	if (N < 0) return 0;
	if (vec[N] != -1) return vec[N];

	long long ans;
	ans = 4 * calc(N - 1) - 2 * calc(N - 3) - 3 * calc(N - 4) - calcg(N - 2) + calcg(N - 3);

	while (ans < 0) ans += md;
	ans %= md;
	vec[N] = ans;
	return ans;
}

long long calcg(int N) {
	if (N < 0) return 0;
	if (vecg[N] != -1) return vecg[N];

	long long ans;
	ans = calc(N - 1) - calc(N - 3) + calcg(N - 3);

	while (ans < 0) ans += md;
	ans %= md;
	vecg[N] = ans;
	return ans;
}

int main()
{
	int N;
	cin >> N;

	vec[0] = 1;
	vecg[0] = 0;

	cout << calc(N) << endl;
}

