long long dp[105][4][4][4] = {0};

long long solve();

int main() {
  cin >> n;
  cout << solve() << endl;
  return 0;
}

long long solve() {
  dp[0][1][1][1] = 1;
  for(int i = 0; i < n; ++i)
    for(int j = 0; j < 4; ++j)
      for(int k = 0; k < 4; ++k)
        for(int l = 0; l < 4; ++l) {
          // m l k j
          long long num = 0;
          if(l == 0 && k == 3 && j == 2) continue;
          if(l == 0 && k == 2 && j == 3) continue;
          if(l == 2 && k == 0 && j == 3) continue;
          for(int m = 0; m < 4; ++m) {
            if(m == 0 && k == 2 && j == 3) continue;
            if(m == 0 && l == 2 && j == 3) continue;
            num += dp[i][k][l][m];
            num %= N;
          }
          dp[i + 1][j][k][l] += num;
          dp[i + 1][j][k][l] %= N;
        }
  long long ans = 0;
  for(int i = 0; i < 4; ++i)
    for(int j = 0; j < 4; ++j)
      for(int k = 0; k < 4; ++k) {
        ans += dp[n][i][j][k];
        ans %= N;
      }
  return ans;
}

