int main() {
  ll n;
  cin >> n;
  ll MOD = 1e9+7;
  vl a(n),t(n),g(n),c(n);
  REP(i,n){
    if(i==0){
      a[i] = 1;
      t[i] = 1;
      g[i] = 1;
      c[i] = 1;
      continue;
    }
    if(i==1){
      a[i] = 4;
      t[i] = 4;
      g[i] = 4;
      c[i] = 4;
      continue;
    }
    a[i] = a[i-1] + t[i-1] + g[i-1] + c[i-1];
    t[i] = a[i-1] + t[i-1] + g[i-1] + c[i-1];
    g[i] = a[i-1] + t[i-1] + g[i-1] + c[i-1] - a[i-2];
    c[i] = a[i-1] + t[i-1] + g[i-1] + c[i-1] - a[i-2] -g[i-2];
    if(i==2) continue;
    c[i] -= 3*a[i-3];
    g[i] += g[i-3];
    a[i] += MOD;
    t[i] += MOD;
    g[i] += MOD;
    c[i] += MOD;
    a[i] %= MOD;
    t[i] %= MOD;
    g[i] %= MOD;
    c[i] %= MOD;
  }
  ll ans = a[n-1]+t[n-1]+g[n-1]+c[n-1];
  ans %= MOD;
  cout << ans  << endl;
  return 0;
}

