#include <bits/stdc++.h>
#include <algorithm>
using namespace std;
typedef long long ll;
const ll MOD = pow(10,9) + 7;
ll memo[100][64];



bool cont_AGC(string t)
{
  if(t[0]=='A'&&t[1]=='G'&&t[2]=='C') return true;
  if(t[1]=='A') return t[2]=='G'&&t[3]=='C';
  return false;
}

bool ok(string last4)
{
  for(int i=0; i<4; i++)
  {
    string t = last4;
    if(i>0){
      t[3-i] = last4[4-i];
      t[4-i] = last4[3-i];
    }
    if(cont_AGC(t)) return false;
  }
  return true;
}

int para(char t)
{
  switch (t) {
    case 'A':
      return 0;
      break;
    case 'T':
      return 1;
      break;
    case 'G':
      return 2;
      break;
    case 'C':
      return 3;
      break;
  }
  cout <<"t = "<< t << "Bad input on para()" << endl;
  return -1;
}

int dict(string S)
{
  int tmp = 0;
  for(int i=0; i<3; i++)
  {
    tmp += pow(4,i)*para(S[i]);
  }
  return tmp;
}

ll dfs(int n, int cur, string last3)
{
  if(cur == n) return 1;
  if(memo[cur][dict(last3)]!=-1) return memo[cur][dict(last3)];
  ll ret = 0;
  string s = "ATGC";
  for(int i=0; i<4; i++)
  {
    if(ok(last3+s[i])) ret = (ret + dfs(n,cur+1,last3.substr(1)+s[i])) % MOD;
  }
  memo[cur][dict(last3)] = ret;
  return ret;
}

int main()
{
  for(int i=0; i<100; i++)
  {
    for(int j=0; j<64; j++)
    {
      memo[i][j] = -1;
    }
  }
  int n;
  cin >> n;
  cout << dfs(n,0,"TTT") << endl;
  return 0;
}

