void solve()
{
    ll ans = 0;
    REP(i, 4){
        REP(j, 4){
            REP(k, 4){
                if(atgc[i] == 'a' && atgc[j] == 'g' && atgc[k] == 'c') continue;
                if(atgc[i] == 'a' && atgc[j] == 'c' && atgc[k] == 'g') continue;
                if(atgc[i] == 'g' && atgc[j] == 'a' && atgc[k] == 'c') continue;
                dp[3][i][j][k] = 1;
            }
        }
    }
    FOR(i, 4, N+1){
        REP(j, 4){
            REP(k, 4){
                REP(l, 4){
                    REP(m, 4){
                        if(atgc[m] == 'a' && atgc[k] == 'g' && atgc[l] == 'c') continue;
