                        if(atgc[m] == 'a' && atgc[j] == 'g' && atgc[l] == 'c') continue;
                        dp[i][j][k][l] += dp[i-1][m][j][k];
                        dp[i][j][k][l] %= MOD;
                    }
                }
            }
        }
    }
    REP(i, 4){
        REP(j, 4){
            REP(k, 4){
                ans += dp[N][i][j][k];
                ans %= MOD;
            }
        }
    }
    cout << ans << endl;
}

