            if (IsOk(last_three + c)) {
                val += f(f, idx + 1, last_three.substr(1, 2) + c);
                val %= mod;
            }
        }

        dp[idx][last_three] = val;
        return val;
    };

    std::cout << dfs(dfs, 0, "TTT") << std::endl;
}

