                            || (j == 1 && k == 3 && l == 2) || (j == 2 && k == 1 && l == 3)) {
                            continue;
                        }
                        dp[n + 1][j][k][l] += dp[n][i][j][k];
                    }
                }
            }
        }
    }
    modint ans = modint(0);
    FOR(i, 1, 5) {
        FOR(j, 1, 5) {
