        (ans += solve(i + 1, k, l, 'A')) %= MOD;
        (ans += solve(i + 1, k, l, 'T')) %= MOD;
        (ans += solve(i + 1, k, l, 'G')) %= MOD;
    } else if (k == 'A' && l == 'C') {
        (ans += solve(i + 1, k, l, 'A')) %= MOD;
        (ans += solve(i + 1, k, l, 'T')) %= MOD;
        (ans += solve(i + 1, k, l, 'C')) %= MOD;
    } else {
        (ans += solve(i + 1, k, l, 'A')) %= MOD;
        (ans += solve(i + 1, k, l, 'T')) %= MOD;
        (ans += solve(i + 1, k, l, 'C')) %= MOD;
        (ans += solve(i + 1, k, l, 'G')) %= MOD;
    }

    return memo[curr].second = ans;
}

