ll mod = 1e9 + 7LL;

bool is_agc(char *s)
{
    if (strcmp(s + 1, "AGC") == 0) return true;
    s[3] = 0;
    if (strcmp(s, "AGC") == 0) return true;
    return false;
}

bool ng(const char s[])
{
    char ls[5];
    memset(ls, 0, sizeof(ls));
    char tmp;

    memcpy(ls, s, 4);
    if (is_agc(ls)) return true;

    memcpy(ls, s, 4);
    tmp = ls[0]; ls[0] = ls[1]; ls[1] = tmp;
    if (is_agc(ls)) return true;

    memcpy(ls, s, 4);
    tmp = ls[1]; ls[1] = ls[2]; ls[2] = tmp;
    if (is_agc(ls)) return true;

    memcpy(ls, s, 4);
    tmp = ls[2]; ls[2] = ls[3]; ls[3] = tmp;
    if (is_agc(ls)) return true;

    return false;
}

void solve(ll dp[101][4][4][4], const M<int, char> &ic, ll previdx)
{
    ll idx = previdx + 1LL;

    rep (a, 4) {
        rep (b, 4) {
            rep (c, 4) {
                rep (d, 4) {

                    char nows[4];
                    nows[0] = ic.at(a); nows[1] = ic.at(b);
                    nows[2] = ic.at(c); nows[3] = ic.at(d);

                    if (ng(nows)) continue;

                    dp[idx][b][c][d] += dp[previdx][a][b][c];
                    dp[idx][b][c][d] %= mod;

                }
            }
        }
    }
}

int _main()
{
    ll n; llin(n);

    M<int, char> ic;
    ic[0] = 'A'; ic[1] = 'C'; ic[2] = 'G'; ic[3] = 'T';

    static ll dp[101][4][4][4];
    memset(dp, 0, sizeof(dp));
    rep (a, 4) rep (b, 4) rep (c, 4) {
        string s; s += ic[a]; s += ic[b]; s += ic[c];
        if (s == "AGC") continue;
        if (s == "ACG") continue;
        if (s == "GAC") continue;
        dp[3][a][b][c] = 1LL;
    }

    srep (i, 3LL, n) solve(dp, ic, i);

    ll ans = 0LL;
    rep (a, 4) rep (b, 4) rep (c, 4) {
        ans += dp[n][a][b][c];
