long modpow(long src, long pow, long mod)
{
    long res = 1;
    while (0 < pow) {
        if (pow % 2 == 1) {
            res = (res * src) % mod;
            pow--;
        }
        src = (src * src) % mod;
        pow /= 2;
    }
    return res;
}

long modinv(long src, long mod)
{
    return modpow(src, mod - 2, mod);
}

