int call(int mask, int i, int n)
{
    if(i==n) return 1;
    mask = mask%64;
    if(dp[mask][i]!=-1) return dp[mask][i];

    dp[mask][i] = 0;

    int vis[3];
    memset(vis,0,sizeof vis);
    if(mask%16==1 || mask%16==4 || (i>2 && (mask/16)%4==0 && (mask%4==1 || (mask/4)%4==1))) vis[2] = 1;
    if(mask%16==2) vis[1] = 1;
