            dp[mask][i] += call(mask*4 + c,i+1,n);
            if(dp[mask][i]>=M) dp[mask][i] -= M;
        }
    }
    dp[mask][i] += call(mask*4 + 3,i+1,n);
    if(dp[mask][i]>=M) dp[mask][i] -= M;
    return dp[mask][i];
}

