#define MOD 1000000007

using namespace std;

typedef long long ll;

bool isOk(string s)
{
    REP(i, s.size())
    {
        string swapS;
        REP(j, s.size())
        {
            if (j == i && j + 1 < s.size())
            {
                swapS += s[j + 1];
                swapS += s[j];
                j++;
            }
            else
            {
                swapS += s[j];
            }
        }
        REP(j, s.size() - 2)
        {
            string checkS = swapS.substr(j, 3);
            if (checkS == "AGC")
            {
                return false;
            }
        }
    }

    return true;
}

int main()
{
    ll N;
    cin >> N;
    vector<string> s = {"A", "C", "G", "T"};
    ll size = s.size();
    vector<string> last3vec;
    REP(i, size)
    {
        REP(j, size)
        {
            REP(k, size)
            {
                string t;
                t = s[i] + s[j] + s[k];
                if (t != "AGC" && t != "ACG" && t != "GAC")
                {
                    last3vec.push_back(t);
                }
            }
        }
    }

    map<string, ll> dp[N + 1];
    for (ll i = 3; i <= N; ++i)
    {
        REPV(it, last3vec)
        {
            if (i == 3)
            {               
                dp[i][*it] = 1;
            }
            else
            {
                dp[i][*it] = 0;
            }
        }
    }

    for (ll i = 4; i <= N; ++i)
    {
        REPV(it, last3vec)
        {
            REP(j, size)
            {
                string last4 = *it + s[j];
                if (isOk(last4))
                {
                    dp[i][last4.substr(1, 3)] += dp[i - 1][*it];
                    dp[i][last4.substr(1, 3)] = dp[i][last4.substr(1, 3)] % MOD;
                }
            }
        }
    }

    ll ans = 0;
    REPV(it, last3vec)
    {
        ans += dp[N][*it];
        ans = ans % MOD;
    }

    cout << ans << endl;
}

