bool is_allowed(vector<int> vs) {
    assert(vs.size() == 4);
    auto check = [&]() {
        if (vs[0] == 0 && vs[1] == 1 && vs[2] == 2) {
            return false;
        }
        if (vs[1] == 0 && vs[2] == 1 && vs[3] == 2) {
            return false;
        }
        return true;
    };
    if (!check()) {
        return false;
    }
    for (int i = 0; i < 3; ++i) {
        swap(vs[i], vs[i+1]);
        if (!check()) {
            return false;
        }
        swap(vs[i], vs[i+1]);
    }
    return true;
}

vector<vector<int>> all_allowed() {
    vector<vector<int>> all;
    for (int a = 0; a < 4; ++a) {
        for (int b = 0; b < 4; ++b) {
            for (int c = 0; c < 4; ++c) {
                for (int d = 0; d < 4; ++d) {
                    vector<int> xs = {a, b, c, d};
                    if (is_allowed(xs)) {
                        all.push_back(xs);
                    }
                }
            }
        }
    }
    return all;
}

long long prime = 1000000007;

vector<vector<long long>> mul(vector<vector<long long>> a, vector<vector<long long>> b) {
    // auto t0 = clock();
    // assert (a[0].size() == b.size());
    int m = (int) a.size(), n = (int) b.size(), p = (int) b[0].size();
    // (m x n) * (n x p)
    vector<vector<long long>> c(m, vector<long long>(p, 0LL));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < p; ++j) {
            long long s = 0;
            for (int k = 0; k < n; ++k) {
                s += (a[i][k] * b[k][j]) % prime;
            }
            c[i][j] = s % prime;
        }
    }
    // cerr << "simple mul time: " << (clock() - t0) << " -- " << m << ", " << n << ", " << p << endl;
    return c;
}

vector<vector<long long>> pow(vector<vector<long long>> a, int r) {
    if (r == 1) {
        return a;
    }
    if (r % 2 == 1) {
        auto b = pow(a, r-1);
        return mul(a, b);
    }
    auto b = pow(a, r/2);
    return mul(b, b);
}

