void solve() {
    int n; cin >> n;
    for (int j = 0; j < (1<<6); j++) {
        dp[3][j] = 1;
    }
    int A = 0, C = 1, G = 2, T = 3;
    dp[3][A|(C<<2)|(G<<4)] = 0;
    dp[3][A|(G<<2)|(C<<4)] = 0;
    dp[3][G|(A<<2)|(C<<4)] = 0;
    for (int i = 4; i <= n; i++) {
        for (int j = 0; j < (1<<6); j++) {
            for (int k = 0; k < (1<<2); k++) {
                dp[i][(j>>2)|(k<<4)] += dp[i-1][j];
            }
        }
        dp[i][A|(C<<2)|(G<<4)] = 0;
        dp[i][A|(G<<2)|(C<<4)] = 0;
        dp[i][G|(A<<2)|(C<<4)] = 0;
        dp[i][G|(G<<2)|(C<<4)] -= dp[i-1][A|(G<<2)|(G<<4)];
        dp[i][T|(G<<2)|(C<<4)] -= dp[i-1][A|(T<<2)|(G<<4)];
        dp[i][G|(T<<2)|(C<<4)] -= dp[i-1][A|(G<<2)|(T<<4)];
    }
    mint res = 0;
    for (int j = 0; j < (1<<6); j++) {
        res += dp[n][j];
    }
