    M_BOOL bRead = M_FALSE;
    for (;;) {
        char c = getchar();
        if (!bRead) {
            if ('-' == c) {
                dMultiplier = -1;
            }
        }
        if ('.' == c) {
            pdCur = &dFrac;
        } else if (('0' <= c) && (c <= '9')) {
            (*pdCur) *= 10;
            (*pdCur) += (DOUBLE)(c - '0');
            bRead = M_TRUE;
            if (pdCur == &dFrac) {
                dwFpCnt++;
            }
        } else {
            if (bRead) {
                return dMultiplier * (dInt + dFrac / (pow((DOUBLE)10.0 , (DOUBLE)dwFpCnt)));
            }
        }
    }
}

static SQWORD calcZeroToNumXor(SQWORD sqNum)
{
    SQWORD sqRet = 0;
    for (DWORD dwBit = 1; dwBit < 64; dwBit++) {
        SQWORD sqMask = 0x1LL << dwBit;
        if (sqMask & sqNum) {
            if (0 == (sqNum & 0x1)) {
                sqRet |= sqMask;
            }
        }
    }

    /* lowest bit */
    if ((sqNum % 4 == 1) || (sqNum % 4 == 2)) {
        sqRet |= 1;
    }

    return sqRet;
}

