     *  dp[i][last3] 
     *      最後の3文字が last3 で、AGCが現れない文字列の数
     *  dp[0][*] = 0
     *  dp[1][*] = 4
     *  dp[2][*] = 16
     *  dp[3][*] = 61
     * 
     *  dp[j+1][*] = dp[j][]
     */

    memset(s_aasqDpTbl, 0, sizeof(s_aasqDpTbl));

    /* dp[1] を手動で初期化する */
    for (DWORD dwKey_1 = 1; dwKey_1 <= 4; dwKey_1++) {
        DWORD dwKey = dwKey_1;
