    SQWORD sqAns = 0;
    for (DWORD dwKey_3 = 1; dwKey_3 <= 4; dwKey_3++) {
        for (DWORD dwKey_2 = 1; dwKey_2 <= 4; dwKey_2++) {
            for (DWORD dwKey_1 = 1; dwKey_1 <= 4; dwKey_1++) {
