long long solve(int idx,int l1,int l2,int l3,int l4)
{
    if(idx == n)
        return !isBad(l1,l2,l3,l4,0);
    if(dp[idx][l1][l2][l3][l4] != -1)
        return dp[idx][l1][l2][l3][l4];
    long long C = 0;
    for(int i = 1;i <= 4;i++)
    {
        if(isBad(l1,l2,l3,l4,i))
            continue;
        if(l1 == 0 && l2 == 0 && l3 == 0 && l4 == 0)
            C += solve(idx + 1,i,0,0,0) % MOD;
        else if(l2 == 0 && l3 == 0 && l4 == 0)
            C += solve(idx + 1,l1,i,0,0) % MOD;
        else if(l3 == 0 && l4 == 0)
            C += solve(idx + 1,l1,l2,i,0) % MOD;
        else if(l4 == 0)
            C += solve(idx + 1,l1,l2,l3,i) % MOD;
        else
            C += solve(idx + 1,l2,l3,l4,i) % MOD;
    }
    return dp[idx][l1][l2][l3][l4] = C % MOD;
}
