constexpr int M = 1000000007;

// NG : AGC, A*GC, AG*C, ACG, GAC

int count_strs(int n) {
  vector<map<string, int>> dp(n + 1);
  vector<string> ok3 = {"AAA","AAG","AAC","AAT","AGA","AGG","AGT","ACA","ACC","ACT","ATA","ATG","ATC","ATT","GAA","GAG", "GAT","GGA","GGG","GGC","GGT","GCA","GCG","GCC","GCT","GTA","GTG","GTC","GTT","CAA","CAG","CAC","CAT","CGA","CGG","CGC","CGT","CCA","CCG","CCC","CCT","CTA","CTG","CTC","CTT","TAA","TAG","TAC","TAT","TGA","TGG","TGC","TGT","TCA","TCG","TCC","TCT","TTA","TTG","TTC","TTT"};
  for (auto&& s : ok3)
    dp[3][s] = 1;
  regex c_ng("(.AG)|(A.G)|(AG.)|(.GA)");
  for (int i = 3; i < n; i++) {
    for (auto&& p : dp[i]) {
      int pats; string s;
      tie(s, pats) = p;
      auto stail = s.substr(1, 3);
      dp[i + 1][stail + 'A'] += pats;
      dp[i + 1][stail + 'A'] %= M;
      dp[i + 1][stail + 'T'] += pats;
      dp[i + 1][stail + 'T'] %= M;
      if (!regex_match(begin(s), end(s), c_ng)) {
        dp[i + 1][stail + 'C'] += pats;
        dp[i + 1][stail + 'C'] %= M;
      }
      if (s[1] != 'A' || s[2] != 'C') {
        dp[i + 1][stail + 'G'] += pats;
        dp[i + 1][stail + 'G'] %= M;
      }
    }
  }

  int result = 0;
  for (auto&& p : dp[n]) {
    result += p.second;
    result %= M;
  }
  return result;
}



