#define rep(i, n) for(int i = 0, i##_len = (n); i < i##_len; i++)
#define reps(i, s, n) for(int i = (s), i##_len = (n); i < i##_len; i++)
#define rrep(i, n) for(int i = (n) - 1; i >= 0; i--)
#define rreps(i, e, n) for(int i = (n) - 1; i >= (e); i--)
#define all(x) (x).begin(), (x).end()
#define sz(x) ((int)(x).size())
#define uniq(x) (x).erase(unique((x).begin(), (x).end()), (x).end())

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    const ll mod = 1e9 + 7;
    int n;
    cin >> n;
    // NG: AGC, ACG, GAC, A*GC, AG*C
    vector<map<string, ll>> dp(n, map<string, ll>());
    char s[] = {'A', 'C', 'G', 'T'};
    vector<string> sk;
    ll ans = 0;
    rep(i, 4) {
        rep(ii, 4) {
            rep(iii, 4) {
                sk.push_back({s[i], s[ii], s[iii]});
            }
        }
    }
    rep(i, sz(sk)) {
        if ((sk[i] == "AGC") || (sk[i] == "ACG") || (sk[i] == "GAC")) {
            dp[2][sk[i]] = 0;
        }
        else {
            dp[2][sk[i]] = 1;
        }
    }
    reps(i, 3, n) {
        for (auto x : dp[i - 1]) {
            set<char> kh;
            rep(ii, 4) kh.insert(s[ii]);
            if ((x.first[1] == 'A') && (x.first[2] == 'G')) kh.erase('C');
            if ((x.first[1] == 'A') && (x.first[2] == 'C')) kh.erase('G');
            if ((x.first[1] == 'G') && (x.first[2] == 'A')) kh.erase('C');
            if ((x.first[0] == 'A') && (x.first[2] == 'G')) kh.erase('C');
            if ((x.first[0] == 'A') && (x.first[1] == 'G')) kh.erase('C');
            for (auto y : kh) {
                string ns = {x.first[1], x.first[2], y};
                dp[i][ns] = (dp[i][ns] + x.second) % mod;
            }
        }
    }
    for (auto x : dp[n - 1]) {
        ans = (ans + x.second) % mod;
    }
    cout << ans << endl;
    return 0;
}

