typedef long long ll;
const ll mod = 1000000000+7;
ll mod_pow(ll N, ll P, ll M){
    if(P==0) return 1;
    if(P%2==0){
        ll t = mod_pow(N, P/2, M);
        return t*t % M;
    }
    return N * mod_pow(N, P-1, M);
}

ll dp[100][4][4][4];
int main(){
    ll N;
    cin>>N;

    dp[0][3][3][3]=1;

    for(int len=0;len<N;len++){
        for(int c1=0;c1<4;c1++){
            for(int c2=0;c2<4;c2++){
                for(int c3=0;c3<4;c3++){
                    if(dp[len][c1][c2][c3]==0)continue;

                    for(int a=0;a<4;a++){
                        //agc
                        if(a==2&&c1==1&&c2==0)continue;
                        //acg
                        if(a==2&&c1==0&&c2==1)continue;
                        //gac
                        if(a==1&&c1==2&&c2==0)continue;
                        //a?gc
                        if(a==2&&c2==1&&c3==0)continue;
                        //ag?c
                        if(a==2&&c1==1&&c3==0)continue;

                        dp[len+1][a][c1][c2]+=dp[len][c1][c2][c3];
                        dp[len+1][a][c1][c2]%=mod;
                    }
                }
            }
        }
    }

    ll ans=0;
    for(int c1=0;c1<4;c1++)for(int c2=0;c2<4;c2++)for(int c3=0;c3<4;c3++){
