                        if (i2 == 2 && i1 == 0 && i == 1) continue; // *GAC
                        if (i2 == 0 && i1 == 1 && i == 2) continue; // *ACG
                        if (i3 == 0 && i2 == 2 && i == 1) continue; // AG*C
                        if (i3 == 0 && i1 == 2 && i == 1) continue; // A*GC

                        dp[N+1][i2][i1][i] += dp[N][i3][i2][i1];
                        dp[N+1][i2][i1][i] %= mod;
                    }
                }
            }
        }
    }

    lli ans = 0;
    for (int i3=0; i3<=3; i3++) {
        for (int i2=0; i2<=3; i2++) {
