#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
char s[101];
long long mem[100][256];
bool flag[100][256]={false};
const long long cc = pow(10,9)+7;
bool ng(int n){
    if(n < 3) return false;
    if(strncmp(&s[n-3], "AGC", 3)==0) return true;
    if(strncmp(&s[n-3], "ACG", 3)==0) return true;
    if(strncmp(&s[n-3], "GAC", 3)==0) return true;

    if(n < 4) return false;
    if((strncmp(&s[n-4], "A", 1)==0)&&(strncmp(&s[n-2],"GC", 2)==0)) return true;
    if((strncmp(&s[n-4], "AG", 2)==0)&&(strncmp(&s[n-1], "C", 1)==0)) return true;

    return false;    
}
ll dfs(int p, int size){
    char cand[4]={'A', 'C', 'G', 'T' };
    ll result = 0;
    int index=0;
    if( p > 2 ){
        for(int i=0; i<3; i++){
            index = index << 2;
            if( s[p-1-i] == 'A') index+=0;
            if( s[p-1-i] == 'G') index+=1;
            if( s[p-1-i] == 'C') index+=2;
            if( s[p-1-i] == 'T') index+=3;
        }
        if( flag[p][index]==true){
            return mem[p][index];
        }
    }
    if( ng(p) == true) {
        //ll c1 = pow(4,size-p);
        ll c1 = 1;
        for(int i=0; i<(size-p); i++) c1 = (c1*4)%cc;
        return c1;
    }
    if( p==size ) return 0;

    for(int i=0; i<4; i++){
        s[p]=cand[i];
        result += dfs(p+1, size)%cc;
    }
    result = result%cc;
    if( p>2){
        mem[p][index] = result;
        flag[p][index]=true;
    }
    return result;
}
int main(){
    int n;
    std::cin >> n;
    //long long result=pow(4, n);
    long long result=1;
    for(int i=0; i<n; i++){
        result = (result*4)%cc;
    }
    long long search;
    result = result;
    search = dfs(0,n)%cc;
    result -= search;

    cout << result%cc << endl;
    return 0;
}

