bool judge(string s) {
  string t = "AGC";
  if (s.substr(0, 3) == t) return false;
  if (s.substr(1, 3) == t) return false;
  rep (i, 3) {
    string ss = s;
    swap(ss[i], ss[i + 1]);
    if (ss.substr(0, 3) == t) return false;
    if (ss.substr(1, 3) == t) return false;
  }
  return true;
}

