                    dp[i][1][2][l] = (dp[i-1][2][l][1] + dp[i-1][2][l][2] + dp[i-1][2][l][3])%mod;
                }
                dp[i][1][k][2] = (dp[i-1][k][2][1] + dp[i-1][k][2][2] + dp[i-1][k][2][3])%mod;
            }
        }

        // 第3~5ケース
        dp[i][1][2][0] = 0;
        dp[i][1][0][2] = 0;
        dp[i][2][1][0] = 0;
    }

    ll ans;
    rep(i, 4){
        rep(j, 4){
            rep(k, 4){
                ans += dp[N][i][j][k];
            }
        }
    }

    cout << ans%mod;

}

