typedef unsigned long ulong;

static unordered_map<ulong, unordered_map<ulong, ulong>> g_gcd_cache;
static unsigned long euclidean_gcd(unsigned long a, unsigned long b) {

    auto origA = a, origB = b;
    auto it1 = g_gcd_cache.find(a);
    if (it1 != g_gcd_cache.end())
    {
        auto it2 = it1->second.find(b);
        if (it2 != it1->second.end())
        {
            return it2->second;
        }
    }

    if (a < b)
    {
        auto v = euclidean_gcd(b, a);
        return v;
    }
    unsigned r;
    while ((r = a%b)) {
        a = b;
        b = r;
    }
    g_gcd_cache[origA][origB] = b;
    g_gcd_cache[origB][origA] = b;
    return b;
}

