bool contain(string s) {
	int n = s.length();
	if (n <= 2) return false;

	rep(i, 0, n - 2) {
		string t = s.substr(i, 3);
		if (t == "AGC") return true;
	}

	return false;
}
string add(string s, char c) {
	string res = s + c;

	int n = res.length();
	if (n <= 2) return res;

	if (contain(res)) return "";

	rep(i, 0, n - 1) {
		string tes = res;
		swap(tes[i], tes[i + 1]);
		if (contain(tes)) return "";
	}

	return res;
}
