  //初期化
  for(int num=0;num<=2;num++){
    for(int i=0;i<4;i++){
      for(int j=0;j<4;j++){
        for(int k=0;k<4;k++){
          dp[num][i][j][k] = 0;
        }
      }
    }
  }
  for(int i=0;i<4;i++){
    for(int j=0;j<4;j++){
      for(int k=0;k<4;k++){
        dp[3][i][j][k] = 1;
      }
