  dp[3][1][0][2] = 0;
  dp[3][0][2][1] = 0;

  for(int num=3;num<=N;num++){
    for(int a=0;a<4;a++){
      for(int b=0;b<4;b++){
        for(int c=0;c<4;c++){
          dp[num][a][b][c] %= MOD;
          if(b==0 && c==1) {
            dp[num+1][b][c][0] += dp[num][a][b][c];
            dp[num+1][b][c][1] += dp[num][a][b][c];
            dp[num+1][b][c][2] += 0;
            dp[num+1][b][c][3] += dp[num][a][b][c];
            continue;
          }else if(b==1 && c==0) {
            dp[num+1][b][c][0] += dp[num][a][b][c];
            dp[num+1][b][c][1] += dp[num][a][b][c];
            dp[num+1][b][c][2] += 0;
            dp[num+1][b][c][3] += dp[num][a][b][c];
