            dp[num+1][1][c][1] += dp[num][a][b][c];
            dp[num+1][1][c][2] += 0;
            dp[num+1][1][c][3] += dp[num][a][b][c];
            continue;
          }

          for(int key=0;key<4;key++)
            dp[num+1][b][c][key] += dp[num][a][b][c];
        }
      }
    }
  }

  ll ans = 0;
