  ll tmp = n - 2;
  ll tmp2 = 6 * pow(4,n-3) % mod;
  ll tmp3 = ((4 * pow(4,n-3) % mod) * (n-4) % mod);

  ans -= (tmp + tmp2 + tmp3);
  while(ans < 0) ans += mod;

  cout << ans << endl;

}

