using namespace std;

bool is_allowed(vector<int> vs) {
    assert(vs.size() == 4);
    auto check = [&]() {
        if (vs[0] == 0 && vs[1] == 1 && vs[2] == 2) {
            return false;
        }
        if (vs[1] == 0 && vs[2] == 1 && vs[3] == 2) {
            return false;
        }
        return true;
    };
    if (!check()) {
        return false;
    }
    for (int i = 0; i < 3; ++i) {
        swap(vs[i], vs[i+1]);
        if (!check()) {
            return false;
        }
        swap(vs[i], vs[i+1]);
    }
    return true;
}

vector<vector<int>> all_allowed() {
    vector<vector<int>> all;
    for (int a = 0; a < 4; ++a) {
        for (int b = 0; b < 4; ++b) {
            for (int c = 0; c < 4; ++c) {
                for (int d = 0; d < 4; ++d) {
                    vector<int> xs = {a, b, c, d};
                    if (is_allowed(xs)) {
                        all.push_back(xs);
                    }
                }
            }
        }
    }
    return all;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    if (n == 3) {
        cout << 61 << endl;
        return 0;
    }
    vector<map<vector<int>, long long>> count(n+1);
    for (auto& xs : all_allowed()) {
        count[4][xs] = 1;
    }
    long long prime = 1000000007;
    for (int i = 5; i <= n; ++i) {
        for (auto& p : count[i-1]) {
            for (int a = 0; a < 4; ++a) {
                vector<int> xs(p.first.begin()+1, p.first.end());
                xs.push_back(a);
                if (is_allowed(xs)) {
                    count[i][xs] = (count[i][xs] + p.second) % prime;
                }
            }
        }
    }
    long long result = 0;
    for (auto& p : count[n]) {
        result = (result + p.second) % prime;
    }
    cout << result << endl;
    return 0;
}

