    dp[0][3][3][3] = 1;

    /* a:0 c:1 g:2 t:3 */
    REP(i, n) {
        REP(j, 4) {
            REP(k, 4) {
                REP(l, 4) {
                    /* 意味ないからcontinue */
                    if (dp[i][j][k][l] == 0) {
                        continue;
                    }
                    REP(m, 4) {
                        /* AGC */
