                            continue;
                        }
                        /* AG#C */
                        if (m == 1 && k == 2 && l == 0) {
                            continue;
                        }
                        dp[i + 1][m][j][k] += dp[i][j][k][l];
                        dp[i + 1][m][j][k] %= MOD;
                    }
                }
            }
        }
    }

    REP(i, 4) {
        REP(j, 4) {
            REP(k, 4) {
