                    for(m=0; m<4; m++) {
                        if(j==0 && k==1 && l==2) dp[i][j][k][l]=0;
                        if(j==0 && k==2 && l==1) dp[i][j][k][l]=0;
                        if(j==2 && k==0 && l==1) dp[i][j][k][l]=0;

                        if(j==0 && k==2 && m==1) continue;

                        if(j==0 && l==2 && m==1) continue;

                        else moC(dp[i+1][k][l][m], +, dp[i][j][k][l]);
                    }

                }
            }
        }
    }

    ll ans=0;
    for(j=0; j<4; j++) {
        for(k=0; k<4; k++) {
            for(l=0; l<4; l++) {
                moC(ans, +, dp[N][j][k][l]);
            }
        }
    }

    pt(ans);
}

