                if (notAGC(temp1) && temp2 != "agc" && temp3 != "agc") {
                    dp[i + 1][temp1] += (*itr).second;
                    dp[i + 1][temp1] %= p;
                }
            }
        }
    }
    long long int ans = 0;
    for (auto itr = dp[n].begin(); itr != dp[n].end(); itr++) {
        ans += (*itr).second;
        ans %= p;
    }
