        rep(i, n + 1) rep(j, 4) rep(k, 4) rep(l, 4) dp[i][j][k][l] = 0;
        // dp[i][j][k][l]: i文字目までで, i文字目がj, i+1文字目がk, i+2文字目がl, i+3文字目がm
