lli call(int in, int i, int j, int k)
{
    if(i==0 && j==2 && k==1) return 0;
    if(i==2 && j==0 && k==1) return 0;
    if(i==0 && j==1 && k==2) return 0;

    if(in == n) return 1;
    lli &ret = dp[in][i][j][k];
    if(ret != -1) return ret;

    ret = 0;
    for(int x=0; x<4; x++){
        if(i==0 && k==2 && x==1);
        else if(i==0 && j==2 && x==1);
        else ret = (ret+call(in+1, j, k, x))%mod;
    }
    return ret;
}

