int dfs(int index,string last3) {
  if(index == N) {
    return 1;
  }
  int strToInt[3];
  rep(i,3){
    switch (last3[i])
    {
      case 'T':
        strToInt[i] = 0;
        break;
      case 'A':
        strToInt[i] = 1;
        break;
      case 'G':
      strToInt[i] = 2;
        break;
      case 'C':
        strToInt[i] = 3;
        break;
      default:
        break;
    }
  }
  if(memo[index][strToInt[0]][strToInt[1]][strToInt[2]] != -1) {
    return memo[index][strToInt[0]][strToInt[1]][strToInt[2]];
  }
  int n = 0;
  string t = "",a = "", g = "", c = "";
  t += last3[1];
  t += last3[2];
  t += 'T';
  a += last3[1];
  a += last3[2];
  a += 'A';
  g += last3[1];
  g += last3[2];
  g += 'G';
  c += last3[1];
  c += last3[2];
  c += 'C';
  n = (n + dfs(index+1,t)) % ((int)pow(10,9) + 7);
  n = (n + dfs(index+1,a)) % ((int)pow(10,9) + 7);
  if (!(last3[1] == 'A' && last3[2] == 'C')) {
    n = (n + dfs(index + 1,g)) % ((int)pow(10,9) + 7);
  }
  if (!((last3[1] == 'A' && last3[2] == 'G') || (last3[1] == 'G' && last3[2] == 'A') || (last3[0] == 'A' && last3[2] == 'G') || (last3[0] == 'A' && last3[1] == 'G'))) {
    n = (n + dfs(index + 1,c)) % ((int)pow(10,9) + 7);
  }
  memo[index][strToInt[0]][strToInt[1]][strToInt[2]] = n;
  return n;
}
