long long dfs(int n, char b1, char b2, char b3)
{
	if (n == 0) return 1;
	auto status = make_tuple(n, b1, b2, b3);
	if (dp.count(status)) return dp[status];
	static string str = "ACGT";
	long long res = 0;
	for(auto&& c : str)
	{
		if(c == 'C')
		{
