			if (b1 == 'A' && b2 == 'G') continue;
			if (b3 == 'A' && b2 == 'G') continue;
			res += dfs(n - 1, c, b1, b2);
			res %= INF;
		}
		else if(c == 'G')
		{
			if (b1 == 'C' && b2 == 'A') continue;
			res += dfs(n - 1, c, b1, b2);
			res %= INF;
		}
		else
		{
			res += dfs(n - 1, c, b1, b2);
			res %= INF;
		}
	}
	return dp[status] = res;
}

