        std::string key("TTT");
        key.push_back(c);
        dp[0][key] = 1;
    }
    for (int i = 0; i < N-1; i++) {
        for (const auto& pair : dp[i]) {
            const std::string& key = pair.first;
            ll value = pair.second;
            for (const char& c : characters) {
                std::string nextKey(key.substr(1, 3) + c);
                if( isValid(nextKey) ) {
                    dp[i+1][nextKey] += value;
                    dp[i+1][nextKey] %= MOD;
                }
            }
        }
    }

    ll answer = 0;
    for (const auto& pair : dp[N-1]) {
        answer += pair.second;
        answer %= MOD;
    }

    return answer;
}

