inline bool check(vi v) {
	int cnt1 = 0, cnt2 = 0;
	lp(j,0,2)
		cnt1 += (v[j] == arr[j]);
	lp(j,1,3)
		cnt2 += (v[j] == arr[j - 1]);
	return (cnt1 == 3 || cnt2 == 3);
}
inline bool can(vi v) {
	if (check(v))
		return true;
	lp(i,0,2)
	{
		swap(v[i], v[i + 1]);
		if (check(v))
			return true;
		swap(v[i], v[i + 1]);
	}
	return false;
}
int solve(int idx, int prv1, int prv2, int prv3) {
	if (idx >= n)
		return 1;
	int &ret = dp[idx][prv1][prv2][prv3];
	if (ret != -1)
		re (ret % mod);
	ret = 0;
	lp(i,0,3)
	{
		vi v;
		v.pb(prv3);
		v.pb(prv2);
		v.pb(prv1);
		v.pb(i);
		if (can(v))
			continue;
		ret += solve(idx + 1, i, prv1, prv2);
		if (ret >= mod)
			ret %= mod;
	}
	re ret;
}
