    // 012, 102, 021, 0?12, 01?2
    int N;
    cin >> N;

    long long MOD = 10e9 + 7;
    auto dp = make_vec<long long>(N+1, 4, 4, 4); // nまでの実現可能な文字列の通り
    // fill_v(dp, 0); // make_vecで作った多次元vectorを任意の値で初期化する

