            if(i==0 && j==1 &&         l==2) continue;
            dp[n][j][k][l] += dp[n-1][i][j][k] % MOD;
        }
    }

    // sum
    long long res = 0;
    rep(i,4) rep(j,4) rep(k,4){
        res += dp[N][i][j][k];
