long long sum[4][4][4];

bool check4(int i, int j, int k, int l) {
    if (j == 0 && k == 2 && l == 1) return false;
    if (j == 2 && k == 0 && l == 1) return false;
    if (j == 0 && k == 1 && l == 2) return false;
    if (i == 0 && k == 2 && l == 1) return false;
    if (i == 0 && j == 2 && l == 1) return false;
    return true;
}

bool check3(int i, int j, int k) {
    if (i == 0 && j == 2 && k == 1) return false;
    if (i == 0 && j == 1 && k == 2) return false;
    if (i == 2 && j == 0 && k == 1) return false;
    return true;
}

void mul() {
    long long before[4][4][4];
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            for (int k = 0; k < 4; k++) {
                before[i][j][k] = sum[i][j][k];
            }
        }
    }
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            for (int k = 0; k < 4; k++) {
                sum[i][j][k] = 0;
            }
        }
    }
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            for (int k = 0; k < 4; k++) {
                for (int l = 0; l < 4; l++) {
                    if (check4(i, j, k, l)) sum[j][k][l] = (before[i][j][k] + sum[j][k][l]) % MOD;
                }
            }
        }
    }
}

int main() {
    int N;
    cin >> N;
    if (N == 3) {
        cout << 61 << endl;
        return 0;
    }
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            for (int k = 0; k < 4; k++) {
                sum[i][j][k] = check3(i, j, k) ? 1 : 0;
            }
        }
    }
    for (int i = 4; i <= N; i++) {
        mul();
    }
    long long ans = 0;
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            for (int k = 0; k < 4; k++) {
                ans = (ans + sum[i][j][k]) % MOD;
            }
        }
    }
    cout << ans << endl;
    return 0;
}

