                        if (j == 0 && k == 1 && m == 2) continue;
                        if (j == 0 && l == 1 && m == 2) continue;
                        dp[i+1][k][l][m] += dp[i][j][k][l];
                        dp[i+1][k][l][m] %= mod;
                    }
                }
            }
        }
    }

    int ans = 0;
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            for (int k = 0; k < 4; k++) {
                ans += dp[n][i][j][k];
                ans %= mod;
            }
        }
    }
