template<int mod=MOD>
struct ModuloRingOperators {
   static int Add(int lhs, int rhs) { return (lhs + rhs) % mod; };
   static int Mul(int lhs, int rhs) { return (lhs * rhs) % mod; };
   static int IdAdd() { return 0; };
   static int IdMul() { return 1; };
   static int Opposite(int value) { return ((-value % mod) + mod) % mod; };
   static bool Less(int lhs, int rhs) { return lhs < rhs; };
   static int Power(int value, int n) {
      int res = IdMul();
      while (n > 0) {
         if (n & 1) res = Mul(res, value);
         value = Mul(value, value); n >>= 1;
      }
      return res;
   }
};

using MR = Ring<int, ModuloRingOperators<MOD>>;

template<int mod=MOD>
struct GaloisFieldOperators : ModuloRingOperators<mod> {
   static int Reciprocal(int value) { return ModuloRingOperators<mod>::Power(value, mod-2); }
};

