#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD=1000000007LL;

ll power(int x, int n){
  ll v=1;
  while(n>=1){
    if(n&1){
      (v*=x)%=MOD;
    }
    n=n>>1;
    x=(x*x)%MOD;
  }
  return v;
}


bool is_bad(int a, int b, int c, int d){
  if(      b==1&&c==2&&d==3){return true;}
  else if(      b==1&&c==3&&d==2){return true;}
  else if(      b==2&&c==1&&d==3){return true;}
  else if(a==1&&      c==2&&d==3){return true;}
  else if(a==1&&b==2&&      d==3){return true;}
  else {return false;}
}


ll solve(int N){
  ll dp[N+1][256][2];
  memset(dp, 0, sizeof(dp));
  dp[0][0][0]=1;

  for (int i=0;i<N;++i){
    for (int a=0;a<4;++a){
      for(int b=0;b<4;++b){ 
        for(int c=0;c<4;++c){ 
          for (int d=0;d<4;++d){
            int abcd=((a*4+b)*4+c)*4+d;
            for (int e=0;e<4;++e){
              int bcde=((b*4+c)*4+d)*4+e;
              bool bad_=is_bad(b,c,d,e);
              for (int j=0;j<2;++j){
                (dp[i+1][bcde][bad_||j]+=dp[i][abcd][j])%=MOD;
              }
            }
          }
        }
      }
    }
  }

  ll ans=0;
  for (int i=0;i<256;++i){
    (ans+=dp[N][i][1])%=MOD;
  }
  ans=(power(4,N)-ans+MOD)%MOD;
  return ans;
}

int main(){
  int N;cin>>N;
  cout << solve(N)<<endl;
  return 0;
}

