void adds(int& i, int j) {
    if((i += j) >= mod) i -= mod;
    return ;
}

bool rd(int i, int j, int k, int d) {
    if(j == 1 && k == 2 && d == 3) return true;
    swap(i, j);
    if(j == 1 && k == 2 && d == 3) return true;
    swap(i, j);
    swap(j, k);
    if(j == 1 && k == 2 && d == 3) return true;
    swap(j, k);
    swap(k, d);
    if(j == 1 && k == 2 && d == 3) return true;
    if(i == 1 && j == 2 && k == 3) return true;
    swap(k, d);
    return false;
}

int f(int i, int j, int k, int d, int r) {
    if(rd(i, j, k, d)) return 0;
    if(r == n) return 1;
    if(dp[i][j][k][d][r] != -1) return dp[i][j][k][d][r];
    int mx = 0;
    for(int l = 0; l < 4; ++l)
        adds(mx, f(j, k, d, l, r + 1));

    return dp[i][j][k][d][r] = mx;
}

