const unsigned int M = 1000000007;

struct Node {
	unsigned int num;
	unsigned int tmp;
	Node *a, *g, *c, *t;
	Node () {
		num = tmp = 0;
	}
	void add(unsigned int n) {
		tmp += n;
		tmp %= M;
	}

	void next_gen() {
		num = tmp;
		tmp = 0;
	}
};


