void solve()
{
	ll N;
	cin >> N;
	vvvvmll dp(N, vvvmll(4, vvmll(4, vmll(4, 0))));

	REP(j, 4)REP(k, 4)REP(l, 4){
		if      (j == 0 && k == 1 && l == 2) dp[2][j][k][l] = 0;
		else if (j == 1 && k == 0 && l == 2) dp[2][j][k][l] = 0;
		else if (j == 0 && k == 2 && l == 1) dp[2][j][k][l] = 0;
		else                                 dp[2][j][k][l] = 1;
	}
	REPS(i,3,N-1)REP(j, 4)REP(k, 4)REP(l, 4)REP(m, 4){
		if      (          k == 0 && l == 1 && m == 2);
		else if (j == 0 &&           l == 1 && m == 2);
		else if (          k == 1 && l == 0 && m == 2);
		else if (          k == 0 && l == 2 && m == 1);
		else if (j == 0 && k == 1 &&           m == 2);
		else{
			dp[i][k][l][m] += dp[i-1][j][k][l];
		}
	}

	mll sum = 0;
	REP(j, 4)REP(k, 4)REP(l, 4){
		sum += dp[N-1][j][k][l];
	}
