bool Ok(string last4) {
    for (int i = 0; i < 4; i++) {
        string tmp = last4;
        if (i > 0) {
            swap(tmp[i], tmp[i-1]);
        }
        if (tmp.find("AGC") != -1) {
            return false;
        }
    }
    return true;
}


int DFS(int cnt, string last3, vector<map<string, int> >& memo) {
    if (memo[cnt].count(last3)) {
        return memo[cnt][last3];
    }
    if (cnt == N) {
        return 1;
    }
    int ret = 0;
    string s = "ACGT";
    for (char i : s) {
        if (Ok(last3 + i)) {
            ret = (ret + DFS(cnt + 1, last3.substr(1, 2) + i, memo)) % mod;
        }
    }
    memo[cnt][last3] = ret;
    return ret;
}



