/*
方針:
アウトになるのは
?AG+C
?GA+C
A?G+C
AG?+C
?AC+G
の5パターン
->最後4文字から考える
*/
int N;
int ans;
int solve()
{

    int memo[101][4][4][4];
    REP(j, 0, 4)
    REP(k, 0, 4)
    REP(l, 0, 4)
    {
        //AGC
        if (j == A && k == G && l == C)
            continue;
        //GAC
        if (j == G && k == A && l == C)
            continue;
        //ACG
        if (j == A && k == C && l == G)
            continue;
        memo[3][j][k][l] = 1;
    }
    REP(length, 3, N)
    REP(i, 0, 4)
    REP(j, 0, 4)
    REP(k, 0, 4)
    REP(l, 0, 4)
    {
        //?AGC
        if (j == A && k == G && l == C)
            continue;
        //A?GC
        if (i == A && k == G && l == C)
            continue;
        //GA?C
        if (j == G && k == A && l == C)
            continue;
        //?ACG
        if (j == A && k == C && l == G)
            continue;
        //AG?C
        if (i == A && j == G && l == C)
            continue;
        memo[length + 1][j][k][l] += memo[length][i][j][k];
        memo[length + 1][j][k][l] %= MOD;
    }
    REP(i, 0, 4)
    REP(j, 0, 4)
    REP(k, 0, 4)
    {
        ans += memo[N][i][j][k];
        ans %= MOD;
    }
}
int main()
{
    cin >> N;
    solve();
    cout << ans << endl;
    return 0;
}

