    int n;
    std::cin >> n;
    //long long result=pow(4, n);
    long long result=1;
    for(int i=0; i<n; i++){
        result = (result*4)%cc;
    }
    long long search;
    result = result;
    search = dfs(0,n)%cc;
    //result -= search;
    //cerr << " " << result << " " << search << endl;
    if (result > search ) cout << (result -search)%cc << endl;
    else cout << (search - result)%cc << endl;
    return 0;
}

