using namespace std;

const int MOD = 1000000007;

int dp[105][64];

const int A = 0;
const int C = 1;
const int G = 2;
const int T = 3;

map<char, int> MP = {{'A', A}, {'C', C}, {'G', G}, {'T', T}, {'.', 0}, {'x', 3}};

vector<string> badPre = {".AC", ".CA", ".AG", "A.C", "AC."};
vector<string> mask =   {".xx", ".xx", ".xx", "x.x", "xx."};
vector<int> badNext =   {    G,     G,     C,     G,     G};

// convert from string representation to dp array index
inline int convert(string s) {
    int r = 0;
    for(char c : s) {
        r = r<<2;
        r |= MP[c];
    }
    return r;
}

// restricts bad secuences
bool ok(int pre, int next) {
    for(int i = 0; i < 5; i++) {
        if((pre & convert(mask[i])) == convert(badPre[i]) && next == badNext[i] ) {
            return false;
        }   
    }

    return true;
}

int nextIndex(int pre, int next) {
    pre = pre & 15;
    pre <<= 2;
    pre |= next;
    return pre;
}

int main() {

    int n;
    cin >> n;

    for(int i = 0; i < 64; i++) {
        dp[3][i] = 1;
    }
    dp[3][convert("ACG")] = 0;
    dp[3][convert("CAG")] = 0;
    dp[3][convert("AGC")] = 0;

    for(int i = 4; i <= n; i++) {
        for(int seq = 0; seq < 64; seq++) {
            for(int letter = 0; letter < 4; letter++) {
                if(ok(seq, letter)) {
                    dp[i][nextIndex(seq, letter)] += dp[i-1][seq];
                    dp[i][nextIndex(seq, letter)] %= MOD;
                }
            }
        }
    }

    int result = 0;

    for(int i = 0; i < 64; i++) {
        result += dp[n][i];
        result %= MOD;
    }

    cout << result << endl;

    return 0;
}

