template<typename Itr>
int to_int(Itr begin, Itr end) {
	return std::accumulate(begin, end, 0, [](int r, int p) {return r * 4 + p; });
}
int to_int(const std::vector<int>& prev3) {
	return to_int(prev3.begin(), prev3.end());
}
template<typename Itr>
bool is_agc(Itr begin, Itr end) {
	return std::distance(begin, end) == 3 && to_int(begin, end) == 6;
}
bool contains_agc(const std::vector<int>& vec) {
	for (auto i = 0; i + 2 < vec.size(); ++i) {
		if (is_agc(std::next(vec.begin(), i), std::next(vec.begin(), i + 3))) return true;
	}
	return false;
}
bool is_match(std::vector<int> seq) {
	if (contains_agc(seq)) return true;
	for (auto i = 0; i + 1 < seq.size(); ++i) {
		std::swap(seq[i], seq[i + 1]);
		if (contains_agc(seq)) return true;
		std::swap(seq[i], seq[i + 1]);
	}
	return false;

}
constexpr long long int MOD = 1000000007LL;
long long int pattern(int length, const std::vector<int>& prev3, std::vector<std::vector<long long int>>& memo) {
	if (length == 2) return is_match(prev3) ? 0 : 1;
	if (memo[length][to_int(prev3)] >= 0) return memo[length][to_int(prev3)];
	std::vector<int> last(4); std::copy(prev3.begin(), prev3.end(), std::next(last.begin()));
	std::vector<int> last3(3); std::copy(last.begin(), std::prev(last.end()), last3.begin());
	long long int result = 0;
	for (auto i = 0; i < 4; ++i) {
		last[0] = last3[0] = i;
		if (!is_match(last)) {
			result += pattern(length - 1, last3, memo);
		}
	}
	return memo[length][to_int(prev3)] = result % MOD;
}
