	int n; std::cin >> n;
	if (n == 3) {
		std::cout << 61 << std::endl;
		return 0;
	}
	std::vector<std::vector<long long int>> memo(n, std::vector<long long int>(256, -1));
	std::vector<int> last3(3);
	long long int result = 0;
	for (auto i = 0; i < 64; ++i) {
		auto p = i;
		for (auto j = 0; j < 3; ++j) {
			last3[j] = p % 4;
			p /= 4;
		}
		result += pattern(n - 1, last3, memo);
		result %= MOD;
	}
	std::cout << result << std::endl;
}

