char num_to_char(int k){
  switch(k){
    case 0:
      return 'A';
    case 1:
      return 'C';
    case 2:
      return 'G';
    case 3:
      return 'T';
  }
  fprintf(stderr, "unexpected erorr\n");
  exit(0);
}

string num_to_str(int k){
  char a1 = num_to_char(k/16);
  k %= 16;
  char a2 = num_to_char(k/4);
  k %= 4;
  char a3 = num_to_char(k);

  string str = "";
  str += a1;
  str += a2;
  str += a3;
  return str;
}

ll char_to_num(char ch){
  if(ch=='A') return 0;
  if(ch=='C') return 1;
  if(ch=='G') return 2;
  if(ch=='T') return 3;
  return -1;
}

ll str_to_num(string str){
  str.resize(3);
  int a1 = char_to_num(str[0]);
  int a2 = char_to_num(str[1]);
  int a3 = char_to_num(str[2]);
  return a1*16 + a2*4 + a3;
}

