const int MOD = (int)1e9 + 7;

const int A = 0, G = 1, C = 2, T = 3;

int N;

//末尾の3文字の中で入れ替えすると条件に反するものを除く
bool isOK3(int x1, int x2, int x3) {
  if ((x1 == A && x2 == G && x3 == C) || (x1 == G && x2 == A && x3 == C) ||
      (x1 == A && x2 == C && x3 == G)) {
    return false;
  } else {
    return true;
  }
}

//末尾の4文字の中で入れ替えすると条件に反するものを除く
bool isOK4(int x1, int x2, int x3, int x4) {
  if ((x1 == G && x2 == A && x3 == C) || (x2 == G && x3 == A && x4 == C) ||
      (x1 == A && x2 == C && x3 == G) || (x2 == A && x3 == C && x4 == G) ||
      (x1 == A && x3 == G && x4 == C) || (x1 == A && x2 == G && x4 == C)) {
    return false;
  } else {
    return true;
  }
}

void abc132d() {
  int dp[102][4][4][4] = {0};

  for (int j = 0; j < 4; j++) {
    for (int k = 0; k < 4; k++) {
      for (int l = 0; l < 4; l++) {
        if (isOK3(j, k, l)) {
          dp[3][j][k][l] = 1;
        }
      }
    }
  }

  for (int i = 3; i < N; i++) {
    for (int j = 0; j < 4; j++) {
      for (int k = 0; k < 4; k++) {
        for (int l = 0; l < 4; l++) {
          for (int c = 0; c < 4; c++) {
            if (isOK3(k, l, c) && isOK4(j, k, l, c)) {
              dp[i + 1][k][l][c] += dp[i][j][k][l];
              dp[i + 1][k][l][c] %= MOD;
            }
          }
        }
      }
    }
  }

  ll res = 0;

  for (int j = 0; j < 4; j++) {
    for (int k = 0; k < 4; k++) {
      for (int l = 0; l < 4; l++) {
        res += dp[N][j][k][l];
        res %= MOD;
      }
    }
  }
  cout << res << "\n";
}

