const ll A=0,C=1,G=2,T=3;
bool OK(ll i,ll j,ll k,ll l){
	if(i==A&&j==G&&k==C)return false;
	if(i==A&&j==C&&k==G)return false;
	if(i==G&&j==A&&k==C)return false;
	if(j==A&&k==G&&l==C)return false;
	if(j==A&&k==C&&l==G)return false;
	if(j==G&&k==A&&l==C)return false;
	if(i==A&&k==G&&l==C)return false;
	if(i==A&&j==G&&l==C)return false;
	return true;
}

