const int MOD = 1000000007;
int N;
ll dp[105][4][4][4] = {0};

ll solve() {
  dp[0][1][1][1] = 1;
  for (int i = 0; i < N; i++) {
    for (int j = 0; j < 4; j++) {
      for (int k = 0; k < 4; k++) {
        for (int l = 0; l < 4; l++) {
          ll num = 0;
          if (l == 0 && k == 3 && j == 2) continue;
          if (l == 0 && k == 2 && j == 3) continue;
          if (l == 2 && k == 0 && j == 3) continue;
          for (int m = 0; m < 4; m++) {
            if (m == 0 && k == 2 && j == 3) continue;
            if (m == 0 && l == 2 && j == 3) continue;
            num = (num + dp[i][k][l][m]) % MOD;
          }
          dp[i + 1][j][k][l] = (dp[i + 1][j][k][l] + num) % MOD;
        }
      }
    }
  }
  ll res = 0;
  for (int i = 0; i < 4; i++) {
    for (int j = 0; j < 4; j++) {
      for (int k = 0; k < 4; k++) {
        res = (res + dp[N][i][j][k]) % MOD;
      }
    }
  }
  return res;
}

