const string S = "ACGT";

const int mod = 1e9 + 7;

int main()
{
    int N;
    cin >> N;
    vector<vector<int>> dp(N + 1, vector<int>(1 << 6));
    for(int i = 0;i < (1 << 6);i++){
        string t;
        for(int j = 0;j < 3;j++){
            int v = (i >> (j * 2)) & 3;
            t += S[v];
        }
        dp[3][i] = t != "AGC" && t != "GAC" && t != "ACG";
    }
    for(int i = 3;i < N;i++){
        for(int j = 0;j < (1 << 6);j++){
            string t;
            for(int k = 0;k < 3;k++){
                int v = (j >> (k * 2)) & 3;
                t += S[v];
            }
            for(int c = 0;c < 4;c++){
                if(S[c] == 'C'){
                    if(t[1] == 'A' && t[2] == 'G') continue;
                    if(t[1] == 'G' && t[2] == 'A') continue;
                    if(t[0] == 'A' && t[2] == 'G') continue;
                    if(t[0] == 'A' && t[1] == 'G') continue;
                }
                else if(S[c] == 'G'){
                    if(t[1] == 'A' && t[2] == 'C') continue;
                }
                int x = (j >> 2) | (c << 4);
                dp[i + 1][x] += dp[i][j];
                if(dp[i + 1][x] >= mod) dp[i + 1][x] -= mod;
            }
        }
    }
    int res = 0;
    for(int i = 0;i < (1 << 6);i++){
        res += dp[N][i];
        if(res >= mod) res -= mod;
