const lli mod = 1e9+7;
lli n, memo[101][4][4][4];

lli toi(char c) {
  if (c == 'A') return 0;
  if (c == 'C') return 1;
  if (c == 'G') return 2;
  return 3;
}

lli rec(lli i, char c, char d, char e) {
  auto& ref = memo[i][toi(c)][toi(d)][toi(e)];
  if (i == n) return 1;
  if (ref > 0) return ref;
  bool C = true, G = true;
  if ((c == 'A' || d == 'A' || e == 'A') 
      && (d == 'G' || e == 'G')) C = false;
  if (d == 'A' && e == 'C') G = false;
  lli res = 0;
  res += rec(i+1, d, e, 'A');
  if (C) res += rec(i+1, d, e, 'C');
  if (G) res += rec(i+1, d, e, 'G');
  res += rec(i+1, d, e, 'T');
  return ref = res % mod;
}

int main() {
  cin >> n;
  lli ans = rec(0, 'T', 'T', 'T');
  for (lli i=3; i<=100; ++i) {
    fill(&memo[0][0][0][0], &memo[100][3][3][3]+1, 0);
    n = i;
    cout << i << '\t' << rec(0, 'T', 'T', 'T') << endl;
  }
  cout << ans << endl;
  return 0;
}

