inline bool check(string s) {
    string ss = "";
    ss += s[0];
    ss += s[1];
    ss += s[2];
    if (s1 == ss) return false;
    if ((int)s.size() == 3) return true;
    ss = "";
    ss += s[1];
    ss += s[2];
    ss += s[3];
    if (s1 == ss) return false;
    return true;
}

