constexpr char CHARS[] = { 'A', 'C', 'G', 'T' };

bool is_ok(const string& s) {
    i64 n = SIZE(s);

    if(s.find("AGC") != string::npos) return false;
    FOR(i, 0, n-1) {
        string t(s);
        swap(t[i], t[i+1]);
        if(t.find("AGC") != string::npos) return false;
    }
    return true;
}

void solve() {
    i64 N; RD(N);

    unordered_map<string,ModP> cur;
    REP(i, 4) REP(j, 4) REP(k, 4) {
        string s { CHARS[i], CHARS[j], CHARS[k] };
        if(is_ok(s)) {
            ++cur[s];
        }
    }

    REP(m, N-3) {
        unordered_map<string,ModP> nex;
        for(const auto& p : cur) {
            string s; ModP v; tie(s,v) = p;
            for(char c : CHARS) {
                string t = s + c;
                if(is_ok(t)) {
                    nex[t.substr(1)] += cur[s];
                }
            }
        }
        cur = move(nex);
    }

    ModP ans = 0;
    for(const auto& p : cur) {
        ModP v; tie(ignore,v) = p;
        ans += v;
    }

