int dfs(string s, int l, int n) {

  // cout << "dfs: " + s << endl;
  int tmp = 0;

  // if (l == n) return 1;
  if (l == n) {
    // cout << s << endl;
    return 1;
  }

  if (l > 2 && s[l - 3] == 'A' && (s[l - 1] == 'G' || s[l - 2] == 'G')) {
    tmp += dfs(s + 'A', l + 1, n) + dfs(s + 'G', l + 1, n) + dfs(s + 'T', l + 1, n);
  } else if ((s[l - 2] == 'A' && s[l - 1] == 'G') || (s[l - 2] == 'G' && s[l - 1] == 'A')) {
    tmp += dfs(s + 'A', l + 1, n) + dfs(s + 'G', l + 1, n) + dfs(s + 'T', l + 1, n);
  } else if (s[l - 2] == 'A' && s[l - 1] == 'C') {
    tmp += dfs(s + 'A', l + 1, n) + dfs(s + 'C', l + 1, n) + dfs(s + 'T', l + 1, n);
  } else {
    tmp += dfs(s + 'A', l + 1, n) + dfs(s + 'C', l + 1, n) + dfs(s + 'G', l + 1, n) + dfs(s + 'T', l + 1, n);
  }

  return tmp;

}

