bool check(int num) {
	vector<int> line(4);
	for (int i = 0; i < 4; ++i) {
		line[i] = num & 3;
		num /= 4;
	}
	bool flag = true;
	for (int i = 0; i < 3; ++i) {
		if (line[i] != i + 1) {
			flag = false;
			break;
		}
	}
	if (flag) {
		return true;
	}
	flag = true;
	for(int i= 1;i<4;++i){
		if (line[i] != i) {
			flag = false;
			break;
		}
	}
	if (flag) {
		return true;
	}
	for (int i = 0; i < 3; ++i) {
		swap(line[i], line[i + 1]);
		flag = true;
		for (int j = 0; j < 3; ++j) {
			if (line[j] != j + 1) {
				flag = false;
				break;
			}
		}
		if (flag) {
			return true;
		}
		flag = true;
		for (int j = 1; j < 4; ++j) {
			if (line[j] != j) {
				flag = false;
				break;
			}
		}
		if (flag) {
			return true;
		}
		swap(line[i], line[i + 1]);
	}
	return false;
}

int addn(int x, int a) {
	return (x * 4 + a) % 256;
}
int func(int place, int num) {
	if (place == N) {
		return 1;
	}
	if (dp[place][num] >= 0) {
		return dp[place][num];
	}
	int res = 0;
	for (int i = 0; i < 4; ++i) {
		int nn = addn(num, i);
		if (check(nn))continue;
		res = (res + func(place + 1, nn)) % MOD;
	}
	dp[place][num] = res;
	return res;
}
int main() {
	cin >> N;
	cout << func(0, 0) << endl;
	return 0;
}

