using namespace std;
typedef long long ll;
const int MOD = 1e9 + 7;

int n;
ll dp[110][64]; // [i][j] # of valid string when we read till ith character and
                // last 3 characters are j.
vector<string> candidate = {"A", "C", "G", "T"};
vector<string> invalid = {"AGC", "ACG", "GAC"};

bool valid(string pre, string tmp) {
  return find(invalid.begin(), invalid.end(), tmp) == invalid.end() &&
         pre + tmp.substr(1, 2) != "AGC" &&
         pre + tmp.substr(0, 1) + tmp.substr(2, 1) != "AGC";
}

void solve() {
  map<string, int> m;
  int index = 0;
  for (auto c1 : candidate) {
    for (auto c2 : candidate) {
      for (auto c3 : candidate) {
        string tmp = c1 + c2 + c3;
        if (valid("", tmp)) {
          dp[2][index] = 1;
        }
        m[tmp] = index++;
      }
    }
  }

  for (int i = 2; i < n; i++) {
    for (auto x : m) {
      for (auto c : candidate) {
        string tmp = x.first.substr(1, 2) + c;
        if (valid(x.first.substr(0, 1), tmp)) {
          dp[i + 1][m[tmp]] += dp[i][m[x.first]];
          dp[i + 1][m[tmp]] %= MOD;
        }
      }
    }
  }
  ll sum = 0;
  for (auto x : m) {
    sum = (sum + dp[n - 1][x.second]) % MOD;
  }
  cout << sum << endl;
}

int main() {
  cin >> n;
  solve();
}

