ll repeatSquaring(ll n, ll p)
{
  if (p == 0)
    return 1;
  if (p % 2 == 0)
  {
    ll t = repeatSquaring(n, p / 2);
    return (t * t) % MOD;
  }
  return (n * repeatSquaring(n, p - 1)) % MOD;
}

int main()
{
  ll n;
  cin >> n;

  ll ans = repeatSquaring(4, n);
  ll res = 0;
  ll num[110] = {};
  num[3] = 3;
  for (ll i = 4; i <= 105; ++i)
  {
    num[i] = (3 * ((i - 3 + 1) * repeatSquaring(4, i - 3) % MOD) % MOD) % MOD;
    for (ll j = i - 3; j >= 3; --j)
    {
      num[i] = (num[i] - (6 * num[i - j]) % MOD + MOD) % MOD;
    }
    num[i] = (num[i] + (2 * ((i - 4 + 1) * (repeatSquaring(4, i - 4) - num[i - 4] + MOD) % MOD) % MOD) % MOD) % MOD;
    for (ll j = i - 4; j >= 3; --j)
    {
      num[i] = (num[i] - (4 * num[i - j]) % MOD + MOD) % MOD;
    }
  }
  res = num[n];
  ans -= res;
  if (ans < 0)
    ans += MOD;
  cout << ans << endl;

  return 0;
}

