                        dp[3][i][j][k][l] = 0;
                    } else if(i == 0 && j == 2 && l == 1){
                        //AG*C
                        dp[3][i][j][k][l] = 0;
                    } else {
                        dp[3][i][j][k][l] = 1;
                    }
                }
            }
        }
    }

    for(int m = 4; m < N; m++){
        for(int i = 0; i < 4; i++){
            for(int j = 0; j < 4; j++){
                for(int k = 0; k < 4; k++){
