namespace xelmh_RCR {
    class RCR {
        // Residue Class Ring
        static constexpr ll NIL = -1;
        static constexpr int64_t MOD = 1'000'000'007;
//        static constexpr int64_t MOD = 998'244'353;

        ll val;
    public:
        RCR(ll x) : val(x >= 0 ? x % MOD : MOD - (-x) % MOD) {}
        RCR(signed x) : val(x >= 0 ? x % MOD : MOD - (-x) % MOD) {}
        RCR(ull x) : val(x % MOD) {}
        RCR(unsigned x) : val(x % MOD) {}
        RCR() : val{NIL} {}

        bool is_nil() { return val == NIL; }

        RCR pow(ll n) const {
            ll r = 1, a = val;
            while (n) {
                if (n & 1) {
                    r *= a;
                    r %= MOD;
                }
                a *= a;
                a %= MOD;
                n /= 2;
            }
            return {r};
        }
        RCR inv() const { /* return Inverse */ assert(val != 0);
            return this->pow(MOD - 2);
        }

        void operator+=(const RCR &a) {
            val += a.val;
            if (val >= MOD) val -= MOD;
        }
        void operator-=(const RCR &a) {
            val -= a.val;
            if (val < 0) val += MOD;
        }
        void operator*=(const RCR &a) {
            val *= a.val;
            val %= MOD;
        }
        void operator/=(const RCR &a) {
            val *= a.inv().val;
            val %= MOD;
        }

        RCR operator+(const RCR &x) const {
            ll v = val + x.val;
            return {v};
        }
        RCR operator-(const RCR &x) const {
            ll v = val - x.val;
            return {v};
        }
        RCR operator*(const RCR &x) const {
            ll v = val * x.val;
            return {v};
        }
        RCR operator/(const RCR &x) const {
            ll v = val * x.inv().val;
            return {v};
        }

        bool operator==(const RCR &x) const { return x.val == val; }
        bool operator!=(const RCR &x) const { return x.val != val; }

        friend istream &operator>>(istream &is, RCR &r) {
            ll tmp;
            is >> tmp;
            r = tmp;
            return is;
        }
        friend ostream &operator<<(ostream &os, const RCR &r) { return os << r.val; }
    };

    RCR fact(ll N) {
        /* N -> N! */
        static vector<RCR> cal(1, RCR{1});
        assert(N >= 0);

        if (cal.size() > N) return cal[N];
        else {
            RCR nm = fact(N - 1);
            assert(cal.size() == N);
            cal.push_back(nm * N);
            return cal.back();
        }
    }

    /* N, k -> N C k */
    RCR choose(ll N, ll k) {
        // N! / k!(N-k!)
        RCR ans = fact(N) / (fact(k) * fact(N - k));
        return ans;
    }

    RCR operator "" _mod(unsigned long long x) {
        return RCR{x};
    }
}
using namespace xelmh_RCR;


class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    int N;
    bool input() {
        is >> N;
        return !!is;
    }

    const map<char, int> mp{
              {'A', 1}, {'C', 2}
            , {'G', 3}, {'T', 4}};

    int num(const string& s) {
        int ans = 0;
        for (auto &&c : s) {
            ans *= 5;
            ans += mp.at(c);
        } // end c
        return ans;
    }

    bool equitable(int k, const string& s){
        auto rs = s.rbegin();
        while(*rs == 0) rs++;
        while(rs != s.rend()){
            if(*rs != '.' and k%5 != mp.at(*rs)){
                return true;
            }
            rs++; k /= 5;
        }
        return false;
    }

    bool valid(int k){
        return k % 125  != num("AGC") and k / 5 != num("AGC")
            and (k%125 != num("GAC") and k/5 != num("GAC"))
            and (k%125 != num("ACG") and k/5 != num("ACG"))
            and equitable(k, "AG.C")
            and equitable(k, "A.GC");
    }

    vector<vector<RCR>> memo;

    // A, C, G, T -> 1, 2, 3, 4,
    RCR dp(int d, int pp){
        if(!valid(pp)) return 0;
        if(d >= N) return 1;
        pp %= 125;
        if(!memo[d][pp].is_nil()) return memo[d][pp];

        memo[d][pp] = dp(d+1, (pp*5+1));
        memo[d][pp] += dp(d+1, (pp*5+2));
        memo[d][pp] += dp(d+1, (pp*5+3));
        memo[d][pp] += dp(d+1, (pp*5+4));
        return memo[d][pp];
    }

    void run();
};

int main(int argc, char *argv[]) {
    cin.tie(nullptr);
