const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n;
ll dp[69][105];
str ng[] = {"AGC", "ACG", "GAC"};
str semi_ng[] = {"AGA", "AGG", "AGT", "ATG"};
str ss[] = {"A", "C", "G", "T"};
msl si;

str get_key(ll bit){
    str key = "";
    rep(j, 3) {key += ss[bit % 4]; bit /= 4;}
    return key;
}

bool is_ng(str key){
    rep(j, 3) if (key == ng[j]) return true;
    return false;
}

bool is_seming(str key){
    rep(j, 4) if (key == semi_ng[j]) return true;
    return false;
}

void solve(){
    /*
    NG
    AGC
    ACG
    GAC
    AGA & C
    AGG & C
    AGT & C
    ATG & C
    */

    rep(bit, 4 * 4 * 4){
        str key = get_key(bit);
        si[key] = bit;
        rep(i, n + 1) dp[bit][0] = 0;
        dp[bit][3] = 1 - is_ng(key);
    }

    For(i, 4, n + 1) rep(bit, 4 * 4 * 4){
        str key = get_key(bit);
        str key2 = substring(key, 1, 3);
        rep(j, 4){
            str next = ss[j];
            if (is_ng(key2 + next)) continue;
            else if (is_seming(key) && next == "C") continue;
            ll b = si[key2 + next];
            dp[b][i] += dp[bit][i - 1]; dp[b][i] %= MOD;
        }
        // prl4(i, bit, key, dp[i][bit]);
    }
    rep(bit, 4 * 4 * 4){
        if (is_ng(get_key(bit))) continue;
        answer += dp[bit][n]; answer %= MOD;
    }
    prl(answer);
}

int main(void){
    in1(n);
    solve();
    // assert(n <= 10000);
    return 0;
}

