static const llong MOD = 1.0e+9 + 7;

int main()
{
  // Input
  int N;
  std::cin >> N;
  assert(3 <= N and N <= 100);

  // Initialization
  std::vector<llong> dp(1 + N, 0);

  // Initial condition
  dp[0] = 1;
  dp[1] = 4;
  dp[2] = 16;
  dp[3] = 61;

  // DP main
  for (int i = 4; i <= N; ++i) {
    dp[i] = 4 * dp[i - 1] - 2 * dp[i - 3] - 6 * dp[i - 4];
    dp[i] %= MOD;
  }

  // Output
  if (dp[N] < 0)
    dp[N] += MOD;

  std::cout << dp[N] << std::endl;

  return 0;
}

