long An(int);
long Bn(int);

long An(int n) {
	if (n == 3) {
		return 63;
	}
	else  {
		return An(n - 1) * 3 + Bn(n);
	}
}

long Bn(int n) {
	if (n == 3) {
		return 15;
	}
	if (n == 4) {
		return 54;
	}
	if (n == 5) {
		return Bn(n - 1) + Bn(n - 2) * 3 + 116 ;
	}
	if (n == 6) {
		return Bn(n - 1) + An(n - 3) * 5 + Bn(n - 2) * 3 + Bn(n - 3) * 3 + 96;
	}
	else {
		return Bn(n - 1) + An(n - 3) * 5 + Bn(n - 2) * 3 + An(n - 4) * 6 + Bn(n - 3) * 3;
	}
}

