ll f(int x, int y){
    if(y==0)return 1;
    if(dp[x][y]!=-1)return dp[x][y];
    int a=(x/16)%4, b=(x/4)%4, c=x%4;
    ll r=f(b*16+c*4, y-1);
    r += f(b*16+c*4+3, y-1);
    r%=M;
    if(b!=0||c!=1)r+=f(b*16+c*4+2, y-1);
    r%=M;
    if(!(b==0&&c==2)&&
       !(b==2&&c==0)&&
       !(a==0&&b==2)&&
       !(a==0&&c==2)
    ){
        r += f(b*16+c*4+1, y-1);
    }
    return dp[x][y]=r;
}
