bool valid(string s)
{
	int n = (int) s.size();
	if(s.find("132") != string::npos)
		return false;
	for (int i = 0; i < n - 1; ++i)
	{
		swap(s[i], s[i + 1]);
		if(s.find("132") != string::npos)
			return false;
		swap(s[i], s[i + 1]);
	}
	return true;
}
void calc_matrix()
{
