	int cnt = 0;
	for (int i = 1; i <= 64; ++i)
	{
		for (int j = 1; j <= 64; ++j)
		{
			s = rm[i], t = rm[j];
			if(s[1] != t[0] || s[2] != t[1])
				continue;
			s.push_back(t.back());
			if(valid(s))
			{
				A[j][i] = 1;
			}
		}
	}
}
void matrix_mul(ll x[][65], ll y[][65])
{
	ll c[65][65];
	memset(c, 0, sizeof(c));
	for (int i = 1; i <= 64; ++i)
	{
		for (int j = 1; j <= 64; ++j)
		{
			for (int k = 1; k <= 64; ++k)
			{
				c[i][j] += x[i][k] * y[k][j];
				c[i][j] %= MOD;
			}
		}
	}
	for (int i = 1; i <= 64; ++i)
		for (int j = 1; j <= 64; ++j)
			x[i][j] = c[i][j];
}
ll matrix_expo(ll mat[][65], int b)
{
	ll res[65][65], cnt = 0;
	memset(res, 0, sizeof(res));
	for (int i = 1; i <= 64; ++i)
	{
		res[i][i] = 1;
	}
	while(b != 0)
	{
		if(b & 1)
			matrix_mul(res, mat);
		matrix_mul(mat, mat);
		b /= 2;
	}
	for (int i = 1; i <= 64; ++i)
	{
		for (int j = 1; j <= 64; ++j)
		{
			cnt += res[i][j];
			cnt %= MOD;
		}
	}
	return cnt;
}
