#define mod 1000000007

char lis[] = "AGCT";

bool check_agc(char *last) {
    if ((last[0] == 'A') && (last[1] == 'G') && (last[2] == 'C')) return false;
    if ((last[1] == 'A') && (last[2] == 'G') && (last[3] == 'C')) return false;
    return true;
}

bool check(char *last) {
    if (!check_agc(last)) return false;
    for (int i=0; i<3; i++) {
        char buf = last[i];
        last[i] = last[i+1];
        last[i+1] = buf;
        if (!check_agc(last)) {
            last[i+1] = last[i];
            last[i] = buf;
            return false;
        }
        last[i+1] = last[i];
        last[i] = buf;
    }
    return true;
}

int ret_num(char *s) {
    int buf = 0;
    if (s[0] == 'G') buf += 16;
    else if (s[0] == 'C') buf += 32;
    else if (s[0] == 'T') buf += 48;
    if (s[1] == 'G') buf += 4;
    else if (s[1] == 'C') buf += 8;
    else if (s[1] == 'T') buf += 12;
    if (s[2] == 'G') buf += 1;
    else if (s[2] == 'C') buf += 2;
    else if (s[2] == 'T') buf += 3;
    return buf;
}

long int counting(char *last, int count, int n, int **mem) {
    long int buf = 0;
    if (count == n) return 1;
    int num = ret_num(last);
    if (mem[count][num] != -1) return mem[count][num];
    for (int i=0; i<4; i++) {
        last[3] = lis[i];
        if (check(last)) {
            char last_next[5];
            for (int i=0; i<4; i++) {
                last_next[i] = last[i+1];
            }
            last_next[4] = '\0';
            buf = (buf + counting(last_next, count+1, n, mem)) % mod;
        }
    }
    mem[count][num] = buf;
    return buf;
}

