typedef int32_t i32;

#define POS(i,j) (((i) & 1) * m + (j) % m)

int cond (i32 n) {
  i32 d[4];
  for (i32 i = 0; i < 4; ++i) {
    d[i] = n % 4;
    n /= 4;
  }
  for (i32 i = 0; i < 2; ++i) {
    if (d[i] ==0 && d[i + 1] == 1 && d[i + 2] ==2) {
      return 0;
    }
  }
  for (i32 j = 0; j < 3; ++j) {
    i32 swap = d[j];
    d[j] = d[j + 1];
    d[j + 1] = swap;
    for (i32 i = 0; i < 2; ++i) {
      if (d[i] ==0 && d[i + 1] == 1 && d[i + 2] ==2) {
	return 0;
      }
    }
    swap = d[j + 1];
    d[j + 1] = d[j];
    d[j] = swap;
  }
  return 1;
}

void run (void) {
  i32 n;
  scanf ("%" SCNi32, &n);
  i32 m = 1 << 8;
  i32 *dp = (i32 *) calloc (2 * m, sizeof (i32));
  i32 *ok = (i32 *) calloc (m, sizeof (i32));
  for (i32 i = 0; i < m; ++i) {
    ok[i] = cond (i);
  }
  const i32 mod = 1000000007;
  dp[POS(0, m - 1)] = 1;
  for (i32 i = 1; i <= n; ++i) {
    memset (dp + POS(i,0), 0, m * sizeof (i32));
    for (i32 j = 0; j < m; ++j) {
      for (i32 k = 0; k < 4; ++k) {
	dp[POS(i, 4 * j + k)] += dp[POS(i - 1, j)];
	dp[POS(i, 4 * j + k)] %= mod;
      }
    }
    for (i32 j = 0; j < m; ++j) {
      dp[POS(i, j)] *= ok[j];
    }
  }
  i32 sum = 0;
  for (i32 i = 0; i < m; ++i) {
    sum = (sum + dp[POS(n, i)]) % mod;
  }
  printf("%" PRIi32 "\n", sum);
}

int main (void) {
  run ();
  return 0;
}

