bool isaaa (ull x[]) {
	if (x[0] == 0 && x[1] == 1 && x[2] == 2) return true;
	if (x[1] == 0 && x[2] == 1 && x[3] == 2) return true;
	return false;
}

bool isagc (ull x[]) {
	if (isaaa(x)) return true;

	x[0] ^= (x[1] ^= (x[0] ^= x[1]));
	if (isaaa(x)) return true;
	x[0] ^= (x[1] ^= (x[0] ^= x[1]));

	x[2] ^= (x[1] ^= (x[2] ^= x[1]));
	if (isaaa(x)) return true;
	x[2] ^= (x[1] ^= (x[2] ^= x[1]));

	x[2] ^= (x[3] ^= (x[2] ^= x[3]));
	if (isaaa(x)) return true;
	x[2] ^= (x[3] ^= (x[2] ^= x[3]));

	return false;
}

