#include<stdio.h>
#define MOD 1000000007
#define modadd(rhs,lhs) (((rhs)+(lhs)) % MOD)

int main(void){
    register int i,j,k,l,m;
    int n;
    scanf("%d",&n);
    static long dp[101][4][4][4]; //0:A 1:G 2:C 3:T
    for(i = 0;i < 4;i++)for(j = 0;j < 4;j++)for(k = 0;k < 4;k++)dp[3][i][j][k] = 1;
    dp[3][0][1][2] = 0;     dp[3][0][2][1] = 0;     dp[3][1][0][2] = 0;

    for(i = 3;i < n;i++)for(j = 0;j < 4;j++)for(k = 0;k < 4;k++)for(l = 0;l < 4;l++)for(m = 0;m < 4;m++){
        if(k == 0 && l == 1 && m == 2)continue;
        if(k == 0 && l == 2 && m == 1)continue;
        if(k == 1 && l == 0 && m == 2)continue;
        if(j == 0 && k == 1 && m == 2)continue;
        if(j == 0 && l == 1 && m == 2)continue;
        dp[i+1][k][l][m] = modadd(dp[i+1][k][l][m],dp[i][j][k][l]);
    }
    long ans = 0;
    for(i = 0;i < 4;i++)for(j = 0;j < 4;j++)for(k = 0;k < 4;k++)ans = modadd(ans,dp[n][i][j][k]);
    printf("%ld",ans);
    return 0; 
}

