typedef long long ll;

typedef enum {
	A = 1,
	C = 2, 
	G = 3,
	T = 4
} ACGT;

const ll mod = (long long)(1e9) + 7ll;

ll n;
//ll dp[now][s1][s2][s3][s4];
ll dp[105][5][5][5][5];

ll dfs(int now, int s1, int s2, int s3, int s4)
{
	if (dp[now][s1][s2][s3][s4] != -1) {
		return dp[now][s1][s2][s3][s4];
	}

	if ((s2 == A && s3 == G && s4 == C) ||
		(s2 == A && s3 == C && s4 == G) ||
		(s2 == G && s3 == A && s4 == C) ||
		(s1 == A && s2 == G && s4 == C) ||
		(s1 == A && s3 == G && s4 == C)) {
		return 0;
	}

	if (now == n) {
		return 1;
	}

	dp[now][s1][s2][s3][s4] = 0;
	for (ACGT i = A; i <= T; i++) {
		dp[now][s1][s2][s3][s4] += dfs(now + 1, s2, s3, s4, i);
		dp[now][s1][s2][s3][s4] %= mod;
	}

	return dp[now][s1][s2][s3][s4];
}


