fun solve() {
    val n = nextLong()
    val dp = Array(n.toInt() + 1) { Array(5) { Array(5) {  LongArray(5) { 0L } } } }
    for (i in 1..4) {
        dp[1][i][0][0] = 1L
    }
    for (i in 1..4) {
        for (j in 1..4) {
            dp[2][i][j][0] += dp[1][j][0][0]
        }
    }
    for (i in 1..4) {
        for (j in 1..4) {
            for (k in 1..4) {
                if(i == 2 && j == 3 && k == 1) continue
                if(i == 3 && j == 2 && k == 1) continue
                if(i == 2 && j == 1 && k == 3) continue
                dp[3][i][j][k] += dp[2][j][k][0]
            }
        }
    }


    for (i in 3 until n) {
        for (now in 1..4) {
            for (past1 in 1..4) {
                for (past2 in 1..4) {
                    for (past3 in 1..4) {
                        if(now == 2 && past1 == 3 && past2 == 1) continue
                        if(now == 2 && past2 == 3 && past3 == 1) continue
                        if(now == 3 && past1 == 2 && past2 == 1) continue
                        if(now == 2 && past1 == 3 && past3 == 1) continue
                        if(now == 2 && past1 == 1 && past2 == 3) continue
                        dp[i + 1][now][past1][past2] = (dp[i + 1][now][past1][past2] + dp[i][past1][past2][past3]) % MOD
                    }
                }
            }
        }
    }

    var ans = 0L
    for (past1 in 1..4) {
        for (past2 in 1..4) {
            for (past3 in 1..4) {
