    var MOD = 1000000007
    // A C G T -> 0 1 2 3
    dp[0][0][0][0] = 1
    for (len in 0 until N)
        for (c1 in 0 until 4)
            for (c2 in 0 until 4)
                for (c3 in 0 until 4) {
                    if (dp[len][c1][c2][c3] == 0) continue
