                        if (a == 2 && c1 == 1 && c3 == 0) continue // 0 ? 1 2
                        if (a == 2 && c2 == 1 && c3 == 0) continue // 0 1 ? 2
                        // S = ...... c3 c2 c1
                        // nextS = ...... c2 c1 a
                        dp[len + 1][a][c1][c2] += dp[len][c1][c2][c3]
                        dp[len + 1][a][c1][c2] %= MOD
                    }
                }
    var ans = 0
