import java.lang.Math.*

const val MOD = 1000000007L
const val INF = 1000000007L

fun main(args: Array<String>) {

    val n = readInt()

    val dp = Array(n + 1) {
        return@Array mutableMapOf<String, Long>()
    }

    val cCheckArray = arrayOf("AG", "GA")

    fun dfs(now: Int, prev: String): Long {
        if (dp[now].containsKey(prev)) {
            return dp[now][prev]!!
        }
        if (now == n) {
            return 1
        }

        var ret = 0L
        "AGCT".forEach {
            when (it) {
                'A', 'T' -> {
                    ret += dfs(now + 1, prev.substring(1, 3) + it) % MOD
                }
                'C' -> {
                    if (cCheckArray.contains(prev.substring(1, 3)) || prev.substring(
                            0,
                            2
                        ) == "AG" || (prev[0] == 'A' && prev[2] == 'G')
                    ) {
                        return@forEach
                    }
                    ret += dfs(now + 1, prev.substring(1, 3) + it) % MOD
                }
                'G' -> {
                    if (prev.subSequence(1, 3) == "AC") {
                        return@forEach
                    }
                    ret += dfs(now + 1, prev.substring(1, 3) + it) % MOD
                }
            }
        }
        dp[now][prev] = ret % MOD
        return dp[now][prev]!!
    }

    val ans = dfs(0, "TTT")
    println(ans)
}

