	static void solve() {
		int n = ni();
		long[][] dp = new long[n+1][4];
		for(int i=0;i<4;i++) dp[1][i] = 1;
		for(int i=1;i<n;i++) {
			for(int j=0;j<4;j++) {
				long res = 0;
				for(int k=0;k<4;k++) {
					res += dp[i][k];//ACGT
					res %= mod;
				}
				dp[i+1][j] = res;
				//だめな物を引いていく
				if(j==0) continue;
				if(j==1) {//C
					//3個前がA, 1個前C以外の3つ
					if(i - 2 >= 0) {
						dp[i+1][j] -= dp[i-2][0] * 2 % mod;
						if(dp[i+1][j] < 0) dp[i+1][j] += mod;
					}
					//3個前がA, 2個前A以外の3つ
					if(i - 2 >= 0) {
						dp[i+1][j] -= dp[i-2][0] * 2 % mod;
						if(dp[i+1][j] < 0) dp[i+1][j] += mod;
					}
					//ダブル引きしたAGGCを足す
					if(i - 2 >= 0) {
						dp[i+1][j] += dp[i-2][0];
						dp[i+1][j] %= mod;
					}
					//2個前A, 1個前Gの物
					dp[i+1][j] -= dp[i-1][0];
					if(dp[i+1][j] < 0) dp[i+1][j] += mod;
					//2個前G, 1個前Aの物
					dp[i+1][j] -= dp[i-1][2];
					if(dp[i+1][j] < 0) dp[i+1][j] += mod;
				}
				if(j == 2) {//G
					//2個前A, 1個前Cの物
					dp[i+1][j] -= dp[i-1][0];
					if(i - 2 >= 0) dp[i+1][j] += dp[i-2][2];
					dp[i+1][j] %= mod;
					if(dp[i+1][j] < 0) dp[i+1][j] += mod;					
				}
				if(j == 3) continue;
			}
		}
		long ans = 0;
		for(int i=0;i<4;i++) {
			ans += dp[n][i];
			ans %= mod;
		}
		out.println(ans);
	}

