public class Main {
	public static void main(String[] args) throws Exception {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		sc.close();

		long[] dp = new long[n + 1];
		dp[0] = 1;
		dp[1] = 4;
		dp[2] = 16;
		dp[3] = 61;
		for (int i = 4; i <= n; i++) {
			// A, T
			dp[i] = getMod(dp[i - 1] * 2);
			// G
			dp[i] += getMod(dp[i - 1] - dp[i - 3]);
			dp[i] = getMod(dp[i]);
			// C
			dp[i] += getMod(getMod(dp[i - 1] - getMod(dp[i - 3] * 2)) - getMod(dp[i - 4] * 2));
			dp[i] = getMod(dp[i]);
		}
		System.out.println(dp[n]);
	}

	static long getMod(long val) {
		int mod = 1000000007;
		while (val < 0) {
			val += mod;
		}
		return val % mod;
	}
}

import java.util.*;
public class Main {

	/*
	 * 122D
	 * 
	 * This problem might be hard for students
	 *
	 * General Idea:
	 * This is a DP Problem and they should know how to MOD 1e9+7
	 * We note that only substrings with length 4 of
	 * ?AGC, ?ACG, ?GAC, A?GC, AG?C are not good (? means any character)
	 * So we can build our dp solution based on that
	 * DP[n][4th last character][3rd last character][2nd last character][last character]
	 * = number of good strings of length n and ends with those 4 characters
	 * The transition will be what happens when we append either character A G C T to it
	 * 
	 * Implementation Specific:
	 * This problem might be confusing to code because it has a lot of information
	 * Assume we are adding TTTT to the start of the string (This will not change our answer)
	 * So our initial case or base case is dp[0][T][T][T][T] = 1
	 * Also because storing character will use a lot of memory, we will compress it 
	 * A = 0, G = 1, C = 2, T = 3, ? = -1
	 * We will also store all the bad substrings encoded this way
	 * 
	 * Questions that might come up:
	 * Q: If ?AGC is bad then isn't AGC? also bad?
	 * A: Yes but this case is already covered by ?AGC
	 * Q: Do we have store the last 4 characters why not last 3 characters
	 * A: Yes you can also do it by storing last 3 characters.
	 *
	 * Time Complexity O(N * 4^4 * C) C is some large constant, Memory Complexity O(N * 4^4)
	 * 
	 */

	static char AGCT[] = {'A', 'G', 'C', 'T'};
	static int bad[][] = {{-1,0,1,2},{-1,0,2,1},{-1,1,0,2},{0,-1,1,2},{0,1,-1,2}};

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		long DP[][][][][] = new long[N+1][4][4][4][4];
		DP[0][3][3][3][3] = 1;
		for(int i = 0; i<N; i++) {
			for(int a = 0; a<4; a++) {
				for(int b = 0; b<4; b++) {
					for(int c = 0; c<4; c++) {
						for(int d = 0; d<4; d++) {
							//Those for loops above me control the state
							for(int e = 0; e<4; e++) {
								boolean good = true;
								for(int k = 0; k<5; k++) {
									boolean tempgood = true;
									tempgood &= (bad[k][0] == -1 ? true : bad[k][0] == b);
									tempgood &= (bad[k][1] == -1 ? true : bad[k][1] == c);
									tempgood &= (bad[k][2] == -1 ? true : bad[k][2] == d);
									tempgood &= (bad[k][3] == -1 ? true : bad[k][3] == e);
									if(tempgood) {
										good = false;
									}
								}
								if(good) {
									DP[i+1][b][c][d][e] += DP[i][a][b][c][d];
									DP[i+1][b][c][d][e] %= 1000000007;
								}
							}
						}
					}
				}
			}
		}
		long ans = 0;
		for(int a = 0; a<4; a++) {
			for(int b = 0; b<4; b++) {
				for(int c = 0; c<4; c++) {
					for(int d = 0; d<4; d++) {
						ans += DP[N][a][b][c][d];
						ans %= 1000000007;
					}
				}
			}
		}
		System.out.println(ans);
	}
}

import java.util.*;

public class Main {
  private static boolean valid4(String s) {
    // invalid XACG AXCG, ACXG
    return !s.matches(".AGC") && !s.matches("A.GC") && !s.matches("AG.C") && !s.matches("AGC.")
        && !s.matches(".AGC") && !s.matches(".ACG") && !s.matches(".GAC");
  }

  private static boolean valid3(String s) {
    return !s.equals("AGC") && !s.equals("ACG") && !s.equals("GAC");
  }

  private static long solve(int n) {
    if (n == 1) {
      return 4;
    } else if (n == 2) {
      return 16;
    }

    char[] atcg = new char[]{'A', 'T', 'C', 'G'};

    long[] init = new long[64];
    ArrayList<ArrayList<Integer>> transform = new ArrayList<ArrayList<Integer>>();
    for (int i = 0; i < 64; i++) {
      transform.add(new ArrayList<Integer>());
    }

    for (int a = 0; a < atcg.length; a++) {
      for (int b = 0; b < atcg.length; b++) {
        for (int c = 0; c < atcg.length; c++) {
          int indexSrc = (a << 4) | (b << 2) | c;
          String str3 = "" + atcg[a] + atcg[b] + atcg[c];
          if (valid3(str3)) {
            init[indexSrc] = 1;
          } else {
            init[indexSrc] = 0;
            continue;
          }

          for (int d = 0; d < atcg.length; d++) {
            int indexDst = (b << 4) | (c << 2) | d;
            String str4 = str3 + atcg[d];
            if (valid4(str4)) {
              transform.get(indexDst).add(indexSrc);
//              System.out.println(str3 + " - " + str4);
            }
          }
        }
      }
    }

    long[] src = init;
    for (int i = 3; i < n; i++) {
      long[] dst = new long[64];
      for (int j = 0; j < 64; j++) {
        dst[j] = 0;
        for (int indexSrc: transform.get(j)) {
          dst[j] += src[indexSrc];
          dst[j] %= 1000000007;
        }
      }
      src = dst;
    }

    long sum = 0;
    for (int i = 0; i < 64; i++) {
      sum += src[i];
      sum %= 1000000007;
    }
    return sum;
  }

  public static void main(String[] args) {
    Scanner s = new Scanner(System.in);

    System.out.println(solve(s.nextInt()));
  }
}

