		List<String> str = new ArrayList<>();
		Map<String, Integer> hm = new HashMap<>();
		for (int i0 = 0; i0 < 4; i0++) {
			for (int i1 = 0; i1 < 4; i1++) {
				for (int i2 = 0; i2 < 4; i2++) {
