    		if(depth >= 3 &&
    			((c3 == 0 &&  c2 == 1 && c1 == 2)			// A G C
    			|| (c3 == 1 &&  c2 == 0 && c1 == 2)			// G A C
       			|| (c3 == 0 &&  c2 == 2 && c1 == 1))) {		// A C G
    				dp[c3][c2][c1][depth] = 0;
