public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        DWeLikeAGC solver = new DWeLikeAGC();
        solver.solve(1, in, out);
        out.close();
    }

    static class DWeLikeAGC {
        char[] agct = {'A', 'G', 'C', 'T'};
        int N;
        final long MOD = (long) 1e9 + 7;
        HashMap<String, Long>[] memo = new HashMap[101];

        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            for (int i = 0; i < 101; i++) {
                memo[i] = new HashMap<>();
            }
            N = in.nextInt();
            long ans = dfs(0, "TTT");
            out.println(ans);
        }

        boolean ok(String last4) {
            if ((last4.startsWith("A") && last4.endsWith("GC")) ||
                    (last4.startsWith("AG") && last4.endsWith("C")) ||
                    last4.startsWith("AGC") ||
                    last4.startsWith("ACG") ||
                    last4.startsWith("GAC")) {
                return false;
            }
            return true;
        }

        long dfs(int i, String last3) {
            if (memo[i].containsKey(last3)) return memo[i].get(last3);
            if (i == N) return 1;
            long ret = 0;
            for (char c : agct) {
                String last4 = c + last3;
                if (ok(last4)) {
                    ret += dfs(i + 1, c + last3.substring(0, 2));
                    ret %= MOD;
                }
            }
            memo[i].put(last3, ret);
            return ret;
        }

    }

    static class FastScanner implements Closeable {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        public boolean hasNext() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
            return hasNextByte();
        }

        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) {
                throw new NumberFormatException();
            }
            while (true) {
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                } else if (b == -1 || !isPrintableChar(b)) {
                    return minus ? -n : n;
                } else {
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }

        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }

        public void close() {
            try {
                in.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

    }
}

