        int N = nint();
        final int A = 1, G = 2, C = 3, T = 4;
        final int[] cs = {A, G, C, T};

        int[][][][] dp = new int[N+1][5][5][5]; // [文字列の長さL][L-2文字目][L-1文字目][L文字目]
        dp[0][4][4][4] = 1;

        for (int n = 1; n <= N; n++) {
            for (int c3 : cs) {
                for (int c2 : cs) {
                    for (int c1 : cs) {
                        for (int cn : cs) {
