                            if (           c2 == G && c1 == A && cn == C) continue;
                            if (c3 == A &&            c1 == G && cn == C) continue;
                            if (c3 == A && c2 == G            && cn == C) continue;

                            dp[n][c2][c1][cn] += dp[n-1][c3][c2][c1];
                            dp[n][c2][c1][cn] %= MOD;
                        }
                    }
                }
            }
        }

        int ans = 0;
        for (int c3 : cs) {
            for (int c2 : cs) {
                for (int c1 : cs) {
