	public void run() {
		PrintWriter out = new PrintWriter(System.out);
		InputReader sc = new InputReader(System.in);

		try {
			/**
			 * Bit 全探索
				//Nは要素数 (bit全探索)
				//計算量はO(2^N) Nが0-20~25 (30は多分無理)くらいまでしか使えない
				Out: for (int bit = 0; bit < (1 << N); bit++) {
					System.out.println(Integer.toBinaryString(bit));
					In: for (int j = 0; j < N; j++) {
						System.out.println(1 & (bit >> j));
						//1が立ってれば対象。例えば101だったら1桁目と3桁目は選ばれている
						//「二進数iをjだけ右にビットシフトしたときの、iの1桁目と1とでビット論理積をとって、演算結果が1であるなら処理を実行する」
						if ((1 & bit >> j) == 1) {
						}
					}
				}
			 *
			 * 表示系
			 *   System.out.println();
			 *   System.out.println("i:" + i + " ,j:" + j);
			 *   System.out.println(Arrays.toString(A));
			 *
			 * Sort (Arrays)
			 *  Integer[] A = new Integer[N];
			 *    Desc : Arrays.sort(A , Collections.reverseOrder());
			 *    Asc  : Arrays.sort(A);
			 *
			 * 定義系
			 *   int[] s = new int[M];
			 *   ArrayDeque<Integer> deq= new ArrayDeque<>();//先頭と末尾への要素の追加・先頭と末尾の要素の取り出しと削除が定数時間
			 *   ArrayList<Integer> arr = new ArrayList<Integer>();//定数時間
			 *   HashMap<Integer,Integer> hm = new HashMap<>(); //定数時間
			 *
			 *   //要素の追加と、最小の要素の取り出しと削除が対数時間
			 *   PriorityQueue<Integer> pq = new PriorityQueue<>();//昇順
			 *   PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder()); //逆順。降順
			 *
			 *   TreeSet<Integer> ts = new TreeSet<>();//対数時間(重複はできない)
			 *
			 * 文字系
			 *   String S = sc.next().trim();
			 *   for (char i = 'a'; i <= 'z'; i++) {}
			 *   S.substring(1,2);//あいうえお → い
			 *   S.substring(0,1); // 1文字目をとりたいとき
			 *   文字列のSort
			 *    String sorted = S.chars().sorted().collect(StringBuilder::new,StringBuilder::appendCodePoint, StringBuilder::append) .toString();
			 */

			int N = sc.nextInt();

			//AGC,ACG,GACがダメ
			//2文字前まで保持していれば良い。
			//1=A 2=C 3=G 4=T
			long[][][][] dp = new long[N + 1][4][4][4];//2つめが1文字目、3つめが上2文字目、4つめが上3文字目

			//初期値セット

			for (int i = 0; i < 4; i++) {
				for (int j = 0; j < 4; j++) {
					for (int k = 0; k < 4; k++) {
						//GAC, ACG, A?GC, AG?C
						//GAC, ACG,       AGC (3文字の時にダメなやつ)
						if ((i == 2 && j == 0 && k == 1) || (i == 0 && j == 1 && k == 2)
								|| (i == 0 && j == 2 && k == 1)) {
							dp[3][i][j][k] = 0;
						} else {
							dp[3][i][j][k] = 1;
						}
					}
				}
			}

			for (int n = 4; n <= N; n++) {
				for (int i = 0; i < 4; i++) {
					for (int j = 0; j < 4; j++) {
						for (int k = 0; k < 4; k++) {
							//GAC, ACGはだめ
							if ((i == 2 && j == 0 && k == 1) || (i == 0 && j == 1 && k == 2)
									|| (i == 0 && j == 2 && k == 1)) {

							} else {
								for (int plus = 0; plus < 4; plus++) {
									//A?GC, AG?Cはダメ
									if ((i == 0 && k == 2 && plus == 1) || (i == 0 && j == 2 && plus == 1)
											|| (j == 2 && k == 0 && plus == 1) || (j == 0 && k == 1 && plus == 2)) {
									} else {
										dp[n][i][j][k] += dp[n - 1][j][k][plus] % mod;
									}
								}
							}
						}
					}
				}
			}

			long ans = 0;
			for (int i = 0; i < 4; i++) {
				for (int j = 0; j < 4; j++) {
					for (int k = 0; k < 4; k++) {
						//out.println("N:" + N + " ,i:" + i + " ,j:" + j + " ,k:" + k + " ,dp :" + dp[N][i][j][k]);
						ans += dp[N][i][j][k] % mod;
					}
				}
			}

			out.println(ans % mod);
			//Flushしてからcloseするのが無難
			out.flush();
			out.close();

		} catch (ArithmeticException ae) {
			ae.printStackTrace();
			throw new RuntimeException();
		} catch (Exception e) {
			e.printStackTrace();
			throw new RuntimeException();
		}

	}

	public static long comb(long a, long b) {
		if (a < b)
			return 0;
		long res = 1;
		long inv = pow(fact(Math.min(b, a - b)), mod - 2);
		for (long i = a; i > a - Math.min(b, a - b); i--) {
			res *= i;
			res %= mod;
		}
		res *= inv;
		res %= mod;
		return res;
	}

	public static long pow(long x, long n) {
		long res = 1;
		while (n > 0) {
			if ((n & 1) == 1) {
				res *= x;
				res %= mod;
			}
			x *= x;
			x %= mod;
			n >>= 1;
		}
		return res;
	}

	public static long fact(long n) {
		long res = 1;
		while (n > 0) {
			res *= n;
			res %= mod;
			n--;
		}
		return res;
	}

