public class Main{

	static int [][][][]memo;
	static int MOD=(int)1e9+7,n;

	static boolean ok(int x1,int x2,int x3,int x4) {
		if(x1==0 && x2==1 && x3==2)
			return false;
		if(x2==0 && x3==1 && x4==2)
			return false;
		return true;
	}
	static int dp(int idx,int x1,int x2,int x3) {
		if(idx==n)
			return 1;
		if(memo[x1][x2][x3][idx]!=0)
			return memo[x1][x2][x3][idx];
		int ans=0;
		for(int nxt=0;nxt<=3;nxt++) {
			if(!ok(x1,x2,x3,nxt))
				continue;
			if(!ok(x1,x2,nxt,x3))
				continue;
			if(!ok(x1,x3,x2,nxt))
				continue;
			if(!ok(x2,x1,x3,nxt))
				continue;
			ans+=dp(idx+1, x2, x3, nxt);
			ans%=MOD;
		}
		return memo[x1][x2][x3][idx]=ans;
	}

