    dp[0][0][0][0] = 1;
    for (int i = 0; i < n; i++) {
      for (int s = 0; s <= 4; s++) {
        for (int t = 0; t <= 4; t++) {
          for (int u = 0; u <= 4; u++) {
            for (int k = 1; k <= 4; k++) {
              if (check(s, t, u, k)) {
                dp[i + 1][t][u][k] += dp[i][s][t][u];
                dp[i + 1][t][u][k] %= mod;
              }
            }
          }
        }
      }
    }

    long ret = 0;
    for (int s = 0; s <= 4; s++) {
      for (int t = 0; t <= 4; t++) {
