        int[][][][] dp = new int[n][4][4][4];
        int mod = 1000000007;
        for (int j = 0; j < 4; j++) {
            for (int k = 0; k < 4; k++) {
                for (int l = 0; l < 4; l++) {
                    if ((j == 0 && k == 2 && l == 1) || (j == 0 && k == 1 && l == 2) || (j == 2 && k == 0 && l == 1))
                        continue;
                    dp[2][j][k][l] = 1;
                }
            }
        }
        for (int i = 2; i < n - 1; i++) {
            for (int j = 0; j < 4; j++) {
                for (int k = 0; k < 4; k++) {
                    for (int l = 0; l < 4; l++) {
                        for (int m = 0; m < 4; m++) {
                            if (check(j, k, l, m))
                                dp[i + 1][k][l][m] = (dp[i + 1][k][l][m] + dp[i][j][k][l]) % mod;
                        }
                    }
                }
            }
        }
        long ans = 0;
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                for (int k = 0; k < 4; k++) {
                    ans = (ans + dp[n - 1][i][j][k]) % mod;
                }
            }
        }
        out.println(ans);
    }

    static boolean check(int j, int k, int l, int m) {
        int a = 0, c = 1, g = 2, t = 3;
