	for(int x = 0; x < 64; x ++) {
		int i = x % 4;
		int j = x / 4 % 4;
		int k = x / 16 % 4;
		if(ng(-1, i, j, k)) continue;
		dp[3][i][j][k] = 1;
	}
	for(int a = 4; a <= num; a ++) {
		for(int x = 0; x < 256; x ++) {
			int i = x % 4;
			int j = x / 4 % 4;
			int k = x / 16 % 4;
			int l = x / 64 % 4;
			if(ng(i, j, k, l)) continue;
			dp[a][j][k][l] += dp[a - 1][i][j][k];
		}
		for(int x = 0; x < 64; x ++) {
			int i = x % 4;
			int j = x / 4 % 4;
			int k = x / 16 % 4;
			dp[a][i][j][k] = mod(dp[a][i][j][k]);
		}
	}
	long ans = 0;
	for(int x = 0; x < 64; x ++) {
		int i = x % 4;
		int j = x / 4 % 4;
		int k = x / 16 % 4;
		ans += dp[num][i][j][k];
		ans = mod(ans);
	}

	prtln(ans);
