    private boolean ng (int a, int b, int c) {
        return (a == 1 && b == 2 && c == 3);
    }

    private void solve() {
        try {
            long seven = (long) Math.pow(10, 9) + 7;
            n = sc.nextInt();
            long ans = 0;
            long[][][][] dp = new long[n+1][4][4][4];

            dp[0][0][0][0] = 1;

            for (int i = 0; i < n; i++) {
                for (int a = 0; a < 4; a++) {
                    for (int b = 0; b < 4; b++) {
                        for (int c = 0; c < 4; c++) {
                            for (int d = 0; d < 4; d++) {
                                if(ng(b, c, d) || ng(c, b, d) || ng(b, d, c))
                                    continue;
                                if(ng(a, c, d) || ng(a, b, d))
                                    continue;
                                dp[i+1][b][c][d] += dp[i][a][b][c];
                                dp[i+1][b][c][d] %= seven;
                            }
                        }
                    }
                }
            }

            for(int a=0; a<4; a++)
                for(int b=0; b<4; b++)
                    for(int c=0; c<4; c++)
                        ans = (ans + dp[n][a][b][c]) % seven;

            System.out.println(ans);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

