import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Scanner;
import java.util.Set;

public class Main {
    static final int MODULUS = 1_000_000_007;
    static final char[] ALPHABET = { 'A', 'C', 'G', 'T' };
    static final Set<String> EXCLUDED_PATTERNS = new HashSet<>(
            Arrays.asList("AGC", "GAC", "ACG", "AGGC", "ATGC", "AGTC"));

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();

        System.out.println(solve(N));

        sc.close();
    }

    static int solve(int N) {
        Map<String, Integer> patternToWayNum = new HashMap<>();
        patternToWayNum.put("", 1);

        for (int i = 0; i < N; ++i) {
            Map<String, Integer> nextPatternToWayNum = new HashMap<>();
            for (String pattern : patternToWayNum.keySet()) {
                for (char letter : ALPHABET) {
                    String nextPattern = pattern + letter;
                    if (nextPattern.length() > 4) {
                        nextPattern = nextPattern.substring(nextPattern.length() - 4);
                    }
                    String nextLastThreePattern = (nextPattern.length() == 4) ? nextPattern.substring(1) : nextPattern;

                    if (!EXCLUDED_PATTERNS.contains(nextPattern) && !EXCLUDED_PATTERNS.contains(nextLastThreePattern)) {
                        nextPatternToWayNum.put(nextPattern,
                                addMod(nextPatternToWayNum.getOrDefault(nextPattern, 0), patternToWayNum.get(pattern)));
                    }
                }
            }

            patternToWayNum = nextPatternToWayNum;
        }

        return patternToWayNum.values().stream().mapToInt(x -> x).reduce(Main::addMod).getAsInt();
    }

    static int addMod(int x, int y) {
        return (x + y) % MODULUS;
    }
}

import java.util.*;

public class Main {

    private static final long MOD = 1000000007L;

    public static void main(String[] args) {
        Main main = new Main();
        main.solve();
    }

    private boolean isAGC(String str) {
        if (str.contains("AGC")) {
            return true;
        } else if (str.contains("GAC")) {
            return true;
        } else if (str.contains("ACG")) {
            return true;
        } else if (str.startsWith("A") && str.endsWith("GC")) {
            return true;
        } else if (str.startsWith("AG") && str.endsWith("C")) {
            return true;
        }
        return false;
    }

    private void solve() {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        if (N == 3) {
            System.out.println(61);
            return;
        }

        String ACGT = "ACGT";
        Map<String, Long> map = new HashMap<>();
        for (char c1 : ACGT.toCharArray()) {
            for (char c2 : ACGT.toCharArray()) {
                for (char c3 : ACGT.toCharArray()) {
                    for (char c4 : ACGT.toCharArray()) {
                        String key = "" + c1 + c2 +c3 + c4;
                        map.put(key, isAGC(key) ? 0L : 1L);
                    }
                }
            }
        }
        for (int cur = 4; cur < N; cur += 1) {
            Map<String, Long> nextMap = new HashMap<>();
            for (String key : map.keySet()) {
                for (char next : ACGT.toCharArray()) {
                    String nextKey = (key + next).substring(1);
                    if (!isAGC(nextKey)) {
                        if (!nextMap.containsKey(nextKey)) {
                            nextMap.put(nextKey, 0L);
                        }
                        long nextValue = nextMap.get(nextKey) + map.get(key);
                        nextValue %= MOD;
                        nextMap.put(nextKey, nextValue);
                    }
                }
            }
            map = nextMap;
        }

        long ans = 0L;
        for (long value : map.values()) {
            ans += value;
            ans %= MOD;
        }
        System.out.println(ans);
    }

}

