	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int N = in.nextInt();

		int[][][][] dp = new int[N + 1][4][4][4];
		dp[0][3][3][3] = 1;

		// AGC,ACG,GAC,AG?C,A?GC
		// A=0, C=1, G=2, T=3
		for (int len = 1; len <= N; len++) {
