import java.util.Arrays;
import java.util.Scanner;
import java.util.stream.IntStream;

/**
 * 解説通りに作成したソースコード
 * 
 * https://atcoder.jp/contests/abc122/submissions/4696453 にも参考
 */
public class Main {

	/** 文字の種類数 */
	private static final int N = 4;

	private static final long MOD = 1_000_000_007L;

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt();
			long[][][][] memo = new long[N + 1][N + 1][N + 1][n];
			IntStream.rangeClosed(0, N).forEach(i -> IntStream.rangeClosed(0, N)
					.forEach(j -> IntStream.rangeClosed(0, N).forEach(k -> Arrays.fill(memo[i][j][k], -1))));
			System.out.println(dp(n, N, N, N, 0, memo));
		}
	}

	/**
	 * 処理結果を再帰的に計算する
	 * 
	 * @param n     総文字数
	 * @param x1    三つ前の文字（0:A、1:C、2:G、3:T、4:その他）
	 * @param x2    二つ前の文字（0:A、1:C、2:G、3:T、4:その他）
	 * @param x3    一つ前の文字（0:A、1:C、2:G、3:T、4:その他）
	 * @param index 現在処理している文字の場所
	 * @param memo  処理結果を保存する配列
	 * @return 処理結果
	 */
	private static long dp(int n, int x1, int x2, int x3, int index, long[][][][] memo) {
		if (n == index) {
			return 1L;
		}
		if (memo[x1][x2][x3][index] >= 0) {
			return memo[x1][x2][x3][index];
		}
		long answer = 0L;
		for (int next = 0; next < N; next++) {
			if (ok(x1, x2, x3, next) && ok(x1, x2, next, x3) && ok(x1, x3, x2, next) && ok(x2, x1, x3, next)) {
				answer = (answer + dp(n, x2, x3, next, index + 1, memo)) % MOD;
			}
		}
		return memo[x1][x2][x3][index] = answer;
	}

	/**
	 * x1x2x3x4で組合せた文字列に「AGC」が含まれないかをチェックする
	 * 
	 * @param x1 一つ目の文字（0:A、1:C、2:G、3:T、4:その他）
	 * @param x2 二つ目の文字（0:A、1:C、2:G、3:T、4:その他）
	 * @param x3 三つ目の文字（0:A、1:C、2:G、3:T、4:その他）
	 * @param x4 四つ目の文字（0:A、1:C、2:G、3:T、4:その他）
	 * @return x1x2x3x4で組合せた文字列に「AGC」が含まれない場合true
	 */
	private static boolean ok(int x1, int x2, int x3, int x4) {
		return !((0 == x1) && (2 == x2) && (1 == x3)) && !((0 == x2) && (2 == x3) && (1 == x4));
	}
}

import java.util.*;
class Main {
    public static void main(String[] args) {
	Scanner sc = new Scanner(System.in);
	int N = sc.nextInt();
	long[][][][] a = new long[N+1][4][4][4];
	a[0][3][3][3] = 1;
	long mod = (long)Math.pow(10,9)+7;
	for(int len = 1; len<N+1; len++) {
	    for(int i = 0; i<4; i++) {
		for(int j = 0; j<4; j++) {
		    for(int k = 0; k<4; k++) {
			if(a[len-1][i][j][k] == 0) continue;
			for(int e = 0; e<4;e++) {
			    if(e==2 && i==1 && j==0) continue;
			    if(e==2 && i==0 && j==1) continue;
			    if(e==1 && i==2 && j==0) continue;
			    if(e==2 && i==1 && k==0) continue;
			    if(e==2 && j==1 && k==0) continue;

			    a[len][e][i][j] += a[len-1][i][j][k];
			    if(a[len][e][i][j]>=mod) a[len][e][i][j] %= mod;
			}
		    }
		}
	    }
	}
	long ans = 0;
	for(int i=0; i<4; i++) {
	    for(int j=0; j<4; j++) {
		for(int k=0; k<4; k++) {
		    ans += a[N][i][j][k];
		    ans %= mod;
		}
	    }
	}
	System.out.println(ans);

    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        try (CustomReader in = new CustomReader()) {
            new Main().execute(in);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void execute(CustomReader in) throws IOException {
        final int N = Integer.parseInt(in.readLine());
        final char[] arr = {'A', 'T', 'G', 'C'};
        HashMap<String, Integer> countBySuffix = new HashMap<>();
        for (char c1 : arr) {
            for (char c2 : arr) {
                for (char c3 : arr) {
                    StringBuilder str = new StringBuilder();
                    str.append(c1);
                    str.append(c2);
                    str.append(c3);
                    String suffix = str.toString();
                    if (suffix.endsWith("AGC") || suffix.endsWith("ACG") || suffix.endsWith("GAC")) {
                        continue;
                    }
                    countBySuffix.put(suffix, 1);
                }
            }
        }


        for (int i = 4; i <= N; i++) {
            HashMap<String, Integer> countBySuffix2 = new HashMap<>();
            for (String suf : countBySuffix.keySet()) {
                for (char c : arr) {
                    String st = suf + Character.toString(c);
                    if (st.endsWith("AGC") || st.endsWith("ACG") || st.endsWith("GAC")) {
                        continue;
                    } if (st.endsWith("GC") && st.charAt(0) == 'A') {
                        continue;
                    } if(st.endsWith("C") && st.startsWith("AG")){
                        continue;
                    }
                    else {
                        String suf2 = st.substring(1, 4);
                        int cnt = (countBySuffix2.getOrDefault(suf2, 0) + countBySuffix.get(suf)) % MOD;
                        countBySuffix2.put(suf2, cnt);
                    }
                }
            }
            countBySuffix = countBySuffix2;
        }

        long total = 0L;
        for (String sf : countBySuffix.keySet()) {
//            System.out.println(sf + ":" + countBySuffix.get(sf));
            total = (total + countBySuffix.get(sf)) % MOD;
        }
        System.out.println(total);
    }


    static class CustomReader extends BufferedReader {

        private static final int DEFAULT_BUF_SIZE = 2048;
        // private static final int DEFAULT_BUF_SIZE = 4096;
        // private static final int DEFAULT_BUF_SIZE = 8192;
        //private static final int DEFAULT_BUF_SIZE = 16384;
        // private static final int DEFAULT_BUF_SIZE = 1048576;

        public CustomReader() throws IOException {
            super(new InputStreamReader(System.in), DEFAULT_BUF_SIZE);
        }

        public int[] readLineAsIntArray() throws IOException {
            String[] strArray = this.readLine().split(" ");
            int[] intArray = new int[strArray.length];
            for (int i = 0, n = strArray.length; i < n; i++) {
                intArray[i] = Integer.parseInt(strArray[i]);
            }
            return intArray;
        }

        public int[][] readAsIntMatrix(int rows, int columns) throws IOException {
            int[][] matrix = new int[rows][columns];
            for (int i = 0; i < rows; i++) {
                String[] r = this.readLine().split(" ");
                for (int j = 0; j < columns; j++) {
                    matrix[i][j] = Integer.parseInt(r[j]);
                }
            }
            return matrix;
        }
    }
}

import java.util.*;

public class Main {
    static int A = 0;
    static int C = 1;
    static int G = 2;
    static int T = 3;
    static long MOD = (long) 1e9 + 7;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();

        // A => 0, C => 1, G => 2, T => 3
        // AGC, ACG, GAC
        // 021, 012, 201

        // dp[n][i][i - 1][i - 2]

        long[][][][] dp = new long[N][4][4][4];

        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                for (int k = 0; k < 4; k++) {
                    if ((i == 0 && j == 2 && k == 1) || (i == 0 && j == 1 && k == 2) || (i == 2 && j == 0 && k == 1)) {
                        dp[2][k][j][i] = 0;
                    } else {
                        dp[2][k][j][i] = 1;
                    }
                }
            }
        }


        // A => 0, C => 1, G => 2, T => 3
        // おしり <- CGA, GCA, CAG
        //          120, 210, 102

        // dp[n][i][i - 1][i - 2]

        for (int n = 3; n < N; n++) {
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    for (int k = 0; k < 4; k++) {
                        for (int l = 0; l < 4; l++) {
//                            System.out.println((isValid(i, j, k, l) ? "isValid" : "isNotValid") + ".... i:" + i + " ,j:" + j + " , k:" + k + ", l:" + l);

                            if (isValid(k, j, i, l)) {
                                dp[n][k][j][i] += dp[n - 1][j][i][l];
                                dp[n][k][j][i] %= MOD;
                            }
                        }
                    }
                }
            }
        }

        long count = 0;
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                for (int k = 0; k < 4; k++) {
                    count += dp[N - 1][k][j][i];
                    count %= MOD;
                }
            }
        }

        System.out.println(count);
    }

    static boolean isValid(int k, int j, int i, int l) {
        // AGC, ACG, GAC
        if ((i == A && j == G && k == C)
                || (i == A && j == C && k == G)
                || (i == G && j == A && k == C)
        ) {
            return false;
        } else if ((k == C && j == G && l == A) || (k == C && i == G && l == A)) {
            // 4文字
            return false;
        } else {
            return true;
        }
    }
}

