	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		if (n == 3) {
		    System.out.println(61);
		    return;
		}
		int[][][][] dp = new int[n + 1][4][4][4];
		for (int i = 0; i < 4; i++) {
		    for (int j = 0; j < 4; j++) {
		        for (int k = 0; k < 4; k++) {
		            dp[3][i][j][k] = 1;
		        }
		    }
