    		for (int i = 0; i < 4; i++) {
    		    for (int j = 0; j < 4; j++) {
    		        for (int k = 0; k < 4; k++) {
    		            for (int l = 0; l < 4; l++) {
    		                if (checkNum(i, j, k, l)) {
    		                    continue;
    		                }
    		                dp[a][j][k][l] += dp[a - 1][i][j][k];
    		                dp[a][j][k][l] %= MOD;
    		            }
    		        }
    		    }
    		}
		}
		int ans = 0;
		for (int i = 0; i < 4; i++) {
		    for (int j = 0; j < 4; j++) {
