/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();

            if (n == 3) {
                out.printLine(61);
                return;
            }

            final long MOD = (long) 1e9 + 7;

            long[] dp = new long[1 << 8];
            Arrays.fill(dp, 1);
            for (int i = 0; i < 1 << 8; i++) {
                int[] a = new int[4];
                for (int j = 0; j < 4; j++) {
                    a[j] = (i >> (j * 2)) & 3;
                }

                if (a[0] == 0 && a[1] == 1 && a[2] == 2
                        || a[1] == 0 && a[2] == 1 && a[3] == 2) {
                    dp[i] = 0;
                }

                for (int j = 0; j < 3; j++) {
                    int tmp = a[j];
                    a[j] = a[j + 1];
                    a[j + 1] = tmp;

                    if (a[0] == 0 && a[1] == 1 && a[2] == 2
                            || a[1] == 0 && a[2] == 1 && a[3] == 2) {
                        dp[i] = 0;
                    }

                    tmp = a[j];
                    a[j] = a[j + 1];
                    a[j + 1] = tmp;
                }
            }

            for (int i = 0; i < n - 4; i++) {
                long[] next = new long[1 << 8];
                for (int j = 0; j < 1 << 8; j++) {
                    for (int k = 0; k < 4; k++) {
                        int cand = (j << 2) & ~(-1 << 8) | k;
                        if (dp[cand] == 0) continue;

                        next[cand] = (next[cand] + dp[j]) % MOD;
                    }
                }
                dp = next;
            }

            long ans = 0;
            for (int i = 0; i < 1 << 8; i++) {
                ans = (ans + dp[i]) % MOD;
            }

            out.printLine(ans);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void printLine(long i) {
            writer.println(i);
        }

        public void printLine(int i) {
            writer.println(i);
        }

    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
		int n = in.nextInt();
		System.out.println(solve(n));
		in.close();
	}

	static int[][][][] h = new int[4][4][4][100];
	static int[] hi = new int[256];

	private static int solve(int n) {
		for (int i = 0; i < 4; i++)
			for (int j = 0; j < 4; j++)
				for (int k = 0; k < 4; k++)
					for (int l = 0; l < 100; l++)
						h[i][j][k][l] = -1;
		hi['A'] = 0;
		hi['G'] = 1;
		hi['C'] = 2;
		hi['T'] = 3;
		char[] s = new char[n];
		return fnc(s, 0);
	}

	private static int fnc(char[] s, int i) {
		if (!chk(s, i - 1))
			return 0;
		if (i == s.length)
			return 1;
		if (hist(s, i) >= 0)
			return hist(s, i);
		int c = 0;
		s[i] = 'A';
		c += fnc(s, i + 1);
		c %= 1000000007;
		s[i] = 'G';
		c += fnc(s, i + 1);
		c %= 1000000007;
		s[i] = 'T';
		c += fnc(s, i + 1);
		c %= 1000000007;
		s[i] = 'C';
		c += fnc(s, i + 1);
		c %= 1000000007;
		histSave(s, i, c);
		return c;
	}

	private static void histSave(char[] s, int m, int c) {
		if (m > 3)
			h[hi[s[m - 3]]][hi[s[m - 2]]][hi[s[m - 1]]][m] = c;
	}

	private static int hist(char[] s, int m) {
		if (m < 4)
			return -1;
		return h[hi[s[m - 3]]][hi[s[m - 2]]][hi[s[m - 1]]][m];
	}

	private static boolean chk(char[] s, int r) {
		if (r < 2)
			return true;
		if (s[r - 2] == 'A' && s[r - 1] == 'G' && s[r] == 'C')
			return false;
		if (s[r - 2] == 'A' && s[r - 1] == 'C' && s[r] == 'G')
			return false;
		if (s[r - 2] == 'G' && s[r - 1] == 'A' && s[r] == 'C')
			return false;
		if (r < 3)
			return true;
		if (s[r - 3] == 'A' && s[r - 1] == 'G' && s[r] == 'C')
			return false;
		if (s[r - 3] == 'A' && s[r - 2] == 'G' && s[r] == 'C')
			return false;
		return true;
	}
}

