static class CodeJam
{
    static bool Safe(string s)
    {
        string s3 = s.Substring(Math.Max(0, s.Length - 3));

        if (s3 == "AGC") { return false; }
        if (s3 == "GAC") { return false; }
        if (s3 == "ACG") { return false; }

        if (s.Length == 4)
        {
            if (s[0] == 'A' && s[1] == 'G' && s[3] == 'C') { return false; }
            if (s[0] == 'A' && s[2] == 'G' && s[3] == 'C') { return false; }
        }

        return true;
    }

    static long Solve(int N)
    {
        var C = new[] { 'A', 'C', 'G', 'T' };
        var dp1 = new Dictionary<string, long>();
        foreach (char c1 in C)
        {
            foreach (char c2 in C)
            {
                dp1[c1.ToString() + c2.ToString()] = 1;
            }
        }
        for (int i = 2; i < N; ++i)
        {
            var dp2 = new Dictionary<string, long>();
            foreach (var key1 in dp1.Keys)
            {
                foreach (char c in C)
                {
                    string key2 = key1 + c.ToString();
                    if (Safe(key2))
                    {
                        string key = key2.Substring(Math.Max(key2.Length - 3, 0));
                        if (!dp2.ContainsKey(key)) { dp2[key] = 0; }
                        dp2[key] = (dp2[key] + dp1[key1]) % 1000000007;
                    }
                }
            }
            dp1 = dp2;
        }
        long sum = 0;
        foreach (long value in dp1.Values) { sum = (sum + value) % 1000000007; }
        return sum;
    }

    static void Main(string[] args)
    {
        int N = int.Parse(Console.ReadLine());
        Console.WriteLine(Solve(N));
    }
}

using System;
