public class Program
{
    public static readonly int Mod = 1000000007;

    public static bool solve(int a, int b, int c, int d)
    {
        if((a == 1 || b == 1) && c == 2 && d == 3)
        {
            return true;
        }
        if(a == 1 && b == 2 && (b == 3 || d == 3))
        {
            return true;
        }

        if(a == 1 && (b == 2 || c == 2) && (b == 3 || c == 3))
        {
            return true;
        }

        if ((a == 1 || b == 1) && (a == 2 || b == 2) && c == 3)
        {
            return true;
        }

        return false;
    }

    public static void Main(string[] args)
    {
        int N = Scanner.Int;

        var dp = new int[N + 1, 5, 5, 5, 2];
        dp[0, 0, 0, 0, 0] = 1;

        foreach(int i in Enumerable.Range(0, N))
        {
            foreach(int d in Enumerable.Range(1, 4))
            {
                foreach(int b1 in Enumerable.Range(0, 5))
                {
                    foreach(int b2 in Enumerable.Range(0, 5))
                    {
                        foreach (int b3 in Enumerable.Range(0, 5))
                        {
                            bool ff = solve(d, b1, b2, b3);

                            foreach (int f in Enumerable.Range(0, 2))
                            {
                                dp[i + 1, d, b1, b2, (f == 1 || ff) ? 1 : 0] += dp[i, b1, b2, b3, f];
                                dp[i + 1, d, b1, b2, (f == 1 || ff) ? 1 : 0] %= Mod;
                            }
                        }
                    }
                }
            }
        }

        int sum = 0;
        foreach (int b1 in Enumerable.Range(0, 5))
        {
            foreach (int b2 in Enumerable.Range(0, 5))
            {
                foreach (int b3 in Enumerable.Range(0, 5))
                {
                    sum += dp[N, b1, b2, b3, 0];
                    sum %= Mod;
                }
            }
        }

        Console.WriteLine(sum);
        Console.ReadLine();
    }
}

