public static class NagataKanaIsAGenius {
    public static void Main() {
        int n=int.Parse(Console.ReadLine());
        if(n==3){
            Console.WriteLine(61);
            return;
        }
        bool[]ng=new bool[256];
        for(int bs=0;bs<256;bs++){
            ng[bs]=IsNg(bs);
        }
        int[]dp=new int[64];
        for(int i=0;i<256;i++){
            if(!ng[i])Add(ref dp[i%64],1);
        }
        for(int i=4;i<n;i++){
            int[]swp=new int[64];
            for(int j=0;j<64;j++){
                for(int k=0;k<4;k++){
                    if(!ng[j*4+k])Add(ref swp[(j*4+k)%64],dp[j]);
                }
            }
            dp=swp.ToArray();
        }
        int ans=0;
        for(int i=0;i<64;i++){
            Add(ref ans,dp[i]);
        }
        Console.WriteLine(ans);
    }
    public static bool IsNg(int x){
        if(ContainsAGC(x)) return true;
        for(int i=0;i<3;i++){
            if(ContainsAGC(TwoBitsSwapped(x,i,i+1)))return true;
        }
        return false;
    }
    public static void BitSwap(ref int x, int i, int j){
        if((x>>i&1)!=(x>>j&1)){
            x^=1<<i;
            x^=1<<j;
        }
    }
    public static int TwoBitsSwapped(int x, int i, int j){
        BitSwap(ref x,2*i,2*j);
        BitSwap(ref x,2*i+1,2*j+1);
        return x;
    }
    public static bool ContainsAGC(int x){
        return (x>>6&3)==0&&(x>>4&3)==1&&(x>>2&3)==2
            || (x>>4&3)==0&&(x>>2&3)==1&&(x>>0&3)==2;
    }
    static int mod = 1000000007;
    public static void Add(ref int x, int y){
        x+=y;
        if(mod<=x)x-=mod;
    }
}

