class Program
{
    static void Main(string[] args)
    {
        var num = Input.num;
        var res = 0L;
        var com = new Modulo.Combination(101);
        res += (long)3 * (num - 2) * Modulo.Pow(4, num - 3);
        if (num > 5)
        {
            var dif = 0L;
            if (num == 6)
                dif = 6;
            else dif= (long)6 *com.Comb(num-5,2)* Modulo.Pow(4, num - 6);
            if (num == 9)
                dif -= 6;
            else if (num == 10)
                dif -= 48;
            else if(num > 8)
                dif -= (long)6 * com.Comb(num-8,3) * Modulo.Pow(4, num - 9);
            if (dif < 0) dif += Input.MOD;
            res -= dif;
        }
        if (res < 0) res += Input.MOD;
        if (num > 4)
            res -= (long)(num - 4) * Modulo.Pow(4, num - 5);

        res += (long)2 * (num - 3) * Modulo.Pow(4, num - 4);
        if (num == 8)
            res -= 2;
        else if (num > 8)
            res -= (long)2 * com.Comb(num - 7, 2) * Modulo.Pow(4, num - 8);
        if (res < 0) res += Input.MOD;
        var r = Modulo.Pow(4, num) - res % Input.MOD;
        if (r < 0) r += Input.MOD;
        WriteLine(r%Input.MOD);
    }
