    {
        static long mod = 1000000007;
        static void Main(string[] args)
        {
            //var NM = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
            var N = long.Parse(Console.ReadLine());

            var dp = new long[N + 1, 4, 4, 4];
            for (int i = 0; i < 4; i++)
            {
                for (int j = 0; j < 4; j++)
                {
                    for (int k = 0; k < 4; k++)
                    {
                        if(!((i == 0 && j == 2 && k == 3) || (i == 0 && j == 3 && k == 2) || (i == 2 && j == 0 && k == 3)))
                        {
                            dp[3, i, j, k] = 1;
                        }
                    }
                }
            }

            for (int n = 4; n <= N; n++)
            {
                for (int i = 0; i < 4; i++)
                {
                    for (int j = 0; j < 4; j++)
                    {
                        for (int k = 0; k < 4; k++)
                        {
                            for (int l = 0; l < 4; l++)
                            {
                                if (!((j == 0 && k == 2 && l == 3) || (j == 0 && k == 3 && l == 2) || (j == 2 && k == 0 && l == 3)|| (i == 0 && k == 2 && l == 3) || (i == 0 && j == 2 && l == 3)))
                                {
                                    dp[n, j, k, l] += dp[n-1, i, j, k];
                                    dp[n, j, k, l] %= mod;
                                }
                            }
                        }
                    }
                }
            }

            long ans = 0;
            for (int i = 0; i < 4; i++)
            {
                for (int j = 0; j < 4; j++)
                {
                    for (int k = 0; k < 4; k++)
                    {
                        ans += dp[N, i, j, k];
                        ans %= mod;
                    }
                }
            }
            Console.WriteLine(ans);
        }
    }
