namespace AtCoderTemplate {
    public class Program {
        public static void Main (string[] args) {
            var N = ReadInt ();

            var div = p10_9plus7;
            var dp = new long[N + 1, 4, 4, 4];
            //                  n    a  b  c
            // 「直近4文字のabcdと長さnで何通りか定まる」
            //      <=>
            // 「長さnの通りは、直近3文字と(n-1)の通りで定まる」

            var A = 0;
            var G = 1;
            var C = 2;
            var T = 3;

            foreach (var j in Interval (0, 4)) {
                foreach (var k in Interval (0, 4)) {
                    foreach (var l in Interval (0, 4)) {
                        if (j == A && k == G && l == C ||
                            j == G && k == A && l == C ||
                            j == A && k == C && l == G) {
                            dp[3, j, k, l] = 0;
                        } else {
                            dp[3, j, k, l] = 1;
                        }
                    }
                }
            }

            foreach (var n in Interval (4, N + 1)) {
                foreach (var j in Interval (0, 4)) {
                    foreach (var k in Interval (0, 4)) {
                        foreach (var l in Interval (0, 4)) {
                            dp[n, j, k, l] = Interval (0, 4).Select (i => {
                                if (j == A && k == G && l == C ||
                                    j == G && k == A && l == C ||
                                    j == A && k == C && l == G ||
                                    i == A && k == G && l == C ||
                                    i == A && j == G && l == C) {
                                    return 0L;
                                } else {
                                    return dp[n - 1, i, j, k];
                                }
                            }).Aggregate (0L, (a, b) => (a + b) % div);
                        }
                    }
                }
            }

            var ans = 0L;
            foreach (var i in Interval (0, 4)) {
                foreach (var j in Interval (0, 4)) {
                    foreach (var k in Interval (0, 4)) {
                        ans = (ans + dp[N, i, j, k]) % div;
                    }
                }
            }

            Print (ans);
        }
    }

