namespace AtCoderer
{
    public class App
    {
        const int A = 0;
        const int G = 2;
        const int C = 1;
        const int T = 3;
        public static void Solve()
        {
            //AGC A_GC AG_C GAC ACG
            int n = Parse() - 1;
            var dp = new long[4, 4, 4, 4, n+1];
            dp[3, 3, 3,3 , 0] = 1;
            for(int i = 1;i<=n;i++)
            {
                for (int c1 = 0; c1 < 4; c1++)
                {
                    for (int c2 = 0; c2 < 4; c2++)
                    {
                        for (int c3 = 0; c3 < 4; c3++)
                        {
                            for (int c4 = 0; c4 < 4; c4++)
                            {
                                if (c2 == A && c3 == G && c4 == C)
                                    continue;
                                if (c2 == G && c3 == A && c4 == C)
                                    continue;
                                if (c2 == A && c3 == C && c4 == G)
                                    continue;
                                if (c1 == A && c2 == G && c4 == C)
                                    continue;
                                if (c1 == A && c3 == G && c4 == C)
                                    continue;
                                dp[c1, c2, c3, c4, i] += dp[0, c1, c2, c3, i-1];
                                dp[c1, c2, c3, c4, i] += dp[1, c1, c2, c3, i-1];
                                dp[c1, c2, c3, c4, i] += dp[2, c1, c2, c3, i-1];
                                dp[c1, c2, c3, c4, i] += dp[3, c1, c2, c3, i-1];
                                dp[c1, c2, c3, c4, i] %= mod;
                            }
                        }
                    }
                }
            }
            long sum = 0;
            for (int c1 = 0; c1 < 4; c1++)
            {
                for (int c2 = 0; c2 < 4; c2++)
                {
                    for (int c3 = 0; c3 < 4; c3++)
                    {
                        for (int c4 = 0; c4 < 4; c4++)
                        {
                            if (c2 == A && c3 == G && c4 == C)
                                continue;
                            if (c2 == G && c3 == A && c4 == C)
                                continue;
                            if (c2 == A && c3 == C && c4 == G)
                                continue;
                            if (c1 == A && c2 == G && c4 == C)
                                continue;
                            if (c1 == A && c3 == G && c4 == C)
                                continue;
                            sum += dp[0, c1, c2, c3, n];
                            sum += dp[1, c1, c2, c3, n];
                            sum += dp[2, c1, c2, c3, n];
                            sum += dp[3, c1, c2, c3, n];
                            sum %= mod;
                        }
                    }
                }
            }
            Console.WriteLine(sum);
        }
        public static void Main(string[] args)
        {
            Solve();
            Console.ReadKey();
        }
        public static int To4(char c)
        {
            switch(c)
            {
                case 'A':
                    return 0;
                case 'C':
                    return 1;
                case 'G':
                    return 2;
                case 'T':
                    return 3;
                default:
                    throw new NotSupportedException();
            }
        }
    }
