        {
            var N = Sarray()[0];
            memo = new long[N + 1].Select(_ => new Dictionary<string, long>()).ToArray();
            WriteLine(dfs(N, "TTT"));
        }
        static bool ok(string last4)
        {
            for (var i = 0; i < 4; ++i)
            {
                var t = last4.ToCharArray();
                if (1 <= i)
                    (t[i - 1], t[i]) = (t[i], t[i - 1]);
                if (string.Join("", t).Contains("AGC"))
                    return false;
            }
            return true;
