namespace AtCoderProject
{
    class AGCT
    {
        public BigInteger sum;
        public BigInteger ag;
        public BigInteger ac;
        public BigInteger ga;

        public BigInteger three;
    }
    public class Program
    {
        public object Calc()
        {
            const int mod = 1000000007;

            var N = consoleReader.Int32();
            var result = new AGCT[N + 1];
            result[0] = new AGCT { sum = 1 };
            result[1] = new AGCT { sum = 4 };
            result[2] = new AGCT { sum = 16, ag = 1, ac = 1, ga = 1 };
            result[3] = new AGCT { sum = 61, ag = 4, ac = 3, ga = 4, three = 3 };

            for (int i = 4; i <= N; i++)
            {
                var next = new AGCT();

                next.sum = 4 * result[i - 1].sum - result[i - 1].ag - result[i - 1].ac - result[i - 1].ga - result[i - 1].three;

                next.ag = result[i - 2].sum ;
                next.ac = 3 * result[i - 3].sum - result[i - 3].ag - result[i - 3].ga - result[i - 3].three;
                next.ga = result[i - 2].sum - result[i - 2].ac;
                next.three = 3 * result[i - 3].sum;

                result[i] = next;
            }


            return result[N].sum % mod;
        }

        private readonly ConsoleReader consoleReader;
        public Program() : this(new ConsoleReader()) { }
        public Program(ConsoleReader consoleReader) { this.consoleReader = consoleReader; }
        static void Main() => Console.WriteLine(new Program().Calc());
    }

