        public static long GetAns(int n)
        {
            var mod = 1000000007;

            var i_a = 0;
            var i_g = 1;
            var i_c = 2;

            var dp = new long[n, 4, 4, 4];

            for (int i = 0; i < 4; i++)
            {
                dp[0, 0, 0, i] = 1;
            }
            for (int i = 0; i < 4; i++)
            {
                for (int j = 0; j < 4; j++)
                {
                    dp[1, 0, i, j] = 1;
                }
            }

            for (int i = 2; i < n; i++)
            {
                for (int x = 0; x < 4; x++)
                {
                    for (int y = 0; y < 4; y++)
                    {
                        for (int z = 0; z < 4; z++)
                        {
                            for (int cur = 0; cur < 4; cur++)
                            {
                                var ok = true;

                                if (cur == i_c)
                                {
                                    if (i > 1 && y == i_a && z == i_g) ok = false;
                                    if (i > 1 && y == i_g && z == i_a) ok = false;
                                    if (i > 2 && x == i_a && z == i_g) ok = false;
                                    if (i > 2 && x == i_a && y == i_g) ok = false;
                                }
                                if (cur == i_g)
                                {
                                    if (i > 1 && y == i_a && z == i_c) ok = false;
                                }

                                if (ok) dp[i, y, z, cur] += dp[i - 1, x, y, z];
                                dp[i, y, z, cur] %= mod;
                            }
                        }
                    }
                }
            }

            var ret = 0L;
            for (int i = 0; i < 4; i++)
            {
                for (int j = 0; j < 4; j++)
                {
                    for (int k = 0; k < 4; k++)
                    {
                        ret += dp[n - 1, i, j, k];
                        ret %= mod;
                    }
                }
            }
            return ret;
        }
    }

