            {
                for (int j = 0; j < 64; j++)
                {
                    for(int k = 0; k < 4; k++)
                    {
                        dp[i][j] = (dp[i][j] + dp[i - 1][j / 4 + k * 16]) % mod;
                    }
                }
                for(int k = 0; k < 4; k++)
                {
                    dp[i][gi(k, g, c)] = (dp[i][gi(k, g, c)] - dp[i - 1][gi(a, k, g)] + mod) % mod;
                    dp[i][gi(g, k, c)] = (dp[i][gi(g, k, c)] - dp[i - 1][gi(a, g, k)] + mod) % mod;
