public class PriorityQueue<T> {
    private T[] array = new T[100];
    private int size = 0;
    private readonly Comparer<T> _comparer;

    public PriorityQueue() {
        _comparer = Comparer<T>.Default;
    }

    public PriorityQueue(Comparison<T> comp) {
        _comparer = Comparer<T>.Create(comp);
    }

    public int Count { get { return size; } }

    private void Swap(int a, int b) {
        var t = array[a];
        array[a] = array[b];
        array[b] = t;
    }

    private void Expand() {
        var newlist = new T[array.Length * 2];
        Array.Copy(array, newlist, array.Length);
        array = newlist;
    }

    public bool Any() {
        return size > 0;
    }

    public void Enqueue(T newValue) {
        if (size >= array.Length) {
            Expand();
        }
        array[size++] = newValue;
        int pos = size - 1;
        while (pos > 0) {
            int parent = (pos - 1) / 2;
            if (_comparer.Compare(array[parent], array[pos]) > 0) {
                Swap(parent, pos);
                pos = parent;
            } else {
                break;
            }
        }
    }

    public T Peek() {
        return array[0];
    }

    public T Dequeue() {
        var top = array[0];
        array[0] = array[--size];
        int pos = 0;
        while (pos * 2 + 1 < size) {
            int left = pos * 2 + 1;
            int right = left + 1;
            int next = left;
            if (right < size && _comparer.Compare(array[left], array[right]) > 0) {
                next = right;
            }

            if (_comparer.Compare(array[pos], array[next]) > 0) {
                Swap(next, pos);
                pos = next;
            } else {
                break;
            }
        }

        return top;
    }
};



