  class ABC122
    {
        public void SolveD(ConsoleInput cin)
        {
            var n = cin.ReadInt;
            var MOD = (int)(Pow(10, 9) + 7);
            var dp = new int[n + 1, 4, 4, 4];
            //T=0 A=1 G=2 C=3
            //NG: AGC,ACG,GAC,AxGC,AGxC
            //NG: 123,132,213,1x23,12x3
            dp[0, 0, 0, 0] = 1;
            //DP法
            for (int i = 0; i < n; i++)
            {
                for (int a = 0; a < 4; a++)
                {
                    for (int b = 0; b < 4; b++)
                    {
                        for (int c = 0; c < 4; c++)
                        {
                            for (int d = 0; d < 4; d++)
                            {
                                //３文字のNGパターン
                                if (ng(b, c, d) || ng(b, d, c) || ng(c, b, d)) continue;
                                //４文字のNGパターン
                                if (ng(a, c, d) || ng(a, b, d)) continue;
                                dp[i + 1, b, c, d] = (dp[i + 1, b, c, d] + dp[i, a, b, c]) % MOD;
                            }
                        }
                    }
                }
            }
            var sum = 0;

            for (int a = 0; a < 4; a++)
            {
                for (int b = 0; b < 4; b++)
                {
                    for (int c = 0; c < 4; c++)
                    {
                        sum = (sum + dp[n, a, b, c]) % MOD;
                    }
                }
            }

            WriteLine(sum);
            ReadLine();
        }

        bool ng(int a, int b, int c)
        {
            return (a == 1 && b == 2 && c == 3);
        }
    }
}

