        long[] dpAXG = new long[n + 1];
        long[] dpAG = new long[n + 1];
        long[] dpAC = new long[n + 1];
        long[] dpAT = new long[n + 1];
        long[] dpGA = new long[n + 1];
        long[] dpA = new long[n + 1];
        long[] dpG = new long[n + 1];
        long[] dp = new long[n + 1];
        dp[0] = 1;
        foreach(int i in Enumerable.Range(1, n))
        {
            //dp[j] + dpAC[j] + + dpGA[j] + dpA[j] + dpAT[j] + dpAGX[j] + dpAG[j] + dpG[j] + dpAXG[j];
            int j = i - 1;
            foreach(char c in "ACGT")
            {
                if(c == 'A')
                {
                    dpA[i] += dp[j] + dpAC[j] + dpGA[j] + dpA[j] + dpAT[j] + dpAGX[j];
                    dpGA[i] += dpG[j] + dpAXG[j] + dpAG[j];
                }
                else if(c == 'C')
                {
                    dpAC[i] += dpA[j] ;
                    dp[i] += dp[j] + dpAC[j] + dpAT[j] + dpG[j];
                }
                else if(c == 'G')
                {
                    dpAXG[i] += dpAG[j] + dpAT[j] ;
                    dpG[i] += dp[j] + dpAGX[j] + dpG[j] + dpAXG[j];
                    dpAG[i] += dpA[j] + dpGA[j];
                }
