                {
                    dp[i] += dp[j] + dpAC[j] + dpAT[j] + dpAGX[j] + dpG[j] + dpAXG[j];
                    dpAGX[i] += dpAG[j] ;
                    dpAT[i] += dpA[j] + dpGA[j];
