class Program
{
    static long mod = 1000000007;
    static void Main(string[] args) {
        int n = int.Parse(Console.ReadLine());
        Console.WriteLine(solve(n));
    }

    static long solve(int n) {
        long[,,,] dp = new long[n+1,4,4,4];
        dp[0,3,3,3] = 1;
        for(int i = 0; i < n; i ++) {
            for(int z = 0; z < 4; z ++) {
                for(int y = 0; y < 4; y ++) {
                    for(int x = 0; x < 4; x ++) {
                        for(int w = 0; w < 4; w ++) {
                            //a==0,g==1,c==2,t==3
                            if(y == 0 && x == 1 && w == 2) continue; //~AGC
                            if(z == 0 && y == 1 && w == 2) continue; //AG~C
                            if(y == 0 && x == 2 && w == 1) continue; //~ACG
                            if(y == 1 && x == 0 && w == 2) continue; //~GAC
                            if(z == 0 && y == 1 && w == 2) continue; //AG~C
                            dp[i+1,y,x,w] += dp[i,z,y,x];
                            dp[i+1,y,x,w] %= mod;
                        }
                    }
                }
            }
        }
        long ans = 0;
        for(int x = 0; x < 4; x ++) {
            for(int y = 0; y < 4; y ++) {
                for(int z = 0; z < 4; z ++) {
                    ans += dp[n,x,y,z];
                    ans %= mod;
                }
            }
        }
        return ans;
    }
}

