				{
					var t = dfa[s, c];
					dp[i + 1, t] = (dp[i + 1, t] + dp[i, s]) % MOD;
				}
		WriteLine((Pow(4, N) - dp[N, 1] + MOD) % MOD);
	}
	public static long Pow(long a, long b)
	{
		var p = 1L;
		var x = a;
		while (b > 0)
		{
			if ((b & 1) == 1) p = p * x % MOD;
			b >>= 1;
			x = x * x % MOD;
		}
		return p;
	}
}

