                dp[i + 1][(j << 2 | 1) & 63] = (dp[i + 1][(j << 2 | 1) & 63] + dp[i][j]) % M;
                if (b != 1 || c != 3)
                    dp[i + 1][(j << 2 | 2) & 63] = (dp[i + 1][(j << 2 | 2) & 63] + dp[i][j]) % M;
                if (a != 1 && b != 1 && (b != 2 || c != 1) || b != 2 && c != 2)
                    dp[i + 1][(j << 2 | 3) & 63] = (dp[i + 1][(j << 2 | 3) & 63] + dp[i][j]) % M;
            }
        }
        Prt(dp[n].Sum() % M);
        sw.Flush();
    }

