class Program
{
    static void Main(string[] args)
    {
        N = sc.ReadInt();
        DP = new ModInt[N + 1, 4, 4, 4];
        Memo = new bool[N + 1, 4, 4, 4];
        var ans = Rec(0, -1, -1, -1);
        Console.WriteLine(ans);
    }

    static int N;
    static ModInt[,,,] DP;
    static bool[,,,] Memo;
    static ModInt Rec(int n, int prev1, int prev2, int prev3)
    {
        if (n == N) return 1;
        if (prev1 >= 0 && prev2 >= 0 && prev3 >= 0 && Memo[n, prev1, prev2, prev3])
            return DP[n, prev1, prev2, prev3];

        ModInt res = 0;
        for (int now = 0; now < 4; now++)
        {
            // [A, C, G, T]
            // _AG -> C (0,2,1)
            // _AC -> G (0,1,2)
            // _GA -> C (2,0,1)
            // AG_ -> C (0,2,X,1)
            // A_G -> C (0,X,2,1)
            if (prev2 == 0 && prev1 == 2 && now == 1) continue;
            if (prev2 == 0 && prev1 == 1 && now == 2) continue;
            if (prev2 == 2 && prev1 == 0 && now == 1) continue;
            if (prev3 == 0 && prev2 == 2 && now == 1) continue;
            if (prev3 == 0 && prev1 == 2 && now == 1) continue;
            res += Rec(n + 1, now, prev1, prev2);
        }
        if (prev1 >= 0 && prev2 >= 0 && prev3 >= 0)
        {
            Memo[n, prev1, prev2, prev3] = true;
            DP[n, prev1, prev2, prev3] = res;
        }
        return res;
    }
    public struct ModInt
    {
        public const long Mod = (int)1e9 + 7;
        public long num;
        public ModInt(long n) { num = n; }
        public override string ToString() { return num.ToString(); }
        public static ModInt operator +(ModInt l, ModInt r) { l.num += r.num; if (l.num >= Mod) l.num -= Mod; return l; }
        public static ModInt operator -(ModInt l, ModInt r) { l.num -= r.num; if (l.num < 0) l.num += Mod; return l; }
        public static ModInt operator *(ModInt l, ModInt r) { return new ModInt(l.num * r.num % Mod); }
        public static ModInt operator /(ModInt l, ModInt r) { return l * Inverse(r); }
        public static implicit operator ModInt(long n) { n %= Mod; if (n < 0) n += Mod; return new ModInt(n); }
        public static ModInt Pow(ModInt v, long k) { return Pow(v.num, k); }
        public static ModInt Pow(long v, long k)
        {
            long ret = 1;
            for (k %= Mod - 1; k > 0; k >>= 1, v = v * v % Mod)
                if ((k & 1) == 1) ret = ret * v % Mod;
            return new ModInt(ret);
        }
        public static ModInt Inverse(ModInt v) { return Pow(v, Mod - 2); }
        private static List<ModInt> Facs = new List<ModInt> { 1 };
        public static ModInt Fac(int n)
        {
            for (int i = Facs.Count; i <= n; i++)
            {
                Facs.Add(i * Facs[i - 1]);
            }
            return Facs[n];
        }
        public static ModInt nCr(int n, int r)
        {
            if (n < r) return 0;
            if (n == r) return 1;
            //var b = new BinomialCoefficient(n);
            //return b[n, r];
            return Fac(n) / (Fac(r) * Fac(n - r));
        }
        public static ModInt nHr(int n, int r)
        {
            return nCr(n + r - 1, r);
        }
    }
    public class BinomialCoefficient
    {
        public ModInt[] fact, ifact;
        public BinomialCoefficient(int n)
        {
            fact = new ModInt[n + 1];
            ifact = new ModInt[n + 1];
            fact[0] = 1;
            for (int i = 1; i <= n; i++)
                fact[i] = fact[i - 1] * i;
            ifact[n] = ModInt.Inverse(fact[n]);
            for (int i = n - 1; i >= 0; i--)
                ifact[i] = ifact[i + 1] * (i + 1);
            ifact[0] = ifact[1];
        }
        public ModInt this[int n, int r]
        {
            get
            {
                if (n < 0 || n >= fact.Length || r < 0 || r > n) return 0;
                return fact[n] * ifact[n - r] * ifact[r];
            }
        }
        public ModInt RepeatedCombination(int n, int k)
        {
            if (k == 0) return 1;
            return this[n + k - 1, k];
        }
    }
