        static void Main(){
            int im = 1000000007;
            long n = long.Parse(Console.ReadLine());
            long[,,,] dp = new long[n-2,4,4,4];
            const int a = 0; const int g = 1; const int c = 2; const int t = 3;

            for(int i=0;i<4;i++){
                for(int j=0;j<4;j++){
                    for(int k=0;k<4;k++){
                        dp[0,i,j,k] = 1;
                    }
                }
            }
            dp[0,a,g,c] = 0;
            dp[0,g,a,c] = 0;
            dp[0,a,c,g] = 0;

            for(int i=1;i<n-2;i++){

                dp[i,a,a,a] = dp[i-1,a,a,a] + dp[i-1,g,a,a] + dp[i-1,c,a,a] + dp[i-1,t,a,a];
                dp[i,a,a,g] = dp[i-1,a,a,a] + dp[i-1,g,a,a] + dp[i-1,c,a,a] + dp[i-1,t,a,a];
                dp[i,a,a,c] = dp[i-1,a,a,a] + dp[i-1,g,a,a] + dp[i-1,c,a,a] + dp[i-1,t,a,a];
                dp[i,a,a,t] = dp[i-1,a,a,a] + dp[i-1,g,a,a] + dp[i-1,c,a,a] + dp[i-1,t,a,a];

                dp[i,a,g,a] = dp[i-1,a,a,g] + dp[i-1,g,a,g] + dp[i-1,c,a,g] + dp[i-1,t,a,g];
                dp[i,a,g,g] = dp[i-1,a,a,g] + dp[i-1,g,a,g] + dp[i-1,c,a,g] + dp[i-1,t,a,g];
                dp[i,a,g,c] = 0                                                            ;
                dp[i,a,g,t] = dp[i-1,a,a,g] + dp[i-1,g,a,g] + dp[i-1,c,a,g] + dp[i-1,t,a,g];

                dp[i,a,c,a] = dp[i-1,a,a,c]                 + dp[i-1,c,a,c] + dp[i-1,t,a,c];
                dp[i,a,c,g] = 0                                                            ;
