                dp[i,a,c,t] = dp[i-1,a,a,c] + dp[i-1,g,a,c] + dp[i-1,c,a,c] + dp[i-1,t,a,c];

                dp[i,a,t,a] = dp[i-1,a,a,t] + dp[i-1,g,a,t] + dp[i-1,c,a,t] + dp[i-1,t,a,t];
                dp[i,a,t,g] = dp[i-1,a,a,t] + dp[i-1,g,a,t] + dp[i-1,c,a,t] + dp[i-1,t,a,t];
                dp[i,a,t,c] = dp[i-1,a,a,t] + dp[i-1,g,a,t] + dp[i-1,c,a,t] + dp[i-1,t,a,t];
                dp[i,a,t,t] = dp[i-1,a,a,t] + dp[i-1,g,a,t] + dp[i-1,c,a,t] + dp[i-1,t,a,t];


                dp[i,g,a,a] = dp[i-1,a,g,a] + dp[i-1,g,g,a] + dp[i-1,c,g,a] + dp[i-1,t,g,a];
                dp[i,g,a,g] = dp[i-1,a,g,a] + dp[i-1,g,g,a] + dp[i-1,c,g,a] + dp[i-1,t,g,a];
                dp[i,g,a,c] = 0;
                dp[i,g,a,t] = dp[i-1,a,g,a] + dp[i-1,g,g,a] + dp[i-1,c,g,a] + dp[i-1,t,g,a];

                dp[i,g,g,a] = dp[i-1,a,g,g] + dp[i-1,g,g,g] + dp[i-1,c,g,g] + dp[i-1,t,g,g];
