                dp[i,g,g,c] =               + dp[i-1,g,g,g] + dp[i-1,c,g,g] + dp[i-1,t,g,g];
                dp[i,g,g,t] = dp[i-1,a,g,g] + dp[i-1,g,g,g] + dp[i-1,c,g,g] + dp[i-1,t,g,g];

