                dp[i,g,c,g] =               + dp[i-1,g,g,c] + dp[i-1,c,g,c] + dp[i-1,t,g,c];
                dp[i,g,c,c] =               + dp[i-1,g,g,c] + dp[i-1,c,g,c] + dp[i-1,t,g,c];
