                dp[i,c,t,a] = dp[i-1,a,c,t] + dp[i-1,g,c,t] + dp[i-1,c,c,t] + dp[i-1,t,c,t];
                dp[i,c,t,g] = dp[i-1,a,c,t] + dp[i-1,g,c,t] + dp[i-1,c,c,t] + dp[i-1,t,c,t];
                dp[i,c,t,c] = dp[i-1,a,c,t] + dp[i-1,g,c,t] + dp[i-1,c,c,t] + dp[i-1,t,c,t];
