                dp[i,t,a,a] = dp[i-1,a,t,a] + dp[i-1,g,t,a] + dp[i-1,c,t,a] + dp[i-1,t,t,a];
                dp[i,t,a,g] = dp[i-1,a,t,a] + dp[i-1,g,t,a] + dp[i-1,c,t,a] + dp[i-1,t,t,a];
                dp[i,t,a,c] = dp[i-1,a,t,a] + dp[i-1,g,t,a] + dp[i-1,c,t,a] + dp[i-1,t,t,a];
                dp[i,t,a,t] = dp[i-1,a,t,a] + dp[i-1,g,t,a] + dp[i-1,c,t,a] + dp[i-1,t,t,a];

                dp[i,t,g,a] = dp[i-1,a,t,g] + dp[i-1,g,t,g] + dp[i-1,c,t,g] + dp[i-1,t,t,g];
                dp[i,t,g,g] = dp[i-1,a,t,g] + dp[i-1,g,t,g] + dp[i-1,c,t,g] + dp[i-1,t,t,g];
                dp[i,t,g,c] =               + dp[i-1,g,t,g] + dp[i-1,c,t,g] + dp[i-1,t,t,g];
                dp[i,t,g,t] = dp[i-1,a,t,g] + dp[i-1,g,t,g] + dp[i-1,c,t,g] + dp[i-1,t,t,g];

                dp[i,t,c,a] = dp[i-1,a,t,c] + dp[i-1,g,t,c] + dp[i-1,c,t,c] + dp[i-1,t,t,c];
                dp[i,t,c,g] = dp[i-1,a,t,c] + dp[i-1,g,t,c] + dp[i-1,c,t,c] + dp[i-1,t,t,c];
                dp[i,t,c,c] = dp[i-1,a,t,c] + dp[i-1,g,t,c] + dp[i-1,c,t,c] + dp[i-1,t,t,c];
                dp[i,t,c,t] = dp[i-1,a,t,c] + dp[i-1,g,t,c] + dp[i-1,c,t,c] + dp[i-1,t,t,c];

                dp[i,t,t,a] = dp[i-1,a,t,t] + dp[i-1,g,t,t] + dp[i-1,c,t,t] + dp[i-1,t,t,t];
                dp[i,t,t,g] = dp[i-1,a,t,t] + dp[i-1,g,t,t] + dp[i-1,c,t,t] + dp[i-1,t,t,t];
                dp[i,t,t,c] = dp[i-1,a,t,t] + dp[i-1,g,t,t] + dp[i-1,c,t,t] + dp[i-1,t,t,t];
                dp[i,t,t,t] = dp[i-1,a,t,t] + dp[i-1,g,t,t] + dp[i-1,c,t,t] + dp[i-1,t,t,t];

                dp[i,a,a,a] %= 1000000007; dp[i,a,a,g] %= 1000000007; dp[i,a,a,c] %= 1000000007; dp[i,a,a,t] %= 1000000007; 
                dp[i,a,g,a] %= 1000000007; dp[i,a,g,g] %= 1000000007; dp[i,a,g,c] %= 1000000007; dp[i,a,g,t] %= 1000000007; 
                dp[i,a,c,a] %= 1000000007; dp[i,a,c,g] %= 1000000007; dp[i,a,c,c] %= 1000000007; dp[i,a,c,t] %= 1000000007; 
                dp[i,a,t,a] %= 1000000007; dp[i,a,t,g] %= 1000000007; dp[i,a,t,c] %= 1000000007; dp[i,a,t,t] %= 1000000007; 

                dp[i,g,a,a] %= 1000000007; dp[i,g,a,g] %= 1000000007; dp[i,g,a,c] %= 1000000007; dp[i,g,a,t] %= 1000000007; 
