public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr; public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        N = cr;
        var dp = NewArray(4, 4, 4, new Mod(1));
        dp[0][1][2] = 0;
        dp[0][2][1] = 0;
        dp[1][0][2] = 0;
        for (int q = 3; q < N; q++)
        {
            var nx = NewArray(4, 4, 4, new Mod(0));
            for (int i = 0; i < 4; i++)
                for (int j = 0; j < 4; j++)
                    for (int k = 0; k < 4; k++)
                        for (int l = 0; l < 4; l++)
                        {
                            if (j == 0 && k == 1 && l == 2) { }
                            else if (j == 0 && k == 2 && l == 1) { }
                            else if (j == 1 && k == 0 && l == 2) { }
                            else if (i == 0 && k == 1 && l == 2) { }
                            else if (i == 0 && j == 1 && l == 2) { }
                            else
                                nx[j][k][l] += dp[i][j][k];
                        }
            dp = nx;
        }
        return dp.SelectMany(dd => dd).SelectMany(dd => dd).Aggregate((m1, m2) => m1 + m2);
    }
    int N;
}
struct Mod : IEquatable<Mod> { public const long mod = 1000000007; public static readonly Mod invalid = new Mod(-1, false); public readonly long val; private Mod(long val, bool isValid) : this(val) { if (!isValid) this.val = val; } public Mod(long val) { this.val = val % mod; if (this.val < 0) this.val += mod; } public override bool Equals(object obj) => (obj is Mod) ? this == ((Mod)obj) : false; public bool Equals(Mod obj) => this == obj; public override int GetHashCode() => val.GetHashCode(); public override string ToString() => val.ToString(); public static implicit operator Mod(long x) => new Mod(x); public static Mod operator +(Mod x, Mod y) => (x.val + y.val) % mod; public static Mod operator -(Mod x, Mod y) => x.val >= y.val ? (x.val - y.val) % mod : (x.val - y.val) % mod + mod; public static Mod operator *(Mod x, Mod y) => (x.val * y.val) % mod; public static Mod operator /(Mod x, Mod y) => x * y.Inverse(); public static bool operator ==(Mod x, Mod y) => x.val == y.val; public static bool operator !=(Mod x, Mod y) => x.val != y.val; public Mod Inverse() { long a = val, b = mod, u = 1, v = 0; while (b > 0) { long t = a / b; var b2 = a - t * b; a = b; b = b2; var v2 = u - t * v; u = v; v = v2; } u %= mod; if (u < 0) u += mod; return u; } public static Mod Pow(Mod x, int y) { Mod res = 1; for (; y > 0; y >>= 1) { if ((y & 1) == 1) res *= x; x *= x; } return res; } public static Factor CreateFactor(int max) => new Factor(max); public class Factor { private readonly Mod[] fac, finv; public Factor(int max) { ++max; var inv = new Mod[max]; fac = new Mod[max]; finv = new Mod[max]; fac[0] = fac[1] = 1; finv[0] = finv[1] = 1; inv[1] = 1; for (var i = 2; i < max; i++) { fac[i] = fac[i - 1] * i; inv[i] = mod - inv[mod % i].val * (mod / i) % mod; finv[i] = finv[i - 1] * inv[i]; } } /** <summary>組み合わせ関数(二項係数)</summary> */ public Mod Combine(int n, int k) { if (n < k) return 0; if (n < 0 || k < 0) return 0; return fac[n] * finv[k] * finv[n - k]; } public Mod Factorial(int n) => fac[n]; public Mod FactorialInvers(int n) => finv[n]; } }

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Text;
using System.Linq;
using static System.Math;

class Program{
    static long mod = (long)1e9 + 7;

    static void Main(){
        int n = int.Parse(Console.ReadLine());
        long[,] dp = new long[n+1,16];
        for (int i = 0;i < 16;i++){
            dp[2,i] = 1;
        }
        for (int i = 3;i <= n;i++){
            dp[i,0] = (dp[i,0] + dp[i-1,0]) % mod;
            dp[i,0] = (dp[i,0] + dp[i-1,4]) % mod;
            dp[i,0] = (dp[i,0] + dp[i-1,8]) % mod;
            dp[i,0] = (dp[i,0] + dp[i-1,12]) % mod;

            dp[i,1] = (dp[i,1] + dp[i-1,0]) % mod;
            dp[i,1] = (dp[i,1] + dp[i-1,4]) % mod;
            dp[i,1] = (dp[i,1] + dp[i-1,12]) % mod;

            dp[i,2] = (dp[i,2] + dp[i-1,0]) % mod;
            dp[i,2] = (dp[i,2] + dp[i-1,4]) % mod;
            dp[i,2] = (dp[i,2] + dp[i-1,8]) % mod;
            dp[i,2] = (dp[i,2] + dp[i-1,12]) % mod;

            dp[i,3] = (dp[i,3] + dp[i-1,0]) % mod;
            dp[i,3] = (dp[i,3] + dp[i-1,4]) % mod;
            dp[i,3] = (dp[i,3] + dp[i-1,8]) % mod;
            dp[i,3] = (dp[i,3] + dp[i-1,12]) % mod;

            dp[i,4] = (dp[i,4] + dp[i - 1,1]) % mod;
            dp[i,4] = (dp[i,4] + dp[i - 1,5]) % mod;
            dp[i,4] = (dp[i,4] + dp[i - 1,9]) % mod;
            dp[i,4] = (dp[i,4] + dp[i - 1,13]) % mod;

            dp[i,5] = (dp[i,5] + dp[i - 1,1]) % mod;
            dp[i,5] = (dp[i,5] + dp[i - 1,5]) % mod;
            dp[i,5] = (dp[i,5] + dp[i - 1,9]) % mod;
            dp[i,5] = (dp[i,5] + dp[i - 1,13]) % mod;

            dp[i,6] = (dp[i,6] + dp[i-1,5]) % mod;
            dp[i,6] = (dp[i,6] + dp[i-1,9]) % mod;
            dp[i,6] = (dp[i,6] + dp[i-1,13]) % mod;

            dp[i,7] = (dp[i,7] + dp[i-1,1]) % mod;
            dp[i,7] = (dp[i,7] + dp[i-1,5]) % mod;
            dp[i,7] = (dp[i,7] + dp[i-1,9]) % mod;
            dp[i,7] = (dp[i,7] + dp[i-1,13]) % mod;

            dp[i,8] = (dp[i,8] + dp[i-1,2]) % mod;
            dp[i,8] = (dp[i,8] + dp[i-1,6]) % mod;
            dp[i,8] = (dp[i,8] + dp[i-1,10]) % mod;
            dp[i,8] = (dp[i,8] + dp[i-1,14]) % mod;

            dp[i,9] = (dp[i,9] + dp[i-1,6]) % mod;
            dp[i,9] = (dp[i,9] + dp[i-1,10]) % mod;
            dp[i,9] = (dp[i,9] + dp[i-1,14]) % mod;
            dp[i,9] = (dp[i,9] - dp[i-2,2] - dp[i-2,3] + 2*mod) % mod;

            dp[i,10] = (dp[i,10] + dp[i-1,2]) % mod;
            dp[i,10] = (dp[i,10] + dp[i-1,6]) % mod;
            dp[i,10] = (dp[i,10] + dp[i-1,10]) % mod;
            dp[i,10] = (dp[i,10] + dp[i-1,14]) % mod;

            dp[i,11] = (dp[i,11] + dp[i-1,2]) % mod;
            dp[i,11] = (dp[i,11] + dp[i-1,6]) % mod;
            dp[i,11] = (dp[i,11] + dp[i-1,10]) % mod;
            dp[i,11] = (dp[i,11] + dp[i-1,14]) % mod;

            dp[i,12] = (dp[i,12] + dp[i-1,3]) % mod;
            dp[i,12] = (dp[i,12] + dp[i-1,7]) % mod;
            dp[i,12] = (dp[i,12] + dp[i-1,11]) % mod;
            dp[i,12] = (dp[i,12] + dp[i-1,15]) % mod;

            dp[i,13] = (dp[i,13] + dp[i-1,3]) % mod;
            dp[i,13] = (dp[i,13] + dp[i-1,7]) % mod;
            dp[i,13] = (dp[i,13] + dp[i-1,11]) % mod;
            dp[i,13] = (dp[i,13] + dp[i-1,15]) % mod;
            dp[i,13] = (dp[i,13] - dp[i-2,2] + mod) % mod;

            dp[i,14] = (dp[i,14] + dp[i-1,3]) % mod;
            dp[i,14] = (dp[i,14] + dp[i-1,7]) % mod;
            dp[i,14] = (dp[i,14] + dp[i-1,11]) % mod;
            dp[i,14] = (dp[i,14] + dp[i-1,15]) % mod;

            dp[i,15] = (dp[i,15] + dp[i-1,3]) % mod;
            dp[i,15] = (dp[i,15] + dp[i-1,7]) % mod;
            dp[i,15] = (dp[i,15] + dp[i-1,11]) % mod;
            dp[i,15] = (dp[i,15] + dp[i-1,15]) % mod;
        }

        long ans = 0;
        for (int i = 0;i < 16;i++){
            ans += dp[n,i];
            ans %= mod;
        }

        Console.WriteLine(ans);
    }
}

