using System.Collections.Generic;
using System.Text;


public class D
{	
	public static void Main()
	{
		int N = Int32.Parse(Console.ReadLine());

		int mod = 1000000007;
		int[,,,] dp = new int[N+1,4,4,4];
		dp[0,3,3,3] = 1;
		for(int i = 0; i < N; i++)
		{
			for(int p3 = 0; p3 < 4; p3++)
			{
				for(int p2 = 0; p2 < 4; p2++)
				{
					for(int p1 = 0; p1 < 4; p1++)
					{
						for(int c = 0; c < 4; c++)
						{							
							if((p2 == 0) && (p1 == 2) && (c == 1))  // AGC
								continue;
							if((p3 == 0) && (p1 == 2) && (c == 1))  // A?GC
								continue;
							if((p2 == 2) && (p1 == 0) && (c == 1))  // GAC
								continue;
							if((p2 == 0) && (p1 == 1) && (c == 2))  // ACG
								continue;
							if((p3 == 0) && (p2 == 2) && (c == 1))  // AG?C
								continue;

							dp[i+1,c,p1,p2] += dp[i,p1,p2,p3];
							dp[i+1,c,p1,p2] %= mod;
						}
					}
				}
			}
		}

		int ans = 0;
		for(int p3 = 0; p3 < 4; p3++)
		{
			for(int p2 = 0; p2 < 4; p2++)
			{
				for(int p1 = 0; p1 < 4; p1++)
				{
					ans += dp[N,p1,p2,p3];
					ans %= mod;
				}
			}
		}

		Console.WriteLine(ans);
	}	
}

