    class Solver
    {
        public Solver()
        {
            Input input = new Input();
            input.Int(out N);
        }

        private int N;

        private long MOD = 1000000007;
        private Dictionary<string, long>[] memo;
        char[] ACGT = {'A', 'C', 'G', 'T'};

        public void Solve()
        {
            memo = new Dictionary<string, long>[N + 1];
            for (long i = 0; i <= N; i++)
            {
                memo[i] = new Dictionary<string, long>();
            }

            Console.WriteLine(dfs(0, "TTT"));
        }


        public long dfs(int cur, string last3)
        {
            if (memo[cur].ContainsKey(last3))
            {
                return memo[cur][last3];
            }

            if (cur == N) return 1;
            long ret = 0;
            foreach (char c in ACGT)
            {
                if (Ok(last3 + c))
                {
                    ret = (ret + dfs(cur + 1, last3.Substring(1, 2) + c)) % MOD;
                }
            }

            memo[cur].Add(last3, ret);
            return ret;
        }

        public bool Ok(string last4)
        {
            for (int i = 0; i < 4; i++)
            {
                var t = last4.ToList();
                if (i >= 1)
                {
                    var tmp = t[i - 1];
                    t[i - 1] = t[i];
                    t[i] = tmp;
                }

                int c = 0;
                foreach (char c1 in t)
                {
                    if (c == 0 && c1 == 'A')
                    {
                        c++;
                        continue;
                    }

                    if (c == 1 && c1 == 'G')
                    {
                        c++;
                        continue;
                    }

                    if (c == 2 && c1 == 'C')
                    {
                        return false;
                    }

                    c = c1 == 'A' ? 1 : 0;
                }
            }

            return true;
        }
    }
}

using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        var N = Int32.Parse(Console.ReadLine());
        //dummy=0,A=1,G=2,C=3,T=4
        var dp = new long[N+1,5,5,5];
        dp[0, 0, 0, 0] = 1;
        for (int n = 0; n < N; ++n)
        {
            for (int i = 0; i < 5; ++i)
            {
                for (int j = 0; j < 5; ++j)
                {
                    for (int k = 0; k < 5; ++k)
                    {
                        for (int l = 1; l < 5; ++l)
                        {
                            //AGC GAC ACG A?GC AG?C (i,j,k,l)
                            if (j == 1 && k == 2 && l == 3
                            || j == 2 && k == 1 && l == 3
                            || j == 1 && k == 3 && l == 2
                            || i == 1 && k == 2 && l == 3
                            || i == 1 && j == 2 && l == 3)
                            {
                                continue;
                            }
                            dp[n + 1, j, k, l] = (dp[n + 1, j, k, l] + dp[n, i, j, k]) % 1000000007;
                        }
                    }
                }
            }
        }
        var ans = 0L;
        for (int i = 1; i < 5; ++i)
        {
            for (int j = 1; j < 5; ++j)
            {
                for (int k = 1; k < 5; ++k)
                {
                    ans = (ans + dp[N, i, j, k]) % 1000000007;
                }
            }
        }
        Console.WriteLine(ans);
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.Numerics;
class Program
{
	static void Main(string[] args)
	{
		const int A = 1;
		const int C = 2;
		const int G = 3;
		const int T = 4;

		int N = int.Parse(Console.ReadLine());

		var dic = new Dictionary<int, BigInteger>();

		dic.Add(A, new BigInteger(1));
		dic.Add(C, new BigInteger(1));
		dic.Add(G, new BigInteger(1));
		dic.Add(T, new BigInteger(1));

		for(int i=1; i<N; i++) {
			var temp = new Dictionary<int, BigInteger>();

			foreach(KeyValuePair<int, BigInteger> pair in dic){

				for(int ACGT = A; ACGT<=T; ACGT++) {
					int checkValue = (pair.Key * 10 + ACGT) % 10000;
					if(!ContainAGC(checkValue)) {
						if(temp.ContainsKey(checkValue)) {
							BigInteger bi = temp[checkValue];
							bi += pair.Value;
							temp[checkValue] = bi;
						}
						else {
							BigInteger bi = new BigInteger();
							bi += pair.Value;
							temp.Add(checkValue, bi);
						}
					}
				}
			}
			dic = temp;
		}

		BigInteger sum = 0;
		foreach(KeyValuePair<int, BigInteger> pair in dic){
			sum += pair.Value;
		}

		Console.WriteLine(sum%1000000007);
	}


	static bool ContainAGC(int val) {
		if(val/10 == 132) return true; // AGC*
		if(val/100 == 13 && val%10 == 2) return true; // AG*C
		if(val/1000 == 1 && val%100 == 32) return true; // A*GC
		if(val%1000 == 132 || val%1000 == 123 || val%1000 == 312) return true; // *AGC, *ACG, *GAC
		return false;
	}
}

