    class Program
    {
        static void Main(string[] args)
        {
            var N = ReadInt;

            long[,] dp = new long[N, 64];
            for (int j = 0; j < 64; j++)
            {
                if (j == 6 || j == 9 || j == 18) continue;
                dp[0, j] = 1;
            }

            Draw2D(dp);

            for (int i = 0; i < N - 1; i++)
            {
                for (int j = 0; j < 64; j++)
                {
                    for (int k = 0; k < 4; k++)
                    {
                        //nextが特定の値の時（AGC）のときcontinue
                        int next = j * 4 % 64 + k;
                        if (next == 6 || next == 9 || next == 18) continue;
                        if (k == 2)
                        {
                            if (j / 16 == 0 && j / 4 == 1) continue;
                            if (j / 16 == 0 && j % 4 == 1) continue;
                        }

                        dp[i + 1, next] += dp[i, j];
                        dp[i + 1, next] %= 1000000007;
                    }
                }
            }

            Draw2D(dp);

            long ans = 0;
            for (int i = 0; i < 64; i++)
            {
                ans += dp[N - 3, i];
                ans %= 1000000007;
            }
            Console.WriteLine(ans);
        }


    }


