using static System.Console;
class K
{
	const int MOD = 1000000007;
	static void Main()
	{
		const int M = 10;
		var N = int.Parse(ReadLine());
		var g = new int[M, 4] {
			{ 3, 4, 1, 1 }, { 2, 2, 2, 2 },
			{ 3, 5, 6, 7 }, { 8, 4, 1, 1 },
			{ 8, 9, 2, 10 }, { 3, 2, 1, 1 },
			{ 3, 9, 1, 1 }, { 3, 5, 2, 7 },
			{ 8, 4, 2, 1 }, { 3, 4, 2, 1 } };
		for (var i = 0; i < M; i++) for (var j = 0; j < 4; j++) g[i, j]--;
		// start = 0, accepted = {1}
		var dp = new long[N + 1, M];
		dp[0, 0] = 1;
		for (var i = 0; i < N; i++) for (var s = 0; s < M; s++) for (var c = 0; c < 4; c++) Add(ref dp[i + 1, g[s, c]], dp[i, s]);
		WriteLine((Pow(4, N) - dp[N, 1] + MOD) % MOD);
	}
	static void Add(ref long a, long b) => a = (a + b) % MOD;
	static long Pow(long a, long b)
	{
		long p = 1, x = a;
		while (b > 0)
		{
			if ((b & 1) == 1) p = p * x % MOD;
			b >>= 1;
			x = x * x % MOD;
		}
		return p;
	}
}

using System;
using System.Collections.Generic;
using System.Linq;

class Procon
{
    public Procon() { }
    static void Main(string[] agrs)
    {
        new Procon().Do();
    }

    Scanner cin;

    int N;

    Dictionary<string, long>[] last4str;

    string[] Alphabet = new string[4] { "A", "G", "C", "T" };

    public bool Check(string key)
    {
        if (key.Contains("AGC"))
        {
            return true;
        }

        for (int i = 1; i < key.Length; i++)
        {
            char[] tmpCharArray = key.ToCharArray();
            char tmp = tmpCharArray[i];
            tmpCharArray[i] = tmpCharArray[i - 1];
            tmpCharArray[i - 1] = tmp;
            string tmpKey = new string(tmpCharArray);
            if (tmpKey.Contains("AGC"))
            {
                return true;
            }
        }
        return false;
    }

    public long Count(long i)
    {
        last4str[i] = new Dictionary<string, long>();
        if (i == 0)
        {
            last4str[i]["A"] = 1;
            last4str[i]["G"] = 1;
            last4str[i]["C"] = 1;
            last4str[i]["T"] = 1;
        }
        else
        {
            foreach (string k in last4str[i - 1].Keys)
            {
                foreach (string a in Alphabet)
                {
                    var newKey = k + a;
                    if (Check(newKey))
                    {
                        continue;
                    }
                    newKey = newKey.Substring(Math.Max(newKey.Length - 3, 0));
                    if (last4str[i].ContainsKey(newKey))
                    {
                        last4str[i][newKey] = (last4str[i][newKey] + last4str[i - 1][k]) % 1000000007;
                    }
                    else
                    {
                        last4str[i].Add(newKey, last4str[i - 1][k]);
                    }
                }
            }
        }

        long ans = 0;
        foreach (long v in last4str[i].Values)
        {
            ans += v;
        }

        return ans;
    }

    public void Do()
    {
        cin = new Scanner();
        N = cin.nextInt();

        last4str = new Dictionary<string, long>[N];
        long ans = 0;
        for (int i = 0; i < N; i++)
        {
            ans = Count(i);
        }
        Console.WriteLine(ans);
    }
}

class Scanner
{
    string[] s;
    int i;
    int max_i;

    public Scanner()
    {
        s = new string[0];
        max_i = 0;
        i = 0;
    }

    public string nextString()
    {
        if (i >= s.Length)
        {
            s = Console.ReadLine().Split(' ');
            max_i = s.Length;
            i = 0;
            if (max_i == 0)
            {
                return "";
            }
            return s[i++];
        }
        else
        {
            return s[i++];
        }
    }

    public int nextInt()
    {
        return int.Parse(nextString());
    }

    public long nextLong()
    {
        return long.Parse(nextString());
    }

    public double nextDouble()
    {
        return double.Parse(nextString());
    }

    public string[] arrayString()
