using System;
using System.Collections.Generic;
using System.Linq;



namespace CSharpSample01
{



    class Program
    {
        const long MOD = 1000000007;


        static long DP(int N)
        {
            //dp[n, t, s, f] := n文字の文字列の通りで、最後がf、最後-1がs、最後-2がtとなっている
            long[,,,] dp = new long[N + 1, 5, 5, 5];

            dp[0, 0, 0, 0] = 1;

            for(int n = 0; n < N; n++)
            {
                for (int t = 0; t < 5; t++)
                {
                    for(int s = 0; s < 5; s++)
                    {
                        for(int f = 0; f < 5; f++)
                        {
                            //dp[n, t, s, f]を使って、n+1文字目の文字nextを決める
                            for (int next = 1; next < 5; next++)
                            {
                                if (t == 1 && s == 2 && next == 3) continue;
                                if (t == 1 && f == 2 && next == 3) continue;
                                if (s == 1 && f == 2 && next == 3) continue;
                                if (s == 2 && f == 1 && next == 3) continue;
                                if (s == 1 && f == 3 && next == 2) continue;
                                dp[n + 1, s, f, next] += dp[n, t, s, f];
                                dp[n + 1, s, f, next] %= MOD;
                            }
                        }               
                    }
                }
            }

            long ans = 0;

            for(int t = 1; t < 5; t++)
            {
                for(int s = 1; s < 5; s++)
                {
                    for(int f = 1; f < 5; f++)
                    {
                        ans += dp[N, t, s, f];
                        ans %= MOD;
                    }
                }
            }

            return ans;
        }

        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());

            Console.WriteLine(DP(N));
        }
    }
}

