    class ProgramD
    {
        public void main()
        {

            //入力
            int n = int.Parse(Console.ReadLine());
            long MOD = 1000000000 + 7;
            long[,,,] dp = new long[n, 4, 4, 4];



            //初項
            for (int k = 0; k < 4; k++)//2つ前
                for (int l = 0; l < 4; l++)//一つ前
                    for (int m = 0; m < 4; m++)//今
                    {
                        if ((k == 0 && l == 2 && m == 1) || (k == 0 && l == 1 && m == 2) || (k == 2 && l == 0 && m == 1))
                            continue;

                        dp[2, k, l, m] = 1;
                    }


            //動的計画法
            for (int i = 3; i < n; i++)//4文字目から見る
                for (int j = 0; j < 4; j++)//3つ前
                    for (int k = 0; k < 4; k++)//2つ前
                        for (int l = 0; l < 4; l++)//一つ前
                            for (int m = 0; m < 4; m++)//今参照してる列
                            {
                                // [A, C, G, T]
                                // _AG -> C (0,2,1)
                                // _AC -> G (0,1,2)
                                // _GA -> C (2,0,1)
                                // AG_ -> C (0,2,X,1)
                                // A_G -> C (0,X,2,1)
                                if ((k == 0 && l == 2 && m == 1) || (k == 0 && l == 1 && m == 2) ||
                                    (k == 2 && l == 0 && m == 1) || (j == 0 && k == 2 && m == 1) || (j == 0 && l == 2 && m == 1))
                                    continue;

                                dp[i, k, l, m] += dp[i - 1, j, k, l];
                                dp[i, k, l, m] %= MOD;


                            }

            long ans = 0;

            for (int k = 0; k < 4; k++)//2つ前
                for (int l = 0; l < 4; l++)//一つ前
                    for (int m = 0; m < 4; m++)//今
                    {
                        ans += dp[n -1, k, l, m];
                        ans %= MOD;
                    }


            Console.WriteLine(ans);

        }



    }




}

