using System;
using System.Collections.Generic;

namespace ConsoleApp1
{
    class Program
    {
        const long Mod = 1000000000 + 7;

        static Dictionary<string, long> Solve(int n)
        {
            if (n == 1)
            {
                return new Dictionary<string, long>
                {
                    ["A"] = 1,
                    ["G"] = 1,
                    ["C"] = 1,
                    ["T"] = 1,
                };
            }

            var previous = Solve(n - 1);
            var result = new Dictionary<string, long>();

            foreach (var pair in previous)
            {
                string str = pair.Key;
                long count = pair.Value;
                HashSet<char> chars = new HashSet<char> { 'A', 'C', 'G', 'T' };

                if (str.Length >= 3 && ((str[0] == 'G' && str[2] == 'C') || (str[1] == 'G' && str[2] == 'C')))
                {
                    chars.Remove('A');
                }
                else
                {
                    switch (str.Substring(0, Math.Min(2, str.Length)))
                    {
                        case "AC":
                            chars.Remove('G');
                            break;
                        case "CG":
                        case "GC":
                            chars.Remove('A');
                            break;
                        default:
                            break;
                    }
                }

                foreach (var c in chars)
                {
                    string key = (c + str).Substring(0, Math.Min(3, 1 + str.Length));
                    result.TryGetValue(key, out var value);
                    value = (value + count) % Mod;
                    result[key] = value;
                }
            }

            return result;
        }

        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            var dictionary = Solve(n);

            long ans = 0;
            foreach (var pair in dictionary)
            {
                ans = (ans + pair.Value) % Mod;
            }

            Console.WriteLine(ans);
        }
    }
}

