class Program
{
    static int N;
    static Dictionary<(int, string), long> memo = new Dictionary<(int, string), long>();
    const string chars = "AGCT";
    const int MOD = (int)(1e9 + 7);

    static bool IsValid(string last4)
    {
        for (int i = 0; i < 4; i++)
        {
            var cur = last4.ToCharArray();
            if (i >= 1)
            {
                var tmp = cur[i];
                cur[i] = cur[i - 1];
                cur[i - 1] = tmp;
            }
            string ss = new string(cur);
            if(ss.Contains("AGC")){
                return false;
            }
        }
        return true;
    }

    static long Dfs(int k, string last3)
    {
        var key = (k, last3);
        if(memo.ContainsKey(key))
        {
            return memo[key];
        }
        if (k == N)
        {
            return 1;
        }

        long ans = 0;
        foreach (var c in chars)
        {
            string cs = c.ToString();
            if(IsValid(last3 + cs))
            {
                ans = (ans + Dfs(k+1, last3.Substring(1) + cs)) % MOD;
            }
        }
        memo[key] = ans;
        return ans;
    }

    static void Main(string[] args)
    {
        N = int.Parse(Console.ReadLine());
        Console.WriteLine(Dfs(0, "TTT"));
    }
}

