                                if (j == 1 && k == 2 && l == 3) continue;
                                if (j == 2 && k == 1 && l == 3) continue;
                                if (j == 1 && k == 3 && l == 2) continue;
                                ModAdd(ref dp[n + 1,j,k,l], dp[n,i,j,k]);
                            }

            long res = 0;
            for (int i = 1; i < 5; i++)
                for (int j = 1; j < 5; j++)
                    for (int k = 1; k < 5; k++)
                        ModAdd(ref res, dp[N, i, j, k]);

            return res;
        }


