    public class App
    {
      	const int mod = 1000000007;
        public static void Main()
        {
            int n = int.Parse(Console.ReadLine());
            var dp = new long[256, n+1];
            dp[255, 0] = 1;
            long sum = 0;
            for (int i = 1;i<=n;i++)
            {
                sum = 0;
                for (int c = 0; c < 256; c++)
                {
                    if ((c & 63) == 9)
                        continue;
                    if ((c & 207) == 9)
                        continue;
                    if ((c & 243) == 33)
                        continue;
                    if ((c & 63) == 33)
                        continue;
                    if ((c & 63) == 6)
                        continue;
                    for (int b = 0; b < 256; b += 64)
                    {
                        dp[c, i] += dp[(c >> 2) + b, i - 1];
                    }
                    sum += dp[c, i];
                    sum %= mod;
                    dp[c, i] %= mod;
                }
            }
            Console.WriteLine(sum);
        }
    }
}

