namespace AtCoderCore {
	public class Program {
		private const int MOD = 1000000007;

		static Dictionary<string, int>[] memo;

		static void Main (string[] args) {
			int n = int.Parse(Console.ReadLine());
			memo = new Dictionary<string, int>[n];
			for (int i = 0; i < n; i++)
			{
				memo[i] = new Dictionary<string, int>();
			}

			//AGC
			//GAC, ACG, AG*C, A*GC
			int ans = DFS(0, "TTT", n);
			Console.WriteLine(ans);
		}

		public static int DFS(int n, string last3, int max)
		{
			if(n == max){
				return 1;
			}

			if(memo[n].ContainsKey(last3)){
				return memo[n][last3];
			}

			int ret = 0;
			foreach(char c in "AGCT"){
				if(IsOK(last3 + c)){
					ret = (ret + DFS(n + 1, last3.Substring(1, 2) + c, max)) % MOD;
				}
			}

			memo[n][last3] = ret;

			return ret;
		}

		public static bool IsOK(string str){
			if(str.Contains("AGC")){
				return false;
			}

			string temp1 = new string(new char[]{str[1], str[0], str[2], str[3]});
			if(temp1.Contains("AGC")){
				return false;
			}

			string temp2 = new string(new char[]{str[0], str[2], str[1], str[3]});
			if(temp2.Contains("AGC")){
				return false;
			}

			string temp3 = new string(new char[]{str[0], str[1], str[3], str[2]});
			if(temp3.Contains("AGC")){
				return false;
			}

			return true;
		}
	}
