type Chars []rune

const MOD = 1000000007

func (chars Chars) Clone() Chars {
	res := make([]rune, len(chars))
	copy(res, chars)
	return res
}

func (chars Chars) Added(char rune) Chars {
	res := chars.Clone()
	res = append(res, char)
	return res
}

func (chars Chars) satisfied() bool {
	if strings.Contains(string(chars), "AGC") {
		return false
	}

	for i := 0; i+1 < len(chars); i++ {
		cs := chars.Clone()
		cs[i], cs[i+1] = cs[i+1], cs[i]

		if strings.Contains(string(cs), "AGC") {
			return false
		}
	}

	return true
}

func dfs(restCharCount int, lastThreeChars Chars, memo []map[string]int) int {
	if restCharCount == 0 {
		return 1
	}

	res := 0

	for _, char := range Chars("ACGT") {
		lastFourChars := lastThreeChars.Added(char)

		if lastFourChars.satisfied() {
			if _, memoExists := memo[restCharCount-1][string(lastFourChars[1:])]; !memoExists {
				resForChar := dfs(restCharCount-1, lastFourChars[1:], memo) % MOD
				memo[restCharCount-1][string(lastFourChars[1:])] = resForChar
			}

			res += memo[restCharCount-1][string(lastFourChars[1:])]
		}
	}

	return res % MOD
}

