func dp(s string, n int, m map[int]map[string]int) {
	if s != "AGC" && s != "ACG" && s != "GAC" {
		s1 := "A" + s[0:2]
		s2 := "C" + s[0:2]
		s3 := "G" + s[0:2]
		s4 := "T" + s[0:2]
		m[n][s] = m[n-1][s1] + m[n-1][s2] + m[n-1][s3] + m[n-1][s4]
		if (s[0] == 'G' && s[2] == 'C') || (s[1:] == "GC") {
			m[n][s] -= m[n-1][s1]
		}
		m[n][s] %= 1000000007
	} else {
		m[n][s] = 0
	}
}

