}

func (mw MyWriter)Puts(v MyPut) {
	_, _ = fmt.Fprintf(mw.stdout, "%v\n", v)
}

var dp [100][4][4][4]int
var mod int = 1000000007

func isAGC(i, j, k int) bool {
	return i == 0 && j == 2 && k == 1
}

func isACG(i, j, k int) bool {
	return i == 0 && j == 1 && k == 2
}

func isGAC(i, j, k int) bool {
	return i == 2 && j == 0 && k == 1
}

func isMatch(i, j, k int) bool {
	return isAGC(i, j, k) || isACG(i, j, k) || isGAC(i, j, k)
}

func DPInit() {
	for i := 0; i < 4; i++ {
		for j := 0; j < 4; j++ {
			for k := 0; k < 4; k++ {
				if isMatch(i, j, k) {
					dp[2][i][j][k] = 0
				} else {
					dp[2][i][j][k] = 1
				}
			}
		}
	}
}

func CalcDP(n int) {
	for i := 0; i < 4; i++ {
		for j := 0; j < 4; j++ {
			for k := 0; k < 4; k++ {
				if isMatch(i, j, k) {
					continue
				}
				for l := 0; l < 4; l++ {
					if isMatch(j, k, l) {
						continue
					}
					if isAGC(i, k, l) || isAGC(i, j, l) {
						continue
					}
					dp[n][j][k][l] += dp[n - 1][i][j][k]
					dp[n][j][k][l] %= mod
				}
			}
		}
	}
}

func DPSum(n int) (ret int) {
	for i := 0; i < 4; i++ {
		for j := 0; j < 4; j++ {
			for k := 0; k < 4; k++ {
				ret += dp[n][i][j][k]
				ret %= mod
			}
		}
	}
	return
}

func Solve(stdin io.Reader, stdout io.Writer) {
	sc := MyScanner{getScanner(stdin)}
	mw := MyWriter{stdout}

	n := sc.Int()

	DPInit()

	for i := 3; i < n; i++ {
		CalcDP(i)
	}

	mw.Puts(DPSum(n - 1))
}

func main() {
	Solve(os.Stdin, os.Stdout)
	return
}

