var mod int = int(1e9 + 7)
var chars []string = []string{
  "A",
  "C",
  "G",
  "T",
}

var n int
var memo [101]map[string]int

func ok(str string) bool {
  org := []rune(str)
  s := make([]rune, len(org))
  for i:=0; i<4; i++ {
    copy(s, org)

    if i < 3 {
      s[i], s[i+1] = s[i+1], s[i]
    }

    if strings.Contains(string(s), "AGC") {
      return false
    }
  }
  return true
}

func rec(i int, last3 string) int {
	v, exists := memo[i][last3]
	if exists {
		return v
	}

	if i == n {
		return 1
	}

	var ret int
	for _, c := range chars {
		if ok(last3 + c) {
			ret = (ret + rec(i+1, string(last3[1:] + c))) % mod
		}
	}

	memo[i][last3] = ret
	return ret
}

func main() {
	fmt.Scan(&n)
	for i:=0; i<101; i++ {
		memo[i] = map[string]int{}
	}

	fmt.Println(rec(0, "TTT"))

}

