const (
	M          = 1000000007
	A, C, G, T = 0, 1, 2, 3
)

func i2c(v int) byte {
	switch v {
	case A:
		return 'A'
	case C:
		return 'C'
	case G:
		return 'G'
	case T:
		return 'T'
	}
	return byte(255)
}

func check(c0, c1, c2, c3 int) bool {
	s := []byte{i2c(c3), i2c(c2), i2c(c1), i2c(c0)}
	if bytes.Contains(s, []byte{'A', 'G', 'C'}) {
		return false
	}
	if bytes.Contains(s, []byte{'G', 'A', 'C'}) {
		return false
	}
	if bytes.Contains(s, []byte{'A', 'C', 'G'}) {
		return false
	}
	if s[0] == 'A' && s[2] == 'G' && s[3] == 'C' {
		return false
	}
	if s[0] == 'A' && s[1] == 'G' && s[3] == 'C' {
		return false
	}
	return true
}

func main() {
	defer stdout.Flush()

	n := readInt()
	dp := make([][4][4][4]int, n+1)
	dp[0][T][T][T] = 1
	for i := 1; i <= n; i++ {
		for _, p3 := range []int{A, C, G, T} {
			for _, p2 := range []int{A, C, G, T} {
				for _, p1 := range []int{A, C, G, T} {
					for _, cur := range []int{A, C, G, T} {
						if check(cur, p1, p2, p3) {
							dp[i][cur][p1][p2] = (dp[i][cur][p1][p2] + dp[i-1][p1][p2][p3]) % M
						}
					}
				}
			}
		}
	}
	sum := 0
	for _, p1 := range []int{A, C, G, T} {
		for _, p2 := range []int{A, C, G, T} {
			for _, p3 := range []int{A, C, G, T} {
				sum = (sum + dp[n][p1][p2][p3]) % M
			}
		}
	}
	println(sum)
}

