var sc = bufio.NewScanner(os.Stdin)

func Scanner() string {
	sc.Scan()
	return sc.Text()
}

func main() {
	buf := make([]byte, 0)
	sc.Buffer(buf, 1000000007)
	sc.Split(bufio.ScanWords)
	n, _ := strconv.Atoi(Scanner())
	d := int(1e9) + 7
	list := []string{"A", "C", "G", "T"}
	dict := make(map[string]int)
	for _, i := range list {
		for _, j := range list {
			for _, k := range list {
				dict[i+j+k] = 0
			}
		}
	}
	dict["TTT"] = 1
	for i := 0; i < n; i++ {
		tmp := make(map[string]int)
		for _, c := range list {
			for k, v := range dict {
				key := k[1:] + c
				if judge1(key) && judge2(k, c) {
					tmp[key] += v
					tmp[key] %= d
				}
			}
		}
		for k, _ := range dict {
			dict[k] = tmp[k]
		}
	}
	ans := 0
	for _, v := range dict {
		ans += v
	}
	fmt.Println(ans % d)
}
func judge1(s string) bool {
	if s == "AGC" {
		return false
	} else if s == "ACG" {
		return false
	} else if s == "GAC" {
		return false
	} else {
		return true
	}
}
func judge2(k, c string) bool {
	if string(k[0]) == "A" && (string(k[1]) == "G" || string(k[2]) == "G") && c == "C" {
		return false
	} else {
		return true
	}
}

