const mod int = 1e9 + 7

func main() {
	var n int
	fmt.Scan(&n)

	memo := make([]map[string]int, n+1)
	for i := 0; i < n+1; i++ {
		memo[i] = make(map[string]int)
	}

	var dfs func(i int, tmp string) int
	dfs = func(i int, tmp string) int {
		if i == n {
			return 1
		}

		if c, ok := memo[i][tmp]; ok {
			return c
		}

		cnt := 0
		for _, c := range "AGCT" {
			t := string(c)
			if !isOK(tmp + t) {
				continue
			}
			s := tmp + t
			if 3 < len(s) {
				s = s[1:]
			}

			cnt += dfs(i+1, s)
			cnt %= mod
		}

		memo[i][tmp] = cnt
		return cnt
	}

	ans := dfs(0, "")
	fmt.Println(ans)
}

func isOK(s string) bool {
	ngs := []string{"AGC", "GAC", "ACG"}
	for _, ng := range ngs {
		if strings.Contains(s, ng) {
			return false
		}
	}

	if len(s) == 4 {
		t1 := string([]byte{s[0], s[2], s[3]}) // A*GC
		t2 := string([]byte{s[0], s[1], s[3]}) // AG*C
		if t1 == "AGC" || t2 == "AGC" {
			return false
		}
	}

	return true
}

