var mod int = int(1e9 + 7)

var chars []string = []string{
	"A",
	"C",
	"G",
	"T",
}

func ok(str string) bool {
	org := []rune(str)
	s := make([]rune, len(org))
	for i:=0; i<4; i++ {
		copy(s, org)

		if i < 3 {
			s[i], s[i+1] = s[i+1], s[i]
		}

		if strings.Contains(string(s), "AGC") {
			return false
		}
	}
	return true
}

func main() {
	var n int
	fmt.Scan(&n)

	// 初期値を3文字の場合で作る
	dp := [101][4][4][4]int{}
	for j:=0; j<4; j++ {
		for k:=0; k<4; k++ {
			for l:=0; l<4; l++ {
				str := chars[j]+chars[k]+chars[l]
				if str == "AGC" || str == "GAC" || str == "ACG" {
					continue
				}
				dp[3][j][k][l] = 1
			}
		}
	}

	for i:=3; i<n; i++ {
		for j:=0; j<4; j++ {
			for k:=0; k<4; k++ {
				for l:=0; l<4; l++ {
					for m:=0; m<4; m++ {
						s := chars[j] + chars[k] + chars[l] + chars[m]
						if !ok(s) {
							continue
						}

						dp[i+1][k][l][m] += dp[i][j][k][l]
						dp[i+1][k][l][m] %= mod
					}
				}
			}
		}
	}

	s := 0
	for j:=0; j<4; j++ {
		for k:=0; k<4; k++ {
			for l:=0; l<4; l++ {
				s += dp[n][j][k][l]
				s %= mod
			}
		}
	}

	fmt.Println(s)
}

