func main() {
	var N int
	fmt.Scan(&N)
	dp[0][3][3][3] = 1
	for n := 0; n < N; n++ {
		for c1 := 0; c1 < 4; c1++ {
			for c2 := 0; c2 < 4; c2++ {
				for c3 := 0; c3 < 4; c3++ {
					if dp[n][c1][c2][c3] == 0 {
						continue
					}
					// 追加する文字
					for a := 0; a < 4; a++ {
						if a == 2 && c1 == 1 && c2 == 0 {
							continue
						}
						if a == 2 && c1 == 0 && c2 == 1 {
							continue
						}
						if a == 1 && c1 == 2 && c2 == 0 {
							continue
						}
						if a == 2 && c1 == 1 && c3 == 0 {
							continue
						}
						if a == 2 && c2 == 1 && c3 == 0 {
							continue
						}
						// ダメな条件を抜けたらaを足した文字列が作れる
						// now  = ...... c3 c2 c1
						// next = ...... c3 c2 c1 a
						dp[n+1][a][c1][c2] += dp[n][c1][c2][c3]
						dp[n+1][a][c1][c2] %= Mod
					}
				}
			}
		}
	}
	ans := 0
	for c1 := 0; c1 < 4; c1++ {
		for c2 := 0; c2 < 4; c2++ {
			for c3 := 0; c3 < 4; c3++ {
				ans += dp[N][c1][c2][c3]
				ans %= Mod
			}
		}
	}
	fmt.Println(ans)
}

