  "T",
}

var n int
var memo [101]map[string]int

func ok(str string) bool {
  org := []rune(str)
  s := make([]rune, len(org))
  for i:=0; i<4; i++ {
    copy(s, org)

    if i < 3 {
      s[i], s[i+1] = s[i+1], s[i]
    }

    if strings.Contains(string(s), "AGC") {
      return false
    }
  }
  return true
}

func rec(i int, last3 string) int {
	v, exists := memo[i][last3]
	if exists {
		return v
	}

	if i == n {
		return 1
	}

	var ret int
	for _, c := range chars {
		if ok(last3 + c) {
			ret = (ret + rec(i+1, string(last3[1:] + c))) % mod
		}
	}
	return ret
}

