var rexp *regexp.Regexp
var memo map[string]int64

func rec(last3 string,n int) int64{
	if n<=0 {
		return 1
	}
	key := fmt.Sprintf("%s%d",last3,n)
	memoValue, exits := memo[key]
	if exits {
		return memoValue
	}
	sum := int64(0)
	for _,c := range []string{"A","C","G","T"} {
