func ok(last4 string) bool {
	for i := range last4 {
		var t string
		if i >= 1 {
			t = swap(last4, i-1, i)
		} else {
			t = last4
		}
		if strings.Contains(t, "AGC") {
			return false
		}
	}
	return true
}

func swap(last4 string, i, j int) string {
	ret := ""
	for k := range last4 {
		if k == i {
			ret = strings.Join([]string{ret, string(last4[j])}, "")
		} else if k == j {
			ret = strings.Join([]string{ret, string(last4[i])}, "")
		} else {
			ret = strings.Join([]string{ret, string(last4[k])}, "")
		}
	}
	return ret
}

