		return v
	}
	if cur == N {
		return 1
	}
	ret := 0
	for _, c := range "ACGT" {
		if ok(last3 + string(c)) {
			ret = (ret + dfs(cur+1, last3[1:]+string(c))) % 1000000007
		}
	}
	memo[cur][last3] = ret
	return ret
}

