const MOD = int(1e+9) + 7
const INF = 1 << 60

func main() {
	sc := NewScanner()
	wtr := bufio.NewWriter(os.Stdout)
	defer wtr.Flush()
	N := sc.nextInt()
	memo := make([]map[string]int, N+1)
	done := make([]map[string]bool, N+1)
	for i := 0; i <= N; i++ {
		memo[i] = make(map[string]int)
		done[i] = make(map[string]bool)
	}
	var dfs func(cur int, before string) int
	dfs = func(cur int, before string) int {
		if done[cur][before] {
			return memo[cur][before]
		}
		if cur == N {
			return 1
		}
		res := 0
		next := []string{"A", "G", "C", "T"}
		for i := 0; i < 4; i++ {
			if isOk([]rune(before + next[i])) {
				res += dfs(cur+1, before[1:]+next[i])
				res %= MOD
			}
		}
		done[cur][before] = true
		memo[cur][before] = res
		return res
	}
	fmt.Fprintln(wtr, dfs(0, "TTT"))
}

func isOk(before4 []rune) bool {
	for i := 0; i < 4; i++ {
		runes := make([]rune, len(before4))
		copy(runes, before4)
		if i != 0 {
			runes[i], runes[i-1] = runes[i-1], runes[i]
		}
		if strings.Contains(string(runes), "AGC") {
			return false
		}
	}
	return true
}

