const getACMap = (s) => {
  const acPoint = []
  let flag = 0
  s.split("").map((c, i) => {
    if (c == "A") {
      flag = 1
      return
    }
    if (flag == 1 && c == "C") {
      acPoint.push(i - 1)
      return
    }
    flag = 0
  })
  return acPoint
}

const solve = (input) => {
  const [head, s, ...qLine] = input.split("\n")
  const qs = qLine.map((q) => q.split(" ").map(Number))
  const acMap = getACMap(s)
  // debug(acMap)
  const revAcMap = acMap.concat().reverse()
  const r = qs.map((q) => {
    const l = q[0] - 2
    const r = q[1] - 1
    const min = acMap.findIndex((v) => {
      return l < v
    })
    const preMax = revAcMap.findIndex((v) => r > v)
    const max = preMax > -1 ? acMap.length - preMax : -1
    return Math.max(max - min, 0)
  })
  return r.join("\n")
}

if (process.env.NODE_ENV === "test") {
  module.exports = (input) => solve(input.trim())
} else {
  const input = require("fs").readFileSync("/dev/stdin", "utf8")
