    $ret = 0;
    foreach (STRS as $next) {
        if (is_ok($last3string . $next)) {
            $ret += sch($current + 1, substr($last3string, 1) . $next);
        }
    }
    $ret = $ret % MOD;
    $sch_cache[$current][$last3string] = $ret;
    return $ret;
};

