sub ok
{
    my ($s) = @_;

    if ($s =~ m/(AGC|GAC|ACG|A.GC|AG.C)/) {
        return 0;
    }

    return 1;
}

sub solve3
{
    my %last3 = ();
    my @ACGT = ("A", "C", "G", "T");

    # リスト生成
    for (my $i = 0; $i < 64; $i++) {
        my $key;
        $key  = $ACGT[int($i / (4 ** 0) % 4)];
        $key .= $ACGT[int($i / (4 ** 1) % 4)];
        $key .= $ACGT[int($i / (4 ** 2) % 4)];
        if (&ok($key)) {
            $last3{$key} = 1;
        }
    }

    # カウント
    my $sum = 0;
    foreach my $key (keys %last3) {
        $sum += $last3{$key};
    }

    return ($sum, %last3);
}

sub solve
{
    my ($n) = @_;
    my @ACGT = ("A", "C", "G", "T");

    if ($n == 3) {
        return &solve3();
    }

    # (n - 1)のリスト生成
    my (undef, %last3) = solve($n - 1);

    # リスト生成
    my %new3 = ();
    for (my $i = 0; $i < 4; $i++) {
        my $c = $ACGT[$i];
        foreach my $key (keys %last3) {
            my $s = $key.$c;
            if (&ok($s)) {
                $new3{substr($s, -3, 3)} += $last3{$key};
                $new3{substr($s, -3, 3)} %= (1e+9 + 7);
            }
        }
    }

    # カウント
    my $sum = 0;
    foreach my $key (keys %new3) {
        $sum += $new3{$key};
        $sum %= (1e+9 + 7);
    }

    return ($sum, %new3);
}

