                        if (j1 == 1 && j3 == 3 && k == 2) continue; // A*GC
                        if (j1 == 1 && j2 == 3 && k == 2) continue; // AG*C
                        dp[i][j2][j3][k] += dp[i-1][j1][j2][j3];
