import sys
import collections

def main():
	N = int(input())

	total = runEXP(4, N)
	if N == 3:
		tmp = ((3  * (N-2)) + ((N-3)*2)) % 1000000007
	else:
		tmp = runEXP(3, (N))  % 1000000007

	print(total - tmp)

def runEXP(N, P):
	if P == 0:
		return 1
	if P == 1:
		return N
	if P == 2:
		return N * N
	else:
		if P % 2 == 0:
			tmp = runEXP(N, P // 2)
			return  (tmp % 1000000007) * (tmp % 1000000007)
		else:
			P -= 1
			tmp = runEXP(N, P // 2)
