from collections import defaultdict


def find_ans(dp, mod):
    nex = defaultdict(int)
    for key, val in dp.items():
        for c in ["A", "G", "C", "T"]:
            if (key[1:] == "AG" and c == "C")\
                or (key[1:] == "AC" and c == "G")\
                or (key[1:] == "GA" and c == "C")\
                or (key[:1] == "A" and key[2:] == "G" and c == "C")\
                or (key[:1] == "A" and key[1:2] == "G" and c == "C"):
                continue
            else:
                nex[key[1:] + c] += val
                nex[key[1:] + c] %= mod

    return nex

