    return True


def dfs(cur, last3, N, memo=[]):
    if last3 in memo[cur]:
        return memo[cur][last3]

    if cur == N:
        return 1

    ret = 0
    for c in 'AGCT':
        if check(last3 + c):
            ret = (ret + dfs(cur+1, last3[1:]+c, N, memo)) % (10**9 + 7)
    memo[cur][last3] = ret
    return ret


