def conv(cur, N):
    s = [0] * N
    ptr = 0
    while ptr < N:
        code = cur % 4
        if code == 0:
            s[ptr] = "A"
        elif code == 1:
            s[ptr] = "G"
        elif code == 2:
            s[ptr] = "T"
        elif code == 3:
            s[ptr] = "C"
        cur = cur // 4
        ptr += 1
    return s


