def chk_str (s):
  for i in range(4):
    tmp = list(s[-4:])
    if i > 0:
      tmp[i], tmp[i-1] = tmp[i-1], tmp[i]
    if ''.join(tmp).count("AGC") == 1:
      return False
  return True

def count_str (s="_"):
  if len(s) == N+1:
    return 1
  if len(s) < 3:
    return(sum(count_str(s + x) for x in 'ATCG'))
  else:
    cnt = 0
    for x in 'ATCG':
      if chk_str(s + x):
        cnt += count_str(s + x)
    return cnt


