def least_AGC_num(num):
    if num <= 2:
        return 0
    return 4 ** (num - 3) * (num - 2)


def no_AGC_num(num):
    return 4 ** num - least_AGC_num(num)


def no_AGC_and_not_edge_num(num):
    return 4 ** (num - 1) * 3 - least_AGC_num(num)


