# ACGT文字列が問題の条件にマッチするならば真となる述語
@lru_cache(maxsize=None)
def p(s):
    return all(
        'AGC' not in s[:i] + s[i + 1:i + 2] + s[i] + s[i + 2:]
        for i in range(len(s))
    )


