@lru_cache(maxsize=None)
def f(i, s):
    return (
        0 if i == 3 and not p(s) else
        1 if i == 3 and p(s) else
        sum(f(i - 1, t) for t in T if t[1:] == s[:2] and p(t + s[-1]))
    )


