def runEXP(N, P):
	if P == 0:
		return 1
	if P == 1:
		return N
	if P == 2:
		return N * N
	else:
		if P % 2 == 0:
			tmp = runEXP(N, P // 2)
			return  (tmp % 1000000007) * (tmp % 1000000007)
		else:
			P -= 1
			tmp = runEXP(N, P // 2)
			return  (tmp % 1000000007) *  (tmp % 1000000007) * N

