use std::ops::*;

const MOD: usize = 1000000007;
#[derive(Copy, Clone)]
struct ModInt {
    n: usize,
}

impl ModInt {
    fn pow(self, power: usize) -> ModInt {
        if power == 0 {
            return mod_int(1);
        }
        if power % 2 == 0 {
            let t = self.pow(power/2);
            return t * t;
        }
        self * self.pow(power-1)
    }
    fn inv(self) -> ModInt {
        self.pow(MOD - 2)
    }
}

fn mod_int(n: usize) -> ModInt {
    ModInt { n: n % MOD }
}

impl Add for ModInt {
    type Output = ModInt;

    fn add(self, rhs: ModInt) -> ModInt {
        let mut tmp = self;
        tmp.n += rhs.n;
        if tmp.n >= MOD {
            tmp.n -= MOD;
        }
        tmp
    }
}

impl AddAssign for ModInt {
    fn add_assign(&mut self, rhs: ModInt) {
        *self = *self + rhs;
    }
}

impl Sub for ModInt {
    type Output = ModInt;

    fn sub(self, rhs: ModInt) -> ModInt {
        let mut tmp = self;
        if tmp.n < rhs.n {
            tmp.n += MOD;
        }
        tmp.n -= rhs.n;
        tmp
    }
}

impl SubAssign for ModInt {
    fn sub_assign(&mut self, rhs: ModInt) {
        *self = *self - rhs;
    }
}

impl Mul for ModInt {
    type Output = ModInt;

    fn mul(self, rhs: ModInt) -> ModInt {
        let mut tmp = self;
        tmp.n *= rhs.n;
        tmp.n %= MOD;
        tmp
    }
}

impl MulAssign for ModInt {
    fn mul_assign(&mut self, rhs: ModInt) {
        *self = *self * rhs;
    }
}

impl Div for ModInt {
    type Output = ModInt;

    fn div(self, rhs: ModInt) -> ModInt {
        let mut tmp = self;
        tmp.n *= rhs.inv().n;
        tmp.n %= MOD;
        tmp
    }
}

impl DivAssign for ModInt {
    fn div_assign(&mut self, rhs: ModInt) {
        *self = *self / rhs;
    }
}

