                // AGC, ACG, GAC はだめ
                if i == 1 && j == 3 && k == 2
                    || i == 1 && j == 2 && k == 3
                    || i == 3 && j == 1 && k == 2
                {
                    continue;
                }
                dp[3][i][j][k] = 1;
            }
        }
    }

    for n in 4..=N {
        // AGC, ACG, GAC, A*GC, AG*C がだめなパターン
        // これらNGパターンに遷移しないように遷移式を構築していく
        for i in 1..5 {
            for j in 1..5 {
                for k in 1..5 {
                    for any in 1..5 {
                        // AGC
                        let agc = i == 1 && j == 3 && k == 2;
                        // ACG
                        let acg = i == 1 && j == 2 && k == 3;
                        // GAC
                        let gac = i == 3 && j == 1 && k == 2;
                        // A*GC
                        let a_gc = any == 1 && j == 3 && k == 2;
                        // AG*C
                        let ag_c = any == 1 && i == 3 && k == 2;
                        if agc || acg || gac || a_gc || ag_c {
                            continue;
                        }
                        dp[n][i][j][k] += dp[n - 1][any][i][j];
                        dp[n][i][j][k] %= MOD;
                    }
                }
            }
        }
    }

    let mut ans = 0;
    for i in 1..5 {
        for j in 1..5 {
            for k in 1..5 {
                ans += dp[N][i][j][k];
                ans %= MOD;
            }
        }
    }
    println!("{}", ans);
}

