#[allow(unused_imports)]
use std::cmp::*;
#[allow(unused_imports)]
use std::collections::*;

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

fn is_disallowed(i: usize, j: usize, k: usize, l: usize) -> bool {
    // disallowed:
    // AGC: 0 2 1
    // GAC: 2 0 1
    // ACG: 0 1 2
    // AXGC: 0 X 2 1
    // AGXC: 0 2 X 1

    // AGC: 0 2 1
    if i == 0 && j == 2 && k == 1 {
        return false;
    }
    if j == 0 && k == 2 && l == 1 {
        return false;
    }

    // GAC: 2 0 1
    if i == 2 && j == 0 && k == 1 {
        return false;
    }
    if j == 2 && k == 0 && l == 1 {
        return false;
    }
    // ACG: 0 1 2
    if i == 0 && j == 1 && k == 2 {
        return false;
    }
    if j == 0 && k == 1 && l == 2 {
        return false;
    }

    // AXGC: 0 X 2 1
    // AGXC: 0 2 X 1
    if i == 0 && k == 2 && l == 1 {
        return false;
    }
    if i == 0 && j == 2 && l == 1 {
        return false;
    }
    true
}

fn main() {
    let n = read::<usize>();
    let big_int: u64 = 1000_000_000 + 7;
    if n == 3 {
        println!("61");
        return;
    }

    let mut dp = vec![vec![vec![vec![vec![0u64; 4]; 4]; 4]; 4]; n];
    // 0: A, 1: C, 2: G, 3: T
    for i in 0..4 {
        for j in 0..4 {
            for k in 0..4 {
                for l in 0..4 {
                    if !is_disallowed(i, j, k, l) {
                        continue;
                    }
                    dp[0][i][j][k][l] = 1;
                }
            }
        }
    }

    for ni in 1..n - 3 {
        for i in 0..4 {
            for j in 0..4 {
                for k in 0..4 {
                    for l in 0..4 {
                        if !is_disallowed(i, j, k, l) {
                            continue;
                        }
                        dp[ni][i][j][k][l] += dp[ni - 1][0][i][j][k];
                        dp[ni][i][j][k][l] %= big_int;
