    }

    let mut dp = vec![vec![vec![vec![Mod::new(0); 4]; 4]; 4]; n + 1];

    dp[0][3][3][3] = 1.into();

    for i in 0..n {
        for c in 0..4 {
            for d in 0..4 {
                for e in 0..4 {
                    // ACGT

                    // AGC => 0, 2, 1
                    // .ACG
                    // .AGC
                    // .GAC
                    // A.CG
                    // AC.G

                    for f in 0..4 {
                        if d == 0 && e == 2 && f == 1
                            || d == 0 && e == 1 && f == 2
                            || d == 2 && e == 0 && f == 1
                            || c == 0 && e == 2 && f == 1
                            || c == 0 && d == 2 && f == 1
                        {
