                    }
                    // 新しく追加する文字列
                    for a in 0..4 {
                        if
                            a == 2 && c1 == 1 && c2 == 0 ||
                            a == 2 && c1 == 0 && c2 == 1 ||
                            a == 1 && c1 == 2 && c2 == 0 ||
                            a == 2 && c1 == 1 && c3 == 0 ||
                            a == 2 && c2 == 1 && c3 == 0 {
                           continue;
                        }

                        dp[len+1][a][c1][c2] += dp[len][c1][c2][c3];
                        dp[len+1][a][c1][c2] %= MOD;
                    }
                }
            }
        }
    }
    let mut ans = 0;
    for c1 in 0..4 {
        // 最後から2文字目
        for c2 in 0..4 {
            // 最後から3文字目
            for c3 in 0..4 {
                ans += dp[n][c1][c2][c3];
                ans %= MOD;
            }
        }
    }
    println!("{}", ans);
}

