fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
    }
    let mut dp = vec![[[[ModInt::new(0); 4]; 4]; 4]; n + 1];
    let mut ban = [[[[false; 4]; 4]; 4]; 4];
    // A -> 0, C -> 1, G -> 2, T -> 3
    for i in 0..4 {
        // AGC
        ban[i][0][2][1] = true;
        // A?GC
        ban[0][i][2][1] = true;
        // GAC
        ban[i][2][0][1] = true;
        // ACG
        ban[i][0][1][2] = true;
        // AG?C
        ban[0][2][i][1] = true;
    }
    // Let us fill with 'T' first, because 'T' is most unlikely to interact with something.
    dp[0][3][3][3] = ModInt::new(1);
    for i in 0..n {
        for j in 0..4 {
            for k in 0..4 {
                for l in 0..4 {
                    for u in 0..4 {
                        if !ban[j][k][l][u] {
                            dp[i + 1][k][l][u] += dp[i][j][k][l];
                        }
                    }
                }
            }
        }
    }
    let mut tot = ModInt::new(0);
    for i in 0..4 {
        for j in 0..4 {
            for k in 0..4 {
                tot += dp[n][i][j][k];
            }
        }
    }
    puts!("{}\n", tot);
}

