macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

const MOD: usize = 1000000007;
fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    // a: 0, c: 1, g: 2, t: 3
    let mut dp = vec![vec![vec![0; 4]; 4]; 4];
    for i in 0..4 {
        for j in 0..4 {
            for k in 0..4 {
                match (i, j, k) {
                    (0, 2, 1) | (2, 0, 1) | (0, 1, 2) => (),
                    (i, j, k) => dp[i][j][k] = 1,
                }
            }
        }
    }

    for i in 3..n {
        let mut buf = vec![vec![vec![0; 4]; 4]; 4];
        for j in 0..4 {
            for k in 0..4 {
                for l in 0..4 {
                    for m in 0..4 {
                        match (j, k, l, m) {
                            (_, 0, 2, 1) | (_, 0, 1, 2) | (_, 2, 0, 1) => buf[k][l][m] = 0,
                            (0, _, 2, 1) | (0, 2, _, 1) => (),
                            (i, j, k, l) => {
                                buf[j][k][l] += dp[i][j][k];
                                buf[j][k][l] %= MOD
                            }
                        }
                    }
                }
            }
        }
        dp = buf;
    }
    let mut ret = 0;
    for i in 0..4 {
        for j in 0..4 {
            for k in 0..4 {
                ret += dp[i][j][k];
                ret %= MOD;
            }
        }
    }
    println!("{}", ret);
}

