const M: usize = 1_000_000_007;

#[fastout]
fn main() {
    input! {
        n: usize,
    }

    let mut memo = HashMap::new();
    let ans = rec("TTT", n, &mut memo);
    println!("{}", ans);
}

fn rec(s: &str, count: usize, memo: &mut HashMap<(usize, String), usize>) -> usize {
    if let Some(&res) = memo.get(&(count, s.to_string())) {
        return res;
    }
    if count == 0 {
        return 1;
    }

    let mut res = 0usize;
    for c in "AGCT".chars() {
        let mut s = s.to_string();
        s.push(c);
        if is_valid(&s) {
            res += rec(&s[1..], count-1, memo);
            res %= M;
        }
    }
    memo.insert((count, s.to_string()), res);
    res
}

fn is_valid(s: &str) -> bool {
    if s.contains("GAC") || s.contains("ACG") || s.contains("AGC") {
        return false;
    }
    let s2 = "".to_string() + &s[0..1] + &s[2..];
    if s2 == "AGC" {
        return false;
    }
    let s2 = "".to_string() + &s[0..2] + &s[3..];
    if s2 == "AGC" {
        return false;
    }
    true
}

