const MOD: usize = 1e9 as usize + 7;

fn sub(a: usize, b: usize) -> usize {
    ((a +MOD) - b)%MOD
}

fn main() {
    input!{
      n: usize,
    }
    let mut dp = vec![vec![vec![0; 4]; 4]; n];
    for i in 0..4 {
        for j in 0..4 {
            dp[0][i][j] = 1;
        }
    }

    for i in 1..n-1 {
        for c1 in 0..4 {
            for c2 in 0..4 {
                for c3 in 0..4 {
                    dp[i][c1][c2] += dp[i-1][c2][c3];
                    dp[i][c1][c2] %= MOD;
                }
            }
        }

        dp[i][2][1] = sub(dp[i][2][1], dp[i-1][1][0]); // a -> g -> c
        // A*GC pattern
        if i >= 2 {
            for c in 0..4 {
                if c != 0 {
                    dp[i][2][1] = sub(dp[i][2][1], dp[i-2][c][0]);
                }
            }
        }

        dp[i][2][0] = sub(dp[i][2][0], dp[i-1][0][1]); // g -> a -> c
        dp[i][1][2] = sub(dp[i][1][2], dp[i-1][2][0]); // a -> c -> g
    }
    // for i in 0..n-1 {
    //     debug!(dp[i]);
    // }

    let mut ans = 0;
    for c1 in 0..4 {
        for c2 in 0..4 {
            ans += dp[n-2][c1][c2];
            ans %= MOD;
        }
    }
    println!("{}", ans);
}

