use std::collections::HashMap;


const MOD: u64 = 1000000007;

fn main() {
    let n: usize = read();

    println!("{:?}", solve(n));
}


fn solve(n: usize) -> u64 {
    let mut g = G::new(n);

    g.dfs(0, "TTT".to_string())
}


#[derive(Debug)]
struct G {
    n: usize,
    memo: Vec<HashMap<String, u64>>,
}

impl G {
    fn new(n: usize) -> Self {
        G {
            n: n,
            memo: vec![HashMap::new(); n + 1],
        }
    }


    fn dfs(&mut self, cur: usize, last3: String) -> u64 {
        if let Some(ret) = self.memo[cur].get(&last3) {
            return *ret
        }

        if cur == self.n {
            return 1
        }

        let mut ret = 0;
        for c in "AGCT".chars() {
            let last4 = {
                let mut tmp = last3.clone();
                tmp.push(c);
                tmp
            };

            if Self::check(&last4) {
                ret = (ret + self.dfs(cur + 1, splt_off(&last4, 1))) % MOD;
            }
        }
        self.memo[cur].insert(last3, ret);
        ret
    }

    fn check(last4: &String) -> bool {
        let mut ret = true;
        for i in 0..4 {
            unsafe {
                let mut t = last4.clone();
                let mut t = t.as_mut_vec();

                if i >= 1 {
                    // (t[i - 1], t[i]) = (t[i], t[i - 1]);
                    let tmp = t[i];
                    t[i] = t[i - 1];
                    t[i - 1] = tmp;
                }

                if is_sub_string(&String::from_utf8_unchecked(t.to_vec()), &"AGC".to_string()) {
                    ret = false;
                    break;
                }
            }
        }

        ret
    }
}


fn is_sub_string(s: &String, key: &String) -> bool {
    s.matches(key).collect::<Vec<&str>>().len() >= 1
}

fn splt_off(s: &String, mid: usize) -> String {
    let (_, last) = s.split_at(mid);
    last.to_string()
}


fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

