fn check(v: [char; 4]) -> bool {
    let po = ['A', 'G', 'C'];
    for i in 0..4 {
        for j in i..4 {
            if i == 0 && j > 1 {
                continue;
            }
            if i == 1 && j > 2 {
                continue;
            }
            let mut ok = true;
            for k in 0..3 {
                if k == i {
                    if v[j] != po[k] {
                        ok = false;
                    }
                } else if k == j {
                    if v[i] != po[k] {
                        ok = false;
                    }
                } else {
                    if v[k] != po[k] {
                        ok = false;
                    }
                }
            }
            if ok {
                return true;
            }
            ok = true;
            for k in 1..4 {
                if k == i {
                    if v[j] != po[k-1] {
                        ok = false;
                    }
                } else if k == j {
                    if v[i] != po[k-1] {
                        ok = false;
                    }
                } else {
                    if v[k] != po[k-1] {
                        ok = false;
                    }
                }
            }
            if ok {
                return true;
            }
        }
    }
    return false;
}

