pub const MOD: usize = 1000000007;

fn main() {
    let n: usize = input();
    let mut ans = 0usize;
    let s = String::new();

    dfs(s, n, &mut ans);
    println!("{}", ans);
}

fn dfs(s: String, lim: usize, ans: &mut usize) {
    if s.len() == lim {
        *ans += 1;
        return;
    }

    if s.ends_with("AG") {
        for c in "AGT".chars() {
            dfs(
                {
                    let mut s = s.clone();
                    s.push(c);
                    s
                },
                lim,
                ans,
            );
        }
    } else if s.chars().peekable().nth_back(2).unwrap_or(' ') == 'A'
        && s.chars().peekable().nth_back(1).unwrap_or(' ') == 'G'
    {
        for c in "AGT".chars() {
            dfs(
                {
                    let mut s = s.clone();
                    s.push(c);
                    s
                },
                lim,
                ans,
            );
        }
    } else if s.chars().peekable().nth_back(2).unwrap_or(' ') == 'A'
        && s.chars().peekable().nth_back(0).unwrap_or(' ') == 'G'
    {
        for c in "AGT".chars() {
            dfs(
                {
                    let mut s = s.clone();
                    s.push(c);
                    s
                },
                lim,
                ans,
            );
        }
    } else if s.ends_with("AC") {
        for c in "ACT".chars() {
            dfs(
                {
                    let mut s = s.clone();
                    s.push(c);
                    s
                },
                lim,
                ans,
            );
        }
    } else if s.ends_with("GA") {
        for c in "AGT".chars() {
            dfs(
                {
                    let mut s = s.clone();
                    s.push(c);
                    s
                },
                lim,
                ans,
            );
        }
    } else {
        for c in "AGCT".chars() {
            dfs(
                {
                    let mut s = s.clone();
                    s.push(c);
                    s
                },
                lim,
                ans,
            );
        }
    }
}

