const R: u64 = 1000000007;

fn main() {
    let n: usize = read();

    let mut dp: Vec<Vec<Vec<Vec<u64>>>> = vec![vec![vec![vec![1; 4]; 4]; 4]; 101];
    dp[3][0][2][1] = 0;
    dp[3][2][0][1] = 0;
    dp[3][0][1][2] = 0;

    for i in 4..(n + 1) {
        for q in 0..4 {
            for r in 0..4 {
                for s in 0..4 {
                    if q == 0 && r == 2 && s == 1 {
                        dp[i][q][r][s] = 0;
                    } else if q == 2 && r == 0 && s == 1 {
                        dp[i][q][r][s] = 0;
                    } else if q == 0 && r == 1 && s == 2 {
                        dp[i][q][r][s] = 0;
                    } else if r == 2 && s == 1 || q == 2 && s == 1 {
                        dp[i][q][r][s] =
                            (dp[i - 1][1][q][r] + dp[i - 1][2][q][r] + dp[i - 1][3][q][r]) % R;
                    } else {
                        dp[i][q][r][s] = (dp[i - 1][0][q][r]
                            + dp[i - 1][1][q][r]
                            + dp[i - 1][2][q][r]
                            + dp[i - 1][3][q][r])
                            % R;
                    }
                }
            }
        }
    }

    let mut ans: u64 = 0;
    for q in 0..4 {
        for r in 0..4 {
            for s in 0..4 {
                ans = (ans + dp[n][q][r][s]) % R;
            }
        }
    }
    println!("{}", ans);
}

