}

const MOD: i64 = 1e+9 as i64 + 7;

fn calc(n: usize, depth: usize, prev: Vec<char>, memo: &mut Vec<HashMap<Vec<char>, i64>>) -> i64 {
    if depth == n {
        return 1;
    }
    if let Some(&ret) = memo[depth].get(&prev) {
        return ret;
    }
    let mut ret = 0;
    for &c in ['A', 'G', 'C', 'T'].iter() {
        if prev.len() >= 2 {
            let mut last_two = vec![];
            last_two.push(prev[prev.len() - 2]);
            last_two.push(prev[prev.len() - 1]);
            if last_two == vec!['A', 'G'] && c == 'C'
                || last_two == vec!['G', 'A'] && c == 'C'
                || last_two == vec!['A', 'C'] && c == 'G'
            {
                continue;
            }
        }
        if prev.len() == 3
            && ((prev[0] == 'A' && prev[1] == 'G' && c == 'C')
                || (prev[0] == 'A' && prev[2] == 'G' && c == 'C'))
        {
            continue;
        }
        let mut next = prev.clone();
        next.push(c);
        // println!("{:?}", next);
        if next.len() == 4 {
            next.remove(0);
        }
        ret = (ret + calc(n, depth + 1, next, memo)) % MOD;
    }
    memo[depth].insert(prev, ret);
    ret
}

fn main() {
    let n = read::<usize>();
    let mut memo = vec![HashMap::<Vec<char>, i64>::new(); n];
    let ans = calc(n, 0, vec![], &mut memo);
    println!("{}", ans);
}

