fn check(s: String) -> bool {
    if s.contains("AGC") {
        return false;
    }
    for i in 0..s.len()-1 {
        let mut c: Vec<char> = s.chars().collect();
        let c0 = c[i];
        let c1 = c[i+1];
        c[i] = c1;
        c[i+1] = c0;
        let tmp_s = c.iter().fold("".to_string(), |acc, x| format!("{}{}", acc, x));
        if tmp_s.contains("AGC") {
            return false;
        }
    }
    true
}

fn dfs(d: i32, N: i32, last_s: String, hm: &mut HashMap<(i32, String), i32>) -> i32 {
    if d == N {
        return 1
    }
    if hm.contains_key(&(d, last_s.clone())) {
        return hm.get(&(d, last_s.clone())).unwrap().clone();
    }
    let mut tmp_cnt = 0;
    let chars = ["A".to_string(), "G".to_string(), "C".to_string(), "T".to_string()];
    for c in chars.iter() {
        let s: String = format!("{}{}", last_s.clone(), c.clone());
        if check(s) {
            let mut next_s = last_s.clone();
            next_s.remove(0);
            let next_s: String = format!("{}{}", next_s, c.clone());
            tmp_cnt = (tmp_cnt + dfs(d+1, N, next_s, hm)) % 1000000007;
        }
    }
    hm.insert((d, last_s), tmp_cnt);
    tmp_cnt
}

