#[derive(Copy, Clone)]
pub struct Mint(pub i64);

impl Mint {
    pub fn set_mod(modulo: i32) {
        unsafe {
            MODULO = modulo as i64;
        }
    }
    pub fn value(self) -> i64 {
        self.0
    }
}

impl ::std::fmt::Display for Mint {
    fn fmt(&self, f: &mut ::std::fmt::Formatter) -> ::std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

/// ```
/// use contest::math::Mint;
/// Mint::set_mod(5);
/// let a = Mint(2);
/// let b = Mint(3);
/// assert_eq!(0, (a + b).0);
/// assert_eq!(1, (b + b).0);
/// assert_eq!(4, (a + a).0);
/// ```
impl Add for Mint {
    type Output = Mint;
    fn add(self, o: Mint) -> Mint {
        let mut x = self.0 + o.0;
        if x >= modulo() {
            x -= modulo();
        }
        Mint(x)
    }
}

/// ```
/// use contest::math::Mint;
/// Mint::set_mod(5);
/// let mut a = Mint(2);
/// a += Mint(4);
/// assert_eq!(1, a.0);
/// ```
impl AddAssign for Mint {
    fn add_assign(&mut self, o: Mint) {
        let mut x = self.0 + o.0;
        if x >= modulo() {
            x -= modulo();
        }
        self.0 = x;
    }
}

/// ```
/// use contest::math;
/// assert_eq!(3, math::inv(2,5));
/// assert_eq!(1, math::inv(1,2));
/// assert_eq!(1, math::inv(3,2));
/// ```
pub fn inv(value: i32, modulo_prime: i32) -> i32 {
    return pow_mod(value, modulo_prime - 2, modulo_prime);
}

/// ```
/// use contest::math;
/// assert_eq!(8, math::pow_mod(2,3,10));
/// assert_eq!(1, math::pow_mod(3,4,10));
/// assert_eq!(1, math::pow_mod(0,0,3));
/// assert_eq!(0, math::pow_mod(0,0,1));
/// ```
pub fn pow_mod(value: i32, exponent: i32, modulo: i32) -> i32 {
    if exponent < 0 {
        panic!("Exponent should >= 0.");
    }
    if modulo == 1 {
        return 0;
    }
    let modulo = modulo as i64;
    let mut value = value as i64;
    if value >= modulo {
        value %= modulo;
    }
    if value < 0 {
        value = value % modulo + value;
    }
    let mut res = 1;
    let mut exponent = exponent;
    while exponent > 0 {
        if (exponent & 1) == 1 {
            res = res * value % modulo;
        }
        value = value * value % modulo;
        exponent >>= 1;
    }
    res as i32
}

