struct Dfs {
    n: usize,
    dp: Vec<Vec<Vec<Vec<i32>>>>,
}
impl Dfs {
    fn get_vec(&self, i1: usize, i2: usize, i3: usize) -> Vec<usize> {
        // 0123
        // ACGT
        // AGC   02 1
        if i2 == 0 && i1 == 2 {
            return vec![0, 2, 3];
        }
        // ACG   01 2
        if i2 == 0 && i1 == 1 {
            return vec![0, 1, 3];
        }
        // GAC   20 1
        if i2 == 2 && i1 == 0 {
            return vec![0, 2, 3];
        }
        // A?GC 0?2 1
        if i3 == 0 && i1 == 2 {
            return vec![0, 2, 3];
        }
        // AG?C 02? 1
        if i3 == 0 && i2 == 2 {
            return vec![0, 2, 3];
        }
        return vec![0, 1, 2, 3];
    }
    fn res(&mut self, idx: usize, i1: usize, i2: usize, i3: usize) -> i32 {
        if idx == self.n {
            // print!("{}{}{}, ", i3, i2, i1);
            return 1;
        }
        // println!("{}:{} /  {}{}{}", idx, self.n, i3, i2, i1);
        if self.dp[idx][i1][i2][i3] != -1 {
            return self.dp[idx][i1][i2][i3];
        }
        let v = match idx {
            0 | 1 => vec![0, 1, 2, 3],
            _ => self.get_vec(i1, i2, i3),
        };
        // println!("{} {}{}{} => {:?}", idx, i3, i2, i1, v);
        let m = (1000 * 1000 * 1000) + 7;
        let ans = v
            .into_iter()
            .fold(0, |s, i| (s + self.res(idx + 1, i, i1, i2)) % m);
        self.dp[idx][i1][i2][i3] = ans;
        return ans;
    }
}

fn main() {
    input! {
        n: usize,
    }
    let dp = vec![vec![vec![vec![-1; 10]; 10]; 10]; n];
    let mut dfs = Dfs { n: n, dp: dp };
    println!("{:?}", dfs.res(0, 9, 9, 9));
}

