fn main() {
    const MOD: u64 = 1_000_000_000 + 7;
    const LETTERS: &'static str = "ACGT";
    const PROHIBIT: [&'static str; 6] =
        ["AGC", "ACG", "GAC", "AGGC", "AGTC", "ATGC"];

    let n: usize = read_and_parse();
    let mut table = Vec::new();
    let mut codons = Vec::new();
    table.resize(61, Vec::new());

    for codon in table.iter_mut() { codon.resize(n - 2, 0); codon[0] = 1 }

    for first in LETTERS.chars() {
        for second in LETTERS.chars() {
            for third in LETTERS.chars() {
                let mut codon: String = String::new();
                codon.push(first);
                codon.push(second);
                codon.push(third);

                if !PROHIBIT[..3].contains(&codon.as_str()) {
                    codons.push(codon);
                }
            }
        }
    }

    for i in 0..(n - 3) {
        for (codon_id, codon) in codons.iter().enumerate() {
            for append in LETTERS.chars() {
                let mut four_letters = codon.clone();
                four_letters.push(append);
                let mut three_letters = codon[1..].to_string();
                three_letters.push(append);

                if PROHIBIT[..3].contains(&three_letters.as_str()) ||
                       PROHIBIT[3..].contains(&four_letters.as_str()) {
                    continue ;
                }

                let matched_index =
                    codons.binary_search(&three_letters).ok().unwrap();

                table[matched_index][i + 1] += table[codon_id][i];
                table[matched_index][i + 1] %= MOD;
            }
        }
    }

    println!("{}" , table . iter (  ) . fold (
             0 , | acc , codon | ( acc + codon . last (  ) . unwrap (  ) ) %
             MOD ));
}

const MOD: i32 = 1000000007;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let mut dp = vec![vec![vec![vec![0; 4]; 4]; 4]; n + 1];
    //0 -> other
    //1 -> A
    //2 -> G
    //3 -> C
    let p = vec!['T', 'A', 'G', 'C'];
    let agc = "AGC".to_string();
    dp[0][0][0][0] = 1;

    for i in 0..n {
        for j in 0..4 {
            for k in 0..4 {
                for l in 0..4 {
                    if dp[i][j][k][l] == 0 {
                        continue;
                    }
                    for m in 0..4 {
                        let tmp = format!("{}{}{}{}", p[j], p[k], p[l], p[m]);
                        let mut ok = true;
                        if tmp.contains(&agc) {
                            ok = false;
                        }
                        for o in 0..tmp.len() - 1 {
                            let mut tmp1 = tmp.clone().chars().collect::<Vec<char>>();
                            tmp1.swap(o, o + 1);
                            let tmp2: String = tmp1.into_iter().collect();
                            if tmp2.contains(&agc) {
                                ok = false;
                                break;
                            }
                        }

                        if ok {
                            dp[i + 1][k][l][m] += dp[i][j][k][l];
                            dp[i + 1][k][l][m] %= MOD;
                        }
                    }
                }
            }
        }
    }
    let mut res = 0;
    for i in 0..4 {
        for j in 0..4 {
            for k in 0..4 {
                let tmp = format!("{}{}{}", p[i], p[j], p[k]);
                if tmp.contains(&agc) {
                    continue;
                }
                let mut ok = true;
                for o in 0..tmp.len() - 1 {
                    let mut tmp1 = tmp.clone().chars().collect::<Vec<char>>();
                    tmp1.swap(o, o + 1);
                    let tmp2: String = tmp1.into_iter().collect();
                    if tmp2.contains(&agc) {
                        ok = false;
                        break;
                    }
                }
                if ok {
                    res += dp[n][i][j][k];
                    res %= MOD;
                }
            }
        }
    }
    println!("{}", res);
}

