const MOD: u64 = 1000000007;

fn add_mod(a: u64, b: u64) -> u64 {
    (a + b) % MOD
}

fn sub_mod(a: u64, b: u64) -> u64 {
    (a + MOD - b) % MOD
}

fn mul_mod(a: u64, b: u64) -> u64 {
    (a * b) % MOD
}

fn pow_mod(base: u64, exp: u64) -> u64 {
    if exp == 0 {
        1
    } else if exp == 1 {
        base
    } else {
        let prev = pow_mod(base, exp / 2);
        let tmp = if exp % 2 == 0 { 1 } else { base };
        mul_mod(mul_mod(prev, prev), tmp)
    }
}

fn div_mod(a: u64, b: u64) -> u64 {
    mul_mod(a, pow_mod(b, MOD - 2))
}

fn combination_mod(n: u64, k: u64) -> u64 {
    let mut ret = 1;
    for i in 0..k {
        let mul = if i < n { n - i } else { 0 };
        ret = div_mod(mul_mod(ret, mul), i + 1);
        println!("{}a", ret);
    }
    ret
}

use std::io::*;
use std::str::FromStr;

const MOD: usize = 1_000_000_007;

fn check(v: [char; 4]) -> bool {
    if func(v) {
        return true;
    }
    for i in 0..3 {
        let mut v = v.clone();
        let mut a1 = v[i];
        let mut a2 = v[i+1];
        std::mem::swap(&mut a1, &mut a2);
        v[i] = a1;
        v[i+1] = a2;
        if func(v) {
            return true;
        }
    }
    return false;
}

fn func(v: [char; 4]) -> bool {
    let po = ['A', 'G', 'C'];
    let mut ok = true;
    for k in 0..3 {
        if v[k] != po[k] {
            ok = false;
        }
    }
    if ok {
        return true;
    }
    ok = true;
    for k in 1..4 {
        if v[k] != po[k-1] {
            ok = false;
        }
    }
    if ok {
        return true;
    }
    return false;
}

fn main() {
    let n: usize = read();

    let po = ['A', 'C', 'G', 'T'];
    let mut dp = vec![[[[0; 4]; 4]; 4]; n];
    for i in 0..4 {
        for j in 0..4 {
            for k in 0..4 {
                let nya = [['A','G','C'], ['A','C','G'], ['G','A','C']];
                let mut ok = true;
                for l in 0..3 {
                    if po[i] == nya[l][0] && po[j] == nya[l][1] && po[k] == nya[l][2] {
                        ok = false;
                    }
                }
                dp[0][i][j][k] = if ok {1} else {0};
            }
        }
    }
    for i in 0..n-3 {
        for j in 0..4 {
            for k in 0..4 {
                for l in 0..4 {
                    for m in 0..4 {
                        if !check([po[j], po[k], po[l], po[m]]) {
                            dp[i+1][k][l][m] += dp[i][j][k][l];
                            dp[i+1][k][l][m] %= MOD;
                        }
                    }
                }
            }
        }
    }
    let mut ans = 0;
    for j in 0..4 {
        for k in 0..4 {
            for l in 0..4 {
                ans += dp[n-3][j][k][l];
                ans %= MOD;
            }
        }
    }
    println!("{}", ans);
}

