fn solve() {
    input!{
        N:usize,
    }
    let mo = 1_000_000_007;

    // dp[a][b][c][k]
    // 前3つがa,b,c
    // A=0,C=1,G=2,T=3
    // 今見るのがk
    let mut dp = vec![vec![vec![vec![0;N+1];4];4];4];
    for a in 0..4 {
        for b in 0..4 {
            for c in 0..4 {
                if (a,b,c)!=(0,1,2) && (a,b,c)!=(1,0,2) && (a,b,c)!=(0,2,1) {
                    dp[a][b][c][3]=1;
                }
            }
        }
    }
    for k in 4..N+1 {
        for a in 0..4 {
            for b in 0..4 {
                for c in 0..4 {
                    for d in 0..4 { // 新しい文字
                        if (b,c)==(0,1) {
                            if d!=2 {
                                dp[b][c][d][k] += dp[a][b][c][k-1];
                            }
                        }
                        else if (b,c)==(1,0) {
                            if d!=2 {
                                dp[b][c][d][k] += dp[a][b][c][k-1];
                            }
                        }
                        else if (b,c)==(0,2) {
                            if d!=1 {
                                dp[b][c][d][k] += dp[a][b][c][k-1];
                            }
                        }
                        else if (a,b)==(0,1) {
                            if d!=2 {
                                dp[b][c][d][k] += dp[a][b][c][k-1];
                            }
                        }
                        else if (a,c)==(0,1) {
                            if d!=2 {
                                dp[b][c][d][k] += dp[a][b][c][k-1];
                            }
                        }
                        else {
                            dp[b][c][d][k] += dp[a][b][c][k-1];
                        }
                        dp[b][c][d][k] %= mo;
                    }
                }
            }
        }
    }
    // dbg!(&dp);

    let mut res = 0;
    for a in 0..4 {
        for b in 0..4 {
            for c in 0..4 {
                res += dp[a][b][c][N];
                res %= mo;
            }
        }
    }
    println!("{}",res);
}

