#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}


fn main() {
    const MOD: i64 = 1000000007;
    input! {
        n: usize,
    }
    let mut dp: [[[i64; 4]; 4]; 4] = [[[1; 4]; 4]; 4];
    dp[0][1][2] = 0;
    dp[1][0][2] = 0;
    dp[0][2][1] = 0;
    for _ in 3..n {
        let mut ndp: [[[i64; 4]; 4]; 4] = [[[0; 4]; 4]; 4];
        for i in 0..4 {
            for j in 0..4 {
                for k in 0..4 {
                    for l in 0..4 {
                        if (j, k, l) == (0, 1, 2) ||
                            (j, k, l) == (1, 0, 2) ||
                            (j, k, l) == (0, 2, 1) ||
                            (i, j, l) == (0, 1, 2) ||
                            (i, k, l) == (0, 1, 2) {} else {
                            ndp[j][k][l] += dp[i][j][k];
                        }
                    }
                }
            }
        }
        dp = ndp;
        for i in 0..4 {
            for j in 0..4 {
                for k in 0..4 {
                    dp[i][j][k] %= MOD;
                }
            }
        }
    }
    let ans = dp.iter().fold(0, |s, a|
        (s + a.iter().fold(0, |t, b|
            (t + b.iter().fold(0, |u, c| (u + c) % MOD)) % MOD)) % MOD);
    println!("{}", ans)
}

use std::io::prelude::*;

fn input<T>() -> T
    where T: std::str::FromStr {
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}


fn main() {
    const MOD: usize =  1_000_000_000 + 7;
    let n = input::<usize>();
    let mut dp = vec![vec![vec![vec![0; 4]; 4]; 4]; 101];

    dp[0][3][3][3] = 1;
    for len in 0..n {
        // 最後から1文字目
        for c1 in 0..4 {
            // 最後から2文字目
            for c2 in 0..4 {
                // 最後から3文字目
                for c3 in 0..4 {
                    if dp[len][c1][c2][c3] == 0 {
                        continue;
                    }
                    // 新しく追加する文字列
                    for a in 0..4 {
                        if a == 2 && c1 == 1 && c2 == 0 {
                           continue;
                        }
                        if a == 2 && c1 == 0 && c2 == 1 {
                           continue;
                        }
                        if a == 1 && c1 == 2 && c2 == 0 {
                           continue;
                        }
                        if a == 2 && c1 == 1 && c3 == 0 {
                           continue;
                        }
                        if a == 2 && c1 == 1 && c3 == 0 {
                           continue;
                        }

                        dp[len+1][a][c1][c2] += dp[len][c1][c2][c3];
                        dp[len+1][a][c1][c2] %= MOD;
                    }
                }
            }
        }
    }
    let mut ans = 0;
    for c1 in 0..4 {
        // 最後から2文字目
        for c2 in 0..4 {
            // 最後から3文字目
            for c3 in 0..4 {
                ans += dp[n][c1][c2][c3];
                ans %= MOD;
            }
        }
    }
    println!("{}", ans);
}

