use std::str::FromStr;

const MOD: usize = 1_000_000_007;

fn check(v: [char; 4]) -> bool {
    if func(&v[0..3]) || func(&v[1..4]) {
        return true;
    }
    for i in 0..3 {
        let mut v = v.clone();
        let mut a1 = v[i];
        let mut a2 = v[i+1];
        std::mem::swap(&mut a1, &mut a2);
        v[i] = a1;
        v[i+1] = a2;
        if func(&v[0..3]) || func(&v[1..4]) {
            return true;
        }
    }
    return false;
}

fn func(v: &[char]) -> bool {
    let po = ['A', 'G', 'C'];
    for k in 0..3 {
        if v[k] != po[k] {
            return false;
        }
    }
    return true;
}

fn main() {
    let n: usize = read();

    let po = ['A', 'C', 'G', 'T'];
    let mut dp = vec![[[[0; 4]; 4]; 4]; n];

    for i in 0..4 { for j in 0..4 { for k in 0..4 {
        dp[0][i][j][k] += 
            if check([po[i], po[j], po[k], 'X']){0}
            else {1};
    }}}

    for i in 0..n-3 {
        for j in 0..4 { for k in 0..4 { for l in 0..4 { for m in 0..4 {
            if !check([po[j], po[k], po[l], po[m]]) {
                dp[i+1][k][l][m] += dp[i][j][k][l];
                dp[i+1][k][l][m] %= MOD;
            }
        }}}}
    }

    let mut ans = 0;
    for j in 0..4 { for k in 0..4 { for l in 0..4 {
        ans += dp[n-3][j][k][l];
        ans %= MOD;
    }}}
    println!("{}", ans);
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

