#[allow(dead_code)]
struct UnionFind {
    parent: Vec<usize>,
    rank: Vec<usize>,
    size: Vec<usize>,
}

#[allow(dead_code)]
impl UnionFind {
    fn new(n: usize) -> UnionFind {
        let mut p = vec![0; n];
        for i in 0..n {
            p[i] = i;
        }
        return UnionFind {
            parent: p,
            rank: vec![0; n],
            size: vec![1; n],
        };
    }

    fn find(&mut self, x: usize) -> usize {
        if x == self.parent[x] {
            x
        } else {
            let p = self.parent[x];
            let pr = self.find(p);
            self.parent[x] = pr;
            pr
        }
    }

    fn same(&mut self, a: usize, b: usize) -> bool {
        self.find(a) == self.find(b)
    }

    fn unite(&mut self, a: usize, b: usize) {
        let a_root = self.find(a);
        let b_root = self.find(b);
        if self.rank[a_root] > self.rank[b_root] {
            self.parent[b_root] = a_root;
            self.size[a_root] += self.size[b_root];
        } else {
            self.parent[a_root] = b_root;
            self.size[b_root] += self.size[a_root];
            if self.rank[a_root] == self.rank[b_root] {
                self.rank[b_root] += 1;
            }
        }
    }

    fn get_size(&mut self, x: usize) -> usize {
        let root = self.find(x);
        self.size[root]
    }
}

const MOD_P: usize = 1000000007;

#[allow(dead_code)]
// fact(n) = n! mod p
fn fact(n: usize) -> usize {
    let mut acc = 1;
    for i in 1..n + 1 {
        acc = acc * i % MOD_P;
    }
    acc
}

#[allow(dead_code)]
fn mod_pow(b: usize, mut e: usize) -> usize {
    let mut base = b;
    let mut acc = 1;

    while e > 1 {
        if e % 2 == 1 {
            acc = acc * base % MOD_P;
        }
        e /= 2;
        base = base * base % MOD_P;
    }

    if e == 1 {
        acc = acc * base % MOD_P;
    }

    acc
}

#[allow(dead_code)]
fn comb(n: usize, r: usize) -> usize {
    // nCr = n! / (r! (n-r)!) = n! (r!)^(p-2) ((n-r)!)^(p-2)
    fact(n) * mod_pow(fact(r), MOD_P - 2) % MOD_P * mod_pow(fact(n - r), MOD_P - 2) % MOD_P
}

fn main() {
    input! {
        n: usize,
    }

    let mut dp = vec![vec![vec![vec![0; 4]; 4]; 4]; n + 1]; // dp[i][x][y][z] -> x, y, z と続いた i 文字の文字列で題意を満たすのが何通りあるか

    const A: usize = 0;
    const C: usize = 1;
    const G: usize = 2;
    const T: usize = 3;

    dp[0][T][T][T] = 1;

    for i in 0..n {
        for x in 0..4 {
            for y in 0..4 {
                for z in 0..4 {
                    for w in 0..4 {
                        match (x, y, z, w) {
                            (_, A, G, C)
                            | (_, A, C, G)
                            | (_, G, A, C)
                            | (A, _, G, C)
                            | (A, G, _, C) => continue,
                            _ => {
                                dp[i + 1][y][z][w] += dp[i][x][y][z];
                                dp[i + 1][y][z][w] %= MOD_P;
                            }
                        }
                    }
                }
            }
        }
    }

    let mut ans = 0;
    for x in 0..4 {
        for y in 0..4 {
            for z in 0..4 {
                ans += dp[n][x][y][z];
                ans %= MOD_P;
            }
        }
    }

    println!("{}", ans);
}

