fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
    }
    // trans
    let mut trans = vec![vec![]; 4 * 4 * 4];
    for i in 0..4 * 4 * 4 {
        let (i1, i2, i3) = (i / 4 / 4, i / 4 % 4, i % 4);
        for k in 0..4 * 4 * 4 {
            let (k1, k2, k3) = (k / 4 / 4, k / 4 % 4, k % 4);
            if i2 == k1 && i3 == k2 {
                if k1 == 0 && k2 == 2 && k3 == 1 {
                } else if k1 == 2 && k2 == 0 && k3 == 1 {
                } else if k1 == 0 && k2 == 1 && k3 == 2 {
                } else if i1 == 0 && k2 == 2 && k3 == 1 {
                } else if i1 == 0 && k1 == 2 && k3 == 1 {
                } else {
                    trans[i].push(k);
                }
            }
        }
    }
    // init?
    let mut dp = vec![Mod::new(1); 4 * 4 * 4];
    dp[0 * 4 * 4 + 2 * 4 + 1] = Mod::new(0);
    dp[2 * 4 * 4 + 0 * 4 + 1] = Mod::new(0);
    dp[0 * 4 * 4 + 1 * 4 + 2] = Mod::new(0);
    // dp
    for _ in 0..n - 3 {
        let mut dp2 = vec![Mod::new(0); 4 * 4 * 4];
        for i in 0..4 * 4 * 4 {
            for &next in &trans[i] {
                dp2[next] += dp[i];
            }
        }
        dp = dp2;
    }
    let mut res = Mod::new(0);
    for i in 0..64 {
        res += dp[i];
    }
    writeln!(buf, "{}", res.as_u64());
    buf
