static MOD: usize = 1_000_000_007;

fn input<T:FromStr>() -> T {
    let mut line: String = String::new();
    io::stdin().read_line(&mut line);
    line.trim().parse().ok().unwrap()
}

fn dfs(i: usize, s: &Vec<char>, n: usize, memo: &mut Vec<HashMap<Vec<char>, usize>>) -> usize {
    if i == n {
        return 1;
    }
    // println!("{:?}", memo);
    if memo[i].contains_key(s) {
        // println!("{:?}, {}", s, *memo[i].get(s).unwrap());
        return *memo[i].get(s).unwrap();
    }
    let mut candidates: Vec<char> = Vec::new();
    if s[1] == 'A' && s[2] == 'G' {
        candidates.push('A');
        candidates.push('T');
        candidates.push('G');       
    } else if s[0] == 'A' && s[2] == 'G' {
        candidates.push('A');
        candidates.push('T');
        candidates.push('G'); 
    } else if s[1] == 'G' && s[2] == 'A' {
        candidates.push('A');
        candidates.push('T');
        candidates.push('G'); 
    } else if s[1] == 'A' && s[2] == 'C' {
        candidates.push('A');
        candidates.push('T');
        candidates.push('C'); 
    } else if s[0] == 'A' && s[1] == 'G' {
        candidates.push('A');
        candidates.push('T');
        candidates.push('G'); 
    } else {
        candidates.push('A');
        candidates.push('T');
        candidates.push('G'); 
        candidates.push('C'); 
    }
    let mut sum = 0;
    for c in candidates {
        sum += dfs(i+1, &vec!(s[1], s[2], c).into_iter().collect(), n, memo);
    }
    sum %= MOD;

    let n = memo[i].entry(s.to_vec()).or_insert(0);
    *n = sum;
    return sum;
}

