fn main() {
    let n: usize = read();
    let mut dp = Vec::with_capacity(n + 1);
    for i in 0..(n + 1) {
        dp.push(Vec::with_capacity(64));
        for _ in 0..64 {
            dp[i].push(0);
        }
    }
    println!("{}", rec(n, 63, &mut dp));
    for i in 0..(n + 1) {
        for j in 0..64 {
            print!("{} ", dp[i][j]);
        }
        println!("");
    }
}

fn rec(n: usize, i: usize, dp: &mut Vec<Vec<u128>>) -> u128 {
    if dp[n][i] != 0 {
        return dp[n][i];
    } else if n == 0 {
        dp[n][i] = 1;
        return dp[n][i];
    }
    let mut ret = 0;
    for c in 0..4 {
        if ng((i << 2) + c) {
            println!("{}", (i << 2) + c);
            continue;
        }
        let new_i = ((i << 2) + c) & 63;
        ret = add_mod(rec(n - 1, new_i, dp), ret);
    }
    dp[n][i] = ret;
    ret
}

