const MOD: u128 = 1000000007;

fn add_mod(a: u128, b: u128) -> u128 {
    (a + b) % MOD
}

fn sub_mod(a: u128, b: u128) -> u128 {
    (a + MOD - b) % MOD
}

fn mul_mod(a: u128, b: u128) -> u128 {
    (a * b) % MOD
}

fn pow_mod(base: u128, exp: u128) -> u128 {
    if exp == 0 {
        1
    } else if exp == 1 {
        base
    } else {
        let prev = pow_mod(base, exp / 2);
        let tmp = if exp % 2 == 0 { 1 } else { base };
        mul_mod(mul_mod(prev, prev), tmp)
    }
}

fn div_mod(a: u128, b: u128) -> u128 {
    mul_mod(a, pow_mod(b, MOD - 2))
}

fn combination_mod(n: u128, k: u128) -> u128 {
    let mut ret = 1;
    for i in 0..k {
        let mul = if i < n { n - i } else { 0 };
        ret = div_mod(mul_mod(ret, mul), i + 1);
        println!("{}a", ret);
    }
    ret
}

