fn solve() {
    let n = get!(usize);

    let mut dp = vec![vec![vec![vec![0;4];4];4]; n+1];

    let mo = 1_000_000_007;
    dp[0][3][3][3] = 1;

    for i in 0..n {
        for a in 0..4 { //before 3
            for b in 0..4 { //before 2
                for c in 0..4 { //before 1
                    for d in 0..4 { //current
                        //ACGT => 0123
                        //.AGC
                        //.ACG
                        //.GAC
                        //A.GC
                        //AG.C
                        if (b == 0 && c == 1 && d == 2) //.ACG
                            || (b == 2 && c == 0 && d == 1) //.GAC
                            || (a == 0 && c == 2 && d == 1) //A.GC
                            || (a == 0 && b == 2 && d == 1) //AG.C
                            || (b == 0 && c == 2 && d == 1) /*.AGC*/ {
                            continue;
                        }

                        dp[i+1][d][c][b] += dp[i][c][b][a];
                        dp[i+1][d][c][b] %= mo;
                    }
                }
            }
        }
    } 

    let mut res = 0u64;
    for a in 0..4 {
        for b in  0..4 {
            for c in 0..4 {
                res += dp[n][a][b][c];
                res %= mo;
            }
        }
    }
    println!("{}", res);
}

