const MOD: usize = 1_000_000_007;

use std::collections::HashMap;

fn combinations(counter: &mut HashMap<String, usize>, acc: String) {
    if acc.len() == 3 {
        counter.insert(acc, 1);
    } else {
        for next in vec!["A", "G", "T", "C"] {
            combinations(counter, acc.clone() + next);
        }
    }
}

fn main() {
    read!(n = usize);

    let mut counter = HashMap::new();
    combinations(&mut counter, String::new());
    counter.remove("AGC");
    counter.remove("ACG");
    counter.remove("GAC");

    for _ in 3..n {
        let mut new = HashMap::new();
        for (last, cnt) in counter {
            for next_char in vec!["A", "G", "T", "C"] {
                let next = last.to_string() + next_char;
                if !next.ends_with("AGC") &&
                    !next.ends_with("ACG") &&
                    !next.ends_with("GAC") &&
                    !(next.starts_with("A") && next.ends_with("GC")) &&
                    !(next.starts_with("AG") && next.ends_with("C")) {
                        let mut new_cnt = new.entry(next[1..].to_string()).or_insert(0);
                        *new_cnt = (*new_cnt + cnt) % MOD;
                    }
            }
        }
        counter = new;
    }

    let ans = counter.values().sum::<usize>() % MOD;
    println!("{}", ans);
}

const M: isize = 1000000007;

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_line(&mut buf).unwrap();
    let n: usize = buf.trim().parse().unwrap();

    // dp[100][4][4][4]
    let mut dp = vec![vec![vec![vec![0; 4]; 4]; 4]; n+1];

    // TTT
    dp[0][3][3][3] = 1;

    for cnt in 0..n {
        for i in 0..4 {
            for j in 0..4 {
                for k in 0..4 {
                    for c in 0..4 {
                        // A->0, C->1, G->2, T->3
                        // ?AGC
                        // ?ACG
                        // ?GAC
                        // A?GC
                        // AG?C
                        match (i, j, k, c) {
                            (_, 0, 2, 1) |
                            (_, 0, 1, 2) |
                            (_, 2, 0, 1) |
                            (0, _, 2, 1) |
                            (0, 2, _, 1) => {
                                continue;
                            },
                            _ => {
                                dp[cnt+1][j][k][c] += dp[cnt][i][j][k];
                                dp[cnt+1][j][k][c] %= M;
                            }
                        }
                    }
                }
            }
        }
    }

    let mut ans=0;
    for i in 0..4 {
        for j in 0..4 {
            for k in 0..4 {
                ans += dp[n][i][j][k];
                ans %= M;
            }
        }
    }
    println!("{}", ans);
}

