fn main() {
  let MOD: u64 = 1_000_000_000 + 7;
  let n: usize = read();
  let mut dp = vec![vec![vec![vec![0; 4]; 4]; 4]; n+1];
  // 長さ０の文字列は１
  dp[0][3][3][3] = 1;
  // 文字列の文字数
  for len in 0..n {
    // 最後から１文字目の文字
    for i in 0..4 {
      // 最後から２文字目の文字
      for j in 0..4 {
        // 最後から3文字目の文字
        for k in 0..4 {
          // 条件に当てはまる物が無い場合はcontinue
          if dp[len][i][j][k] == 0 { continue; }

          // 新しく追加する文字
          for a in 0..4 {
            // ダメな５つの条件をカットする
            if a == 2 && i == 1 && j == 0 { continue; }
            if a == 2 && i == 0 && j == 1 { continue; }
            if a == 1 && i == 2 && j == 0 { continue; }
            if a == 2 && i == 1 && k == 0 { continue; }
            if a == 2 && j == 1 && k == 0 { continue; }

            // ダメな条件を抜けたら、aを足した文字列が作れる
            dp[len + 1][a][i][j] += dp[len][i][j][k];
            dp[len + 1][a][i][j] %= MOD;
          }
        }
      }
    }
  }

  let mut ans = 0;

  for i in 0..4 {
    for j in 0..4 {
      for k in 0..4 {
        ans += dp[n][i][j][k];
        ans %= MOD;
      }
    }
  }

  println!("{}", ans);
}

