const MOD: usize = 1_000_000_007;

fn solve(src: String) -> String {
    input! {
        source = src,
        n: usize
    }
    let mut dp = vec![vec![vec![vec![0; 4]; 4]; 4]; n+1];
    dp[0][3][3][3] = 1;
    for len in 0..n {
        for i in 0..4 {
            for j in 0..4 {
                for k in 0..4 {
                    if dp[len][i][j][k] == 0 {
                        continue;
                    }

                    for a in 0..4 {
                        match (k,j,i,a) {
                            (_,0,1,2) => continue,
                            (_,0,2,1) => continue,
                            (_,1,0,2) => continue,
                            (0,_,1,2) => continue,
                            (0,1,_,2) => continue,
                            _ => {
                                dp[len+1][a][i][j] += dp[len][i][j][k];
                                dp[len+1][a][i][j] %= MOD;
                            }
                        }
                    }
                }
            }
        }
    }
    let mut ans = 0;
    for i in 0..4 {
        for j in 0..4 {
            for k in 0..4 {
                ans += dp[n][i][j][k];
                ans %= MOD;
            }
        }
    }
    ans.to_string()
}

