    }

    // dp: length, 3文字前, 2文字前, 1文字前
    // A -> 0, C -> 1, G -> 2, T -> 3
    let mut dp = vec![ vec![ vec![ vec![0; 4]; 4]; 4]; N+1];

    dp[0][3][3][3] = 1;
    for len in 0..N {
        for third_last in 0..4 {
            for sec_last in 0..4 {
                for last in 0..4 {
                    for next in 0..4 {
                        match (third_last, sec_last, last, next) {
                            // NG list 
