                            // A ? G C
                            // ? G A C
                            // ? A C G 
                            // A G ? C
                            (_, 0, 2, 1) |
                            (0, _, 2, 1) |
                            (_, 2, 0, 1) |
                            (_, 0, 1, 2) |
                            (0, 2, _, 1) => (),
                            _ => {
                                dp[len+1][sec_last][last][next] +=
                                    dp[len][third_last][sec_last][last];
                                dp[len+1][sec_last][last][next] %= MOD;
                            },
                        }
                    }
                }
            }
        }
    }
    let mut ans = 0;
    for third_last in 0..4 {
        for sec_last in 0..4 {
