        // C
        for j in 0..4 {
            for k in 0..4 {
                for l in 0..4 {
                    // ?AG
                    if j == 2 && k == 0 {
                        continue;
                    }
                    // A?G
                    if j == 2 && l == 0 {
                        continue;
                    }
                    // ?GA
                    if j == 0 && k == 2 {
                        continue;
                    }
                    // AG?
                    if k == 2 && l == 0 {
