        // T
        for j in 0..4 {
            for k in 0..4 {
                for l in 0..4 {
                    dp[i + 1][3][j][k] += dp[i][j][k][l];
                    dp[i + 1][3][j][k] %= MOD;
                }
            }
        }
    }

    let mut ans = 0;
    for v in &dp[n] {
        for w in v {
            for x in w {
                ans += x;
                ans %= MOD;
