fn is_agc(x: usize) -> bool {
    let x1 = x / 64;
    let x2 = (x / 16) % 4;
    let x3 = (x /4) % 4;
    let x4 = x % 4;

    (x1 == 0 && x2 == 2 && x3 == 1) ||
     (x1 == 0 && x2 == 1 && x3 == 2) ||
     (x1 == 2 && x2 == 0 && x3 == 1) ||
     (x2 == 0 && x3 == 2 && x4 == 1) ||
     (x2 == 0 && x3 == 1 && x4 == 2) ||
     (x2 == 2 && x3 == 0 && x4 == 1) ||
     (x1 == 0 && x3 == 2 && x4 == 1) ||
     (x1 == 0 && x2 == 2 && x4 == 1)
}


