fn rec(n: usize, i: usize, dp: &mut Vec<Vec<u64>>) -> u64 {
    if dp[n][i] != 0 {
        return dp[n][i];
    } else if n == 0 {
        dp[n][i] = 1;
        return dp[n][i];
    }
    let mut ret = 0;
    for c in 0..4 {
        if ng((i << 2) + c) {
            continue;
        }
        let new_i = ((i << 2) + c) & 63;
        ret = add_mod(rec(n - 1, new_i, dp), ret);
    }
    dp[n][i] = ret;
    ret
}

