fn ng(n: usize)  -> bool {
    let up = n >> 2;
    let down = n & 63;
    let pos1 = n & 243;
    let pos2 = n & 207;
    up == 6 || down == 6 || up == 33 || down == 33 || up == 9 || down == 9 || pos1 == 33 || pos2 == 9
}

const MOD: u64 = 1000000007;

fn add_mod(a: u64, b: u64) -> u64 {
    (a + b) % MOD
}

fn sub_mod(a: u64, b: u64) -> u64 {
    (a + MOD - b) % MOD
}

fn mul_mod(a: u64, b: u64) -> u64 {
    (a * b) % MOD
}

fn pow_mod(base: u64, exp: u64) -> u64 {
    if exp == 0 {
        1
    } else if exp == 1 {
        base
    } else {
        let prev = pow_mod(base, exp / 2);
        let tmp = if exp % 2 == 0 { 1 } else { base };
        mul_mod(mul_mod(prev, prev), tmp)
    }
}

fn div_mod(a: u64, b: u64) -> u64 {
    mul_mod(a, pow_mod(b, MOD - 2))
}

fn combination_mod(n: u64, k: u64) -> u64 {
    let mut ret = 1;
    for i in 0..k {
        let mul = if i < n { n - i } else { 0 };
        ret = div_mod(mul_mod(ret, mul), i + 1);
    }
    ret
}

