use std::str::FromStr;
use std::fmt::Debug;
use std::cmp;

fn read_as_vec<T>() -> Vec<T>
where T: FromStr, <T as FromStr>::Err : Debug{
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().split_whitespace().map(|c| T::from_str(c).unwrap()).collect()

}

fn read_as_string() -> String{
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().to_string()
}


fn main(){
    let n = read_as_vec::<usize>()[0];
    let mmod: usize = 1000000007;
    let mut dp: Vec<Vec<Vec<Vec<usize>>>> = vec![vec![vec![vec![0;4];4];4];n];//ACGT

    for i in 0..4{
        dp[0][2][2][i] = 1;
    }

    for i in 0..4{
        for j in 0..4{
            dp[1][2][i][j] = 1;
        }
    }


    for i in 2..n{
        for p3 in 0..4{
            for p2 in 0..4{
                for p1 in 0..4{
                    //if (p3 == 0 && p2 == 2 && p1 == 1) ||{
                    //AGC or GAC or ACG
                    if (p3, p2, p1) == (0, 2, 1) ||
                        (p3, p2, p1) == (2, 0, 1)||
                        (p3, p2, p1) == (0, 1, 2){
                        continue;
                    }
                    for p4 in 0..4{
                        if (p4, p2, p1) == (0, 2, 1) ||
                            (p4, p3, p1) == (0, 2, 1){
                                continue;
                            }
                        dp[i][p3][p2][p1] = (dp[i][p3][p2][p1] + dp[i-1][p4][p3][p2])%mmod;
                    }
                }
            }
        }
    }

    let mut ans = 0;

    for p3 in 0..4{
        for p2 in 0..4{
            for p1 in 0..4{
                ans = (ans + dp[n-1][p3][p2][p1])%mmod;
            }
        }
    }

    println!("{}", ans);
}
